                enemyPool: ['enemyHeavy', 'cruiser', 'battleship', 'fighter'],
                bossPool: ['battleship', 'enemyBoss', 'cruiser'],
                obstaclePool: ['medium_shield', 'large_shield', 'small_shield', 'large_asteroid'],
