                    name: g.name,
                    faction: this.ensureGalaxyFaction(g),
                    baseColor: g.baseColor || null,
                    planetIds: (g.planetIds || []).slice(),
                    map: {
                        startPlanetId: map.startPlanetId,
                        nodes: (map.nodes || []).map(n => ({
                            planetId: n.planetId,
                            x: n.x,
                            y: n.y
                        })),
                        edges: (map.edges || []).map(e => [e[0], e[1]])
                    }
