"use strict";

// ProfileManager methods, split from profile-manager.js.
extendClass(ProfileManager, {
    create(name, factionId) {
        const trimmed = String(name || '').trim().toUpperCase().slice(0, 16);
        if (!trimmed) return null;
        const starter = this.getStarterShipId();
        const faction = this.normalizeFactionId(factionId);
        const profile = {
            id: this.createId(),
            name: trimmed,
            faction: faction,
            createdAt: Date.now(),
            progress: this.emptyProgress(),
            ownedShipIds: [starter],
            activeShipId: starter,
            unlockedShopIds: [],
            blueprints: {},
            parts: { weapons: {}, defenses: {}, abilities: {}, energy: { energy_core: 1 } },
            resources: {},
            credits: (typeof economyConfig !== 'undefined' && economyConfig.starterCredits != null)
                ? economyConfig.starterCredits
                : 250,
            cargo: this.emptyCargo(),
            homeStation: {
                lastTeleportAt: 0,
                upgrades: this.emptyStationUpgrades(),
                currentGalaxyId: 'milky_way',
                ownedPortalIds: [],
                exploreCount: {}
            },
            shipUpgrades: {},
            moduleUpgrades: (typeof economyConfig !== 'undefined' && economyConfig.emptyModuleUpgrades)
                ? economyConfig.emptyModuleUpgrades()
                : { weapons: {}, defenses: {}, abilities: {} },
            discovered: this.emptyDiscovered()
        };
        this.ensureEconomyDefaults(profile);
        this.profiles.push(profile);
        this.activeProfileId = profile.id;
        this.discoverShipContents(starter);
        this.save();
        if (typeof factionManager !== 'undefined' && factionManager.join) {
            factionManager.join(faction);
        }
        if (typeof factionShipStyles !== 'undefined' && factionShipStyles.applyDocumentFactionTheme) {
            factionShipStyles.applyDocumentFactionTheme(faction);
        }
        return profile;
    },

    getOwnedShipIds(profile) {
        const p = profile || this.getActiveProfile();
        if (!p) return [this.getStarterShipId()];
        this.ensureEconomyDefaults(p);
        return p.ownedShipIds.slice();
    },

    ownsShip(shipId, profile) {
        const id = String(shipId || '');
        return this.getOwnedShipIds(profile).indexOf(id) !== -1;
    },

    setActiveShip(shipId) {
        const profile = this.getActiveProfile();
        if (!profile) return false;
        this.ensureEconomyDefaults(profile);
        const id = String(shipId || '');
        if (profile.ownedShipIds.indexOf(id) === -1) return false;
        profile.activeShipId = id;
        this.discoverShipContents(id);
        this.save();
        return true;
    },

    getActiveShipId() {
        const profile = this.getActiveProfile();
        if (!profile) return this.getStarterShipId();
        this.ensureEconomyDefaults(profile);
        return profile.activeShipId;
    },

    /** Manual override for which hull-part shape variant set a given owned ship uses. */
    getHullShapeSeed(shipId) {
        const profile = this.getActiveProfile();
        if (!profile || !profile.hullShapeSeeds) return null;
        const seed = profile.hullShapeSeeds[String(shipId || '')];
        return seed != null ? seed : null;
    },

    setHullShapeSeed(shipId, seed) {
        const profile = this.getActiveProfile();
        if (!profile) return false;
        if (!profile.hullShapeSeeds) profile.hullShapeSeeds = {};
        profile.hullShapeSeeds[String(shipId || '')] = String(seed);
        this.save();
        return true;
    },

    /**
     * Per-segment shape variant override — lets a single hull part (nose,
     * center, aft, or the mirrored wing pair) be cycled through its own
     * shape options independently, instead of only being able to reroll
     * every part on the ship at once via the shape seed above.
     */
    getSegmentShapeVariant(shipId, segId) {
        const profile = this.getActiveProfile();
        const byShip = profile && profile.segmentShapeVariants && profile.segmentShapeVariants[String(shipId || '')];
        if (!byShip) return null;
        const v = byShip[String(segId || '')];
        return v != null ? Number(v) : null;
    },

    setSegmentShapeVariant(shipId, segId, variantIndex) {
        const profile = this.getActiveProfile();
        if (!profile) return false;
        if (!profile.segmentShapeVariants) profile.segmentShapeVariants = {};
        const key = String(shipId || '');
        if (!profile.segmentShapeVariants[key]) profile.segmentShapeVariants[key] = {};
        profile.segmentShapeVariants[key][String(segId || '')] = Number(variantIndex) || 0;
        this.save();
        return true;
    },

    getWingStyleSymmetry(shipId) {
        const profile = this.getActiveProfile();
        const byShip = profile && profile.wingStyleSymmetry;
        if (!byShip) return true;
        return byShip[String(shipId || '')] !== false;
    },

    setWingStyleSymmetry(shipId, enabled) {
        const profile = this.getActiveProfile();
        if (!profile) return false;
        if (!profile.wingStyleSymmetry) profile.wingStyleSymmetry = {};
        profile.wingStyleSymmetry[String(shipId || '')] = !!enabled;
        this.save();
        return true;
    },

    addOwnedShip(shipId) {
        const profile = this.getActiveProfile();
        if (!profile) return false;
        this.ensureEconomyDefaults(profile);
        const id = String(shipId || '');
        if (!id) return false;
        if (profile.ownedShipIds.indexOf(id) === -1) {
            profile.ownedShipIds.push(id);
            this.discoverShipContents(id);
            this.save();
        }
        return true;
    },

    removeOwnedShip(shipId) {
        const profile = this.getActiveProfile();
        if (!profile) return false;
        this.ensureEconomyDefaults(profile);
        const id = String(shipId || '');
        const starter = this.getStarterShipId();
        if (!id || id === starter) return false;
        const idx = profile.ownedShipIds.indexOf(id);
        if (idx === -1) return false;
        profile.ownedShipIds.splice(idx, 1);
        if (profile.activeShipId === id) {
            profile.activeShipId = starter;
        }
        this.save();
        return true;
    },

    toggleOwnedShip(shipId) {
        if (this.ownsShip(shipId)) {
            this.removeOwnedShip(shipId);
            return false;
        }
        this.addOwnedShip(shipId);
        return true;
    },

    setPartOwned(kind, partId, owned) {
        const profile = this.getActiveProfile();
        if (!profile) return false;
        this.ensureEconomyDefaults(profile);
        const k = String(kind || '');
        const id = String(partId || '');
        if (!id || (k !== 'weapon' && k !== 'defense' && k !== 'ability')) return false;
        const bag = k === 'weapon' ? profile.parts.weapons
            : (k === 'defense' ? profile.parts.defenses : profile.parts.abilities);
        if (owned) {
            if ((bag[id] || 0) < 1) bag[id] = 1;
            this.discover(k === 'weapon' ? 'weapons' : (k === 'defense' ? 'defenses' : 'abilities'), id);
        } else {
            delete bag[id];
        }
        this.save();
        return true;
    },

    togglePartOwned(kind, partId) {
        const has = this.getPartCount(kind, partId) > 0;
        this.setPartOwned(kind, partId, !has);
        return !has;
    },

    addCargoResource(resourceId, amount, options) {
        const profile = this.getActiveProfile();
        if (!profile) return 0;
        this.ensureEconomyDefaults(profile);
        const id = String(resourceId || '').toLowerCase();
        const n = Math.round(Number(amount) || 0);
        if (!id || n <= 0) return 0;
        const stats = this.getStationStats(profile);
        const applied = this.applyResourceCap(profile.cargo.resources[id], n, stats.cargoCap);
        if (applied.granted <= 0) return 0;
        profile.cargo.resources[id] = applied.next;
        if (!(options && options.skipSave)) {
            this.save();
        }
        return applied.granted;
    },

    addCargoBlueprint(shipId, amount) {
        const profile = this.getActiveProfile();
        if (!profile) return false;
        this.ensureEconomyDefaults(profile);
        const id = String(shipId || '');
        const n = Math.round(Number(amount) || 1);
        if (!id || n <= 0) return false;
        profile.cargo.blueprints[id] = (profile.cargo.blueprints[id] || 0) + n;
        this.discover('ships', id);
        this.save();
        return true;
    },

    grantPlanetResources(planetId) {
        const profile = this.getActiveProfile();
        if (!profile) return null;
        this.ensureEconomyDefaults(profile);
        const pid = String(planetId || '').toLowerCase();
        let table = null;
        if (typeof planetConfigManager !== 'undefined') {
            const cfg = planetConfigManager.getConfig(pid);
            if (cfg && Array.isArray(cfg.resources) && cfg.resources.length) {
                table = cfg.resources;
            }
        }
        if ((!table || !table.length) && typeof economyConfig !== 'undefined') {
            table = economyConfig.defaultPlanetResources[pid] || [];
        }
        if (typeof economyConfig === 'undefined') return null;
        const granted = economyConfig.rollPlanetResources(table);
        const stats = this.getStationStats(profile);
        const actual = {};
        Object.keys(granted).forEach((id) => {
            const n = granted[id] || 0;
            if (n <= 0) return;
            const applied = this.applyResourceCap(profile.cargo.resources[id], n, stats.cargoCap);
            if (applied.granted > 0) {
                profile.cargo.resources[id] = applied.next;
                actual[id] = applied.granted;
            }
        });
        this.save();
        return actual;
    },
});


/* --- js/core/profile-manager/try-blueprint-drop.js?v=faction-gui-4 --- */
"use strict";

// ProfileManager methods, split from profile-manager.js.
extendClass(ProfileManager, {
    tryBlueprintDrop(killInfo) {
        const profile = this.getActiveProfile();
        if (!profile || typeof economyConfig === 'undefined') return null;
        this.ensureEconomyDefaults(profile);
        const stats = this.getStationStats(profile);
        const chance = Math.min(0.5, economyConfig.getBlueprintDropChance(killInfo) + (stats.dropBonus || 0));
        if (Math.random() > chance) return null;
        const shipId = economyConfig.pickBlueprintShipId(profile.ownedShipIds);
        if (!shipId) return null;
        this.addCargoBlueprint(shipId, 1);
        return shipId;
    },

    hasCargo() {
        const profile = this.getActiveProfile();
        if (!profile) return false;
        this.ensureEconomyDefaults(profile);
        const hasRes = Object.keys(profile.cargo.resources).some((k) => profile.cargo.resources[k] > 0);
        const hasBp = Object.keys(profile.cargo.blueprints).some((k) => profile.cargo.blueprints[k] > 0);
        return hasRes || hasBp;
    },

    teleportCargoToStation() {
        const profile = this.getActiveProfile();
        if (!profile) return false;
        this.ensureEconomyDefaults(profile);
        const stats = this.getStationStats(profile);
        let moved = false;
        Object.keys(profile.cargo.resources).forEach((id) => {
            const n = profile.cargo.resources[id] || 0;
            if (n <= 0) return;
            const applied = this.applyResourceCap(profile.resources[id], n, stats.resourceCap);
            if (applied.granted > 0) {
                profile.resources[id] = applied.next;
                moved = true;
            }
            if (applied.leftover > 0) {
                profile.cargo.resources[id] = applied.leftover;
            } else {
                delete profile.cargo.resources[id];
            }
        });
        Object.keys(profile.cargo.blueprints).forEach((id) => {
            const n = profile.cargo.blueprints[id] || 0;
            if (n > 0) {
                profile.blueprints[id] = (profile.blueprints[id] || 0) + n;
                delete profile.cargo.blueprints[id];
                moved = true;
            }
        });
        if (!Object.keys(profile.cargo.resources).length && !Object.keys(profile.cargo.blueprints).length) {
            profile.cargo = this.emptyCargo();
        }
        profile.homeStation.lastTeleportAt = Date.now();
        this.save();
        return moved;
    },

    spendResources(costMap) {
        const profile = this.getActiveProfile();
        if (!profile || typeof economyConfig === 'undefined') return false;
        this.ensureEconomyDefaults(profile);
        if (!economyConfig.canAfford(profile.resources, costMap)) return false;
        Object.keys(costMap || {}).forEach((id) => {
            profile.resources[id] = (profile.resources[id] || 0) - (costMap[id] || 0);
            if (profile.resources[id] <= 0) delete profile.resources[id];
        });
        this.save();
        return true;
    },

    getCredits(profile) {
        const p = profile || this.getActiveProfile();
        if (!p) return 0;
        this.ensureEconomyDefaults(p);
        return Math.max(0, Math.round(Number(p.credits) || 0));
    },

    canAffordCredits(amount, profile) {
        return this.getCredits(profile) >= Math.max(0, Math.round(Number(amount) || 0));
    },

    spendCredits(amount, skipSave) {
        const profile = this.getActiveProfile();
        if (!profile) return false;
        this.ensureEconomyDefaults(profile);
        const n = Math.max(0, Math.round(Number(amount) || 0));
        if (n <= 0) return true;
        if (profile.credits < n) return false;
        profile.credits -= n;
        if (!skipSave) this.save();
        return true;
    },

    addCredits(amount, skipSave) {
        const profile = this.getActiveProfile();
        if (!profile) return false;
        this.ensureEconomyDefaults(profile);
        const n = Math.max(0, Math.round(Number(amount) || 0));
        if (n <= 0) return true;
        profile.credits = Math.max(0, Math.round(Number(profile.credits) || 0) + n);
        if (!skipSave) this.save();
        return true;
    },

    getResourceBag(bag, profile) {
        const p = profile || this.getActiveProfile();
        if (!p) return null;
        this.ensureEconomyDefaults(p);
        const kind = String(bag || 'station').toLowerCase();
        if (kind === 'cargo') return p.cargo.resources;
        return p.resources;
    },

    getResourceBagCap(bag, profile) {
        const stats = this.getStationStats(profile);
        return String(bag || 'station').toLowerCase() === 'cargo'
            ? stats.cargoCap
            : stats.resourceCap;
    },

    /**
     * Buy resource into station or cargo. Paid from uncapped CREDITS.
     * bag: 'station' | 'cargo'
     */
    buyShopResource(resourceId, amount, bag) {
        const profile = this.getActiveProfile();
        if (!profile || typeof economyConfig === 'undefined') {
            return { ok: false, reason: 'NO PROFILE' };
        }
        this.ensureEconomyDefaults(profile);
        const id = String(resourceId || '').toLowerCase();
        const n = Math.max(1, Math.round(Number(amount) || 1));
        const bagKind = String(bag || 'station').toLowerCase() === 'cargo' ? 'cargo' : 'station';
        if (!economyConfig.isResourceTradeable(id)) {
            return { ok: false, reason: 'INVALID' };
        }
        const bagMap = this.getResourceBag(bagKind, profile);
        const cap = this.getResourceBagCap(bagKind, profile);
        const applied = this.applyResourceCap(bagMap[id], n, cap);
        if (applied.granted <= 0) {
            return { ok: false, reason: bagKind === 'cargo' ? 'CARGO FULL' : 'STATION FULL' };
        }
        const paid = economyConfig.getResourceBuyCost(id, applied.granted);
        if (!paid || !this.spendCredits(paid.credits, true)) {
            return { ok: false, reason: 'CREDITS' };
        }
        bagMap[id] = applied.next;
        this.save();
        return { ok: true, amount: applied.granted, bag: bagKind, cost: paid };
    },

    /**
     * Sell resource from station or cargo. Credits payout is uncapped.
     * bag: 'station' | 'cargo'
     */
    sellShopResource(resourceId, amount, bag) {
        const profile = this.getActiveProfile();
        if (!profile || typeof economyConfig === 'undefined') {
            return { ok: false, reason: 'NO PROFILE' };
        }
        this.ensureEconomyDefaults(profile);
        const id = String(resourceId || '').toLowerCase();
        const n = Math.max(1, Math.round(Number(amount) || 1));
        const bagKind = String(bag || 'station').toLowerCase() === 'cargo' ? 'cargo' : 'station';
        if (!economyConfig.isResourceTradeable(id)) {
            return { ok: false, reason: 'INVALID' };
        }
        const bagMap = this.getResourceBag(bagKind, profile);
        const have = Math.max(0, Math.round(Number(bagMap[id]) || 0));
        if (have < 1) return { ok: false, reason: 'EMPTY' };
        const sold = Math.min(n, have);
        const payout = economyConfig.getResourceSellPayout(id, sold);
        if (!payout) return { ok: false, reason: 'INVALID' };
        bagMap[id] = have - sold;
        if (bagMap[id] <= 0) delete bagMap[id];
        this.addCredits(payout.credits, true);
        this.save();
        return { ok: true, amount: sold, bag: bagKind, payout: payout };
    },

    getDiscountedCraftCost(shipConfig, profile) {
        const base = (typeof economyConfig !== 'undefined')
            ? economyConfig.getCraftCost(shipConfig)
            : { scrap: 80 };
        const stats = this.getStationStats(profile);
        const discount = Math.max(0, Math.min(0.5, Number(stats.craftDiscount) || 0));
        if (discount <= 0) return base;
        const out = {};
        Object.keys(base).forEach((id) => {
            out[id] = Math.max(1, Math.ceil(base[id] * (1 - discount)));
        });
        return out;
    },

    isShopUnlocked(shipId) {
        const profile = this.getActiveProfile();
        if (!profile) return false;
        this.ensureEconomyDefaults(profile);
        return profile.unlockedShopIds.indexOf(String(shipId || '')) !== -1;
    },

    unlockShopItem(shipId) {
        const profile = this.getActiveProfile();
        if (!profile) return { ok: false, reason: 'NO PROFILE' };
        this.ensureEconomyDefaults(profile);
        const id = String(shipId || '');
        if (!id || id === this.getStarterShipId()) {
            return { ok: false, reason: 'INVALID' };
        }
        if (profile.unlockedShopIds.indexOf(id) !== -1) {
            return { ok: false, reason: 'ALREADY UNLOCKED' };
        }
        const count = profile.blueprints[id] || 0;
        if (count < 1) return { ok: false, reason: 'NO BLUEPRINT' };
        profile.blueprints[id] = count - 1;
        if (profile.blueprints[id] <= 0) delete profile.blueprints[id];
        profile.unlockedShopIds.push(id);
        this.discover('ships', id);
        this.save();
        return { ok: true };
    },

    buyShip(shipId) {
        const profile = this.getActiveProfile();
        if (!profile || typeof economyConfig === 'undefined' || typeof shipConfigManager === 'undefined') {
            return { ok: false, reason: 'NO PROFILE' };
        }
        this.ensureEconomyDefaults(profile);
        const id = String(shipId || '');
        if (!id || id === this.getStarterShipId()) {
            return { ok: false, reason: 'INVALID' };
        }
        if (profile.ownedShipIds.indexOf(id) !== -1) {
            return { ok: false, reason: 'OWNED' };
        }
        if (this.getFreeShipSlots(profile) < 1) {
            return { ok: false, reason: 'NO SHIP SLOTS' };
        }
        const cfg = shipConfigManager.getConfig(id);
        if (!cfg || cfg.custom) {
            return { ok: false, reason: 'INVALID' };
        }
        if (!this.isShipAvailableInShop(id, profile)) {
            return { ok: false, reason: 'WRONG GALAXY' };
        }
        const cost = economyConfig.getShopCost(cfg);
        const creditCost = Math.max(0, Math.round(Number(cost.credits) || 0));
        if (creditCost > 0) {
            if (!this.spendCredits(creditCost)) {
                return { ok: false, reason: 'CREDITS' };
            }
        } else if (!this.spendResources(cost)) {
            return { ok: false, reason: 'RESOURCES' };
        }
        profile.ownedShipIds.push(id);
        if (profile.unlockedShopIds.indexOf(id) === -1) {
            profile.unlockedShopIds.push(id);
        }
        this.discoverShipContents(id);
        this.save();
        return { ok: true };
    },
});


/* --- js/core/profile-manager/buy-blueprint.js?v=stages-2 --- */
"use strict";

// ProfileManager methods, split from profile-manager.js.
extendClass(ProfileManager, {
    buyBlueprint(shipId) {
        const profile = this.getActiveProfile();
        if (!profile || typeof economyConfig === 'undefined' || typeof shipConfigManager === 'undefined') {
            return { ok: false, reason: 'NO PROFILE' };
        }
        this.ensureEconomyDefaults(profile);
        const id = String(shipId || '');
        if (!id || id === this.getStarterShipId()) {
            return { ok: false, reason: 'INVALID' };
        }
        const cfg = shipConfigManager.getConfig(id);
        if (!cfg || cfg.custom) {
            return { ok: false, reason: 'INVALID' };
        }
        if (!this.isShipAvailableInShop(id, profile)) {
            return { ok: false, reason: 'WRONG GALAXY' };
        }
        const cost = economyConfig.getBlueprintCost(cfg);
        const creditCost = Math.max(0, Math.round(Number(cost.credits) || 0));
        if (creditCost > 0) {
            if (!this.spendCredits(creditCost)) {
                return { ok: false, reason: 'CREDITS' };
            }
        } else if (!this.spendResources(cost)) {
            return { ok: false, reason: 'RESOURCES' };
        }
        profile.blueprints[id] = (profile.blueprints[id] || 0) + 1;
        this.discover('ships', id);
        this.save();
        return { ok: true };
    },

    /** `postId` buys from a docked trading post instead of the home shop. */
    buyPart(kind, partId, postId) {
        const profile = this.getActiveProfile();
        if (!profile || typeof economyConfig === 'undefined') {
            return { ok: false, reason: 'NO PROFILE' };
        }
        this.ensureEconomyDefaults(profile);
        const k = String(kind || '');
        const id = String(partId || '');
        if (!id || (k !== 'weapon' && k !== 'defense' && k !== 'ability' && k !== 'energy')) {
            return { ok: false, reason: 'INVALID' };
        }

        let item = null;
        let discoverCat = null;
        if (k === 'weapon') {
            if (typeof weaponConfigManager === 'undefined') {
                return { ok: false, reason: 'NO PROFILE' };
            }
            item = weaponConfigManager.getWeapon(id);
            if (!item || item.id !== id) {
                return { ok: false, reason: 'INVALID' };
            }
            discoverCat = 'weapons';
        } else if (k === 'defense') {
            if (typeof abilityConfigManager === 'undefined') {
                return { ok: false, reason: 'NO PROFILE' };
            }
            item = abilityConfigManager.getAbility(id);
            if (!item || item.cluster !== 'defense') {
                return { ok: false, reason: 'INVALID' };
            }
            discoverCat = 'defenses';
        } else if (k === 'energy') {
            if (typeof abilityConfigManager === 'undefined') {
                return { ok: false, reason: 'NO PROFILE' };
            }
            item = abilityConfigManager.getAbility(id);
            if (!item || item.id !== id) {
                return { ok: false, reason: 'INVALID' };
            }
            if (typeof shipLoadoutManager !== 'undefined' && shipLoadoutManager.isEnergyId
                && !shipLoadoutManager.isEnergyId(id)) {
                return { ok: false, reason: 'INVALID' };
            }
            discoverCat = 'energy';
        } else {
            if (typeof abilityConfigManager === 'undefined') {
                return { ok: false, reason: 'NO PROFILE' };
            }
            item = abilityConfigManager.getAbility(id);
            if (!item || item.id !== id || item.cluster === 'defense') {
                return { ok: false, reason: 'INVALID' };
            }
            if (typeof shipLoadoutManager !== 'undefined' && shipLoadoutManager.isEnergyId
                && shipLoadoutManager.isEnergyId(id)) {
                return { ok: false, reason: 'INVALID' };
            }
            discoverCat = 'abilities';
        }

        if (postId) {
            if (!this.isPartInTradingPost(postId, k, id)) {
                return { ok: false, reason: 'NOT IN STOCK' };
            }
        } else if (!this.isPartAvailableInShop(k, id, profile)) {
            return { ok: false, reason: 'WRONG GALAXY' };
        }

        const cost = economyConfig.getPartCost(k, item);
        const creditCost = Math.max(0, Math.round(Number(cost.credits) || 0));
        if (creditCost > 0) {
            if (!this.spendCredits(creditCost)) {
                return { ok: false, reason: 'CREDITS' };
            }
        } else if (!this.spendResources(cost)) {
            return { ok: false, reason: 'RESOURCES' };
        }

        const bag = k === 'weapon' ? profile.parts.weapons
            : (k === 'defense' ? profile.parts.defenses
                : (k === 'energy' ? profile.parts.energy : profile.parts.abilities));
        bag[id] = (bag[id] || 0) + 1;
        this.discover(discoverCat, id);
        this.save();
        return { ok: true };
    },

    getPartCount(kind, partId, profile) {
        const p = profile || this.getActiveProfile();
        if (!p) return 0;
        this.ensureEconomyDefaults(p);
        const id = String(partId || '');
        if (kind === 'weapon') return (p.parts.weapons[id] || 0);
        if (kind === 'defense') return (p.parts.defenses[id] || 0);
        if (kind === 'ability') return (p.parts.abilities[id] || 0);
        if (kind === 'energy') return (p.parts.energy && p.parts.energy[id]) || 0;
        return 0;
    },

    craftShip(shipId) {
        const profile = this.getActiveProfile();
        if (!profile || typeof economyConfig === 'undefined' || typeof shipConfigManager === 'undefined') {
            return { ok: false, reason: 'NO PROFILE' };
        }
        this.ensureEconomyDefaults(profile);
        const id = String(shipId || '');
        if (!id || id === this.getStarterShipId()) {
            return { ok: false, reason: 'INVALID' };
        }
        if (profile.ownedShipIds.indexOf(id) !== -1) {
            return { ok: false, reason: 'OWNED' };
        }
        if (this.getFreeShipSlots(profile) < 1) {
            return { ok: false, reason: 'NO SHIP SLOTS' };
        }
        const bp = profile.blueprints[id] || 0;
        if (bp < 1) return { ok: false, reason: 'NO BLUEPRINT' };
        const cfg = shipConfigManager.getConfig(id);
        const cost = this.getDiscountedCraftCost(cfg, profile);
        if (!economyConfig.canAfford(profile.resources, cost)) {
            return { ok: false, reason: 'RESOURCES' };
        }
        if (!this.spendResources(cost)) {
            return { ok: false, reason: 'RESOURCES' };
        }
        profile.blueprints[id] = bp - 1;
        if (profile.blueprints[id] <= 0) delete profile.blueprints[id];
        profile.ownedShipIds.push(id);
        this.discoverShipContents(id);
        this.save();
        return { ok: true };
    },

    rename(id, name) {
        const profile = this.getProfile(id);
        if (!profile) return null;
        const trimmed = String(name || '').trim().toUpperCase().slice(0, 16);
        if (!trimmed) return null;
        profile.name = trimmed;
        this.save();
        return profile;
    },

    delete(id) {
        const pid = String(id || '');
        const idx = this.profiles.findIndex(p => p.id === pid);
        if (idx === -1) return false;
        this.profiles.splice(idx, 1);
        if (this.activeProfileId === pid) {
            this.activeProfileId = this.profiles[0] ? this.profiles[0].id : null;
        }
        this.save();
        return true;
    },

    setActive(id) {
        const profile = this.getProfile(id);
        if (!profile) return false;
        this.activeProfileId = profile.id;
        this.save();
        if (typeof factionShipStyles !== 'undefined' && factionShipStyles.applyDocumentFactionTheme) {
            factionShipStyles.applyDocumentFactionTheme(profile.faction);
        }
        return true;
    },

    logout() {
        this.activeProfileId = null;
        this.save();
    },

    getGalaxyProgress(galaxyId) {
        const profile = this.getActiveProfile();
        if (!profile) {
            return {
                unlockedPlanetIds: [],
                clearedPlanetIds: [],
                stages: {},
                totalPlanets: 0,
                clearedCount: 0,
                unlockedCount: 0,
                label: '0/0 CLEARED'
            };
        }
        const gid = String(galaxyId || '').toLowerCase();
        const gp = this.ensureGalaxyProgress(profile, gid);
        let totalPlanets = 0;
        if (typeof planetConfigManager !== 'undefined') {
            const g = planetConfigManager.getGalaxy(gid);
            totalPlanets = (g && g.planetIds) ? g.planetIds.length : 0;
            const map = planetConfigManager.getGalaxyMap(gid);
            if (map && map.nodes && map.nodes.length) {
                totalPlanets = map.nodes.length;
            }
        }
        const clearedCount = (gp.clearedPlanetIds || []).length;
        const unlockedCount = (gp.unlockedPlanetIds || []).length;
        return {
            unlockedPlanetIds: gp.unlockedPlanetIds.slice(),
            clearedPlanetIds: gp.clearedPlanetIds.slice(),
            stages: Object.assign({}, gp.stages),
            totalPlanets: totalPlanets,
            clearedCount: clearedCount,
            unlockedCount: unlockedCount,
            label: `${clearedCount}/${totalPlanets} CLEARED`
        };
    },

    /**
     * Progress is saved under the planet's own galaxy (markStageCleared), which
     * can differ from the galaxy the map shows it in — so look in both records.
     */
    _planetProgressRecords(profile, galaxyId, pid) {
        const out = [this.ensureGalaxyProgress(profile, galaxyId)];
        const own = typeof planetConfigManager !== 'undefined' && planetConfigManager.getPlanetGalaxyId
            ? planetConfigManager.getPlanetGalaxyId(pid) : null;
        if (own && own !== galaxyId) out.push(this.ensureGalaxyProgress(profile, own));
        return out;
    },

    isPlanetUnlocked(galaxyId, planetId) {
        const profile = this.getActiveProfile();
        if (!profile) return false;
        const pid = String(planetId || '').toLowerCase();
        if (this._planetProgressRecords(profile, galaxyId, pid).some((gp) => gp.unlockedPlanetIds.indexOf(pid) !== -1)) return true;
        // A cleared neighbour along a map edge opens the way (also heals saves
        // that stored the clear under another galaxy).
        if (typeof planetConfigManager !== 'undefined' && planetConfigManager.getGalaxyNeighbors) {
            return planetConfigManager.getGalaxyNeighbors(galaxyId, pid).some((nid) => this.isPlanetCleared(galaxyId, nid));
        }
        return false;
    },

    isPlanetCleared(galaxyId, planetId) {
        const profile = this.getActiveProfile();
        if (!profile) return false;
        const pid = String(planetId || '').toLowerCase();
        return this._planetProgressRecords(profile, galaxyId, pid).some((gp) => gp.clearedPlanetIds.indexOf(pid) !== -1);
    },

    getPlanetStageState(galaxyId, planetId) {
        const profile = this.getActiveProfile();
        if (!profile) return { highestStage: 0, bossCleared: false };
        const pid = String(planetId || '').toLowerCase();
        const gp = this.ensureGalaxyProgress(profile, galaxyId);
        let st = gp.stages[pid];
        // Stage clears are saved under the planet's own galaxy id
        // (markStageCleared → getPlanetGalaxyId), which can differ from the
        // galaxy the map shows it in: read that record as well.
        const own = typeof planetConfigManager !== 'undefined' && planetConfigManager.getPlanetGalaxyId
            ? planetConfigManager.getPlanetGalaxyId(pid) : null;
        if (own && own !== galaxyId) {
            const alt = this.ensureGalaxyProgress(profile, own).stages[pid];
            if (alt && (!st || (Number(alt.highestStage) || 0) > (Number(st.highestStage) || 0) || (alt.bossCleared && !st.bossCleared))) st = alt;
        }
        return st ? Object.assign({}, st) : { highestStage: 0, bossCleared: false };
    },
});


/* --- js/core/profile-manager/get-resume-level-id.js?v=stages-2 --- */
"use strict";

// ProfileManager methods, split from profile-manager.js.
extendClass(ProfileManager, {
    /**
     * Next stage to play for a planet based on saved progress.
     * Plain planet ids (mars) resume after the highest cleared stage.
     */
    getResumeLevelId(planetId) {
        const pid = planetIdOfLevelId(planetId);
        if (!pid) return null;

        let galaxyId = null;
        if (typeof planetConfigManager !== 'undefined') {
            galaxyId = planetConfigManager.getPlanetGalaxyId(pid);
        }
        const stagesPerPlanet = typeof getPlanetStageCount === 'function' ? getPlanetStageCount(pid) : 3;
        const st = galaxyId
            ? this.getPlanetStageState(galaxyId, pid)
            : { highestStage: 0, bossCleared: false };

        if (st.bossCleared) {
            return `${pid}-1`;
        }
        const highest = Math.max(0, Math.round(Number(st.highestStage) || 0));
        if (highest >= stagesPerPlanet) {
            return `${pid}-boss`;
        }
        if (highest > 0) {
            return `${pid}-${highest + 1}`;
        }
        return `${pid}-1`;
    },

    /**
     * Start options for planet select: from stage 1, or continue at saved progress.
     * canChoose is true when mid-planet progress exists (not cleared, highestStage > 0).
     */
    getPlanetStartOptions(planetId) {
        const pid = planetIdOfLevelId(planetId);
        if (!pid) {
            return {
                canChoose: false,
                startLevelId: null,
                resumeLevelId: null,
                resumeLabel: 'STAGE 1'
            };
        }

        let galaxyId = null;
        if (typeof planetConfigManager !== 'undefined') {
            galaxyId = planetConfigManager.getPlanetGalaxyId(pid);
        }
        const stagesPerPlanet = typeof getPlanetStageCount === 'function' ? getPlanetStageCount(pid) : 3;
        const st = galaxyId
            ? this.getPlanetStageState(galaxyId, pid)
            : { highestStage: 0, bossCleared: false };
        const highest = Math.max(0, Math.round(Number(st.highestStage) || 0));
        const resumeLevelId = this.getResumeLevelId(pid) || `${pid}-1`;
        let resumeLabel = 'STAGE 1';
        if (st.bossCleared) {
            resumeLabel = 'STAGE 1';
        } else if (highest >= stagesPerPlanet) {
            resumeLabel = `BOSS ${stagesPerPlanet + 1}/${stagesPerPlanet + 1}`;
        } else if (highest > 0) {
            resumeLabel = `STAGE ${highest + 1}/${stagesPerPlanet + 1}`;
        }

        return {
            canChoose: !st.bossCleared && highest > 0,
            startLevelId: `${pid}-1`,
            resumeLevelId,
            resumeLabel
        };
    },

    markStageCleared(planetId, stageKey) {
        const profile = this.getActiveProfile();
        if (!profile) return false;
        const pid = String(planetId || '').toLowerCase();
        if (!pid) return false;

        let galaxyId = null;
        if (typeof planetConfigManager !== 'undefined') {
            galaxyId = planetConfigManager.getPlanetGalaxyId(pid);
        }
        if (!galaxyId) return false;

        const gp = this.ensureGalaxyProgress(profile, galaxyId);
        if (!gp.stages[pid]) {
            gp.stages[pid] = { highestStage: 0, bossCleared: false };
        }
        const st = gp.stages[pid];
        const key = String(stageKey || '1').toLowerCase();
        if (key === 'boss') {
            st.bossCleared = true;
            this.markPlanetCleared(pid);
            return true;
        }
        const num = parseInt(key, 10);
        if (!Number.isNaN(num) && num > (st.highestStage || 0)) {
            st.highestStage = num;
        }
        if (gp.unlockedPlanetIds.indexOf(pid) === -1) {
            gp.unlockedPlanetIds.push(pid);
        }
        this.save();
        return true;
    },

    markPlanetCleared(planetId) {
        const profile = this.getActiveProfile();
        if (!profile) return false;
        const pid = String(planetId || '').toLowerCase();
        if (!pid) return false;

        let galaxyId = null;
        if (typeof planetConfigManager !== 'undefined') {
            galaxyId = planetConfigManager.getPlanetGalaxyId(pid);
        }
        if (!galaxyId) return false;

        const gp = this.ensureGalaxyProgress(profile, galaxyId);
        if (gp.clearedPlanetIds.indexOf(pid) === -1) {
            gp.clearedPlanetIds.push(pid);
        }
        if (gp.unlockedPlanetIds.indexOf(pid) === -1) {
            gp.unlockedPlanetIds.push(pid);
        }
        if (!gp.stages[pid]) {
            gp.stages[pid] = { highestStage: 3, bossCleared: true };
        } else {
            gp.stages[pid].bossCleared = true;
        }

        // Unlock neighbors along graph edges
        if (typeof planetConfigManager !== 'undefined' && planetConfigManager.getGalaxyNeighbors) {
            const neighbors = planetConfigManager.getGalaxyNeighbors(galaxyId, pid);
            neighbors.forEach(nid => {
                if (gp.unlockedPlanetIds.indexOf(nid) === -1) {
                    gp.unlockedPlanetIds.push(nid);
                }
            });
        }

        this.discover('planets', pid);
        this.save();
        return true;
    },

    unlockPlanet(planetId) {
        const profile = this.getActiveProfile();
        if (!profile) return false;
        const pid = String(planetId || '').toLowerCase();
        if (!pid) return false;
        let galaxyId = null;
        if (typeof planetConfigManager !== 'undefined') {
            galaxyId = planetConfigManager.getPlanetGalaxyId(pid);
        }
        if (!galaxyId) return false;
        const gp = this.ensureGalaxyProgress(profile, galaxyId);
        if (gp.unlockedPlanetIds.indexOf(pid) === -1) {
            gp.unlockedPlanetIds.push(pid);
        }
        this.discover('planets', pid);
        this.save();
        return true;
    },

    lockPlanet(planetId) {
        const profile = this.getActiveProfile();
        if (!profile) return false;
        const pid = String(planetId || '').toLowerCase();
        if (!pid) return false;
        let galaxyId = null;
        if (typeof planetConfigManager !== 'undefined') {
            galaxyId = planetConfigManager.getPlanetGalaxyId(pid);
        }
        if (!galaxyId) return false;
        const gp = this.ensureGalaxyProgress(profile, galaxyId);
        const uIdx = gp.unlockedPlanetIds.indexOf(pid);
        if (uIdx !== -1) gp.unlockedPlanetIds.splice(uIdx, 1);
        const cIdx = gp.clearedPlanetIds.indexOf(pid);
        if (cIdx !== -1) gp.clearedPlanetIds.splice(cIdx, 1);
        if (gp.stages && gp.stages[pid]) delete gp.stages[pid];
        this.undiscover('planets', pid);
        this.save();
        return true;
    },

    togglePlanetVisited(planetId) {
        let galaxyId = null;
        if (typeof planetConfigManager !== 'undefined') {
            galaxyId = planetConfigManager.getPlanetGalaxyId(planetId);
        }
        if (!galaxyId) return false;
        if (this.isPlanetUnlocked(galaxyId, planetId) || this.isPlanetCleared(galaxyId, planetId)) {
            this.lockPlanet(planetId);
            return false;
        }
        this.unlockPlanet(planetId);
        return true;
    },

    unmarkPlanetCleared(planetId) {
        const profile = this.getActiveProfile();
        if (!profile) return false;
        const pid = String(planetId || '').toLowerCase();
        if (!pid) return false;
        let galaxyId = null;
        if (typeof planetConfigManager !== 'undefined') {
            galaxyId = planetConfigManager.getPlanetGalaxyId(pid);
        }
        if (!galaxyId) return false;
        const gp = this.ensureGalaxyProgress(profile, galaxyId);
        const cIdx = gp.clearedPlanetIds.indexOf(pid);
        if (cIdx !== -1) gp.clearedPlanetIds.splice(cIdx, 1);
        if (gp.stages && gp.stages[pid]) {
            gp.stages[pid].bossCleared = false;
        }
        this.save();
        return true;
    },

    togglePlanetCleared(planetId) {
        let galaxyId = null;
        if (typeof planetConfigManager !== 'undefined') {
            galaxyId = planetConfigManager.getPlanetGalaxyId(planetId);
        }
        if (!galaxyId) return false;
        if (this.isPlanetCleared(galaxyId, planetId)) {
            this.unmarkPlanetCleared(planetId);
            return false;
        }
        this.markPlanetCleared(planetId);
        return true;
    },
});


/* --- js/core/profile-manager/style-unlocks.js?v=sell-1 --- */
"use strict";

// ProfileManager methods: cosmetic style unlocks (hull areas, module skins,
// connections). The first STYLE_FREE_COUNT styles of every group are free;
// the rest are bought in the shop's STYLES category.
const STYLE_FREE_COUNT = 3;

extendClass(ProfileManager, {
    /** Style groups in shop order: { id, label, icon }. */
    getStyleGroups() {
        return [
            { id: 'hull:front', label: 'NOSE', icon: 'hsShip' },
            { id: 'hull:center', label: 'CORE', icon: 'hsShip' },
            { id: 'hull:back', label: 'AFT', icon: 'hsShip' },
            { id: 'hull:wing', label: 'WINGS', icon: 'hsShip' },
            { id: 'skin:weapon', label: 'WEAPON', icon: 'statWeapon' },
            { id: 'skin:defense', label: 'DEFENSE', icon: 'statArmor' },
            { id: 'skin:ability', label: 'ABILITY', icon: 'statAbilities' },
            { id: 'skin:energy', label: 'ENERGY', icon: 'ability_energy_shield' },
            { id: 'joint', label: 'CONNECTION', icon: 'hsCraft' }
        ];
    },

    /** Hull segment ids (wingLeft / wingRight / wing) → style group id. */
    hullStyleGroup(segmentId) {
        const seg = String(segmentId || '');
        return 'hull:' + (seg.indexOf('wing') === 0 ? 'wing' : seg);
    },

    /** Ordered styles of a group: [{ id, label }]. Hull ids are indices. */
    getStyleGroupEntries(groupId) {
        const group = String(groupId || '');
        if (group.indexOf('hull:') === 0) {
            const loader = (typeof graphicsManager !== 'undefined') ? graphicsManager.shipAssetLoader : null;
            if (!loader) return [];
            const seg = group.slice(5);
            const labels = seg === 'wing'
                ? loader.wingShapeVariants.map((v) => v.label)
                : loader.bodyShapeVariantLabels(seg);
            return labels.map((label, index) => ({ id: String(index), label: label }));
        }
        if (group.indexOf('skin:') === 0) {
            if (typeof shipLoadoutManager === 'undefined') return [];
            return shipLoadoutManager.getAvailableSkins(group.slice(5));
        }
        if (group === 'joint') {
            return ['strut', 'plate', 'double', 'hinge'].map((id) => ({ id: id, label: id.toUpperCase() }));
        }
        return [];
    },

    /** Credits price of the style at `index` in its group (0 when free). */
    getStyleCost(index) {
        const tier = index - STYLE_FREE_COUNT + 1;
        if (tier <= 0) return null;
        return { credits: 100 + (tier - 1) * 75 };
    },

    isStyleUnlocked(groupId, styleId, profile) {
        const entries = this.getStyleGroupEntries(groupId);
        const index = entries.findIndex((e) => e.id === String(styleId));
        if (index === -1) return false;
        if (index < STYLE_FREE_COUNT) return true;
        const p = profile || this.getActiveProfile();
        const owned = p && p.unlockedStyles && p.unlockedStyles[groupId];
        return Array.isArray(owned) && owned.indexOf(String(styleId)) !== -1;
    },

    canPurchaseStyle(groupId, styleId, profile) {
        const p = profile || this.getActiveProfile();
        if (!p || typeof economyConfig === 'undefined') return { ok: false, reason: 'NO PROFILE' };
        const entries = this.getStyleGroupEntries(groupId);
        const index = entries.findIndex((e) => e.id === String(styleId));
        if (index === -1) return { ok: false, reason: 'INVALID' };
        if (this.isStyleUnlocked(groupId, styleId, p)) return { ok: false, reason: 'OWNED' };
        const cost = this.getStyleCost(index);
        // Style prices are credits, which live on the profile, not in resources.
        if ((Number(p.credits) || 0) < cost.credits) {
            return { ok: false, reason: 'RESOURCES', cost: cost };
        }
        return { ok: true, cost: cost };
    },

    purchaseStyle(groupId, styleId) {
        const profile = this.getActiveProfile();
        const check = this.canPurchaseStyle(groupId, styleId, profile);
        if (!check.ok) return check;
        if (!this.spendCredits(check.cost.credits)) return { ok: false, reason: 'RESOURCES', cost: check.cost };
        if (!profile.unlockedStyles || typeof profile.unlockedStyles !== 'object') profile.unlockedStyles = {};
        if (!Array.isArray(profile.unlockedStyles[groupId])) profile.unlockedStyles[groupId] = [];
        profile.unlockedStyles[groupId].push(String(styleId));
        this.save();
        return { ok: true };
    },
});


/* --- js/core/profile-manager/trading-posts.js?v=pull-1 --- */
"use strict";

// ProfileManager methods: trading posts — independent space-station shops
// with their own spot on the galaxy map. Each post is seeded from a planet
// (its "anchor") but placed in free space nearby. A post opens once its
// anchor planet is cleared and stocks parts from the galaxy's faction mixed with other
// factions. Parts always render in the player's own faction colours, so
// mixed loadouts stay visually consistent.

const TRADING_POST_NAMES = [
    'RUSTHAVEN', 'KESTREL DOCK', 'MERIDIAN EXCHANGE', 'SALVAGE RING', 'NOVA BAZAAR',
    'IRON LANTERN', 'DRIFTWORKS', 'HALCYON DEPOT', 'CINDER MARKET', 'VANTAGE POST'
];

// Shop categories a trader can specialise in. Every post also trades
// resources; docking at a post unlocks its trader, and from then on its
// categories are sold at the home station too.
const TRADING_POST_CATEGORIES = ['parts', 'ships', 'blueprints', 'portals', 'styles'];

// Ability ids sold anywhere (same set as the home station shop).
const TRADING_POST_ABILITY_IDS = ['charge_shot', 'overcharge_core', 'charge_drive', 'drive_charge_dampen', 'spike_drive'];

extendClass(ProfileManager, {
    tradingPostHash(text) {
        let h = 2166136261;
        const s = String(text || '');
        for (let i = 0; i < s.length; i++) {
            h ^= s.charCodeAt(i);
            h = Math.imul(h, 16777619);
        }
        return h >>> 0;
    },

    /**
     * Trading posts of a galaxy, derived from its map so every galaxy
     * (including explored ones) gets posts without extra config: roughly one
     * per three planets, never on the start planet, at least one per galaxy.
     */
    getTradingPosts(galaxyId) {
        if (typeof planetConfigManager === 'undefined') return [];
        const gid = String(galaxyId || '').toLowerCase();
        const map = planetConfigManager.getGalaxyMap(gid) || {};
        const nodes = (map.nodes || []).filter((n) => n.planetId !== map.startPlanetId);
        if (!nodes.length) return [];
        let picked = nodes.filter((n) => this.tradingPostHash(gid + '|post|' + n.planetId) % 3 === 0);
        if (!picked.length) picked = [nodes[this.tradingPostHash(gid + '|post') % nodes.length]];
        const placed = [];
        const byId = {};
        (map.nodes || []).forEach((node) => { byId[node.planetId] = node; });
        return picked.map((n) => {
            const id = gid + ':' + n.planetId;
            const h = this.tradingPostHash(id);
            // About half the posts are deep-space stations between two linked
            // planets instead of orbiting one; they open from either side.
            const links = (map.edges || [])
                .filter((e) => e[0] === n.planetId || e[1] === n.planetId)
                .map((e) => byId[e[0] === n.planetId ? e[1] : e[0]])
                .filter(Boolean);
            // Every station belongs to exactly one planet (no deep-space
            // stations between two planets) and sits close to it.
            const deep = false && links.length > 0 && (h >>> 3) % 2 === 0;
            let pos;
            let anchors = [n.planetId];
            if (deep) {
                const other = links[(h >>> 5) % links.length];
                pos = this.placeDeepSpacePost(n, other, map.nodes || [], placed, h);
                anchors = [n.planetId, other.planetId];
            } else {
                pos = this.placeTradingPost(map.nodes || [], n, placed, h, map.edges || []);
            }
            placed.push(pos);
            const faction = this.getTradingPostBuilder(id, gid, n.planetId);
            return {
                id: id,
                galaxyId: gid,
                planetId: n.planetId,
                anchors: anchors,
                deepSpace: deep,
                x: pos.x,
                y: pos.y,
                name: TRADING_POST_NAMES[h % TRADING_POST_NAMES.length],
                faction: faction,
                categories: this.getTradingPostCategories(id)
            };
        });
    },

    /**
     * The faction that built a post: its anchor planet's own faction when first
     * seen, remembered in the profile — so a post keeps its builder's look even
     * after its planet is conquered or the galaxy changes hands.
     */
    getTradingPostBuilder(postId, galaxyId, planetId) {
        const profile = this.getActiveProfile ? this.getActiveProfile() : null;
        if (profile && profile.stationBuilders && profile.stationBuilders[postId]) return profile.stationBuilders[postId];
        let fid = null;
        try {
            const native = planetConfigManager.getPlanetFactions ? planetConfigManager.getPlanetFactions(planetId) : [];
            fid = native && native[0];
            if (!fid && this.getFactionHoldings) {
                const hold = this.getFactionHoldings(galaxyId);
                fid = hold && hold.ruler;
            }
            if (!fid && planetConfigManager.getGalaxyFactionIds) fid = (planetConfigManager.getGalaxyFactionIds(galaxyId) || [])[0];
        } catch (e) { /* ignore */ }
        fid = fid || 'terran';
        if (profile) {
            if (!profile.stationBuilders) profile.stationBuilders = {};
            profile.stationBuilders[postId] = fid;
            if (this.save) this.save();
        }
        return fid;
    },

    /** Faction that built a galaxy's border stations: the ruler when first seen, kept afterwards. */
    getBorderBuilder(galaxyId) {
        const gid = String(galaxyId || '').toLowerCase();
        const key = 'border|' + gid;
        const profile = this.getActiveProfile ? this.getActiveProfile() : null;
        if (profile && profile.stationBuilders && profile.stationBuilders[key]) return profile.stationBuilders[key];
        const hold = this.getFactionHoldings ? this.getFactionHoldings(gid) : null;
        const fid = hold && hold.ruler;
        if (fid && profile) {
            if (!profile.stationBuilders) profile.stationBuilders = {};
            profile.stationBuilders[key] = fid;
            if (this.save) this.save();
        }
        return fid || null;
    },

    /**
     * Deep-space spot off the lane between two linked planets: the lane's
     * midpoint pushed sideways, on whichever side is further from everything.
     */
    placeDeepSpacePost(a, b, nodes, placed, seed) {
        const SX = 544;
        const SY = 224;
        const mx = (a.x + b.x) / 2;
        const my = (a.y + b.y) / 2;
        const dx = (b.x - a.x) * SX;
        const dy = (b.y - a.y) * SY;
        const len = Math.max(1, Math.hypot(dx, dy));
        const off = 34 + (seed % 12);
        const others = nodes.map((o) => ({ x: o.x, y: o.y })).concat(placed);
        let best = { x: mx, y: my };
        let bestScore = -Infinity;
        [1, -1].forEach((side) => {
            const x = Math.min(1, Math.max(0, mx + (-dy / len) * off * side / SX));
            const y = Math.min(1, Math.max(0, my + (dx / len) * off * side / SY));
            let score = Infinity;
            others.forEach((o) => {
                score = Math.min(score, Math.hypot((o.x - x) * SX, (o.y - y) * SY));
            });
            if (score > bestScore) {
                bestScore = score;
                best = { x: x, y: y };
            }
        });
        return best;
    },

    /**
     * Free map spot near the anchor planet: tries seeded angles around it and
     * keeps the one furthest from every planet and already placed post.
     * Distances are measured in map pixels (map area is ~544x224).
     */
    placeTradingPost(nodes, anchor, placed, seed, edges) {
        const SX = 544;
        const SY = 224;
        const others = nodes.map((o) => ({ x: o.x, y: o.y })).concat(placed);
        const byId = {};
        nodes.forEach((n) => { byId[n.planetId] = n; });
        // Lane segments in map pixels: a station must never sit on one.
        const lanes = (edges || []).map((e) => [byId[e[0]], byId[e[1]]])
            .filter((pr) => pr[0] && pr[1])
            .map((pr) => [pr[0].x * SX, pr[0].y * SY, pr[1].x * SX, pr[1].y * SY]);
        const segDist = (px, py, l) => {
            const dx = l[2] - l[0], dy = l[3] - l[1];
            const len2 = dx * dx + dy * dy || 1;
            const t = Math.max(0, Math.min(1, ((px - l[0]) * dx + (py - l[1]) * dy) / len2));
            return Math.hypot(px - (l[0] + t * dx), py - (l[1] + t * dy));
        };
        let best = null;
        let bestScore = -Infinity;
        // Several rings around the planet; the first spot clear of every lane
        // (and of other bodies) wins, else the one with the most clearance.
        // Rings hug the planet: its drawn radius (map.js sizes planets 32..92 units
        // across from the id) plus the (small) station and a gap, in these map pixels.
        const idSum = String(anchor.planetId || '').split('').reduce((sum, ch) => sum + ch.charCodeAt(0), 0);
        const planetR = (32 + (idSum % 7) * 10) / 4;
        [planetR + 9, planetR + 14, planetR + 20].forEach((radius) => {
            for (let i = 0; i < 24; i++) {
                const a = ((seed % 360) + i * 15) * Math.PI / 180;
                const x = Math.min(1, Math.max(0, anchor.x + Math.cos(a) * radius / SX));
                const y = Math.min(1, Math.max(0, anchor.y + Math.sin(a) * radius / SY));
                let bodies = Infinity;
                others.forEach((o) => {
                    bodies = Math.min(bodies, Math.hypot((o.x - x) * SX, (o.y - y) * SY));
                });
                let lane = Infinity;
                lanes.forEach((l) => { lane = Math.min(lane, segDist(x * SX, y * SY, l)); });
                // Lane clearance counts double; staying near the anchor is a small bonus.
                const score = Math.min(bodies, lane * 2, 26) - radius * 0.3;
                if (score > bestScore) {
                    bestScore = score;
                    best = { x: x, y: y };
                }
            }
        });
        return best || { x: anchor.x, y: anchor.y };
    },

    /** Seeded specialty: 1–2 categories plus resources, e.g. ['resources', 'parts', 'styles']. */
    getTradingPostCategories(postId) {
        const h = this.tradingPostHash(String(postId) + '|cats');
        const all = TRADING_POST_CATEGORIES.slice();
        const first = all.splice(h % all.length, 1)[0];
        const cats = [first];
        if ((h >>> 7) % 2 === 0) cats.push(all[(h >>> 9) % all.length]);
        return ['resources'].concat(cats);
    },

    /** Remember a trader once the player has docked there. */
    unlockTrader(postId, profile) {
        const p = profile || this.getActiveProfile();
        if (!p || !postId) return false;
        if (!Array.isArray(p.unlockedTraders)) p.unlockedTraders = [];
        if (p.unlockedTraders.indexOf(postId) !== -1) return false;
        p.unlockedTraders.push(postId);
        if (this.save) this.save();
        return true;
    },

    /** Shop categories open at the home station: resources + every unlocked trader's. */
    getUnlockedShopCategories(profile) {
        const p = profile || this.getActiveProfile();
        const out = ['resources'];
        ((p && p.unlockedTraders) || []).forEach((postId) => {
            this.getTradingPostCategories(postId).forEach((c) => {
                if (out.indexOf(c) === -1) out.push(c);
            });
        });
        return out;
    },

    getTradingPost(postId) {
        const gid = String(postId || '').split(':')[0];
        return this.getTradingPosts(gid).find((p) => p.id === postId) || null;
    },

    /** A post opens once the ship has reached one of its anchor planets. */
    isTradingPostUnlocked(post, profile) {
        if (!post) return false;
        if (typeof startScreenManager !== 'undefined' && startScreenManager.devMode) return true;
        return (post.anchors || [post.planetId]).some((pid) =>
            (this.hasVisitedPlanet && this.hasVisitedPlanet(post.galaxyId, pid, profile))
            || this.isPlanetCleared(post.galaxyId, pid, profile));
    },

    /** Planet names a locked post waits on, e.g. "SATURN / PLUTO". */
    getTradingPostUnlockLabel(post) {
        if (!post || typeof planetConfigManager === 'undefined') return '';
        return (post.anchors || [post.planetId]).map((pid) => {
            const cfg = planetConfigManager.getConfig(pid);
            return String((cfg && cfg.name) || pid).toUpperCase();
        }).join(' / ');
    },

    /** Every part a trading post could sell: [{ kind, id, item, faction }]. */
    getTradingPostPool() {
        const pool = [];
        const add = (kind, id, item) => {
            if (!item) return;
            pool.push({ kind: kind, id: id, item: item, faction: String(item.faction || '').toLowerCase() });
        };
        if (typeof weaponConfigManager !== 'undefined') {
            weaponConfigManager.getIds().forEach((id) => add('weapon', id, weaponConfigManager.getWeapon(id)));
        }
        if (typeof abilityConfigManager !== 'undefined') {
            const byCluster = abilityConfigManager.getIdsByCluster();
            (byCluster.defense || []).forEach((id) => add('defense', id, abilityConfigManager.getAbility(id)));
            TRADING_POST_ABILITY_IDS.forEach((id) => add('ability', id, abilityConfigManager.getAbility(id)));
            add('energy', 'energy_core', abilityConfigManager.getAbility('energy_core'));
        }
        return pool;
    },

    /**
     * A post's fixed stock: the galaxy faction's parts plus a seeded pick of
     * other factions' and neutral parts, so each post sells a different mix.
     */
    getTradingPostStock(post) {
        if (!post) return [];
        const home = (typeof planetConfigManager !== 'undefined' && planetConfigManager.getGalaxyFaction)
            ? String(planetConfigManager.getGalaxyFaction(post.galaxyId) || '').toLowerCase()
            : '';
        const seed = this.tradingPostHash(post.id + '|stock');
        const rank = (entry) => this.tradingPostHash(seed + '|' + entry.kind + ':' + entry.id);
        const pool = this.getTradingPostPool().sort((a, b) => rank(a) - rank(b));
        // Every faction active in the galaxy counts as local, so posts in
        // contested galaxies sell a wider mix of the warring factions.
        const present = (typeof planetConfigManager !== 'undefined' && planetConfigManager.getGalaxyFactionIds)
            ? planetConfigManager.getGalaxyFactionIds(post.galaxyId)
            : [home];
        const isLocal = (e) => e.faction && present.indexOf(e.faction) !== -1;
        const local = pool.filter(isLocal).slice(0, present.length > 1 ? 6 : 4);
        const foreign = pool.filter((e) => e.faction && !isLocal(e)).slice(0, present.length > 1 ? 3 : 4);
        const neutral = pool.filter((e) => !e.faction).slice(0, 3);
        return local.concat(foreign, neutral);
    },

    /**
     * Economic profile of a post for the map card:
     * { stockValue, wealth, sells: { weapon: n, ... }, seeks: [resourceId] }.
     * Wealth is graded on the credit value of the stock; each post seeks two
     * materials, seeded from its id.
     */
    getTradingPostEconomy(post) {
        const stock = this.getTradingPostStock(post);
        const sells = {};
        let stockValue = 0;
        stock.forEach((e) => {
            sells[e.kind] = (sells[e.kind] || 0) + 1;
            if (typeof economyConfig === 'undefined') return;
            const cost = economyConfig.getPartCost(e.kind, e.item) || {};
            stockValue += Number(cost.credits) || (economyConfig.materialCostToCredits
                ? economyConfig.materialCostToCredits(cost) : 0);
        });
        const wealth = stockValue >= 6000 ? 'RICH' : (stockValue >= 5000 ? 'PROSPEROUS' : 'MODEST');
        const materials = (typeof economyConfig !== 'undefined' && economyConfig.resourceIds)
            ? economyConfig.resourceIds.slice()
            : ['scrap', 'ore', 'crystal', 'voltex'];
        const h = this.tradingPostHash((post && post.id) + '|seeks');
        const first = materials[h % materials.length];
        const rest = materials.filter((m) => m !== first);
        return {
            stockValue: Math.round(stockValue),
            wealth: wealth,
            sells: sells,
            seeks: [first, rest[(h >>> 4) % rest.length]]
        };
    },

    isPartInTradingPost(postId, kind, partId) {
        const post = this.getTradingPost(postId);
        if (!post || !this.isTradingPostUnlocked(post)) return false;
        return this.getTradingPostStock(post).some((e) => e.kind === kind && e.id === partId);
    },
});


/* --- js/core/profile-manager/missions.js?v=missions-2 --- */
"use strict";

// ProfileManager methods: the hangar mission board. Missions are drawn from
// the planets of the ship's current galaxy — LIBERATE an unlocked planet that
// isn't cleared yet, or PATROL a cleared one again for half the bounty. One
// mission can be active; clearing any stage on its planet pays the bounty
// (see beginVictoryLootPhase) and rotates the board's offers.

const MISSION_BOUNTY_BY_DIFFICULTY = { EASY: 60, NORMAL: 110, HARD: 180, EXPERT: 260, NIGHTMARE: 360 };

extendClass(ProfileManager, {
    missionHash(text) {
        let h = 2166136261;
        const s = String(text || '');
        for (let i = 0; i < s.length; i++) {
            h ^= s.charCodeAt(i);
            h = Math.imul(h, 16777619);
        }
        return h >>> 0;
    },

    /** Bounty for a planet: credits by difficulty plus one seeded material. */
    getMissionReward(galaxyId, planetId, patrol, profile) {
        const p = profile || this.getActiveProfile();
        const cfg = typeof planetConfigManager !== 'undefined' ? planetConfigManager.getConfig(planetId) : null;
        const diff = String((cfg && cfg.difficulty) || 'NORMAL').toUpperCase();
        const base = MISSION_BOUNTY_BY_DIFFICULTY[diff] || 110;
        const seed = this.missionHash(galaxyId + '|' + planetId + '|' + ((p && p.missionSeed) || 0));
        const mats = (typeof economyConfig !== 'undefined' && economyConfig.resourceIds)
            ? economyConfig.resourceIds.slice() : ['scrap', 'ore', 'crystal', 'voltex'];
        const mat = mats[seed % mats.length];
        const scale = patrol ? 0.5 : 1;
        // ±20% so offers on the board differ a little each rotation.
        const jitter = 0.8 + ((seed >>> 8) % 41) / 100;
        const reward = { credits: Math.round(base * scale * jitter / 5) * 5 };
        reward[mat] = Math.max(2, Math.round((base / 12) * scale * jitter));
        return { difficulty: diff, reward: reward };
    },

    /** Mission entries for the current galaxy, available first. */
    getMissionBoard(profile) {
        const p = profile || this.getActiveProfile();
        if (!p || typeof planetConfigManager === 'undefined') return [];
        const gid = this.getCurrentGalaxyId(p);
        const map = planetConfigManager.getGalaxyMap(gid) || {};
        const active = p.activeMission || null;
        const rank = { available: 0, patrol: 1, locked: 2 };
        return (map.nodes || [])
            .filter((n) => !(planetConfigManager.isEncounterPlanet && planetConfigManager.isEncounterPlanet(n.planetId)))
            .map((n) => {
                const pid = String(n.planetId).toLowerCase();
                const cfg = planetConfigManager.getConfig(pid) || {};
                const cleared = this.isPlanetCleared(gid, pid);
                const unlocked = cleared || this.isPlanetUnlocked(gid, pid);
                const status = cleared ? 'patrol' : (unlocked ? 'available' : 'locked');
                const stage = this.getPlanetStageState ? this.getPlanetStageState(gid, pid) : { highestStage: 0 };
                const rw = this.getMissionReward(gid, pid, status === 'patrol', p);
                return {
                    galaxyId: gid,
                    planetId: pid,
                    name: String(cfg.name || pid).toUpperCase(),
                    type: status === 'patrol' ? 'PATROL' : 'LIBERATE',
                    status: status,
                    difficulty: rw.difficulty,
                    stagesDone: Number(stage.highestStage) || 0,
                    stagesTotal: typeof getPlanetStageCount === 'function' ? getPlanetStageCount(pid) + 1 : 4,
                    reward: rw.reward,
                    active: !!(active && active.planetId === pid && active.galaxyId === gid)
                };
            })
            .sort((a, b) => (b.active - a.active) || (rank[a.status] - rank[b.status]));
    },

    acceptMission(planetId, profile) {
        const p = profile || this.getActiveProfile();
        if (!p) return null;
        const entry = this.getMissionBoard(p).find((m) => m.planetId === String(planetId).toLowerCase());
        if (!entry || entry.status === 'locked') return null;
        p.activeMission = { galaxyId: entry.galaxyId, planetId: entry.planetId, type: entry.type, reward: entry.reward };
        this.save();
        return p.activeMission;
    },

    abandonMission(profile) {
        const p = profile || this.getActiveProfile();
        if (!p) return;
        p.activeMission = null;
        this.save();
    },

    /**
     * A stage on planetId was cleared: pay the active mission's bounty if it
     * targets that planet. Returns the paid mission, or null.
     */
    completeMissionFor(planetId, profile) {
        const p = profile || this.getActiveProfile();
        const m = p && p.activeMission;
        if (!m || m.planetId !== String(planetId || '').toLowerCase()) return null;
        if (!p.resources || typeof p.resources !== 'object') p.resources = {};
        // Credits are their own wallet (profile.credits); materials go to
        // the station stores.
        Object.keys(m.reward || {}).forEach((id) => {
            const n = Number(m.reward[id]) || 0;
            if (id.indexOf('part:weapon:') === 0) {
                const wid = id.slice(12);
                if (!p.parts || typeof p.parts !== 'object') p.parts = {};
                if (!p.parts.weapons || typeof p.parts.weapons !== 'object') p.parts.weapons = {};
                p.parts.weapons[wid] = (Number(p.parts.weapons[wid]) || 0) + Math.max(1, n);
            } else if (id === 'credits') p.credits = Math.max(0, Math.round(Number(p.credits) || 0) + n);
            else p.resources[id] = (Number(p.resources[id]) || 0) + n;
        });
        p.activeMission = null;
        p.missionSeed = (Number(p.missionSeed) || 0) + 1;
        p.missionsCompleted = (Number(p.missionsCompleted) || 0) + 1;
        this.save();
        return m;
    },
});


/* --- js/core/profile-manager/ship-location.js?v=reach-1 --- */
"use strict";

// ProfileManager methods: where the player's ship sits on each galaxy map.
// A location is { kind: 'planet' | 'post', id }. Missions start and trading
// posts open only at the current location — the ship must fly there first.

extendClass(ProfileManager, {
    getShipLocation(galaxyId, profile) {
        const p = profile || this.getActiveProfile();
        const gid = String(galaxyId || '').toLowerCase();
        const stored = p && p.shipLocations && p.shipLocations[gid];
        if (stored && stored.kind && stored.id) return stored;
        const map = (typeof planetConfigManager !== 'undefined') ? planetConfigManager.getGalaxyMap(gid) : null;
        const startId = map && map.startPlanetId;
        return startId ? { kind: 'planet', id: startId } : null;
    },

    setShipLocation(galaxyId, kind, id) {
        const p = this.getActiveProfile();
        if (!p) return;
        if (!p.shipLocations) p.shipLocations = {};
        const gid = String(galaxyId || '').toLowerCase();
        p.shipLocations[gid] = { kind: kind, id: id };
        if (kind === 'planet') this.markPlanetVisited(gid, id, p);
        this.save();
    },

    /** Planets the ship has flown to per galaxy (opens nearby trading posts). */
    markPlanetVisited(galaxyId, planetId, profile) {
        const p = profile || this.getActiveProfile();
        if (!p || !planetId) return;
        if (!p.visitedPlanets) p.visitedPlanets = {};
        const gid = String(galaxyId || '').toLowerCase();
        const list = p.visitedPlanets[gid] || (p.visitedPlanets[gid] = []);
        if (list.indexOf(planetId) === -1) list.push(planetId);
    },

    hasVisitedPlanet(galaxyId, planetId, profile) {
        const p = profile || this.getActiveProfile();
        if (!p) return false;
        const gid = String(galaxyId || '').toLowerCase();
        const list = p.visitedPlanets && p.visitedPlanets[gid];
        if (list && list.indexOf(planetId) !== -1) return true;
        // The ship's current (or default start) spot counts as reached.
        const loc = this.getShipLocation(gid, p);
        return !!(loc && loc.kind === 'planet' && loc.id === planetId);
    },

    isShipAt(galaxyId, kind, id) {
        const loc = this.getShipLocation(galaxyId);
        return !!(loc && loc.kind === kind && loc.id === id);
    },
});


/* --- js/core/profile-manager/sell-items.js?v=sell-1 --- */
"use strict";

// ProfileManager methods: selling ships, unlearned blueprints, parts and
// unlocked styles back to the shop for credits.
const SELL_RATE = 0.5;

extendClass(ProfileManager, {
    /** Credits paid out for an item that was bought for `cost`. */
    getSellValue(cost) {
        if (!cost) return 0;
        const credits = Number(cost.credits) || 0;
        const full = credits > 0
            ? credits
            : ((typeof economyConfig !== 'undefined' && economyConfig.materialCostToCredits)
                ? economyConfig.materialCostToCredits(cost)
                : 0);
        return Math.max(1, Math.floor(full * SELL_RATE));
    },

    /** Why a ship cannot be sold ('' when it can). */
    getShipSellBlock(shipId, profile) {
        const p = profile || this.getActiveProfile();
        if (!p) return 'NO PROFILE';
        const id = String(shipId || '');
        if (p.ownedShipIds.indexOf(id) === -1) return 'NOT OWNED';
        if (id === this.getStarterShipId()) return 'STARTER SHIP';
        if (this.getActiveShipId && this.getActiveShipId() === id) return 'ACTIVE SHIP';
        return '';
    },

    getShipSellValue(shipId) {
        if (typeof economyConfig === 'undefined' || typeof shipConfigManager === 'undefined') return 0;
        return this.getSellValue(economyConfig.getShopCost(shipConfigManager.getConfig(shipId)));
    },

    sellShip(shipId) {
        const profile = this.getActiveProfile();
        const block = this.getShipSellBlock(shipId, profile);
        if (block) return { ok: false, reason: block };
        const credits = this.getShipSellValue(shipId);
        profile.ownedShipIds = profile.ownedShipIds.filter((id) => id !== shipId);
        this.addCredits(credits, true);
        this.save();
        return { ok: true, credits: credits };
    },

    getBlueprintSellValue(shipId) {
        if (typeof economyConfig === 'undefined' || typeof shipConfigManager === 'undefined') return 0;
        return this.getSellValue(economyConfig.getBlueprintCost(shipConfigManager.getConfig(shipId)));
    },

    /** Sells one station blueprint that has not been crafted into a ship. */
    sellBlueprint(shipId) {
        const profile = this.getActiveProfile();
        if (!profile) return { ok: false, reason: 'NO PROFILE' };
        this.ensureEconomyDefaults(profile);
        const id = String(shipId || '');
        if (!((profile.blueprints[id] || 0) > 0)) return { ok: false, reason: 'NONE LEFT' };
        const credits = this.getBlueprintSellValue(id);
        profile.blueprints[id] -= 1;
        if (profile.blueprints[id] <= 0) delete profile.blueprints[id];
        this.addCredits(credits, true);
        this.save();
        return { ok: true, credits: credits };
    },

    getPartItem(kind, partId) {
        if (kind === 'weapon') {
            return typeof weaponConfigManager !== 'undefined' ? weaponConfigManager.getWeapon(partId) : null;
        }
        return typeof abilityConfigManager !== 'undefined' ? abilityConfigManager.getAbility(partId) : null;
    },

    getPartSellValue(kind, partId) {
        if (typeof economyConfig === 'undefined') return 0;
        const item = this.getPartItem(kind, partId);
        return item ? this.getSellValue(economyConfig.getPartCost(kind, item)) : 0;
    },

    /** Sells one stored part. Equipping depends on discovery, not the count. */
    sellPart(kind, partId) {
        const profile = this.getActiveProfile();
        if (!profile) return { ok: false, reason: 'NO PROFILE' };
        this.ensureEconomyDefaults(profile);
        const bag = kind === 'weapon' ? profile.parts.weapons
            : (kind === 'defense' ? profile.parts.defenses
                : (kind === 'energy' ? profile.parts.energy : profile.parts.abilities));
        const id = String(partId || '');
        if (!bag || !((bag[id] || 0) > 0)) return { ok: false, reason: 'NONE LEFT' };
        const credits = this.getPartSellValue(kind, id);
        bag[id] -= 1;
        if (bag[id] <= 0) delete bag[id];
        this.addCredits(credits, true);
        this.save();
        return { ok: true, credits: credits };
    },

    /** Bought (not starter) styles of a group the profile owns. */
    getSellableStyles(groupId, profile) {
        const p = profile || this.getActiveProfile();
        const owned = (p && p.unlockedStyles && p.unlockedStyles[groupId]) || [];
        return this.getStyleGroupEntries(groupId)
            .map((style, index) => ({ style: style, index: index }))
            .filter((e) => owned.indexOf(e.style.id) !== -1 && this.getStyleCost(e.index));
    },

    sellStyle(groupId, styleId) {
        const profile = this.getActiveProfile();
        if (!profile) return { ok: false, reason: 'NO PROFILE' };
        const entry = this.getSellableStyles(groupId, profile).find((e) => e.style.id === String(styleId));
        if (!entry) return { ok: false, reason: 'NOT OWNED' };
        const credits = this.getSellValue(this.getStyleCost(entry.index));
        profile.unlockedStyles[groupId] = profile.unlockedStyles[groupId].filter((id) => id !== String(styleId));
        this.addCredits(credits, true);
        this.save();
        return { ok: true, credits: credits };
    },
});


/* --- js/core/profile-manager/ship-areas.js?v=areas-1 --- */
"use strict";

// ProfileManager: per-ship hull area levels (see ship-loadout/ship-areas.js).
// Stored as profile.shipUpgrades[shipId].areaLevels = { front, center, back, wing }.
extendClass(ProfileManager, {
    getShipAreaLevels(shipId, profile) {
        const p = profile || this.getActiveProfile();
        const out = { front: 0, center: 0, back: 0, wing: 0 };
        if (!p) return out;
        this.ensureEconomyDefaults(p);
        const id = String(shipId || '');
        const entry = p.shipUpgrades && p.shipUpgrades[id];
        if (!entry) return out;
        if (!entry.areaLevels) {
            entry.areaLevels = this.migrateFrameLevelToAreas(entry.frameLevel);
        }
        const max = this.maxShipAreaLevel();
        Object.keys(out).forEach((k) => {
            out[k] = Math.max(0, Math.min(max, Math.round(Number(entry.areaLevels[k]) || 0)));
        });
        return out;
    },

    maxShipAreaLevel() {
        return (typeof shipLoadoutManager !== 'undefined' && shipLoadoutManager.getMaxAreaLevel)
            ? shipLoadoutManager.getMaxAreaLevel() : 2;
    },

    /**
     * Old frame levels added one slot per level (weapons → defenses →
     * abilities). Hand the same number of levels out to the matching areas
     * so an upgraded ship keeps roughly the slots it had.
     */
    migrateFrameLevelToAreas(frameLevel) {
        const levels = { front: 0, center: 0, back: 0, wing: 0 };
        const order = ['wing', 'center', 'back', 'front'];
        const max = this.maxShipAreaLevel();
        let left = Math.max(0, Math.round(Number(frameLevel) || 0));
        let i = 0;
        while (left > 0 && order.some((a) => levels[a] < max)) {
            const a = order[i % order.length];
            if (levels[a] < max) {
                levels[a] += 1;
                left -= 1;
            }
            i += 1;
        }
        return levels;
    },

    canPurchaseShipAreaUpgrade(shipId, areaId, profile) {
        const p = profile || this.getActiveProfile();
        if (!p || typeof economyConfig === 'undefined') {
            return { ok: false, reason: 'NO PROFILE' };
        }
        this.ensureEconomyDefaults(p);
        const id = String(shipId || '');
        if (!this.ownsShip(id, p)) return { ok: false, reason: 'NOT OWNED' };
        const level = this.getShipAreaLevels(id, p)[areaId];
        if (level == null) return { ok: false, reason: 'INVALID' };
        if (level >= this.maxShipAreaLevel()) return { ok: false, reason: 'MAX LEVEL' };
        const cost = economyConfig.getShipAreaUpgradeCost(areaId, level + 1);
        if (!cost) return { ok: false, reason: 'INVALID' };
        if (!economyConfig.canAfford(p.resources, cost)) {
            return { ok: false, reason: 'RESOURCES', cost: cost, nextLevel: level + 1 };
        }
        return { ok: true, cost: cost, nextLevel: level + 1 };
    },

    purchaseShipAreaUpgrade(shipId, areaId) {
        const profile = this.getActiveProfile();
        if (!profile || typeof economyConfig === 'undefined') {
            return { ok: false, reason: 'NO PROFILE' };
        }
        const id = String(shipId || '');
        const check = this.canPurchaseShipAreaUpgrade(id, areaId, profile);
        if (!check.ok) return check;
        if (!this.spendResources(check.cost)) {
            return { ok: false, reason: 'RESOURCES' };
        }
        if (!profile.shipUpgrades[id]) profile.shipUpgrades[id] = { frameLevel: 0 };
        const entry = profile.shipUpgrades[id];
        if (!entry.areaLevels) entry.areaLevels = this.migrateFrameLevelToAreas(entry.frameLevel);
        entry.areaLevels[areaId] = check.nextLevel;
        // Keep the legacy field in step for anything still reading it.
        entry.frameLevel = Object.values(entry.areaLevels).reduce((s, v) => s + (Number(v) || 0), 0);
        this.save();
        return { ok: true, level: check.nextLevel, area: areaId };
    },
});

// The frame level shown across the UI is now the sum of the area levels.
(function wrapFrameLevel() {
    const proto = ProfileManager.prototype;
    proto.getShipFrameLevel = function (shipId, profile) {
        const lv = this.getShipAreaLevels(shipId, profile);
        return Object.values(lv).reduce((s, v) => s + v, 0);
    };
})();


