"use strict";

// GameControlSystem methods, split from game-control-system.js.
extendClass(GameControlSystem, {
    beginVictoryLootPhase() {
        let grace = (typeof economyConfig !== 'undefined' && economyConfig.getVictoryLootGraceMs)
            ? economyConfig.getVictoryLootGraceMs()
            : 10000;
        // Boss: slightly longer safety net only — victory ends as soon as the
        // field is clear (map-wide vacuum pulls remaining drops in).
        const lvl = this.coreLevelManager && this.coreLevelManager.getCurrentLevel
            ? this.coreLevelManager.getCurrentLevel() : null;
        if (lvl && lvl.isBoss) grace = Math.max(grace, 12000);
        this._victoryLootPhase = true;
        this._victoryLootTimer = grace;
        this._victoryLootElapsed = 0;
        this._victoryLootMinMs = 280;
        this._victoryLootLastCount = -1;
        this._victoryLootIdleMs = 0;
        this.lastVictoryLoot = null;

        if (typeof enemyManager !== 'undefined') {
            enemyManager.spawnFrozen = true;
        }
        if (typeof pickupManager !== 'undefined' && pickupManager.beginLootPhase) {
            pickupManager.beginLootPhase(grace + 3000);
        }
        if (typeof levelInfoManager !== 'undefined' && levelInfoManager.showLootNotice) {
            const secs = Math.ceil(grace / 1000);
            levelInfoManager.showLootNotice('COLLECT RESOURCES — ' + secs + 's');
        }

        // Mark stage cleared early so progress is safe if the tab closes mid-loot
        try {
            const currentLevel = this.coreLevelManager && this.coreLevelManager.getCurrentLevel
                ? this.coreLevelManager.getCurrentLevel()
                : null;
            if (currentLevel && typeof profileManager !== 'undefined' && profileManager.hasActiveProfile()) {
                const planetId = currentLevel.planetId
                    || (currentLevel.id && String(currentLevel.id).split('-')[0])
                    || null;
                const stageKey = currentLevel.stageKey
                    || (currentLevel.isBoss ? 'boss' : String(currentLevel.stageIndex || 1));
                if (planetId) {
                    profileManager.markStageCleared(planetId, stageKey);
                    // Active mission on this planet: pay its bounty.
                    const paid = profileManager.completeMissionFor
                        ? profileManager.completeMissionFor(planetId) : null;
                    if (paid && typeof levelInfoManager !== 'undefined' && levelInfoManager.showLootNotice) {
                        levelInfoManager.showLootNotice('MISSION COMPLETE — BOUNTY PAID');
                    }
                    if (profileManager.discover) profileManager.discover('planets', planetId);
                    this._victoryStageMarked = true;
                    profileManager.save();
                }
            }
        } catch (e) {
            console.warn('Progress save failed', e);
        }
    },

    updateVictoryLootPhase(deltaTime) {
        if (!this._victoryLootPhase) return;
        const dt = Math.max(0, Number(deltaTime) || 0);
        this._victoryLootTimer -= dt;
        this._victoryLootMinMs -= dt;
        this._victoryLootElapsed = (this._victoryLootElapsed || 0) + dt;

        const remaining = Math.max(0, this._victoryLootTimer);
        if (typeof levelInfoManager !== 'undefined' && levelInfoManager.showLootNotice
            && Math.floor(remaining / 1000) !== Math.floor((remaining + dt) / 1000)) {
            const secs = Math.ceil(remaining / 1000);
            if (secs > 0) {
                levelInfoManager.showLootNotice('COLLECT RESOURCES — ' + secs + 's');
            }
        }

        let resourceCount = 0;
        if (typeof pickupManager !== 'undefined' && pickupManager.pickups) {
            for (let i = 0; i < pickupManager.pickups.length; i++) {
                if (!pickupManager.pickups[i].powerUp) resourceCount++;
            }
        }
        const noPickups = resourceCount === 0;
        const minElapsed = this._victoryLootMinMs <= 0;

        // If the count has not dropped for a bit, bank leftovers and finish —
        // stranded / cargo-capped drops must not hold the victory screen.
        if (resourceCount === this._victoryLootLastCount) {
            this._victoryLootIdleMs = (this._victoryLootIdleMs || 0) + dt;
        } else {
            this._victoryLootIdleMs = 0;
            this._victoryLootLastCount = resourceCount;
        }
        if (!noPickups && this._victoryLootElapsed >= 900 && this._victoryLootIdleMs >= 700) {
            if (typeof pickupManager !== 'undefined' && pickupManager.collectAll) {
                // Only vacuum resources; leave power-ups alone.
                for (let i = pickupManager.pickups.length - 1; i >= 0; i--) {
                    const p = pickupManager.pickups[i];
                    if (p.powerUp) continue;
                    pickupManager.collectOne(p);
                    pickupManager.pickups.splice(i, 1);
                }
            }
            this.finalizeVictory();
            return;
        }

        // Done as soon as the field is clear (tiny min delay for juice).
        // Timer is only a hard safety net.
        if ((noPickups && minElapsed) || this._victoryLootTimer <= 0) {
            this.finalizeVictory();
        }
    },

    finalizeVictory() {
        if (this._victoryFinalizing) return;
        this._victoryFinalizing = true;
        this._victoryLootPhase = false;
        this._victoryLootTimer = 0;

        if (typeof pickupManager !== 'undefined' && pickupManager.endLootPhase) {
            pickupManager.endLootPhase();
        }
        if (typeof enemyManager !== 'undefined') {
            enemyManager.spawnFrozen = false;
        }

        this.gameState.stopGame();
        this.lastVictoryLoot = null;

        try {
            const currentLevel = this.coreLevelManager && this.coreLevelManager.getCurrentLevel
                ? this.coreLevelManager.getCurrentLevel()
                : null;
            if (currentLevel && typeof profileManager !== 'undefined' && profileManager.hasActiveProfile()) {
                const planetId = currentLevel.planetId
                    || (currentLevel.id && String(currentLevel.id).split('-')[0])
                    || null;
                const stageKey = currentLevel.stageKey
                    || (currentLevel.isBoss ? 'boss' : String(currentLevel.stageIndex || 1));
                if (planetId) {
                    if (!this._victoryStageMarked) {
                        profileManager.markStageCleared(planetId, stageKey);
                        if (profileManager.discover) {
                            profileManager.discover('planets', planetId);
                        }
                    }
                    if (typeof pickupManager !== 'undefined' && pickupManager.collectAll) {
                        pickupManager.collectAll();
                        const granted = pickupManager.getCollectedThisRun
                            ? pickupManager.getCollectedThisRun()
                            : null;
                        this.lastVictoryLoot = granted && Object.keys(granted).length ? granted : null;
                        if (granted && typeof levelInfoManager !== 'undefined' && levelInfoManager.showLootNotice) {
                            const parts = Object.keys(granted).map((id) => {
                                const label = (typeof economyConfig !== 'undefined')
                                    ? economyConfig.getResourceLabel(id)
                                    : id.toUpperCase();
                                return granted[id] + ' ' + label;
                            });
                            if (parts.length) {
                                levelInfoManager.showLootNotice('LOOT: ' + parts.join(', '));
                            }
                        }
                    } else if (profileManager.grantPlanetResources) {
                        const granted = profileManager.grantPlanetResources(planetId);
                        this.lastVictoryLoot = granted && Object.keys(granted).length ? granted : null;
                    }
                    if (profileManager.teleportCargoToStation) {
                        profileManager.teleportCargoToStation();
                    }
                    profileManager.save();
                    try {
                        if (currentLevel.isBoss
                            && typeof factionManager !== 'undefined'
                            && factionManager.recordMissionVictory) {
                            factionManager.recordMissionVictory(planetId);
                        }
                    } catch (factionErr) {
                        console.warn('Faction victory record failed', factionErr);
                    }
                }
            }
        } catch (e) {
            console.warn('Progress save failed', e);
        }

        this._victoryStageMarked = false;
        this._victoryFinalizing = false;
        this.showVictoryOverlay();

        if (typeof soundManager !== 'undefined') {
            if (soundManager.stopPlanetAmbient) soundManager.stopPlanetAmbient();
            soundManager.playVictory();
        }
    },

    // UI overlay management
    showPauseOverlay() {
        const pauseOverlay = document.getElementById('pauseOverlay');
        if (pauseOverlay) {
            pauseOverlay.classList.remove('hidden');
        }
        if (typeof uiManager !== 'undefined') {
            uiManager.pauseMenuIndex = 0;
            uiManager.updatePauseMenuDisplay();
        }
    },

    hidePauseOverlay() {
        const pauseOverlay = document.getElementById('pauseOverlay');
        if (pauseOverlay) {
            pauseOverlay.classList.add('hidden');
        }
    },

    showGameOverOverlay() {
        const gameOverOverlay = document.getElementById('gameOver');
        if (gameOverOverlay) {
            const lost = (typeof pickupManager !== 'undefined' && pickupManager.forfeitRun)
                ? pickupManager.forfeitRun()
                : {};
            this.applyGameOverFaction(gameOverOverlay, lost);
            gameOverOverlay.classList.remove('hidden');
            if (typeof VFGameOverWreck !== 'undefined') VFGameOverWreck.start(gameOverOverlay);
            if (typeof VFBgMouseParallax !== 'undefined' && VFBgMouseParallax.refresh) {
                VFBgMouseParallax.refresh();
            }
            this.persistEndScreen('gameover', { endLoot: lost || {} });
        }
    },

    /** Faction wording + lost-resources list on the death screen. */
    applyGameOverFaction(overlay, lost) {
        const faction = String(document.documentElement.dataset.faction || 'terran').toLowerCase();
        const lines = {
            terran: ['GAME OVER', 'Mission Failed', 'HULL BREACH · CREW EVACUATED'],
            kronax: ['DISHONOR', 'The blade was broken', 'THE CLAN WILL FORGE ANOTHER'],
            voidborn: ['DISSOLVED', 'The void reclaims you', 'THE SHELL RETURNS TO SILENCE'],
            pirate: ['SUNK', 'Ship scuttled, loot lost', 'DEAD MEN TELL NO TALES'],
            machine: ['SYSTEM FAILURE', 'Unit terminated', 'CHASSIS 0x00 · REBOOT PENDING']
        };
        const pick = lines[faction] || lines.terran;
        const content = overlay.querySelector('.game-over-content');
        if (!content) return;
        const h = content.querySelector('h2');
        const p = content.querySelector('p');
        if (h) h.textContent = pick[0];
        if (p) p.textContent = pick[1];
        const ep = content.querySelector('.game-over-epitaph');
        if (ep) ep.textContent = pick[2] || '';
        if (this.applyOutcomeStepper) this.applyOutcomeStepper(ep || p || h, 'lost');
        let box = content.querySelector('.game-over-loss');
        if (!box) {
            box = document.createElement('div');
            box.className = 'victory-loot game-over-loss';
            const buttons = content.querySelector('.game-over-buttons');
            content.insertBefore(box, buttons);
        }
        const ids = Object.keys(lost || {}).filter((id) => lost[id] > 0);
        let rows = '<div class="victory-loot-empty">NOTHING LOST</div>';
        if (ids.length && this.renderVictoryLootHtml) {
            rows = this.renderVictoryLootHtml(lost).replace(/>\+(\d+)</g, '>−$1<');
        }
        box.innerHTML = '<div class="victory-loot-title">RESOURCES LOST</div>' +
            `<div class="victory-loot-list">${rows}</div>`;
    },

    hideGameOverOverlay() {
        const gameOverOverlay = document.getElementById('gameOver');
        if (gameOverOverlay) {
            gameOverOverlay.classList.add('hidden');
        }
        if (typeof VFGameOverWreck !== 'undefined') VFGameOverWreck.stop();
    },
});


/* --- js/core/game-control-system/show-victory-overlay.js?v=1791486957 --- */
"use strict";

// GameControlSystem methods, split from game-control-system.js.
extendClass(GameControlSystem, {
    showVictoryOverlay() {
        // Hide start screen to prevent input conflicts
        if (typeof startScreenManager !== 'undefined') {
            startScreenManager.hide();
        }

        // Hide side HUD clusters
        const leftCluster = document.getElementById('gameLeftCluster');
        if (leftCluster) {
            leftCluster.style.display = 'none';
        }

        const rightCluster = document.getElementById('gameRightCluster');
        if (rightCluster) {
            rightCluster.style.display = 'none';
        }

        // Create / refresh victory overlay layout
        let victoryOverlay = document.getElementById('victoryOverlay');
        const needsBuild = !victoryOverlay || !document.getElementById('victoryLootList');
        if (!victoryOverlay) {
            victoryOverlay = document.createElement('div');
            victoryOverlay.id = 'victoryOverlay';
            victoryOverlay.className = 'victory-screen';
            document.body.appendChild(victoryOverlay);
        }
        if (needsBuild) {
            victoryOverlay.innerHTML = `
                <div class="victory-content">
                    <div class="victory-header">
                        <h1 class="victory-title">VICTORY!</h1>
                        <p class="victory-subtitle">Mission Accomplished</p>
                        <p class="victory-stage" id="victoryStage"></p>
                    </div>

                    <div class="victory-stats">
                        <div class="stat-item">
                            <span class="stat-label">SCORE</span>
                            <span class="stat-value" id="victoryScore">0</span>
                        </div>
                        <div class="stat-item">
                            <span class="stat-label">TIME</span>
                            <span class="stat-value" id="victoryTime">00:00</span>
                        </div>
                        <div class="stat-item">
                            <span class="stat-label">ENEMIES</span>
                            <span class="stat-value" id="victoryEnemies">0</span>
                        </div>
                    </div>

                    <div class="victory-body">
                        <div class="victory-loot" id="victoryLoot">
                            <div class="victory-loot-title">RESOURCES ACQUIRED</div>
                            <div class="victory-loot-list" id="victoryLootList"></div>
                        </div>

                        <div class="victory-buttons">
                            <button class="victory-button" data-index="0" id="victoryNextButton">
                                <span class="button-icon" data-icon="menuStart"></span>
                                <span class="button-text">NEXT STAGE</span>
                            </button>
                            <button class="victory-button" data-index="1">
                                <span class="button-icon" data-icon="menuRetry"></span>
                                <span class="button-text">PLAY AGAIN</span>
                            </button>
                            <button class="victory-button" data-index="2">
                                <span class="button-icon" data-icon="menuPlanets"></span>
                                <span class="button-text">PLANET SELECT</span>
                            </button>
                        </div>
                    </div>

                    <div class="victory-instructions">
                        <p>ARROW KEYS: Navigate | ENTER: Select</p>
                    </div>
                </div>
            `;
            victoryOverlay.dataset.bound = '';
        }
        victoryOverlay.classList.remove('hidden');
        this.applyVictoryFactionFlavor(victoryOverlay);
        this.applyVictoryPixelIcons(victoryOverlay);

        if (!victoryOverlay.dataset.bound) {
            this.bindVictoryButtons(victoryOverlay);
            victoryOverlay.dataset.bound = '1';
        }

        this.updateVictoryNextButton();
        this.cancelVictoryAutoReturn();

        if (typeof uiManager !== 'undefined') {
            uiManager.victoryMenuIndex = 0;
            uiManager.updateVictoryMenuDisplay();
        }

        this.updateVictoryStats();
        if (this.applyOutcomeStepper) this.applyOutcomeStepper(victoryOverlay.querySelector('.victory-header'), 'won');

        if (typeof VFBgMouseParallax !== 'undefined' && VFBgMouseParallax.refresh) {
            VFBgMouseParallax.refresh();
        }
        this.persistEndScreen('victory', { endLoot: this.lastVictoryLoot || null });
    },

    /** Faction-specific victory wording; the look comes from html[data-faction]. */
    applyVictoryFactionFlavor(overlay) {
        const faction = String(document.documentElement.dataset.faction || 'terran').toLowerCase();
        const lines = {
            terran: ['VICTORY!', 'Mission Accomplished'],
            kronax: ['CONQUEST!', 'The blade prevails'],
            voidborn: ['ASCENSION', 'The void has fed'],
            pirate: ['PLUNDERED!', 'Loot secured, crew alive'],
            machine: ['OBJECTIVE COMPLETE', 'Efficiency: optimal']
        };
        const pick = lines[faction] || lines.terran;
        const title = overlay.querySelector('.victory-title');
        const sub = overlay.querySelector('.victory-subtitle');
        if (title) title.textContent = pick[0];
        if (sub) sub.textContent = pick[1];
        overlay.dataset.faction = faction;
    },

    victoryResourceIconKey(id) {
        if (typeof economyConfig !== 'undefined' && economyConfig.getResourceIconKey) {
            return economyConfig.getResourceIconKey(id);
        }
        const map = {
            scrap: 'resScrap',
            ore: 'resOre',
            crystal: 'resCrystal',
            voltex: 'resVoltex'
        };
        return map[id] || 'resScrap';
    },

    renderVictoryLootHtml(loot) {
        const entries = loot
            ? Object.keys(loot).filter((id) => (loot[id] || 0) > 0)
            : [];
        if (!entries.length) {
            return '<div class="victory-loot-empty">NO RESOURCES THIS RUN</div>';
        }
        return entries.map((id) => {
            const amount = loot[id] || 0;
            const label = (typeof economyConfig !== 'undefined')
                ? economyConfig.getResourceLabel(id)
                : String(id).toUpperCase();
            const iconKey = this.victoryResourceIconKey(id);
            const tint = (typeof economyConfig !== 'undefined' && economyConfig.getResourceColor)
                ? economyConfig.getResourceColor(id)
                : undefined;
            const iconHtml = (typeof iconRenderer !== 'undefined')
                ? iconRenderer.imgHtml(iconKey, 28, 'victory-loot-pixel', tint)
                : '';
            const color = tint || '#ccc';
            return `<div class="victory-loot-row victory-loot-${id}" style="--victory-res-color:${color}">` +
                `<span class="victory-loot-icon">${iconHtml}</span>` +
                `<span class="victory-loot-label">${label}</span>` +
                `<span class="victory-loot-amount">+${amount}</span>` +
                `</div>`;
        }).join('');
    },

    applyVictoryPixelIcons(victoryOverlay) {
        if (!victoryOverlay) return;
        const defaults = {
            '0': 'menuStart',
            '1': 'menuRetry',
            '2': 'menuPlanets'
        };
        victoryOverlay.querySelectorAll('.victory-button').forEach((button) => {
            let iconEl = button.querySelector('.button-icon');
            if (!iconEl) {
                iconEl = document.createElement('span');
                iconEl.className = 'button-icon';
                button.insertBefore(iconEl, button.firstChild);
            }
            const key = iconEl.dataset.icon || defaults[button.dataset.index];
            if (!key) return;
            iconEl.dataset.icon = key;
            if (typeof iconRenderer !== 'undefined') {
                iconEl.innerHTML = iconRenderer.imgHtml(key, 20, 'victory-pixel-icon');
            }
        });
    },

    /**
     * Last stage of a planet won → no next stage to offer: show the victory
     * screen briefly (with a countdown) and return to planet selection.
     * Any button pressed meanwhile wins; hiding the overlay cancels the timer.
     */
    getVictoryCurrentLevelId() {
        const level = this.coreLevelManager.getCurrentLevel();
        if (!level) return null;
        if (level.planetId && Number.isFinite(Number(level.stageIndex))) {
            return `${level.planetId}-${level.isBoss ? 'boss' : level.stageIndex}`;
        }
        return level.id || level.levelId || level.stageId || level.planetId || level.background || null;
    },

    scheduleAutoReturnIfPlanetCleared(overlay) {
        this.cancelVictoryAutoReturn();
        const currentLevel = this.coreLevelManager.getCurrentLevel();
        const currentId = this.getVictoryCurrentLevelId();
        const meta = currentId && typeof this.coreLevelManager.getNextLevelMeta === 'function'
            ? this.coreLevelManager.getNextLevelMeta(currentId)
            : null;
        const cleared = !!(currentLevel && currentLevel.isBoss) || !meta || meta.kind === 'planet';
        if (!cleared) return;
        const label = overlay.querySelector('.victory-button[data-index="2"] .button-text');
        let left = 4;
        const tick = () => {
            if (label) label.textContent = `PLANET SELECT (${left})`;
            if (left <= 0) {
                this.cancelVictoryAutoReturn();
                if (label) label.textContent = 'PLANET SELECT';
                if (typeof game !== 'undefined' && game.showLevelSelection) game.showLevelSelection();
                return;
            }
            left -= 1;
            this._victoryAutoReturn = setTimeout(tick, 1000);
        };
        if (typeof uiManager !== 'undefined') {
            uiManager.victoryMenuIndex = 2;
            uiManager.updateVictoryMenuDisplay();
        }
        tick();
    },

    cancelVictoryAutoReturn() {
        if (this._victoryAutoReturn) {
            clearTimeout(this._victoryAutoReturn);
            this._victoryAutoReturn = null;
        }
        const label = document.querySelector('#victoryOverlay .victory-button[data-index="2"] .button-text');
        if (label) label.textContent = 'PLANET SELECT';
    },

    updateVictoryNextButton() {
        const currentLevel = this.coreLevelManager.getCurrentLevel();
        const hasInterruptedTravel = typeof galaxyMapManager !== 'undefined'
            && galaxyMapManager
            && galaxyMapManager._postAmbushFlight;
        const isAmbush = currentLevel && [
            currentLevel.id,
            currentLevel.levelId,
            currentLevel.stageId,
            currentLevel.planetId
        ].some((value) => String(value || '').toLowerCase().indexOf('ambush_') === 0);
        const currentId = this.getVictoryCurrentLevelId();
        const ambushVictory = !!hasInterruptedTravel || isAmbush
            || String(currentId || '').toLowerCase().indexOf('ambush_') === 0;
        const meta = currentId && typeof this.coreLevelManager.getNextLevelMeta === 'function'
            ? this.coreLevelManager.getNextLevelMeta(currentId)
            : null;

        const button = document.querySelector('#victoryOverlay .victory-button[data-index="0"] .button-text')
            || document.querySelector('#victoryNextButton .button-text');
        if (button) {
            const bossVictory = !ambushVictory && !!(currentLevel && currentLevel.isBoss);
            button.textContent = ambushVictory ? 'CONTINUE TRAVEL'
                : (bossVictory ? 'MAP SELECT' : (meta ? meta.label : 'CAMPAIGN COMPLETE'));
        }

        const nextBtn = document.querySelector('#victoryOverlay .victory-button[data-index="0"]');
        if (nextBtn) {
            const canAdvance = !!meta || ambushVictory || !!(currentLevel && currentLevel.isBoss);
            nextBtn.disabled = !canAdvance;
            nextBtn.classList.toggle('disabled', !canAdvance);
        }
    },

    bindVictoryButtons(victoryOverlay) {
        const buttons = victoryOverlay.querySelectorAll('.victory-button');
        buttons.forEach((button) => {
            button.addEventListener('mouseenter', () => {
                const index = parseInt(button.dataset.index, 10);
                if (typeof uiManager !== 'undefined' && !Number.isNaN(index)) {
                    uiManager.victoryMenuIndex = index;
                    uiManager.updateVictoryMenuDisplay();
                }
            });
            button.addEventListener('click', (event) => {
                event.preventDefault();
                const index = parseInt(button.dataset.index, 10);
                if (typeof uiManager !== 'undefined' && !Number.isNaN(index)) {
                    uiManager.victoryMenuIndex = index;
                    uiManager.updateVictoryMenuDisplay();
                    uiManager.selectVictoryOption();
                }
            });
        });
    },

    hideVictoryOverlay() {
        this.cancelVictoryAutoReturn();
        const victoryOverlay = document.getElementById('victoryOverlay');
        if (victoryOverlay) {
            victoryOverlay.classList.add('hidden');
        }

        // Show side HUD clusters again
        const leftCluster = document.getElementById('gameLeftCluster');
        if (leftCluster) {
            leftCluster.style.display = '';
        }

        const rightCluster = document.getElementById('gameRightCluster');
        if (rightCluster) {
            rightCluster.style.display = '';
        }
    },

    hideAllOverlays() {
        this.hidePauseOverlay();
        this.hideGameOverOverlay();
        this.hideVictoryOverlay();

        // Hide settings overlay
        const settingsOverlay = document.getElementById('settingsOverlay');
        if (settingsOverlay) {
            settingsOverlay.classList.add('hidden');
        }
    },

    // Level info management
    updateLevelInfo() {
        const levelInfoManager = this.systemManager.getSubsystem('levelInfoManager');
        if (levelInfoManager) {
            const levelData = levelInfoManager.collectLevelData();
            levelInfoManager.updateLevelData(levelData);
            // Always paint the info panel when combat HUD is up. Only the
            // combat clock waits for FIRE TO START → fly-in to finish.
            if (typeof missionStartManager !== 'undefined' && missionStartManager.isActive()) {
                if (typeof levelInfoManager.prepareForCombat === 'function') {
                    levelInfoManager.prepareForCombat();
                } else {
                    levelInfoManager.showPanel();
                    levelInfoManager.updateDisplay();
                }
            } else {
                levelInfoManager.startLevel();
            }
        } else {
            console.warn('LevelInfoManager not available for update');
        }
    },

    updateLevelStats(stats) {
        const levelInfoManager = this.systemManager.getSubsystem('levelInfoManager');
        if (levelInfoManager) {
            levelInfoManager.updateStats(stats);
        }
    },
});


/* --- js/core/game-control-system/stage-stepper.js?v=2 --- */
"use strict";

// Victory / defeat screens: the planet that was fought on (icon, name,
// galaxy) and a stepper of its stages (1..N + BOSS) — cleared ones checked,
// the one just fought marked WON or LOST, later ones locked.
extendClass(GameControlSystem, {
    renderOutcomeStepperHtml(result) {
        const level = this.coreLevelManager && this.coreLevelManager.getCurrentLevel
            ? this.coreLevelManager.getCurrentLevel() : null;
        if (!level) return '';
        const pid = String(level.planetId || (level.id && String(level.id).split('-')[0]) || '').toLowerCase();
        if (!pid) return '';
        const pcm = typeof planetConfigManager !== 'undefined' ? planetConfigManager : null;
        const cfg = pcm && pcm.getConfig ? pcm.getConfig(pid) : null;
        const gid = pcm && (pcm.getWorldGalaxyOfPlanet ? pcm.getWorldGalaxyOfPlanet(pid) : pcm.getPlanetGalaxyId(pid));
        const galaxy = gid && pcm.getGalaxy ? pcm.getGalaxy(gid) : null;
        const icon = typeof galaxyMapManager !== 'undefined' && galaxyMapManager.planetIconHtml
            ? galaxyMapManager.planetIconHtml(pid, 112, true) : '';
        const name = String(level.planetName || (cfg && cfg.name) || pid).toUpperCase();
        const isAmbush = pid.indexOf('ambush_') === 0;

        let steps = '';
        if (!isAmbush) {
            const n = Math.max(1, Math.round(Number(level.stagesPerPlanet) || (typeof getPlanetStageCount === 'function' ? getPlanetStageCount(pid) : 3)));
            const p = typeof profileManager !== 'undefined' && profileManager.getActiveProfile
                ? profileManager.getActiveProfile() : null;
            const gp = p && gid && profileManager.ensureGalaxyProgress ? profileManager.ensureGalaxyProgress(p, gid) : null;
            const st = (gp && gp.stages && gp.stages[pid]) || { highestStage: 0, bossCleared: false };
            const current = level.isBoss ? n + 1 : Math.max(1, Number(level.stageIndex) || 1);
            const list = [];
            for (let i = 1; i <= n + 1; i++) {
                const boss = i === n + 1;
                const done = boss ? !!st.bossCleared : i <= (st.highestStage || 0);
                let state = done ? 'done' : 'locked';
                if (i === current) state = result === 'won' ? 'won' : 'lost';
                const mark = state === 'won' || state === 'done' ? '✓' : (state === 'lost' ? '✕' : (boss ? '☠' : String(i)));
                list.push(`<li class="outcome-step is-${state}${boss ? ' is-boss' : ''}" title="${boss ? 'BOSS' : 'STAGE ' + i}">` +
                    `<span class="outcome-step-dot">${mark}</span></li>`);
            }
            const which = level.isBoss ? 'BOSS' : 'STAGE ' + current + '/' + (n + 1);
            steps = `<ol class="outcome-stepper">${list.join('')}</ol>` +
                `<p class="outcome-status">${which} ${result === 'won' ? 'CLEARED' : 'FAILED'}</p>`;
        }
        return `<div class="outcome-planet">` +
            `<span class="outcome-planet-icon">${icon}</span>` +
            `<span class="outcome-planet-text"><strong>${name}</strong>` +
            `<span>${galaxy ? String(galaxy.name || gid).toUpperCase() : ''}${isAmbush ? ' · AMBUSH' : ''}</span></span>` +
            `</div>${steps}`;
    },

    /** Puts / refreshes the stepper block right after `anchor`. */
    applyOutcomeStepper(anchor, result) {
        if (!anchor || !anchor.parentNode) return;
        let box = anchor.parentNode.querySelector(':scope > .outcome-progress');
        if (!box) {
            box = document.createElement('div');
            box.className = 'outcome-progress';
            anchor.insertAdjacentElement('afterend', box);
        }
        box.dataset.result = result;
        box.innerHTML = this.renderOutcomeStepperHtml(result);
        box.hidden = !box.innerHTML;
    }
});


/* --- js/core/game-control-system/leave-game-session.js?v=1791486957 --- */
"use strict";

// GameControlSystem methods, split from game-control-system.js.
extendClass(GameControlSystem, {
    leaveGameSession() {
        this.stopGame();
        this.hideAllOverlays();
        if (typeof soundManager !== 'undefined') {
            if (soundManager.stopPlanetAmbient) soundManager.stopPlanetAmbient();
            if (soundManager.ambientPlanetId != null) soundManager.ambientPlanetId = null;
        }

        if (typeof planetEditorUI !== 'undefined' && planetEditorUI.visible) {
            planetEditorUI.returnTo = null;
            planetEditorUI.hide();
        }
        if (typeof enemyEditorUI !== 'undefined' && enemyEditorUI.visible) {
            enemyEditorUI.returnTo = null;
            enemyEditorUI.hide();
        }
        if (typeof shipEditorUI !== 'undefined' && shipEditorUI.visible) {
            shipEditorUI.returnTo = null;
            shipEditorUI.hide();
        }
        if (typeof planetViewerUI !== 'undefined' && planetViewerUI.visible) {
            planetViewerUI.hide();
        }
        if (typeof enemyViewerUI !== 'undefined' && enemyViewerUI.visible) {
            enemyViewerUI.hide();
        }
        if (typeof shipViewerUI !== 'undefined' && shipViewerUI.visible) {
            shipViewerUI.hide();
        }
        if (typeof abilityViewerUI !== 'undefined' && abilityViewerUI.visible) {
            abilityViewerUI.hide();
        }
        if (typeof weaponViewerUI !== 'undefined' && weaponViewerUI.visible) {
            weaponViewerUI.hide();
        }
        if (typeof defenseViewerUI !== 'undefined' && defenseViewerUI.visible) {
            defenseViewerUI.hide();
        }
        if (typeof factionViewerUI !== 'undefined' && factionViewerUI.visible) {
            factionViewerUI.hide();
        }
        if (typeof abilityEditorUI !== 'undefined' && abilityEditorUI.visible) {
            abilityEditorUI.returnTo = null;
            abilityEditorUI.hide();
        }

        if (typeof themeContextManager !== 'undefined') {
            themeContextManager.restoreAppTheme();
        }

        const gameContainer = document.querySelector('.game-container');
        if (gameContainer) {
            gameContainer.style.display = 'none';
        }

        const leftCluster = document.getElementById('gameLeftCluster');
        if (leftCluster) {
            leftCluster.style.display = 'none';
        }

        const rightCluster = document.getElementById('gameRightCluster');
        if (rightCluster) {
            rightCluster.style.display = 'none';
        }
    },

    // Level selection (planet map) — default exit after a run
    showLevelSelection() {
        // The planet just fought on: the map opens with it already selected.
        let foughtPlanet = null;
        try {
            const lvl = this.coreLevelManager && this.coreLevelManager.getCurrentLevel
                ? this.coreLevelManager.getCurrentLevel() : null;
            const pid = lvl && String(lvl.planetId || (lvl.id && String(lvl.id).split('-')[0]) || '').toLowerCase();
            if (pid && pid.indexOf('ambush_') !== 0) foughtPlanet = pid;
        } catch (e) { foughtPlanet = null; }
        this.leaveGameSession();

        if (typeof startScreenManager !== 'undefined') {
            startScreenManager.hide();
        }
        const startScreen = document.getElementById('startScreen');
        if (startScreen) {
            startScreen.classList.add('hidden');
        }

        if (typeof homeStationUI !== 'undefined') {
            homeStationUI.show({
                tab: 'play',
                onClose: () => {
                    if (typeof startScreenManager !== 'undefined') {
                        startScreenManager.returnToHub();
                    }
                }
            });
            if (foughtPlanet && typeof galaxyMapManager !== 'undefined') {
                const selectFought = () => {
                    if (galaxyMapManager.nodeById && galaxyMapManager.nodeById[foughtPlanet] && galaxyMapManager.selectPlanet) {
                        galaxyMapManager.selectPlanet(foughtPlanet);
                        if (galaxyMapManager.markUserPicked) galaxyMapManager.markUserPicked();
                        if (galaxyMapManager.frameSelectionCamera) galaxyMapManager.frameSelectionCamera('follow');
                        return true;
                    }
                    return false;
                };
                if (!selectFought()) requestAnimationFrame(selectFought);
            }
            // Ambush lost: show the flight back to the last station.
            if (typeof galaxyMapManager !== 'undefined' && galaxyMapManager._ambushLost
                && galaxyMapManager._postAmbushFlight && galaxyMapManager.retreatAfterAmbush) {
                const f = galaxyMapManager._postAmbushFlight;
                galaxyMapManager._postAmbushFlight = null;
                galaxyMapManager._ambushLost = false;
                galaxyMapManager.retreatAfterAmbush(f);
            }
            // Ambush won: carry on from the fight spot along the route.
            else if (typeof galaxyMapManager !== 'undefined' && galaxyMapManager._postAmbushFlight
                && galaxyMapManager.resumeAfterAmbush) {
                const f = galaxyMapManager._postAmbushFlight;
                galaxyMapManager._postAmbushFlight = null;
                galaxyMapManager.resumeAfterAmbush(f);
            }
        } else if (typeof combinedSelectionManager !== 'undefined') {
            combinedSelectionManager.show();
        } else if (typeof planetSelectionManager !== 'undefined') {
            planetSelectionManager.show();
        }
    },

    // Main menu
    quitToMainMenu() {
        this.leaveGameSession();

        const startScreen = document.getElementById('startScreen');
        if (startScreen) {
            startScreen.classList.add('hidden');
        }

        if (typeof startScreenManager !== 'undefined') {
            startScreenManager.returnToHub({ tab: 'play' });
        }

        if (typeof menuStateManager !== 'undefined') {
            if (typeof profileManager !== 'undefined' && profileManager.hasActiveProfile()) {
                menuStateManager.setScreen('home-station', { tab: 'play' });
            } else {
                menuStateManager.setScreen('start');
            }
        }
    },

    syncVictoryStatsFromLiveSources() {
        const lim = this.systemManager.getSubsystem('levelInfoManager')
            || (typeof levelInfoManager !== 'undefined' ? levelInfoManager : null);
        const liveScore = (typeof game !== 'undefined' && typeof game.score === 'number')
            ? game.score
            : (lim && lim.stats ? lim.stats.score : 0);
        let levelTime = 0;
        let enemiesKilled = 0;
        if (lim && lim.stats) {
            if (lim.stats.startTime) {
                lim.stats.levelTime = Math.floor((Date.now() - lim.stats.startTime) / 1000);
            }
            levelTime = lim.stats.levelTime || 0;
            enemiesKilled = lim.stats.enemiesKilled || 0;
            lim.stats.score = liveScore;
        }
        this.gameState.updateStats({
            score: liveScore || 0,
            levelTime: levelTime,
            enemiesKilled: enemiesKilled
        });
        return this.gameState.getStats();
    },

    updateVictoryStats() {
        const stageElement = document.getElementById('victoryStage');
        if (stageElement) {
            const currentLevel = this.coreLevelManager.getCurrentLevel();
            const isAmbush = currentLevel
                && String(currentLevel.id || '').toLowerCase().indexOf('ambush_') === 0;
            stageElement.textContent = currentLevel
                ? (isAmbush
                    ? `${currentLevel.planetName || currentLevel.name || 'PIRATE AMBUSH'} — STAGE 1/1`
                    : (currentLevel.name || `${currentLevel.planetName || ''} ${currentLevel.stageLabel || ''}`.trim() || currentLevel.id || ''))
                : '';
        }

        const stats = this.syncVictoryStatsFromLiveSources();

        const scoreElement = document.getElementById('victoryScore');
        if (scoreElement) {
            scoreElement.textContent = String(stats.score || 0);
        }

        const timeElement = document.getElementById('victoryTime');
        if (timeElement) {
            const levelTime = stats.levelTime || 0;
            const minutes = Math.floor(levelTime / 60);
            const seconds = levelTime % 60;
            timeElement.textContent = `${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
        }

        const enemiesElement = document.getElementById('victoryEnemies');
        if (enemiesElement) {
            enemiesElement.textContent = String(stats.enemiesKilled || 0);
        }

        const lootList = document.getElementById('victoryLootList');
        if (lootList) {
            lootList.innerHTML = this.renderVictoryLootHtml(this.lastVictoryLoot);
        }
    },

    /** Remember an end screen so a page refresh lands on it again (menu-state/restore.js). */
    persistEndScreen(kind, extra) {
        if (typeof menuStateManager === 'undefined') return;
        const stats = this.gameState.getStats ? this.gameState.getStats() : {};
        menuStateManager.setScreen('endscreen', Object.assign({
            endKind: kind,
            levelId: this.getRestartLevelId(),
            endStats: { score: stats.score || 0, levelTime: stats.levelTime || 0, enemiesKilled: stats.enemiesKilled || 0 },
            endLoot: null
        }, extra || {}));
    },

    /**
     * Refresh on a victory / game-over screen: load the level (no match), put the
     * saved numbers back and show the same overlay again. Returns false if impossible.
     */
    restoreEndScreen(s) {
        if (!s || !s.levelId || (s.endKind !== 'victory' && s.endKind !== 'gameover')) return false;
        const gameContainer = document.querySelector('.game-container');
        if (gameContainer) gameContainer.style.display = 'flex';
        if (gameContainer) document.documentElement.classList.add('vf-game-shown');
        if (typeof window.viewportFit !== 'undefined' && window.viewportFit.update) window.viewportFit.update();
        if (!this.coreLevelManager.startLevel(s.levelId)) return false;
        const stats = s.endStats || {};
        const lim = this.systemManager.getSubsystem('levelInfoManager');
        if (typeof game !== 'undefined') game.score = stats.score || 0;
        if (lim && lim.stats) {
            lim.stats.score = stats.score || 0;
            lim.stats.levelTime = stats.levelTime || 0;
            lim.stats.enemiesKilled = stats.enemiesKilled || 0;
            lim.stats.startTime = null;
        }
        if (s.endKind === 'victory') {
            this.lastVictoryLoot = s.endLoot || null;
            this.showVictoryOverlay();
        } else {
            const overlay = document.getElementById('gameOver');
            if (!overlay) return false;
            this.applyGameOverFaction(overlay, s.endLoot || {});
            overlay.classList.remove('hidden');
            if (typeof VFGameOverWreck !== 'undefined') VFGameOverWreck.start(overlay);
        }
        return true;
    },
});


