/* --- js/core/game-loop.js?v=voxel-gb-1 --- */
"use strict";

// Game loop and timing management
class GameLoop {
    constructor(gameState, systemManager = null) {
        this.gameState = gameState;
        this.systemManager = systemManager;
        this.lastTime = 0;
        this.frameCount = 0;
        this.gameRunning = true;
    }

    start() {
        this.lastTime = 0;
        this.frameCount = 0;
        this.gameState.gameRunning = true;
        this.loop(performance.now());
    }

    stop() {
        this.gameState.gameRunning = false;
    }

    loop(currentTime) {
        if (!this.gameState.gameRunning) return;
        
        // Fix initial deltaTime spike on first frame
        if (this.lastTime === 0) {
            this.lastTime = currentTime;
        }
        
        const deltaTime = currentTime - this.lastTime;
        this.lastTime = currentTime;
        
        // Fix zero and negative deltaTime issues - ignore negative values completely
        let safeDeltaTime;
        if (deltaTime < 0) {
            // Skip this frame if deltaTime is negative
            requestAnimationFrame((time) => this.loop(time));
            return;
        } else {
            safeDeltaTime = Math.max(deltaTime, 0.1); // Minimum 0.1ms to prevent division by zero
        }
        
        // Cap deltaTime to prevent extreme speed on first frame or lag spikes
        const cappedDeltaTime = Math.min(safeDeltaTime, 50); // Max 50ms = 20 FPS minimum
        
        this.update(cappedDeltaTime);
        this.render();
        
        // Only continue loop if game is still running
        if (this.gameState.gameRunning) {
            requestAnimationFrame((time) => this.loop(time));
        }
    }

    update(deltaTime) {
        this.frameCount++;
        
        // Update start screen first
        if (typeof startScreenManager !== 'undefined') {
            startScreenManager.update(deltaTime);
            if (startScreenManager.isVisible()) {
                return; // Don't update game if start screen is visible
            }
        }
        
        // Increment frame count
        this.gameState.frameCount++;
        
        // Don't update game logic if paused or game over
        if (this.gameState.isPaused || !this.gameState.gameRunning) {
            // Still update UI even when paused
            if (typeof uiManager !== 'undefined') uiManager.updateUI();
            return;
        }

        const introActive = typeof missionStartManager !== 'undefined' && missionStartManager.isActive();
        if (introActive) {
            missionStartManager.update(deltaTime);
            if (typeof parallaxManager !== 'undefined') parallaxManager.update(deltaTime);
            if (typeof graphicsManager !== 'undefined') graphicsManager.updateParticles();
            if (typeof explosionSystem !== 'undefined') explosionSystem.update(16);
            if (typeof uiManager !== 'undefined') uiManager.updateUI();
            return;
        }
        
        if (typeof playerManager !== 'undefined') {
            const inputHandler = this.systemManager ? this.systemManager.getSubsystem('inputHandler') : null;
            if (inputHandler) {
                playerManager.update(inputHandler.keys, deltaTime);
            }
        }
        if (typeof beatSyncManager !== 'undefined') {
            beatSyncManager.update(deltaTime);
        }

        const gameControl = (typeof game !== 'undefined' && game.gameControl)
            ? game.gameControl
            : ((typeof gameCore !== 'undefined' && gameCore.gameControl) ? gameCore.gameControl : null);
        const lootPhase = !!(gameControl && gameControl._victoryLootPhase);
        if (lootPhase) {
            // Keep in-flight shots / obstacles moving during loot scoop / flee cleanup
            if (typeof bulletManager !== 'undefined') {
                const inputHandler = this.systemManager ? this.systemManager.getSubsystem('inputHandler') : null;
                const keys = inputHandler ? inputHandler.keys : null;
                bulletManager.update(deltaTime, keys);
            }
            if (typeof obstacleManager !== 'undefined') obstacleManager.update(deltaTime, this.gameState);
            if (typeof enemyManager !== 'undefined'
                && enemyManager.sideEnemies
                && enemyManager.sideEnemies.length
                && enemyManager.updateSideEnemies) {
                enemyManager.updateSideEnemies(deltaTime, this.gameState);
            }
            if (typeof pickupManager !== 'undefined') pickupManager.update(deltaTime);
            if (typeof parallaxManager !== 'undefined') parallaxManager.update(deltaTime);
            if (typeof graphicsManager !== 'undefined') graphicsManager.updateParticles();
            if (typeof explosionSystem !== 'undefined') explosionSystem.update(deltaTime || 16);
            if (gameControl.updateVictoryLootPhase) gameControl.updateVictoryLootPhase(deltaTime);
            if (typeof window !== 'undefined' && window.combatVoxels && window.combatVoxels.snapWorld) {
                window.combatVoxels.snapWorld();
            }
            if (typeof uiManager !== 'undefined') uiManager.updateUI();
            return;
        }

        if (typeof bulletManager !== 'undefined') {
            const inputHandler = this.systemManager ? this.systemManager.getSubsystem('inputHandler') : null;
            const keys = inputHandler ? inputHandler.keys : null;
            bulletManager.update(deltaTime, keys);
        }
        if (typeof enemyManager !== 'undefined') enemyManager.update(deltaTime, this.gameState);
        if (typeof obstacleManager !== 'undefined') obstacleManager.update(deltaTime, this.gameState);
        if (typeof pickupManager !== 'undefined') pickupManager.update(deltaTime);
        if (typeof collisionManager !== 'undefined') collisionManager.checkCollisions(this.gameState);
        if (typeof parallaxManager !== 'undefined') parallaxManager.update(deltaTime);
        if (typeof graphicsManager !== 'undefined') graphicsManager.updateParticles();
        if (typeof explosionSystem !== 'undefined') explosionSystem.update(deltaTime || 16);

        // VOXEL: lock every combat element to the Game-Boy lattice after physics.
        if (typeof window !== 'undefined' && window.combatVoxels && window.combatVoxels.snapWorld) {
            window.combatVoxels.snapWorld();
        }
        
        // Always update UI, even when paused
        if (typeof uiManager !== 'undefined') uiManager.updateUI();
    }

    render() {
        // Don't render if game is not running
        if (!this.gameState.gameRunning) return;
        
        if (typeof renderManager !== 'undefined') renderManager.render();
    }
}


/* --- js/core/menu-nav.js --- */
"use strict";

/**
 * Shared menu / overlay keyboard helpers.
 * Arrow keys navigate UI when not actively flying the ship.
 */
class MenuNavHelper {
    isPlayingShip() {
        if (typeof gameStateManager === 'undefined' && typeof game === 'undefined') {
            return false;
        }
        const gs = (typeof game !== 'undefined' && game.gameState)
            ? game.gameState
            : (typeof gameStateManager !== 'undefined' ? gameStateManager : null);
        if (!gs) return false;
        if (typeof missionStartManager !== 'undefined' && missionStartManager.isActive()) {
            return false;
        }
        return !!(gs.gameRunning && !gs.isPaused);
    }

    isAnyOverlayOpen() {
        const checks = [
            () => typeof startScreenManager !== 'undefined' && startScreenManager.isVisible && startScreenManager.isVisible(),
            () => typeof homeStationUI !== 'undefined' && homeStationUI.isVisible,
            () => typeof profileSelectionManager !== 'undefined' && profileSelectionManager.isVisible,
            () => typeof combinedSelectionManager !== 'undefined' && combinedSelectionManager.isVisible,
            () => typeof playerSelectionManager !== 'undefined' && playerSelectionManager.isVisible,
            () => typeof planetSelectionManager !== 'undefined' && planetSelectionManager.isVisible,
            () => typeof galaxySelectionManager !== 'undefined' && galaxySelectionManager.isVisible,
            () => typeof galaxyMapManager !== 'undefined' && galaxyMapManager.isVisible,
            () => typeof shipViewerUI !== 'undefined' && shipViewerUI.visible,
            () => typeof planetViewerUI !== 'undefined' && planetViewerUI.visible,
            () => typeof enemyViewerUI !== 'undefined' && enemyViewerUI.visible,
            () => typeof abilityViewerUI !== 'undefined' && abilityViewerUI.visible,
            () => typeof weaponViewerUI !== 'undefined' && weaponViewerUI.visible,
            () => typeof defenseViewerUI !== 'undefined' && defenseViewerUI.visible,
            () => typeof factionViewerUI !== 'undefined' && factionViewerUI.visible,
            () => typeof themeEditorUI !== 'undefined' && themeEditorUI.visible,
            () => typeof shipEditorUI !== 'undefined' && shipEditorUI.visible,
            () => typeof planetEditorUI !== 'undefined' && planetEditorUI.visible,
            () => typeof enemyEditorUI !== 'undefined' && enemyEditorUI.visible,
            () => typeof abilityEditorUI !== 'undefined' && abilityEditorUI.visible,
            () => typeof uiDialog !== 'undefined' && uiDialog.isOpen,
            () => typeof onboardingManager !== 'undefined' && onboardingManager.isVisible
        ];
        return checks.some((fn) => {
            try { return !!fn(); } catch (e) { return false; }
        });
    }

    /** True when arrow keys must not steer the ship. */
    shouldBlockShipControls() {
        return !this.isPlayingShip() || this.isAnyOverlayOpen();
    }

    isArrowKey(key) {
        return key === 'ArrowUp' || key === 'ArrowDown' || key === 'ArrowLeft' || key === 'ArrowRight';
    }

    isMoveKey(key) {
        return this.isArrowKey(key) ||
            key === 'w' || key === 'a' || key === 's' || key === 'd' ||
            key === 'W' || key === 'A' || key === 'S' || key === 'D';
    }

    /**
     * Collect enabled buttons / focusables inside a root.
     */
    collectFocusables(root) {
        if (!root) return [];
        const nodes = root.querySelectorAll(
            'button:not([disabled]), [data-nav-item], a[href], select:not([disabled]), ' +
            'textarea:not([disabled]), input:not([disabled]):not([type="hidden"]), [tabindex]:not([tabindex="-1"])'
        );
        return Array.prototype.slice.call(nodes).filter((el) => {
            if (el.disabled) return false;
            if (el.getAttribute('aria-disabled') === 'true') return false;
            if (el.closest && el.closest('[data-nav-skip], [inert], [aria-hidden="true"]')) return false;
            // Hidden via display:none on any ancestor → no layout box.
            if (typeof el.getClientRects === 'function' && el.getClientRects().length === 0) return false;
            const style = window.getComputedStyle ? window.getComputedStyle(el) : null;
            if (style && (style.display === 'none' || style.visibility === 'hidden')) return false;
            return true;
        });
    }

    /** Text-entry fields keep arrow keys for caret movement. */
    isTextEntry(el) {
        if (!el || !el.tagName) return false;
        if (el.tagName === 'TEXTAREA' || el.isContentEditable) return true;
        if (el.tagName !== 'INPUT') return false;
        const type = (el.getAttribute('type') || 'text').toLowerCase();
        return !['range', 'checkbox', 'radio', 'button', 'submit', 'color'].includes(type);
    }

    applyFocus(list, index) {
        if (!list.length) return 0;
        const i = Math.max(0, Math.min(list.length - 1, index));
        list.forEach((el, idx) => {
            el.classList.toggle('nav-focused', idx === i);
            if (idx === i && typeof el.focus === 'function') {
                try { el.focus({ preventScroll: true }); } catch (e) { el.focus(); }
                if (typeof el.scrollIntoView === 'function') {
                    try { el.scrollIntoView({ block: 'nearest', inline: 'nearest' }); } catch (e) { /* ignore */ }
                }
            }
        });
        return i;
    }

    moveFocus(list, index, delta) {
        if (!list.length) return 0;
        let next = index + delta;
        if (next < 0) next = list.length - 1;
        if (next >= list.length) next = 0;
        return this.applyFocus(list, next);
    }

    /**
     * 2D arrow nav: pick nearest focusable in direction (prefer same row/column).
     * Returns the new index (unchanged if no candidate).
     */
    moveFocusSpatial(list, index, direction) {
        if (!list.length) return 0;
        const i = Math.max(0, Math.min(list.length - 1, index | 0));
        const current = list[i];
        if (!current || typeof current.getBoundingClientRect !== 'function') {
            return this.applyFocus(list, i);
        }
        const curRect = current.getBoundingClientRect();
        const cx = curRect.left + curRect.width / 2;
        const cy = curRect.top + curRect.height / 2;
        const rowSlop = Math.max(18, curRect.height * 0.75);
        const colSlop = Math.max(24, curRect.width * 0.6);

        let best = -1;
        let bestScore = Infinity;
        for (let n = 0; n < list.length; n++) {
            if (n === i) continue;
            const el = list[n];
            if (!el || typeof el.getBoundingClientRect !== 'function') continue;
            const r = el.getBoundingClientRect();
            if (r.width <= 0 && r.height <= 0) continue;
            const x = r.left + r.width / 2;
            const y = r.top + r.height / 2;
            const dx = x - cx;
            const dy = y - cy;
            const absDx = Math.abs(dx);
            const absDy = Math.abs(dy);

            let ok = false;
            let primary = 0;
            let secondary = 0;
            if (direction === 'up') {
                ok = dy < -4;
                primary = -dy;
                secondary = absDx;
                if (absDx <= colSlop) secondary *= 0.15;
            } else if (direction === 'down') {
                ok = dy > 4;
                primary = dy;
                secondary = absDx;
                if (absDx <= colSlop) secondary *= 0.15;
            } else if (direction === 'left') {
                ok = dx < -4;
                primary = -dx;
                secondary = absDy;
                if (absDy <= rowSlop) secondary *= 0.1;
            } else if (direction === 'right') {
                ok = dx > 4;
                primary = dx;
                secondary = absDy;
                if (absDy <= rowSlop) secondary *= 0.1;
            }
            if (!ok) continue;
            const score = primary + secondary * 2.5;
            if (score < bestScore) {
                bestScore = score;
                best = n;
            }
        }
        if (best < 0) return i;
        return this.applyFocus(list, best);
    }
}

const menuNavHelper = new MenuNavHelper();
window.menuNavHelper = menuNavHelper;


/* --- js/core/ui-dialog.js?v=btn-1 --- */
"use strict";

/**
 * Shared in-game modal dialogs — replaces window.confirm / alert / prompt so
 * every modal wears the app + faction styling and speaks the same keyboard
 * language (←/→/↑/↓ move, ENTER confirm, ESC cancel).
 *
 *   uiDialog.confirm('Delete?').then((ok) => { ... });
 *   uiDialog.alert('Saved.');
 *   uiDialog.prompt('Name', 'Default').then((value) => { ... }); // null = cancelled
 *
 * While open, the dialog swallows keys in the capture phase so the overlay
 * underneath never reacts to them.
 */
class UIDialog {
    constructor() {
        this._active = null;
    }

    get isOpen() {
        return !!this._active;
    }

    confirm(message, opts = {}) {
        return this._open({
            message,
            title: opts.title,
            buttons: [
                { label: opts.cancelLabel || 'CANCEL', value: false, cancel: true },
                { label: opts.okLabel || 'OK', value: true, primary: true, danger: !!opts.danger }
            ]
        });
    }

    alert(message, opts = {}) {
        return this._open({
            message,
            title: opts.title,
            buttons: [{ label: opts.okLabel || 'OK', value: undefined, primary: true, cancel: true }]
        });
    }

    prompt(message, defaultValue = '', opts = {}) {
        return this._open({
            message,
            title: opts.title,
            input: { value: defaultValue == null ? '' : String(defaultValue), maxLength: opts.maxLength },
            buttons: [
                { label: opts.cancelLabel || 'CANCEL', value: null, cancel: true },
                { label: opts.okLabel || 'OK', value: 'input', primary: true }
            ]
        });
    }

    _open(spec) {
        if (this._active) this._active.finish(this._active.cancelValue);
        return new Promise((resolve) => {
            const backdrop = document.createElement('div');
            backdrop.className = 'ui-dialog-backdrop';
            const box = document.createElement('div');
            box.className = 'ui-dialog';
            box.setAttribute('role', 'dialog');
            box.setAttribute('aria-modal', 'true');
            const faction = document.documentElement.getAttribute('data-faction');
            if (faction) box.setAttribute('data-faction', faction);

            if (spec.title) {
                const h = document.createElement('h3');
                h.className = 'ui-dialog-title';
                h.textContent = spec.title;
                box.appendChild(h);
            }
            const msg = document.createElement('p');
            msg.className = 'ui-dialog-message';
            msg.textContent = spec.message == null ? '' : String(spec.message);
            box.appendChild(msg);

            let input = null;
            if (spec.input) {
                input = document.createElement('input');
                input.type = 'text';
                input.className = 'ui-dialog-input';
                input.value = spec.input.value;
                input.autocomplete = 'off';
                input.spellcheck = false;
                if (spec.input.maxLength) input.maxLength = spec.input.maxLength;
                box.appendChild(input);
            }

            const actions = document.createElement('div');
            actions.className = 'ui-dialog-actions';
            let cancelValue;
            const buttons = spec.buttons.map((b) => {
                const btn = document.createElement('button');
                btn.type = 'button';
                btn.className = 'action-button' + (b.primary ? '' : ' secondary') + (b.danger ? ' danger' : '');
                btn.textContent = b.label;
                btn.addEventListener('click', () => finish(b.value === 'input' ? input.value : b.value));
                if (b.cancel) cancelValue = b.value;
                actions.appendChild(btn);
                return btn;
            });
            box.appendChild(actions);
            backdrop.appendChild(box);

            const previousFocus = document.activeElement;
            const focusables = input ? [input].concat(buttons) : buttons;
            let focusIdx = 0;
            const focusAt = (i) => {
                focusIdx = (i + focusables.length) % focusables.length;
                focusables.forEach((el, n) => el.classList.toggle('nav-focused', n === focusIdx));
                try { focusables[focusIdx].focus({ preventScroll: true }); } catch (e) { focusables[focusIdx].focus(); }
            };

            const onKey = (e) => {
                const onInput = input && document.activeElement === input;
                if (e.key === 'Escape') {
                    finish(cancelValue);
                } else if (e.key === 'Enter') {
                    const el = focusables[focusIdx];
                    if (onInput || !el || el === input) buttons[0].click();
                    else el.click();
                } else if (e.key === 'ArrowUp' || e.key === 'ArrowDown') {
                    if (input) focusAt(e.key === 'ArrowUp' ? 0 : Math.max(1, focusIdx));
                    else focusAt(focusIdx + (e.key === 'ArrowUp' ? -1 : 1));
                } else if ((e.key === 'ArrowLeft' || e.key === 'ArrowRight') && !onInput) {
                    const b = buttons.indexOf(focusables[focusIdx]);
                    const nb = (b + (e.key === 'ArrowLeft' ? -1 : 1) + buttons.length) % buttons.length;
                    focusAt(focusables.indexOf(buttons[nb]));
                } else if (e.key === 'Tab') {
                    focusAt(focusIdx + (e.shiftKey ? -1 : 1));
                } else if (onInput) {
                    // Let typing reach the text field, but not the overlays below.
                    e.stopImmediatePropagation();
                    return;
                } else {
                    return;
                }
                e.preventDefault();
                e.stopImmediatePropagation();
            };
            const swallow = (e) => {
                if (e.target && box.contains(e.target)) return;
                e.stopImmediatePropagation();
            };
            backdrop.addEventListener('mousedown', (e) => {
                if (e.target === backdrop) e.preventDefault();
            });

            const finish = (value) => {
                if (!this._active || this._active.box !== box) return;
                window.removeEventListener('keydown', onKey, true);
                window.removeEventListener('keyup', swallow, true);
                backdrop.remove();
                this._active = null;
                if (previousFocus && typeof previousFocus.focus === 'function' && document.contains(previousFocus)) {
                    try { previousFocus.focus({ preventScroll: true }); } catch (e) { /* ignore */ }
                }
                resolve(value);
            };

            this._active = { box, finish, cancelValue };
            window.addEventListener('keydown', onKey, true);
            window.addEventListener('keyup', swallow, true);
            document.body.appendChild(backdrop);
            if (input) {
                focusAt(0);
                input.select();
            } else {
                // Positive action sits right (last) — focus it by default.
                const primaryIdx = buttons.findIndex((b) => !b.classList.contains('secondary'));
                focusAt(primaryIdx >= 0 ? primaryIdx : 0);
            }
        });
    }
}

