"use strict";

/**
 * Game Core - Main coordinator
 * Simplified main class that coordinates all subsystems
 */
class GameCore {
    constructor() {
        // Initialize core managers
        this.gameState = new GameStateManager();
        this.levelManager = new CoreLevelManager(this.gameState);
        this.coreLevelManager = this.levelManager;
        this.systemManager = new SystemManager(this.gameState);
        this.gameControl = new GameControlSystem(this.gameState, this.levelManager, this.systemManager);

        // Game state properties
        this.obstacleSpawnTimer = 0;
        this.obstacleSpawnInterval = 2000; // 2 seconds default

        // Legacy compatibility - expose commonly used subsystems
        this.gameLoop = null;
        this.inputHandler = null;
        this.uiManager = null;
        this.cheatSystem = null;
        this.settingsManager = null;
        this.renderManager = null;
        this.levelInfoManager = null;
    }

    init() {

        // Initialize all systems
        this.systemManager.init();

        // Set up legacy compatibility
        this.setupLegacyCompatibility();

        // Theme before any paint (avoid grayscale flash → forest)
        if (typeof themeContextManager !== 'undefined') {
            themeContextManager.restoreAppTheme();
        }

        // Keep shells hidden until restore decides (avoid Start → Station hop on refresh)
        const startScreen = document.getElementById('startScreen');
        if (startScreen) startScreen.classList.add('hidden');
        const gameContainer = document.querySelector('.game-container');
        if (gameContainer) gameContainer.style.display = 'none';

        if (typeof menuStateManager !== 'undefined') {
            this.showBootVeil(menuStateManager.get());
            if (window.vfBootLoader) window.vfBootLoader.setPhase('menu', 0.9);
            setTimeout(() => {
                Promise.resolve(this.restoreMenuWhenReady())
                    .catch((err) => console.error('[boot] menu restore failed:', err))
                    .finally(() => this.dismissBootVeil());
            }, 0);
            // The map's nebula is prepared (or loaded from its stored copy) while the menu builds.
            setTimeout(() => {
                if (typeof galaxyMapManager !== 'undefined' && galaxyMapManager.prewarmNebula) galaxyMapManager.prewarmNebula();
            }, 60);
            // Failsafe: never leave the loader stuck, whatever fails above
            setTimeout(() => this.dismissBootVeil(), 8000);
        } else {
            this.showStartScreen({ skipPersist: true });
            this.dismissBootVeil();
        }

    }

    showBootVeil(state) {
        let veil = document.getElementById('vf-boot-veil');
        if (!veil) {
            veil = document.createElement('div');
            veil.id = 'vf-boot-veil';
            document.body.appendChild(veil);
        }
        // Keep the loading panel; layer destination art behind it while systems finish.
        const loader = document.getElementById('vf-boot-loader');
        veil.className = 'vf-boot-veil vf-boot-veil-loading';
        if (loader) veil.appendChild(loader);
        document.documentElement.classList.add('vf-booting');
        veil.removeAttribute('data-hs-tab');
        veil.style.pointerEvents = 'auto';
        const screen = state && state.screen;
        if (screen === 'home-station') {
            veil.classList.add('vf-boot-veil-hs');
            veil.dataset.hsTab = (state && state.tab) || 'station';
        } else if (
            !screen ||
            screen === 'start' ||
            screen === 'settings' ||
            screen === 'credits' ||
            screen === 'profiles' ||
            screen === 'ingame'
        ) {
            // Same art as .start-screen (ships in hangar)
            veil.classList.add('vf-boot-veil-start');
        } else if (screen === 'theme-editor') {
            veil.classList.add('vf-boot-veil-start');
        } else {
            veil.classList.add('vf-boot-veil-menu');
        }
        if (window.vfBootLoader) window.vfBootLoader.setPhase('assets', 0.86);
    }

    // Menu is built under the veil — finish the loader, then drop the cover.
    dismissBootVeil() {
        const veil = document.getElementById('vf-boot-veil');
        if (!veil) {
            if (window.vfBootLoader && !window.vfBootLoader.isFinished()) {
                window.vfBootLoader.finish({ instant: true });
            }
            return;
        }
        if (veil.dataset.vfDismissed === '1') return;
        veil.dataset.vfDismissed = '1';
        document.querySelectorAll('.vf-menu-enter').forEach((el) => el.classList.remove('vf-menu-enter'));
        if (window.vfBootLoader && !window.vfBootLoader.isFinished()) {
            window.vfBootLoader.setPhase('ready', 1);
            window.vfBootLoader.finish();
            setTimeout(() => {
                if (veil.parentNode) veil.parentNode.removeChild(veil);
                document.documentElement.classList.remove('vf-booting');
            }, 360);
            return;
        }
        if (veil.parentNode) veil.parentNode.removeChild(veil);
        setTimeout(() => document.documentElement.classList.remove('vf-booting'), 800);
    }

    async restoreMenuWhenReady() {
        const state = (typeof menuStateManager !== 'undefined') ? menuStateManager.get() : null;
        const screen = state && state.screen;
        const lightMenu = !screen || screen === 'start' || screen === 'settings' || screen === 'credits' || screen === 'profiles';

        const warm = document.documentElement.getAttribute('data-vf-load') === 'refresh';
        if (!lightMenu && !warm) {
            if (window.vfBootLoader) window.vfBootLoader.setPhase('assets', 0.88);
            // Short wait for icons/ships — boot veil already shows destination art
            const deadline = Date.now() + 600;
            while (Date.now() < deadline) {
                const spritesReady = typeof spriteLoader !== 'undefined' && spriteLoader.isLoaded();
                const shipsReady = typeof graphicsManager !== 'undefined'
                    && graphicsManager.shipAssetLoader
                    && graphicsManager.shipAssetLoader.isLoaded();
                if (spritesReady && shipsReady) break;
                await new Promise((resolve) => setTimeout(resolve, 30));
            }
            if (typeof spriteLoader !== 'undefined' && spriteLoader.whenLoaded) {
                await spriteLoader.whenLoaded(400);
            }
        }

        if (typeof themeContextManager !== 'undefined') {
            themeContextManager.restoreAppTheme();
        }

        // Pixel font must be ready before the menu paints, otherwise the
        // fallback→Silkscreen swap makes the layout jump under the veil fade
        if (window.vfBootLoader) window.vfBootLoader.setPhase('font', 0.9);
        if (document.fonts && document.fonts.load) {
            await Promise.race([
                document.fonts.load("700 16px 'Silkscreen'").catch(() => {}),
                new Promise((resolve) => setTimeout(resolve, warm ? 250 : 800))
            ]);
        }
        if (window.vfBootLoader) window.vfBootLoader.setPhase('menu', 0.95);

        const restored = menuStateManager.restore();
        if (!restored) {
            this.showStartScreen({ skipPersist: true });
            menuStateManager.setScreen('start');
        }
        // Boot intro only on a fresh app start (not a refresh of a running session)
        // and not when we resume straight into the home station
        const landedScreen = menuStateManager.get() && menuStateManager.get().screen;
        let alreadyRunning = false;
        try {
            alreadyRunning = sessionStorage.getItem('vf_app_running_v1') === '1';
            sessionStorage.setItem('vf_app_running_v1', '1');
        } catch (e) { /* storage blocked — treat as fresh start */ }
        const inStation = landedScreen === 'home-station'
            || (typeof homeStationUI !== 'undefined' && homeStationUI.isVisible);
        if (!alreadyRunning && !inStation && typeof VFStartIntro !== 'undefined') {
            VFStartIntro.play({
                title: (typeof startScreenManager !== 'undefined' && startScreenManager.title) || 'GLXEE',
                subtitle: (typeof startScreenManager !== 'undefined' && startScreenManager.subtitle) || ''
            });
        }
        // Let start-screen / station paint under the veil, then fade
        if (typeof VFBgMouseParallax !== 'undefined' && VFBgMouseParallax.refresh) {
            VFBgMouseParallax.refresh();
        }
        requestAnimationFrame(() => {
            if (typeof VFBgMouseParallax !== 'undefined' && VFBgMouseParallax.refresh) {
                VFBgMouseParallax.refresh();
            }
            requestAnimationFrame(() => this.dismissBootVeil());
        });
    }

    setupLegacyCompatibility() {
        // Expose subsystems for backward compatibility
        this.gameLoop = this.systemManager.getSubsystem('gameLoop');
        this.inputHandler = this.systemManager.getSubsystem('inputHandler');
        this.uiManager = this.systemManager.getSubsystem('uiManager');
        this.cheatSystem = this.systemManager.getSubsystem('cheatSystem');
        this.settingsManager = this.systemManager.getSubsystem('settingsManager');
        this.renderManager = this.systemManager.getSubsystem('renderManager');
        this.levelInfoManager = this.systemManager.getSubsystem('levelInfoManager');

        // Make managers globally available
        if (this.uiManager) {
            window.uiManager = this.uiManager;
        }
        if (this.settingsManager) {
            window.settingsManager = this.settingsManager;
        }
        if (typeof colorManager !== 'undefined') {
            window.colorManager = colorManager;
        }
        if (typeof startScreenManager !== 'undefined') {
            window.startScreenManager = startScreenManager;
        }

        // Make game globally available
        window.game = this;
        this.width = this.gameState.width;
        this.height = this.gameState.height;
        this.baseWidth = this.gameState.width;
        this.baseHeight = this.gameState.height;
        this.internalWidth = this.gameState.width;
        this.internalHeight = this.gameState.height;

        if (typeof window.viewportFit !== 'undefined' && window.viewportFit.update) {
            window.viewportFit.update();
        }
    }

    // Main game control methods
    startGame(levelId = 'mars') {
        return this.gameControl.startGame(levelId);
    }

    restart() {
        return this.restartGame();
    }

    restartGame() {
        // Reset obstacle spawn timer
        this.obstacleSpawnTimer = 0;
        return this.gameControl.restartGame();
    }

    stopGame() {
        this.gameControl.stopGame();
    }

    pauseGame() {
        this.gameControl.pauseGame();
    }

    resumeGame() {
        this.gameControl.resumeGame();
    }

    gameOver() {
        this.gameControl.gameOver();
    }

    playerWins() {
        this.gameControl.playerWins();
    }

    quitToMainMenu() {
        this.gameControl.quitToMainMenu();
    }

    showLevelSelection() {
        this.gameControl.showLevelSelection();
    }
}


/* --- js/core/core/show-start-screen.js --- */
"use strict";

// GameCore methods, split from core.js.
extendClass(GameCore, {
    showStartScreen(options) {
        const skipPersist = options && options.skipPersist;
        if (typeof themeContextManager !== 'undefined') {
            themeContextManager.restoreAppTheme();
        }

        // Initialize and show StartScreenManager (routes to Station when profile loaded)
        if (typeof startScreenManager !== 'undefined') {
            startScreenManager.returnToHub({ skipPersist: !!skipPersist });
        } else {
            const startScreen = document.getElementById('startScreen');
            if (startScreen) {
                startScreen.classList.remove('hidden');
            }
        }

        // Hide level info panel
        const levelInfoPanel = document.getElementById('levelInfoPanel');
        if (levelInfoPanel) {
            levelInfoPanel.style.display = 'none';
        }

        // Hide game container
        const gameContainer = document.querySelector('.game-container');
        if (gameContainer) {
            gameContainer.style.display = 'none';
        }

        if (!skipPersist && typeof menuStateManager !== 'undefined') {
            const current = menuStateManager.get();
            if (!current || current.screen === 'ingame') {
                if (typeof profileManager !== 'undefined' && profileManager.hasActiveProfile()) {
                    menuStateManager.setScreen('home-station', { tab: 'station' });
                } else {
                    menuStateManager.setScreen('start');
                }
            }
        }
    },

    hideStartScreen() {
        const startScreen = document.getElementById('startScreen');
        if (startScreen) {
            startScreen.classList.add('hidden');
        }

        // Hide StartScreenManager
        if (typeof startScreenManager !== 'undefined') {
            startScreenManager.hide();
        }
    },

    // Level management
    setLevel(levelId) {
        return this.levelManager.setLevel(levelId);
    },

    getCurrentLevel() {
        return this.levelManager.getCurrentLevel();
    },

    nextLevel() {
        return this.gameControl.nextLevel();
    },

    previousLevel() {
        return this.gameControl.previousLevel();
    },

    // Level info management
    updateLevelInfo() {
        this.gameControl.updateLevelInfo();
    },

    updateLevelStats(stats) {
        this.gameControl.updateLevelStats(stats);
    },

    // Settings management (delegated to settings manager)
    updateColorSetting(color) {
        if (this.settingsManager) {
            this.settingsManager.updateColorSetting(color);
        }
    },

    changeColor() {
        if (this.settingsManager) {
            this.settingsManager.changeColor();
        }
    },

    changeDifficulty() {
        if (this.settingsManager) {
            this.settingsManager.changeDifficulty();
        }
    },

    toggleSound() {
        if (this.settingsManager) {
            this.settingsManager.toggleSound();
        }
    },

    toggleMusic() {
        if (this.settingsManager) {
            this.settingsManager.toggleMusic();
        }
    },

    showSettings() {
        if (this.settingsManager) {
            this.settingsManager.showSettings();
        }
    },

    hideSettings() {
        if (this.settingsManager) {
            this.settingsManager.hideSettings();
        }
    },

    // UI management (delegated to UI manager)
    handleKeyDown(event) {
        if (this.inputHandler) {
            this.inputHandler.handleKeyDown(event);
        }
    },

    handleGameOverInput(event) {
        if (this.uiManager) {
            this.uiManager.handleGameOverInput(event);
        }
    },

    updateGameOverMenuDisplay() {
        if (this.uiManager) {
            this.uiManager.updateGameOverMenuDisplay();
        }
    },

    selectGameOverOption() {
        if (this.uiManager) {
            this.uiManager.selectGameOverOption();
        }
    },

    // Cheat system (delegated to cheat system)
    toggleCheatMenu() {
        if (this.cheatSystem) {
            this.cheatSystem.toggleCheatMenu();
        }
    },

    toggleLevelSelect() {
        if (this.cheatSystem) {
            this.cheatSystem.toggleLevelSelect();
        }
    },

    // Game state access
    getGameState() {
        return this.gameState;
    },

    getLevelManager() {
        return this.levelManager;
    },

    getSystemManager() {
        return this.systemManager;
    },

    getGameControl() {
        return this.gameControl;
    },

    // Status and debugging
    getStatus() {
        return {
            gameState: this.gameState.getStats(),
            levelManager: {
                currentLevel: this.levelManager.getCurrentLevel(),
                availableLevels: this.levelManager.getAvailableLevels()
            },
            systemManager: this.systemManager.getStatus()
        };
    },

    // Cleanup
    cleanup() {
        this.systemManager.cleanup();
    },
});


/* --- js/core/core.js --- */
"use strict";

// GameCore is defined in core/core.js and extended by the other files in core/,
// which index.html loads before this file.
// Global game instance
let game;


/* --- js/game/sounds/core.js --- */
"use strict";

// Procedural Web Audio sound system with named event profiles
class SoundManager {
    constructor() {
        this.audioContext = null;
        this.enabled = true;
        this.soundEnabled = true;
        this.musicEnabled = true;
        this.activeTimeouts = [];
        this.masterVolume = 0.1;
        this.soundVolume = 0.05;
        this.musicVolume = 0.2;

        this.ambientNodes = null;
        this.ambientPlanetId = null;
        this.ambientGain = null;

        this.weaponFamilies = {
            laser: 'laser',
            pierce: 'laser',
            claw_beam: 'laser',
            spread: 'spread',
            burst: 'spread',
            spike_burst: 'spread',
            rapid: 'rapid',
            plasma: 'soft',
            ion: 'soft',
            wave: 'soft',
            missile: 'punch',
            nova: 'punch'
        };

        this.planetAmbient = {
            mars: { base: 55, filter: 420, type: 'sawtooth', lfo: 0.08 },
            jupiter: { base: 40, filter: 280, type: 'triangle', lfo: 0.05 },
            saturn: { base: 70, filter: 900, type: 'sine', lfo: 0.12 },
            neptune: { base: 90, filter: 1400, type: 'sine', lfo: 0.06 },
            pluto: { base: 120, filter: 1800, type: 'triangle', lfo: 0.15 }
        };
    }

    /**
     * Soft boot only — do not create AudioContext here. Browsers block
     * autoplay; creating the context before a user gesture logs a console
     * warning and leaves it suspended anyway. ensureContext() opens it
     * on the first play / gesture.
     */
    init() {
        this.enabled = !!(window.AudioContext || window.webkitAudioContext);
    }

    ensureContext() {
        if (!this.enabled) return null;
        if (!this.audioContext) {
            // Avoid the autoplay console warning: do not construct until
            // the document has seen a real user activation.
            if (navigator.userActivation && !navigator.userActivation.hasBeenActive) {
                return null;
            }
            try {
                this.audioContext = new (window.AudioContext || window.webkitAudioContext)();
            } catch (e) {
                this.enabled = false;
                return null;
            }
        }
        if (this.audioContext.state === 'suspended') {
            this.audioContext.resume().catch(() => {});
        }
        return this.audioContext;
    }

    sfxVolume(scale) {
        const s = scale == null ? 1 : scale;
        return Math.max(0.0001, 0.12 * this.masterVolume * this.soundVolume * s);
    }

    musicVol(scale) {
        const s = scale == null ? 1 : scale;
        return Math.max(0.0001, 0.08 * this.masterVolume * this.musicVolume * s);
    }

    canPlaySfx() {
        return !!(this.enabled && this.ensureContext() && this.soundEnabled);
    }

    canPlayMusic() {
        return !!(this.enabled && this.ensureContext() && this.musicEnabled);
    }

    // --- Synth primitives ---

    createBeep(frequency, duration, type, volumeScale) {
        if (!this.canPlaySfx()) return;
        const ctx = this.audioContext;
        const now = ctx.currentTime;
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.type = type || 'sine';
        osc.frequency.setValueAtTime(Math.max(20, frequency), now);
        const vol = this.sfxVolume(volumeScale);
        gain.gain.setValueAtTime(0.0001, now);
        gain.gain.exponentialRampToValueAtTime(vol, now + 0.008);
        gain.gain.exponentialRampToValueAtTime(0.0001, now + Math.max(0.02, duration));
        osc.start(now);
        osc.stop(now + duration + 0.02);
    }

    createSweep(startFreq, endFreq, duration, type, volumeScale) {
        if (!this.canPlaySfx()) return;
        const ctx = this.audioContext;
        const now = ctx.currentTime;
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.type = type || 'sine';
        const start = Math.max(40, startFreq);
        const end = Math.max(40, endFreq);
        osc.frequency.setValueAtTime(start, now);
        osc.frequency.exponentialRampToValueAtTime(end, now + duration);
        const vol = this.sfxVolume(volumeScale);
        gain.gain.setValueAtTime(0.0001, now);
        gain.gain.linearRampToValueAtTime(vol, now + 0.01);
        gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);
        osc.start(now);
        osc.stop(now + duration + 0.02);
    }

    createNoiseBurst(duration, volumeScale, filterFreq) {
        if (!this.canPlaySfx()) return;
        const ctx = this.audioContext;
        const now = ctx.currentTime;
        const len = Math.max(1, Math.floor(ctx.sampleRate * duration));
        const buffer = ctx.createBuffer(1, len, ctx.sampleRate);
        const data = buffer.getChannelData(0);
        for (let i = 0; i < len; i++) {
            data[i] = (Math.random() * 2 - 1) * (1 - i / len);
        }
        const src = ctx.createBufferSource();
        src.buffer = buffer;
        const filter = ctx.createBiquadFilter();
        filter.type = 'lowpass';
        filter.frequency.setValueAtTime(filterFreq || 800, now);
        filter.frequency.exponentialRampToValueAtTime(120, now + duration);
        const gain = ctx.createGain();
        const vol = this.sfxVolume(volumeScale);
        gain.gain.setValueAtTime(vol, now);
        gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);
        src.connect(filter);
        filter.connect(gain);
        gain.connect(ctx.destination);
        src.start(now);
        src.stop(now + duration + 0.02);
    }

    createDualTone(freq1, freq2, duration, type, volumeScale) {
        if (!this.canPlaySfx()) return;
        this.createBeep(freq1, duration, type || 'sine', (volumeScale || 1) * 0.7);
        this.createBeep(freq2, duration, type || 'sine', (volumeScale || 1) * 0.5);
    }

    schedule(fn, delayMs) {
        const id = setTimeout(fn, delayMs);
        this.activeTimeouts.push(id);
        return id;
    }

    clearActiveTimeouts() {
        this.activeTimeouts.forEach((timeout) => clearTimeout(timeout));
        this.activeTimeouts = [];
    }

    // --- Event API ---

    play(eventId, opts) {
        const id = String(eventId || '').toLowerCase();
        const o = opts || {};
        switch (id) {
            case 'shoot':
            case 'weaponshoot':
                this.playWeaponShoot(o.weaponId || o.weapon || 'laser');
                break;
            case 'enemyshoot':
                this.playEnemyShoot(o.kind);
                break;
            case 'hit':
                this.playHit();
                break;
            case 'kill':
                this.playKill(o.scale);
                break;
            case 'explosion':
                this.playExplosion(o.scale);
                break;
            case 'reflect':
                this.playReflect();
                break;
            case 'hurt':
                this.playHurt();
                break;
            case 'powerup':
                this.playPowerUp();
                break;
            case 'gameover':
                this.playGameOver();
                break;
            case 'victory':
                this.playVictory();
                break;
            default:
                break;
        }
    }

    playWeaponShoot(weaponId) {
        const family = this.weaponFamilies[weaponId] || 'laser';
        switch (family) {
            case 'spread':
                this.createSweep(900, 500, 0.08, 'square', 0.7);
                this.schedule(() => this.createSweep(750, 420, 0.06, 'square', 0.45), 30);
                this.schedule(() => this.createSweep(820, 480, 0.06, 'square', 0.4), 55);
                break;
            case 'rapid':
                this.createSweep(1600, 900, 0.06, 'sine', 0.55);
                break;
            case 'soft':
                this.createSweep(480, 220, 0.18, 'triangle', 0.9);
                this.createBeep(180, 0.12, 'sine', 0.35);
                break;
            case 'punch':
                this.createNoiseBurst(0.08, 0.8, 500);
                this.createSweep(220, 80, 0.2, 'sawtooth', 0.85);
                break;
            case 'laser':
            default:
                this.createSweep(1200, 600, 0.14, 'sine', 0.8);
                break;
        }
    }

    playShoot() {
        this.playWeaponShoot('laser');
    }

    playEnemyShoot(kind) {
        const k = String(kind || 'laser').toLowerCase();
        if (k.indexOf('plasma') !== -1) {
            this.createSweep(320, 140, 0.12, 'sawtooth', 0.75);
        } else if (k.indexOf('spread') !== -1 || k.indexOf('burst') !== -1) {
            this.createSweep(700, 350, 0.07, 'square', 0.65);
            this.schedule(() => this.createSweep(620, 300, 0.05, 'square', 0.4), 25);
        } else if (k.indexOf('rapid') !== -1) {
            this.createSweep(1000, 550, 0.05, 'square', 0.5);
        } else {
            this.createSweep(780, 320, 0.1, 'sawtooth', 0.7);
        }
    }

    playHit() {
        this.createNoiseBurst(0.04, 0.55, 2200);
        this.createBeep(420, 0.04, 'triangle', 0.4);
    }

    playKill(scale) {
        const s = scale == null ? 1 : scale;
        this.createNoiseBurst(0.18 * s, 1.1 * s, 900);
        this.createSweep(280, 70, 0.22 * s, 'sawtooth', 0.9 * s);
        this.schedule(() => this.createBeep(90, 0.12, 'sine', 0.5 * s), 80);
    }

    playExplosion(scale) {
        const s = scale == null ? 1.15 : scale;
        this.createNoiseBurst(0.25 * s, 1.2 * s, 700);
        this.createSweep(200, 50, 0.28 * s, 'sawtooth', s);
        this.schedule(() => this.createNoiseBurst(0.1 * s, 0.6 * s, 400), 90);
    }

    playReflect() {
        this.createDualTone(1400, 2100, 0.06, 'sine', 0.7);
        this.createSweep(1800, 900, 0.08, 'triangle', 0.5);
    }

    playHurt() {
        this.createNoiseBurst(0.07, 0.7, 600);
        this.createSweep(260, 110, 0.16, 'triangle', 0.85);
    }
}


/* --- js/game/sounds/play-game-over.js --- */
"use strict";

// SoundManager methods, split from sounds.js.
extendClass(SoundManager, {
    playGameOver() {
        this.clearActiveTimeouts();
        this.stopPlanetAmbientNodesOnly();
        this.ambientPlanetId = null;
        this.createBeep(300, 0.3, 'sine', 0.9);
        this.schedule(() => this.createBeep(250, 0.3, 'sine', 0.85), 300);
        this.schedule(() => this.createBeep(200, 0.5, 'sine', 0.9), 600);
        if (typeof beatSyncManager !== 'undefined') beatSyncManager.stop();
    },

    playVictory() {
        this.clearActiveTimeouts();
        this.stopPlanetAmbientNodesOnly();
        this.ambientPlanetId = null;
        this.createBeep(500, 0.2, 'sine', 0.85);
        this.schedule(() => this.createBeep(600, 0.2, 'sine', 0.85), 200);
        this.schedule(() => this.createBeep(700, 0.2, 'sine', 0.9), 400);
        this.schedule(() => this.createBeep(800, 0.3, 'sine', 1), 600);
        if (typeof beatSyncManager !== 'undefined') beatSyncManager.stop();
    },

    playPowerUp() {
        this.clearActiveTimeouts();
        this.createBeep(600, 0.1, 'square', 0.8);
        this.schedule(() => this.createBeep(800, 0.1, 'square', 0.85), 100);
        this.schedule(() => this.createBeep(1000, 0.2, 'square', 0.95), 200);
    },

    // --- Planet ambient (music bus) ---

    startPlanetAmbient(planetId) {
        const id = String(planetId || 'mars').toLowerCase().split('-')[0];
        this.ambientPlanetId = id;
        this.stopPlanetAmbientNodesOnly();

        if (typeof youtubeSoundtrackManager !== 'undefined' && youtubeSoundtrackManager.hasPlanetTrack(id)) {
            if (!this.musicEnabled) {
                youtubeSoundtrackManager.setEnabled(false);
                if (typeof beatSyncManager !== 'undefined') beatSyncManager.start(id);
                return;
            }
            youtubeSoundtrackManager.setEnabled(true);
            youtubeSoundtrackManager.setVolume(this.masterVolume * this.musicVolume);
            youtubeSoundtrackManager.playPlanet(id);
            if (typeof beatSyncManager !== 'undefined') {
                beatSyncManager.start(id);
            }
            return;
        }
        if (typeof youtubeSoundtrackManager !== 'undefined') {
            youtubeSoundtrackManager.stop();
        }
        if (!this.canPlayMusic()) {
            if (typeof beatSyncManager !== 'undefined') {
                beatSyncManager.start(id);
            }
            return;
        }

        const profile = this.planetAmbient[id] || this.planetAmbient.mars;
        const ctx = this.audioContext;
        const now = ctx.currentTime;

        const osc = ctx.createOscillator();
        const osc2 = ctx.createOscillator();
        const filter = ctx.createBiquadFilter();
        const gain = ctx.createGain();
        const lfo = ctx.createOscillator();
        const lfoGain = ctx.createGain();

        osc.type = profile.type;
        osc2.type = 'sine';
        osc.frequency.setValueAtTime(profile.base, now);
        osc2.frequency.setValueAtTime(profile.base * 1.5, now);

        filter.type = 'lowpass';
        filter.frequency.setValueAtTime(profile.filter, now);
        filter.Q.setValueAtTime(0.7, now);

        lfo.type = 'sine';
        lfo.frequency.setValueAtTime(profile.lfo, now);
        lfoGain.gain.setValueAtTime(profile.filter * 0.35, now);
        lfo.connect(lfoGain);
        lfoGain.connect(filter.frequency);

        const vol = this.musicVol(0.35);
        gain.gain.setValueAtTime(0.0001, now);
        gain.gain.linearRampToValueAtTime(vol, now + 1.2);

        osc.connect(filter);
        osc2.connect(filter);
        filter.connect(gain);
        gain.connect(ctx.destination);

        osc.start(now);
        osc2.start(now);
        lfo.start(now);

        this.ambientGain = gain;
        this.ambientNodes = { osc, osc2, filter, gain, lfo, lfoGain };

        if (typeof beatSyncManager !== 'undefined') {
            beatSyncManager.start(id);
        }
    },

    stopPlanetAmbientNodesOnly() {
        if (!this.ambientNodes) return;
        const nodes = this.ambientNodes;
        const ctx = this.audioContext;
        try {
            if (this.ambientGain && ctx) {
                const now = ctx.currentTime;
                this.ambientGain.gain.cancelScheduledValues(now);
                this.ambientGain.gain.setValueAtTime(Math.max(0.0001, this.ambientGain.gain.value), now);
                this.ambientGain.gain.linearRampToValueAtTime(0.0001, now + 0.25);
            }
            const stopAt = (ctx ? ctx.currentTime : 0) + 0.3;
            if (nodes.osc) nodes.osc.stop(stopAt);
            if (nodes.osc2) nodes.osc2.stop(stopAt);
            if (nodes.lfo) nodes.lfo.stop(stopAt);
        } catch (e) {
            // ignore stop races
        }
        this.ambientNodes = null;
        this.ambientGain = null;
    },

    stopPlanetAmbient() {
        this.stopPlanetAmbientNodesOnly();
        if (typeof youtubeSoundtrackManager !== 'undefined' && youtubeSoundtrackManager.mode === 'planet') {
            youtubeSoundtrackManager.stop();
        }
        if (typeof beatSyncManager !== 'undefined') {
            beatSyncManager.stop();
        }
        // keep ambientPlanetId so music toggle can restart
    },

    setPlanetAmbient(planetId) {
        this.startPlanetAmbient(planetId);
    },

    startMenuMusic() {
        if (typeof youtubeSoundtrackManager === 'undefined') return;
        youtubeSoundtrackManager.setVolume(this.masterVolume * this.musicVolume);
        youtubeSoundtrackManager.setEnabled(!!this.musicEnabled);
        if (!this.musicEnabled || !youtubeSoundtrackManager.hasMenuTrack()) {
            youtubeSoundtrackManager.stop();
            return;
        }
        this.stopPlanetAmbientNodesOnly();
        this.ambientPlanetId = null;
        youtubeSoundtrackManager.playMenu();
    },

    stopMenuMusic() {
        if (typeof youtubeSoundtrackManager !== 'undefined' && youtubeSoundtrackManager.mode === 'menu') {
            youtubeSoundtrackManager.stop();
        }
    },

    updateAmbientVolume() {
        if (typeof youtubeSoundtrackManager !== 'undefined') {
            youtubeSoundtrackManager.setVolume(this.masterVolume * this.musicVolume);
        }
        if (!this.ambientGain || !this.audioContext) return;
        const now = this.audioContext.currentTime;
        const vol = this.musicEnabled ? this.musicVol(0.35) : 0.0001;
        this.ambientGain.gain.cancelScheduledValues(now);
        this.ambientGain.gain.linearRampToValueAtTime(vol, now + 0.15);
    },

    // --- Volume / settings ---

    setMasterVolume(volume) {
        this.masterVolume = Math.max(0, Math.min(1, volume));
        this.updateAmbientVolume();
    },

    setSoundVolume(volume) {
        this.soundVolume = Math.max(0, Math.min(1, volume));
    },

    setMusicVolume(volume) {
        this.musicVolume = Math.max(0, Math.min(1, volume));
        this.updateAmbientVolume();
    },

    getMasterVolume() {
        return this.masterVolume;
    },

    getSoundVolume() {
        return this.soundVolume;
    },

    getMusicVolume() {
        return this.musicVolume;
    },

    setSoundEnabled(enabled) {
        this.soundEnabled = !!enabled;
    },

    setEnabled(enabled) {
        this.setSoundEnabled(enabled);
    },

    setMusicEnabled(enabled) {
        this.musicEnabled = !!enabled;
        if (typeof youtubeSoundtrackManager !== 'undefined') {
            youtubeSoundtrackManager.setEnabled(this.musicEnabled);
        }
        if (!this.musicEnabled) {
            this.stopPlanetAmbientNodesOnly();
            if (typeof youtubeSoundtrackManager !== 'undefined') {
                youtubeSoundtrackManager.pause();
            }
        } else if (this.ambientPlanetId) {
            this.startPlanetAmbient(this.ambientPlanetId);
        } else if (typeof youtubeSoundtrackManager !== 'undefined' && youtubeSoundtrackManager.hasMenuTrack()) {
            this.startMenuMusic();
        }
    },

    getSoundEnabled() {
        return this.soundEnabled;
    },

    getMusicEnabled() {
        return this.musicEnabled;
    },
});


/* --- js/game/sounds.js --- */
"use strict";

// SoundManager is defined in sounds/core.js and extended by the other files in sounds/,
// which index.html loads before this file.
const soundManager = new SoundManager();

function resumeSoundContext() {
    // Opens (or resumes) the AudioContext after a real user gesture.
    if (typeof soundManager.ensureContext === 'function') soundManager.ensureContext();
}

document.addEventListener('pointerdown', resumeSoundContext, { once: true, capture: true });
document.addEventListener('keydown', resumeSoundContext, { once: true, capture: true });
document.addEventListener('touchstart', resumeSoundContext, { once: true, capture: true });


/* --- js/game/youtube-soundtrack/core.js --- */
"use strict";

/**
 * YouTube IFrame background soundtracks for menu + planets.
 * Stores menu URL in localStorage; planet URLs live on planet configs.
 */
class YouTubeSoundtrackManager {
    constructor() {
        this.storageKey = 'vf_youtube_soundtracks_v1';
        this.menuUrl = '';
        this.apiReady = false;
        this.apiLoading = false;
        this.player = null;
        this.playerReady = false;
        this.pending = null;
        this.currentKey = null;
        this.currentVideoId = null;
        this.mode = null; // 'menu' | 'planet' | null
        this.enabled = true;
        this.volume = 0.2;
        this.hostEl = null;
        this.load();
        // Do not load the YouTube iframe API on boot — it sets cross-site
        // cookies (SameSite warnings) even when no track is configured.
        // loadApi() runs from _playVideo when a menu/planet URL is actually played.
    }

    load() {
        try {
            const raw = localStorage.getItem(this.storageKey);
            if (!raw) return;
            const data = JSON.parse(raw);
            this.menuUrl = (data && data.menuUrl) ? String(data.menuUrl) : '';
        } catch (e) {
            this.menuUrl = '';
        }
    }

    save() {
        try {
            localStorage.setItem(this.storageKey, JSON.stringify({
                menuUrl: this.menuUrl || ''
            }));
        } catch (e) {
            // ignore
        }
    }

    getMenuUrl() {
        return this.menuUrl || '';
    }

    setMenuUrl(url) {
        this.menuUrl = String(url || '').trim();
        this.save();
        if (this.mode === 'menu') {
            if (this.menuUrl) this.playMenu();
            else this.stop();
        }
    }

    extractVideoId(input) {
        const raw = String(input || '').trim();
        if (!raw) return null;
        if (/^[\w-]{11}$/.test(raw)) return raw;

        let url;
        try {
            url = new URL(raw);
        } catch (e) {
            return null;
        }

        const host = (url.hostname || '').replace(/^www\./, '').toLowerCase();
        if (host === 'youtu.be') {
            const id = url.pathname.split('/').filter(Boolean)[0] || '';
            return /^[\w-]{11}$/.test(id) ? id : null;
        }
        if (host === 'youtube.com' || host === 'm.youtube.com' || host === 'music.youtube.com') {
            const v = url.searchParams.get('v');
            if (v && /^[\w-]{11}$/.test(v)) return v;
            const parts = url.pathname.split('/').filter(Boolean);
            if (parts[0] === 'embed' || parts[0] === 'shorts' || parts[0] === 'live') {
                const id = parts[1] || '';
                return /^[\w-]{11}$/.test(id) ? id : null;
            }
        }
        return null;
    }

    getPlanetUrl(planetId) {
        if (typeof planetConfigManager === 'undefined') return '';
        const cfg = planetConfigManager.getConfig(planetId);
        return (cfg && cfg.soundtrackUrl) ? String(cfg.soundtrackUrl) : '';
    }

    ensureHost() {
        if (this.hostEl && document.body.contains(this.hostEl)) return this.hostEl;
        let el = document.getElementById('vfYtSoundtrack');
        if (!el) {
            el = document.createElement('div');
            el.id = 'vfYtSoundtrack';
            el.setAttribute('aria-hidden', 'true');
            el.style.cssText = 'position:fixed;left:-9999px;top:0;width:1px;height:1px;opacity:0;pointer-events:none;overflow:hidden;z-index:-1;';
            const player = document.createElement('div');
            player.id = 'vfYtPlayer';
            el.appendChild(player);
            document.body.appendChild(el);
        }
        this.hostEl = el;
        return el;
    }

    loadApi() {
        if (this.apiReady || this.apiLoading) return;
        if (typeof window.YT !== 'undefined' && window.YT.Player) {
            this.apiReady = true;
            this.flushPending();
            return;
        }
        this.apiLoading = true;
        const prev = window.onYouTubeIframeAPIReady;
        window.onYouTubeIframeAPIReady = () => {
            this.apiReady = true;
            this.apiLoading = false;
            if (typeof prev === 'function') {
                try { prev(); } catch (e) { /* ignore */ }
            }
            this.flushPending();
        };
        if (!document.querySelector('script[src*="youtube.com/iframe_api"]')) {
            const tag = document.createElement('script');
            tag.src = 'https://www.youtube.com/iframe_api';
            tag.async = true;
            document.head.appendChild(tag);
        }
    }

    flushPending() {
        if (!this.pending) return;
        const job = this.pending;
        this.pending = null;
        this._playVideo(job.key, job.videoId, job.mode);
    }

    setEnabled(enabled) {
        this.enabled = !!enabled;
        if (!this.enabled) {
            this.pause();
            return;
        }
        if (this.mode === 'menu') this.playMenu();
        else if (this.mode === 'planet' && this.currentKey) {
            this.playPlanet(this.currentKey);
        }
    }

    setVolume(volume) {
        this.volume = Math.max(0, Math.min(1, Number(volume) || 0));
        this.applyVolume();
    }

    applyVolume() {
        if (!this.player || !this.playerReady || typeof this.player.setVolume !== 'function') return;
        try {
            const pct = Math.round(this.volume * 100);
            this.player.setVolume(pct);
            if (pct <= 0 || !this.enabled) this.player.mute();
            else this.player.unMute();
        } catch (e) {
            // ignore
        }
    }

    playMenu() {
        const videoId = this.extractVideoId(this.menuUrl);
        if (!videoId) {
            if (this.mode === 'menu') this.stop();
            return false;
        }
        return this._playVideo('menu', videoId, 'menu');
    }

    playPlanet(planetId) {
        const id = String(planetId || '').toLowerCase().split('-')[0];
        const videoId = this.extractVideoId(this.getPlanetUrl(id));
        if (!videoId) {
            if (this.mode === 'planet' && this.currentKey === id) this.stop();
            return false;
        }
        return this._playVideo(id, videoId, 'planet');
    }

    hasPlanetTrack(planetId) {
        const id = String(planetId || '').toLowerCase().split('-')[0];
        return !!this.extractVideoId(this.getPlanetUrl(id));
    }

    hasMenuTrack() {
        return !!this.extractVideoId(this.menuUrl);
    }

    _playVideo(key, videoId, mode) {
        if (!this.enabled) {
            this.mode = mode;
            this.currentKey = key;
            this.currentVideoId = videoId;
            return false;
        }
        this.ensureHost();
        this.mode = mode;
        this.currentKey = key;
        this.currentVideoId = videoId;

        // Defer iframe_api until a real user gesture — loading it on boot
        // rejects YouTube's SameSite cookies and spams the console even when
        // playback cannot start yet.
        if (navigator.userActivation && !navigator.userActivation.hasBeenActive) {
            this.pending = { key, videoId, mode };
            this._armGestureUnlock();
            return true;
        }

        this.loadApi();

        if (this.playerReady && this.currentVideoId === videoId && this.mode === mode) {
            this.resume();
            return true;
        }

        if (!this.apiReady) {
            this.pending = { key, videoId, mode };
            return true;
        }

        if (this.player && this.playerReady && typeof this.player.loadVideoById === 'function') {
            try {
                this.player.loadVideoById({ videoId: videoId, startSeconds: 0 });
                this.applyVolume();
                this.player.playVideo();
            } catch (e) {
                this._createPlayer(videoId);
            }
            return true;
        }

        this._createPlayer(videoId);
        return true;
    }

    _armGestureUnlock() {
        if (this._gestureArmed) return;
        this._gestureArmed = true;
        const unlock = () => {
            this._gestureArmed = false;
            if (!this.enabled || !this.currentVideoId) return;
            const job = this.pending || {
                key: this.currentKey,
                videoId: this.currentVideoId,
                mode: this.mode
            };
            this.pending = job;
            this.loadApi();
        };
        document.addEventListener('pointerdown', unlock, { once: true, capture: true });
        document.addEventListener('keydown', unlock, { once: true, capture: true });
        document.addEventListener('touchstart', unlock, { once: true, capture: true });
    }
}


/* --- js/game/youtube-soundtrack/create-player.js --- */
"use strict";

// YouTubeSoundtrackManager methods, split from youtube-soundtrack.js.
extendClass(YouTubeSoundtrackManager, {
    _createPlayer(videoId) {
        this.ensureHost();
        const mount = document.getElementById('vfYtPlayer');
        if (!mount || typeof window.YT === 'undefined' || !window.YT.Player) return;

        if (this.player && typeof this.player.destroy === 'function') {
            try { this.player.destroy(); } catch (e) { /* ignore */ }
        }
        this.player = null;
        this.playerReady = false;
        mount.innerHTML = '';

        this.player = new window.YT.Player('vfYtPlayer', {
            height: '1',
            width: '1',
            videoId: videoId,
            playerVars: {
                autoplay: 1,
                controls: 0,
                disablekb: 1,
                fs: 0,
                modestbranding: 1,
                playsinline: 1,
                rel: 0,
                loop: 1,
                playlist: videoId,
                origin: window.location.origin
            },
            events: {
                onReady: (event) => {
                    this.playerReady = true;
                    this.applyVolume();
                    try {
                        if (this.enabled) event.target.playVideo();
                        else event.target.pauseVideo();
                    } catch (e) { /* ignore */ }
                },
                onStateChange: (event) => {
                    if (event.data === window.YT.PlayerState.PLAYING
                        && this.mode === 'planet'
                        && typeof beatSyncManager !== 'undefined') {
                        beatSyncManager.restartFromNow();
                    }
                    // Loop fallback if playlist loop fails
                    if (event.data === window.YT.PlayerState.ENDED && this.currentVideoId) {
                        try {
                            event.target.seekTo(0);
                            event.target.playVideo();
                        } catch (e) { /* ignore */ }
                    }
                },
                onError: () => {
                    console.warn('YouTube soundtrack failed to play:', this.currentVideoId);
                }
            }
        });
    },

    resume() {
        if (!this.enabled || !this.player || !this.playerReady) return;
        try {
            this.applyVolume();
            this.player.playVideo();
        } catch (e) { /* ignore */ }
    },

    pause() {
        if (!this.player || !this.playerReady) return;
        try {
            this.player.pauseVideo();
        } catch (e) { /* ignore */ }
    },

    stop() {
        this.pending = null;
        this.mode = null;
        this.currentKey = null;
        this.currentVideoId = null;
        if (!this.player || !this.playerReady) return;
        try {
            this.player.stopVideo();
        } catch (e) { /* ignore */ }
    },
});


