/* --- js/game/bullets/get-weapon-icon-key-part2.js?v=voxel-all-1 --- */
"use strict";

// BulletManager members, continued from get-weapon-icon-key.js (kept under ~500 lines per file).
extendClass(BulletManager, {
    shootWithShipWeapon(playerPosition, currentTime, options) {
        const opts = options || {};
        let maxBullets = 6; // Increased for multi-weapon systems
        if (typeof game !== 'undefined' && game.cheats && game.cheats.infiniteAmmo) {
            maxBullets = 999;
        }

        const jammerMul = (typeof enemyManager !== 'undefined' && enemyManager.getJammerCooldownMul)
            ? enemyManager.getJammerCooldownMul()
            : 1;

        // Every equipped weapon fires simultaneously from its own mount,
        // each gated by its own cooldown clock — a twin-cannon loadout
        // fires both guns independently rather than cycling one at a time.
        let firedAny = false;
        this.getWeaponFirePositions(playerPosition).forEach((slot) => {
            // The ALL key (default Space) fires every slot; any other key fires
            // only the slots assigned to it. Calls without a key fire all.
            if (opts.fireKey && opts.fireKey !== 'all' && (slot.fireKey || 'space') !== opts.fireKey) return;
            // Weapons slotted later aren't in the ship's own weaponConfig
            // (built from its stock weapons): use the weapon's defaults.
            const weaponConfig = this.currentShipModel.weaponConfig[slot.id]
                || (typeof weaponConfigManager !== 'undefined' && weaponConfigManager.getDefaultsForShip
                    ? weaponConfigManager.getDefaultsForShip(slot.id) : null);
            if (!weaponConfig) return;
            // Ability effects (ability-stats.js): higher fire rate = shorter cooldown.
            const abilityRate = Number(this.currentShipModel.abilityFireRateMul) || 1;
            let cooldown = weaponConfig.cooldown * jammerMul / abilityRate;
            // RAPID FIRE power-up (power-crates.js).
            if (typeof pickupManager !== 'undefined' && pickupManager.getFireRateMul) cooldown *= pickupManager.getFireRateMul();
            if (opts.cooldownMul && opts.cooldownMul > 0 && opts.cooldownMul < 1) {
                cooldown *= opts.cooldownMul;
            }
            const lastFired = this.weaponCooldowns[slot.key] || 0;
            if (currentTime - lastFired < cooldown) return;
            if (this.bullets.length >= maxBullets) return;

            this.weaponCooldowns[slot.key] = currentTime;
            this.lastShotTime = currentTime;

            const cfg = Object.assign({}, weaponConfig);
            // Mount strength: a nose weapon is one concentrated gun (+25%);
            // a wing weapon is split across both wings and weaker: 45% per
            // side (90% for the pair) — the nose gun always hits hardest.
            const mountMul = slot.mount === 'wing' ? 0.45 : 1.25;
            // Hull class: weapons the ship type is built around hit harder.
            const classMul = typeof weaponConfigManager !== 'undefined' && weaponConfigManager.getShipClassWeaponMul
                ? weaponConfigManager.getShipClassWeaponMul(this.currentShipModel.modelClass, slot.id) : 1;
            // Faction: each faction fights best with one weapon family.
            const factionMul = typeof weaponConfigManager !== 'undefined' && weaponConfigManager.getFactionWeaponMul
                ? weaponConfigManager.getFactionWeaponMul(this.getShipFactionId(), slot.id) : 1;
            const abilityDmg = Number(this.currentShipModel.abilityDamageMul) || 1;
            // Temporary power-up from supply crates.
            const powerShot = (typeof pickupManager !== 'undefined' && pickupManager.getPowerShot)
                ? pickupManager.getPowerShot() : null;
            const powerMul = powerShot ? powerShot.damage : 1;
            cfg.damage = Math.max(1, Math.round((cfg.damage || 10) * mountMul * classMul * factionMul * abilityDmg * powerMul));
            if (opts.chargeMult && opts.chargeMult > 1) {
                const cm = Math.min(1.75, opts.chargeMult);
                cfg.damage = Math.round((cfg.damage || 10) * opts.chargeMult);
                cfg.speed = (cfg.speed || 6) * (1 + (cm - 1) * 0.15);
                // Bonus shots keep their size; they are drawn brighter instead
                // (bullet.bonusGlow, see drawBullet).
                cfg._charged = true;
                cfg._chargeMult = opts.chargeMult;
            }
            if (typeof weaponConfigManager !== 'undefined' && weaponConfigManager.clampWeaponShot) {
                weaponConfigManager.clampWeaponShot(cfg);
            }
            const firstNew = this.bullets.length;
            this.fireWeaponByType(slot.id, slot.position, cfg, false);
            // Tag shots with their weapon so they render in its type colour.
            // Shot size follows the slot size class: S 0.6×, M 1×, L 1.5× the
            // weapon's base shot (at least 1 × 3 px, so S stays visible).
            // Shot size: slot class (S/M/L) × Settings → Player Shots.
            // Applied after spawn so clampBulletSize cannot crush the setting.
            const shotScale = Number(opts.shotScale) || 1;
            const appearanceMul = (typeof uiAppearanceManager !== 'undefined'
                && uiAppearanceManager.getShotSizeMul)
                ? uiAppearanceManager.getShotSizeMul('player') : 1;
            const sizeMul = ([0.6, 1, 1.5][slot.sizeLevel != null ? slot.sizeLevel : 1] || 1)
                * (powerShot ? powerShot.size : 1)
                * appearanceMul;
            for (let i = firstNew; i < this.bullets.length; i++) {
                const b = this.bullets[i];
                b.weaponId = slot.id;
                // 0..1 brightness boost from the charge / beat bonus.
                if (powerShot) b.bonusGlow = Math.max(b.bonusGlow || 0, 0.8);
                if (cfg._charged) b.bonusGlow = Math.max(0, Math.min(1, ((cfg._chargeMult || 1) - 1) / 0.75));
                const cx = b.x + (b.width || 0) / 2;
                // Keep fractional sizes so S→XXL stays visible (not snapped to 1–3).
                b.width = Math.max(1, (b.width || 2) * sizeMul) * shotScale;
                b.height = Math.max(3, (b.height || 8) * sizeMul) * shotScale;
                if (shotScale !== 1) b.speed = (b.speed || 6) * shotScale;
                if (b.lightRadius) b.lightRadius = Math.max(6, b.lightRadius * Math.sqrt(Math.max(0.3, appearanceMul)));
                b.x = cx - b.width / 2;
            }
            if (slot.muzzle) this.addMuzzleFlash(slot, cfg);
            firedAny = true;
        });
        return firedAny;
    },
    fireWeaponByType(weaponId, position, config, isEnemy) {
        const id = String(weaponId || 'laser');
        let cfg = config || (typeof weaponConfigManager !== 'undefined'
            ? weaponConfigManager.getDefaultsForShip(id)
            : {});
        if (typeof weaponConfigManager !== 'undefined' && weaponConfigManager.clampWeaponShot) {
            cfg = weaponConfigManager.clampWeaponShot(Object.assign({}, cfg));
        }
        if (isEnemy) {
            switch (id) {
                case 'spread':
                case 'burst':
                case 'nova':
                    this.enemyShootSpread(position, Object.assign({
                        bulletCount: id === 'nova' ? 5 : (id === 'burst' ? 2 : 2),
                        spreadAngle: id === 'nova' ? 0.5 : (id === 'burst' ? 0.4 : 0.3)
                    }, cfg));
                    break;
                case 'rapid':
                case 'ion':
                    this.enemyShootRapid(position, Object.assign({ bulletCount: 2 }, cfg));
                    break;
                case 'plasma':
                case 'missile':
                    this.enemyShootPlasma(position, cfg);
                    break;
                case 'wave':
                    this.enemyShootLaser(position, Object.assign({}, cfg, { typeHint: 'enemy_wave' }));
                    break;
                case 'pierce':
                    this.enemyShootLaser(position, Object.assign({ width: 2, height: 10 }, cfg));
                    break;
                default:
                    this.enemyShootLaser(position, cfg);
            }
            return;
        }
        switch (id) {
            case 'claw_beam':
                this.shootClawBeam(position, cfg);
                break;
            case 'spread':
                this.shootSpreadWeapon(position, cfg);
                break;
            case 'rapid':
                this.shootRapidWeapon(position, cfg);
                break;
            case 'plasma':
                this.shootPlasma(position, cfg);
                break;
            case 'missile':
                this.shootMissile(position, cfg);
                break;
            case 'ion':
                this.shootIon(position, cfg);
                break;
            case 'wave':
                this.shootWave(position, cfg);
                break;
            case 'burst':
                this.shootBurst(position, cfg);
                break;
            case 'pierce':
                this.shootPierce(position, cfg);
                break;
            case 'nova':
                this.shootNova(position, cfg);
                break;
            case 'laser':
            default:
                this.shootLaser(position, cfg);
                break;
        }
    },
});


/* --- js/game/bullets/shoot-with-legacy-system.js?v=shot-size-2 --- */
"use strict";

// BulletManager methods, split from bullets.js.
extendClass(BulletManager, {
    shootWithLegacySystem(playerPosition, options) {
        const opts = options || {};
        const currentType = this.shotTypes[this.shotType];
        let maxBullets = 4;

        // Check for infinite ammo cheat
        if (typeof game !== 'undefined' && game.cheats && game.cheats.infiniteAmmo) {
            maxBullets = 999;
        }

        // Check if we can shoot based on current bullet count
        if (this.bullets.length >= maxBullets) {
            return false;
        }

        const chargeMult = opts.chargeMult || 1;

        switch (currentType) {
            case 'normal':
            case 'laser':
                this.shootNormal(playerPosition, chargeMult);
                break;
            case 'spread':
                this.shootSpread(playerPosition);
                break;
            case 'rapid':
                this.shootRapid(playerPosition);
                break;
            default:
                this.fireWeaponByType(currentType, playerPosition, {
                    damage: Math.round(10 * chargeMult),
                    speed: 6,
                    _charged: chargeMult > 1,
                    _chargeMult: chargeMult
                }, false);
                break;
        }

        return true; // Shot was fired successfully
    },

    shootNormal(playerPosition, chargeMult) {
        const mult = chargeMult || 1;
        const bullet = {
            x: playerPosition.x + playerPosition.width / 2 - 1.5,
            y: playerPosition.y,
            // Bonus shots keep the base size and glow brighter instead.
            width: 2,
            height: 8,
            bonusGlow: Math.max(0, Math.min(1, (mult - 1) / 0.75)),
            speed: 6 * (1 + (mult - 1) * 0.15),
            damage: Math.round(10 * mult),
            color: '#808080', // Grayscale base - will be colored by render system
            type: 'laser_beam',
            charged: mult > 1,
            // Lighting properties
            lightRadius: 18 * (0.8 + mult * 0.2),
            lightIntensity: 1.2 * mult,
            lightColor: '#808080' // Grayscale base
        };
        this.bullets.push(bullet);
    },

    shootSpread(playerPosition) {
        // Shoot 3 bullets in spread pattern (but respect bullet limit)
        const angles = [-0.3, 0, 0.3];
        const maxBullets = 4;

        angles.forEach(angle => {
            if (this.bullets.length < maxBullets) {
                const bullet = {
                    x: playerPosition.x + playerPosition.width / 2 - 1.5,
                    y: playerPosition.y,
                    width: 2,
                    height: 8,
                    speed: 5,
                    damage: 8,
                    angle: angle,
                    color: '#808080', // Grayscale base - will be colored by render system
                    type: 'spread_beam',
                    // Lighting properties
                    lightRadius: 14,
                    lightIntensity: 1.0,
                    lightColor: '#808080' // Grayscale base
                };
                this.bullets.push(bullet);
            }
        });
    },

    shootRapid(playerPosition) {
        // Shoot 2 bullets rapidly (but respect bullet limit)
        const maxBullets = 4;

        for (let i = 0; i < 2; i++) {
            if (this.bullets.length < maxBullets) {
                const bullet = {
                    x: playerPosition.x + playerPosition.width / 2 - 1.5 + (i * 4),
                    y: playerPosition.y,
                    width: 2,
                    height: 8,
                    speed: 7,
                    damage: 6,
                    color: '#808080', // Grayscale base - will be colored by render system
                    type: 'rapid_beam',
                    // Lighting properties
                    lightRadius: 12,
                    lightIntensity: 0.9,
                    lightColor: '#808080' // Grayscale base
                };
                this.bullets.push(bullet);
            }
        }
    },

    // New ship-specific weapon methods
    shootLaser(playerPosition, config) {
        const charged = !!(config && config._charged);
        const mult = (config && config._chargeMult) || 1;
        const w = (config && config.width) || 3;
        const h = (config && config.height) || 12;
        const bullet = {
            x: playerPosition.x + playerPosition.width / 2 - w / 2,
            y: playerPosition.y,
            width: w,
            height: h,
            speed: config.speed,
            damage: config.damage,
            color: '#808080', // Grayscale base - will be colored by render system
            type: 'laser_beam',
            charged: charged,
            // Lighting properties
            lightRadius: 18 * (0.8 + mult * 0.2),
            lightIntensity: 1.2 * Math.max(1, mult * 0.85),
            lightColor: '#808080' // Grayscale base
        };
        this.bullets.push(bullet);
    },

    shootSpreadWeapon(playerPosition, config) {
        const bulletCount = config.bulletCount || 3;
        const spreadAngle = config.spreadAngle || 0.3;
        const angles = [];

        // Calculate spread angles
        for (let i = 0; i < bulletCount; i++) {
            const angle = (i - (bulletCount - 1) / 2) * spreadAngle;
            angles.push(angle);
        }

        angles.forEach(angle => {
            if (this.bullets.length < 6) { // Max bullets for spread
                const w = (config && config.width) || 2;
                const h = (config && config.height) || 8;
                const bullet = {
                    x: playerPosition.x + playerPosition.width / 2 - w / 2,
                    y: playerPosition.y,
                    width: w,
                    height: h,
                    speed: config.speed,
                    damage: config.damage,
                    angle: angle,
                    color: '#808080', // Grayscale base - will be colored by render system
                    type: 'spread_beam',
                    // Lighting properties
                    lightRadius: 14,
                    lightIntensity: 1.0,
                    lightColor: '#808080' // Grayscale base
                };
                this.bullets.push(bullet);
            }
        });
    },

    shootRapidWeapon(playerPosition, config) {
        const bulletCount = config.bulletCount || 2;
        const w = (config && config.width) || 2;
        const h = (config && config.height) || 8;

        for (let i = 0; i < bulletCount; i++) {
            if (this.bullets.length < 6) {
                const bullet = {
                    x: playerPosition.x + playerPosition.width / 2 - w / 2 + (i - (bulletCount - 1) / 2) * (w + 1),
                    y: playerPosition.y,
                    width: w,
                    height: h,
                    speed: config.speed,
                    damage: config.damage,
                    color: '#808080', // Grayscale base - will be colored by render system
                    type: 'rapid_beam',
                    // Lighting properties
                    lightRadius: 12,
                    lightIntensity: 0.9,
                    lightColor: '#808080' // Grayscale base
                };
                this.bullets.push(bullet);
            }
        }
    },

    shootPlasma(playerPosition, config) {
        const bullet = {
            x: playerPosition.x + playerPosition.width / 2 - (config.width || 4) / 2,
            y: playerPosition.y,
            width: config.width || 4,
            height: config.height || 8,
            speed: config.speed,
            damage: config.damage,
            color: '#808080',
            type: 'plasma_beam',
            lightRadius: 22,
            lightIntensity: 1.5,
            lightColor: '#808080'
        };
        this.bullets.push(bullet);
    },

    shootMissile(playerPosition, config) {
        const bullet = {
            x: playerPosition.x + playerPosition.width / 2 - (config.width || 5) / 2,
            y: playerPosition.y,
            width: config.width || 5,
            height: config.height || 14,
            speed: config.speed || 4,
            damage: config.damage || 28,
            color: '#808080',
            type: 'missile_shot',
            lightRadius: 16,
            lightIntensity: 1.1,
            lightColor: '#808080'
        };
        this.bullets.push(bullet);
    },

    shootIon(playerPosition, config) {
        const count = config.bulletCount || 3;
        const spacing = config.bulletSpacing || 5;
        const start = playerPosition.x + playerPosition.width / 2 - ((count - 1) * spacing) / 2 - 1.5;
        for (let i = 0; i < count; i++) {
            if (this.bullets.length >= 8) break;
            this.bullets.push({
                x: start + i * spacing,
                y: playerPosition.y,
                width: config.width || 3,
                height: config.height || 10,
                speed: config.speed || 11,
                damage: config.damage || 7,
                color: '#808080',
                type: 'ion_beam',
                lightRadius: 14,
                lightIntensity: 1.0,
                lightColor: '#808080'
            });
        }
    },

    shootWave(playerPosition, config) {
        this.bullets.push({
            x: playerPosition.x + playerPosition.width / 2 - (config.width || 4) / 2,
            y: playerPosition.y,
            width: config.width || 4,
            height: config.height || 10,
            speed: config.speed || 8,
            damage: config.damage || 9,
            color: '#808080',
            type: 'wave_beam',
            waveAmp: config.waveAmp || 1.2,
            wavePhase: 0,
            lightRadius: 18,
            lightIntensity: 1.1,
            lightColor: '#808080'
        });
    },
});


/* --- js/game/bullets/shoot-burst.js?v=shot-size-2 --- */
"use strict";

// BulletManager methods, split from bullets.js.
extendClass(BulletManager, {
    shootBurst(playerPosition, config) {
        const bulletCount = config.bulletCount || 5;
        const spreadAngle = config.spreadAngle || 0.45;
        for (let i = 0; i < bulletCount; i++) {
            if (this.bullets.length >= 8) break;
            const angle = (i - (bulletCount - 1) / 2) * spreadAngle;
            this.bullets.push({
                x: playerPosition.x + playerPosition.width / 2 - 1.5,
                y: playerPosition.y,
                width: config.width || 3,
                height: config.height || 8,
                speed: config.speed || 9,
                damage: config.damage || 5,
                angle: angle,
                color: '#808080',
                type: 'burst_shot',
                lightRadius: 12,
                lightIntensity: 0.85,
                lightColor: '#808080'
            });
        }
    },

    /**
     * Claw Beam: two lances from the outer edges of the mount, angled inwards
     * so they cross a short way ahead (a pincer), then fan out again. Laser
     * by contrast is one straight centred beam.
     */
    shootClawBeam(playerPosition, config) {
        const w = config.width || 3;
        const h = config.height || 14;
        const speed = config.speed || 13;
        // Lances start this far apart and meet ~5 bullet-lengths ahead.
        const half = Math.max(4, (config.bulletSpacing || 6) + playerPosition.width * 0.25);
        const meet = h * 5;
        const angle = Math.atan2(half, meet);
        [-1, 1].forEach((side) => {
            this.bullets.push({
                x: playerPosition.x + playerPosition.width / 2 + side * half - w / 2,
                y: playerPosition.y,
                width: w,
                height: h,
                speed: speed,
                damage: config.damage || 11,
                // Negative side (left) steers right and vice versa.
                angle: -side * angle,
                color: '#808080',
                type: 'pierce_beam',
                charged: !!config._charged,
                lightRadius: config.lightRadius || 40,
                lightIntensity: config.lightIntensity || 1.1,
                lightColor: '#808080'
            });
        });
    },

    shootPierce(playerPosition, config) {
        this.bullets.push({
            x: playerPosition.x + playerPosition.width / 2 - (config.width || 2) / 2,
            y: playerPosition.y,
            width: config.width || 2,
            height: config.height || 18,
            speed: config.speed || 16,
            damage: config.damage || 14,
            color: '#808080',
            type: 'pierce_beam',
            pierce: true,
            lightRadius: 20,
            lightIntensity: 1.3,
            lightColor: '#808080'
        });
    },

    shootNova(playerPosition, config) {
        const bulletCount = config.bulletCount || 5;
        const spreadAngle = config.spreadAngle || 0.55;
        for (let i = 0; i < bulletCount; i++) {
            if (this.bullets.length >= 8) break;
            const angle = (i - (bulletCount - 1) / 2) * spreadAngle;
            this.bullets.push({
                x: playerPosition.x + playerPosition.width / 2 - 2,
                y: playerPosition.y,
                width: config.width || 4,
                height: config.height || 8,
                speed: config.speed || 7,
                damage: config.damage || 6,
                angle: angle,
                color: '#808080',
                type: 'nova_shot',
                lightRadius: 22,
                lightIntensity: 1.4,
                lightColor: '#808080'
            });
        }
    },

    /**
     * Share of the gun's width that is barrel, per weapon (from the gun art):
     * shots come out of the barrel, so their width follows it.
     */
    getBarrelFraction(weaponId) {
        return ({
            laser: 0.25, laser_twin: 0.14, railgun: 0.25, spread: 0.2, rapid: 0.14,
            burst: 0.25, plasma: 0.5, claw_beam: 0.2, spike_burst: 0.2, ion: 0.25,
            wave: 0.4, nova: 0.4, missile: 0.3, pierce: 0.2
        })[String(weaponId || '')] || 0.3;
    },

    /**
     * Resize bullets added since `from` so their width matches the barrel of
     * a gun `gunWidth` wide (proportions kept, centre kept). Shots only
     * shrink to the barrel; `maxGrow` (> 1, from a bigger slot size) lets
     * them grow up to that factor of their base size, never past the barrel.
     */
    fitBulletsToBarrel(list, from, gunWidth, weaponId, maxGrow) {
        if (!(gunWidth > 0)) return;
        // Floor at 2 px so Settings → Shot Size still has room to scale up/down.
        const target = Math.max(2, gunWidth * this.getBarrelFraction(weaponId));
        const grow = Math.max(1, Number(maxGrow) || 1);
        for (let i = from; i < list.length; i++) {
            const b = list[i];
            const bw = b.width != null ? b.width : b.w;
            if (!(bw > 0)) continue;
            const s = Math.max(0.3, Math.min(grow, target / bw));
            if (s === 1) continue;
            const cx = b.x + bw / 2;
            const nw = Math.max(1, bw * s);
            if (b.width != null) {
                b.width = nw;
                b.height = Math.max(3, (b.height || 8) * s);
            } else {
                b.w = nw;
                b.h = Math.max(3, (b.h || 8) * s);
            }
            b.x = cx - nw / 2;
        }
    },

    /** Apply Settings → Shot Size (player / enemy / boss) to new bullets. */
    applyShotSizeSetting(list, from, kind) {
        if (!list || !(from >= 0)) return;
        const mul = (typeof uiAppearanceManager !== 'undefined' && uiAppearanceManager.getShotSizeMul)
            ? uiAppearanceManager.getShotSizeMul(kind || 'enemy') : 1;
        if (!(mul > 0) || Math.abs(mul - 1) < 0.01) return;
        for (let i = from; i < list.length; i++) {
            const b = list[i];
            if (!b) continue;
            const bw = b.width != null ? b.width : b.w;
            const bh = b.height != null ? b.height : b.h;
            if (!(bw > 0)) continue;
            const cx = b.x + bw / 2;
            const nw = Math.max(1, Math.round(bw * mul * 100) / 100);
            const nh = Math.max(3, Math.round((bh || 8) * mul * 100) / 100);
            if (b.width != null) {
                b.width = nw;
                b.height = nh;
            } else {
                b.w = nw;
                b.h = nh;
            }
            b.x = cx - nw / 2;
            if (b.lightRadius) b.lightRadius = Math.max(6, b.lightRadius * Math.sqrt(mul));
        }
    },

    /** Weapon an enemy carries (drawn on its hull and fired). */
    getEnemyWeaponId(enemy) {
        if (enemy && enemy.weaponId) return enemy.weaponId;
        const m = (typeof enemyManager !== 'undefined' && enemyManager.currentEnemyModel) || null;
        return (m && m.weaponConfig && m.defaultWeapon) || 'laser';
    },

    /**
     * Enemy gun width in game px, by the weapon's size class on the same scale
     * as player guns (an S mount is ~3 px on the player ship): S 3, M 4.5, L 6.
     */
    getEnemyGunWidth(enemy) {
        const id = this.getEnemyWeaponId(enemy);
        const lv = (typeof shipLoadoutManager !== 'undefined' && shipLoadoutManager.getPartSizeLevel)
            ? shipLoadoutManager.getPartSizeLevel('weapon', id) : 0;
        const cs = (typeof game !== 'undefined' && game && game.contentScale) ? Number(game.contentScale) || 1 : 1;
        const base = [3, 4.5, 6][Math.max(0, Math.min(2, lv))] * cs;
        // Side craft use the same visual scale as their hull. This keeps guns
        // and shots from reading larger than the ship carrying them.
        const scale = enemy && enemy.weaponScale != null
            ? Math.max(0.45, Math.min(1, Number(enemy.weaponScale) || 1)) : 1;
        return base * scale;
    },

    enemyShoot(enemy) {
        if (!enemy) return;
        // Never spawn shots from hulls that are still / already off the playfield.
        const W = (typeof game !== 'undefined' && (game.internalWidth || game.width)) || 240;
        const H = (typeof game !== 'undefined' && (game.internalHeight || game.height)) || 300;
        if (enemy.entering
            || enemy.x + (enemy.width || 0) < 0 || enemy.x > W
            || enemy.y + (enemy.height || 0) < 0 || enemy.y > H) {
            return;
        }

        const currentTime = Date.now();

        // Check cooldown - prevent shooting too frequently
        if (currentTime - this.lastEnemyShotTime < this.enemyShotCooldown) {
            return;
        }

        // Check maximum enemy bullets on screen
        if (this.enemyBullets.length >= this.maxEnemyBullets) {
            return;
        }

        // Get enemy ship model for weapon configuration
        let enemyModel = null;
        if (typeof enemyManager !== 'undefined' && enemyManager.currentEnemyModel) {
            enemyModel = enemyManager.currentEnemyModel;
        }

        // The weapon this enemy carries (drawn on its hull), else the model's.
        let weaponId = this.getEnemyWeaponId(enemy);
        const hasCfg = (enemyModel && enemyModel.weaponConfig && enemyModel.weaponConfig[weaponId])
            || (typeof weaponConfigManager !== 'undefined' && weaponConfigManager.getDefaultsForShip);
        if (hasCfg) {
            this.enemyShootWithWeapon(enemy, enemyModel, weaponId);
        } else {
            // Fallback to default enemy weapon
            const before = this.enemyBullets.length;
            this.enemyShootDefault(enemy);
            this.fitBulletsToBarrel(this.enemyBullets, before, this.getEnemyGunWidth(enemy), weaponId);
            this.applyShotSizeSetting(this.enemyBullets, before,
                enemy && enemy.isBoss ? 'boss' : 'enemy');
        }

        if (typeof soundManager !== 'undefined') {
            soundManager.playEnemyShoot(weaponId);
        }

        if (typeof profileManager !== 'undefined' && profileManager.discover) {
            profileManager.discover('weapons', weaponId);
            if (enemy && enemy.type && profileManager.discoverEnemyContents) {
                profileManager.discoverEnemyContents(enemy.type);
            }
        }

        // Update last shot time
        this.lastEnemyShotTime = currentTime;
    },

    enemyShootWithWeapon(enemy, enemyModel, weaponId) {
        const defaultWeapon = weaponId || (enemyModel && enemyModel.defaultWeapon) || 'laser';
        // The model's tuning for this weapon, else the weapon's own defaults.
        const weaponConfig = (enemyModel && enemyModel.weaponConfig && enemyModel.weaponConfig[defaultWeapon])
            || (typeof weaponConfigManager !== 'undefined' && weaponConfigManager.getDefaultsForShip
                ? weaponConfigManager.getDefaultsForShip(defaultWeapon) : null);

        if (!weaponConfig) {
            this.enemyShootDefault(enemy);
            return;
        }

        const cfg = Object.assign({}, weaponConfig);
        const sideScale = enemy && enemy.weaponScale != null
            ? Math.max(0.45, Math.min(1, Number(enemy.weaponScale) || 1)) : 1;
        if (enemy && enemy.isSideEnemy) {
            if (cfg.width != null) cfg.width *= sideScale;
            if (cfg.height != null) cfg.height *= sideScale;
        }
        // Side craft hit at half strength: escorts pressure, the champion is the threat.
        const damageMul = (enemy && enemy.damageMul != null ? enemy.damageMul : 1)
            * (enemy && enemy.isSideEnemy ? 0.5 : 1);
        if (cfg.damage != null) cfg.damage = Math.max(1, Math.round(Number(cfg.damage) * damageMul));
        if (typeof weaponConfigManager !== 'undefined' && weaponConfigManager.clampWeaponShot) {
            weaponConfigManager.clampWeaponShot(cfg);
        }
        const before = this.enemyBullets.length;
        this.fireWeaponByType(defaultWeapon, enemy, cfg, true);
        // Tag with the weapon: drawn in its type colour and shape, like player shots.
        for (let i = before; i < this.enemyBullets.length; i++) {
            this.enemyBullets[i].weaponId = defaultWeapon;
            this.enemyBullets[i].isEnemyShot = true;
        }
        this.fitBulletsToBarrel(this.enemyBullets, before, this.getEnemyGunWidth(enemy), defaultWeapon);
        this.applyShotSizeSetting(this.enemyBullets, before,
            enemy && enemy.isBoss ? 'boss' : 'enemy');
    },

    enemyShootDefault(enemy) {
        const bullet = {
            x: enemy.x + enemy.width / 2 - 1.5,
            y: enemy.y + enemy.height,
            width: 2,
            height: enemy && enemy.isSideEnemy ? Math.max(3, 8 * (enemy.weaponScale || 1)) : 8,
            speed: 2.5,
            damage: Math.max(1, Math.round(8 * (
                enemy && enemy.damageMul != null ? enemy.damageMul : 1
            ) * (enemy && enemy.isSideEnemy ? 0.5 : 1))),
            color: '#808080', // Grayscale base - will be colored by render system
            type: 'enemy_laser',
            // Lighting properties
            lightRadius: 14,
            lightIntensity: 1.0,
            lightColor: '#808080' // Grayscale base
        };
        this.enemyBullets.push(bullet);
    },

    enemyShootLaser(enemy, config) {
        // Shot size from the weapon config, like the player's shots.
        const bw = config.width || 2;
        const bullet = {
            x: enemy.x + enemy.width / 2 - bw / 2,
            y: enemy.y + enemy.height,
            width: bw,
            height: config.height || 8,
            speed: config.speed,
            damage: config.damage,
            color: '#808080', // Grayscale base - will be colored by render system
            type: 'enemy_laser',
            // Lighting properties
            lightRadius: 18,
            lightIntensity: 1.2,
            lightColor: '#808080' // Grayscale base
        };
        this.enemyBullets.push(bullet);
    },

    enemyShootSpread(enemy, config) {
        // Limit spread shots to maximum 2 bullets to stay within 3 total limit
        const bulletCount = Math.min(config.bulletCount || 3, 2);
        const spreadAngle = config.spreadAngle || 0.3;
        const angles = [];

        // Calculate spread angles
        for (let i = 0; i < bulletCount; i++) {
            const angle = (i - (bulletCount - 1) / 2) * spreadAngle;
            angles.push(angle);
        }

        angles.forEach(angle => {
            const bw = config.width || 2;
            const bullet = {
                x: enemy.x + enemy.width / 2 - bw / 2,
                y: enemy.y + enemy.height,
                width: bw,
                height: config.height || 8,
                speed: config.speed,
                damage: config.damage,
                angle: angle,
                color: '#808080', // Grayscale base - will be colored by render system
                type: 'enemy_spread',
                // Lighting properties
                lightRadius: 14,
                lightIntensity: 1.0,
                lightColor: '#808080' // Grayscale base
            };
            this.enemyBullets.push(bullet);
        });
    },

    enemyShootRapid(enemy, config) {
        // Limit rapid shots to maximum 2 bullets to stay within 3 total limit
        const bulletCount = Math.min(config.bulletCount || 2, 2);

        for (let i = 0; i < bulletCount; i++) {
            const bw = config.width || 2;
            const bullet = {
                x: enemy.x + enemy.width / 2 - bw / 2 + (i - (bulletCount - 1) / 2) * (bw + 1),
                y: enemy.y + enemy.height,
                width: bw,
                height: config.height || 8,
                speed: config.speed,
                damage: config.damage,
                color: '#808080', // Grayscale base - will be colored by render system
                type: 'enemy_rapid',
                // Lighting properties
                lightRadius: 12,
                lightIntensity: 0.9,
                lightColor: '#808080' // Grayscale base
            };
            this.enemyBullets.push(bullet);
        }
    },

    enemyShootPlasma(enemy, config) {
        const bullet = {
            x: enemy.x + enemy.width / 2 - (config.width || 4) / 2,
            y: enemy.y + enemy.height,
            width: config.width || 4,
            height: config.height || 8,
            speed: config.speed,
            damage: config.damage,
            color: '#808080', // Grayscale base - will be colored by render system
            type: 'enemy_plasma',
            // Lighting properties
            lightRadius: 22,
            lightIntensity: 1.5,
            lightColor: '#808080' // Grayscale base
        };
        this.enemyBullets.push(bullet);
    },

    getBullets() {
        return this.bullets;
    },

    getEnemyBullets() {
        return this.enemyBullets;
    },

    removeBullet(index) {
        this.bullets.splice(index, 1);
    },

    removeEnemyBullet(index) {
        this.enemyBullets.splice(index, 1);
    },

    switchShotType() {
        return this.switchWeapon();
    },

    getCurrentShotType() {
        if (this.currentShipModel && this.currentWeapon) {
            return this.currentWeapon;
        }
        return this.shotTypes[this.shotType];
    },

    getCurrentWeapon() {
        return this.currentWeapon;
    },

    getAvailableWeapons() {
        if (this.currentShipModel && this.currentShipModel.availableWeapons) {
            return this.currentShipModel.availableWeapons;
        }
        return this.shotTypes;
    },
});


