                e.isEscort = false;
                e.entering = false;
                const awayX = (e.x + w * 0.5) < canvasWidth * 0.5 ? -1 : 1;
                e.speed = awayX * (1.55 + Math.random() * 0.85);
                e.verticalSpeed = -(1.55 + Math.random() * 0.75);
