        let top = rect.bottom + gap;
        if (left + panel.width > window.innerWidth - 8) {
            left = Math.max(8, window.innerWidth - panel.width - 8);
        }
        if (top + panel.height > window.innerHeight - 8) {
            top = Math.max(8, rect.top - panel.height - gap);
        }
