"use strict";

/**
 * Color palette and color management utilities
 */
class ColorPalette {
    constructor() {
        this.init();
    }

    init() {
        // Game Boy color palette (4 shades of green)
        this.palette = {
            white: '#000000',    // Black for bullets
            light: '#666666',    // Medium-dark gray
            dark: '#808080',     // Light gray
            black: '#999999'     // Bright gray for background
        };
    }

    getColor(index) {
        // Grayscale base palette — lifted floor so sprites stay readable on dark playfields
        const colorShades = [
            'transparent',  // 0
            '#2a2a2a',      // 1 - near-black (lifted)
            '#3d3d3d',      // 2 - very dark gray
            '#525252',      // 3 - dark gray
            '#686868',      // 4 - medium-dark gray
            '#7e7e7e',      // 5 - medium gray
            '#949494',      // 6 - medium-light gray
            '#adadad',      // 7 - light gray
            '#c8c8c8',      // 8 - very light gray
            '#2a2a2a',      // 9 - near-black (repeat)
            '#3d3d3d',      // 10
            '#525252',      // 11
            '#686868',      // 12
            '#7e7e7e',      // 13
            '#949494',      // 14
            '#adadad'       // 15
        ];
        
        return colorShades[index] || 'transparent';
    }

    getPlanetColor(index) {
        // Special colors for planets
        const planetColors = [
            'transparent',  // 0
            '#8B0000',      // 1 - Mars red
            '#CD5C5C',      // 2 - Light red
            '#FF6347',      // 3 - Tomato
            '#FF4500',      // 4 - Orange red
            '#FFD700',      // 5 - Gold
            '#FFA500',      // 6 - Orange
            '#FF8C00',      // 7 - Dark orange
            '#4169E1',      // 8 - Royal blue
            '#87CEEB',      // 9 - Sky blue
            '#B0C4DE',      // 10 - Light steel blue
            '#E0E0E0',      // 11 - Light gray
            '#C0C0C0',      // 12 - Silver
            '#FFFFFF',      // 13 - White
            '#F0F8FF',      // 14 - Alice blue
            '#F5F5F5'       // 15 - White smoke
        ];
        
        return planetColors[index] || 'transparent';
    }

    resolveCssColor(color) {
        if (!color || color === 'transparent') return color;
        if (typeof color === 'string' && color.indexOf('var(') === 0) {
            const match = color.match(/var\(\s*(--[^),\s]+)/);
            if (match) {
                const value = vfCssVar(match[1]);
                if (value) return value;
            }
            return '#999999';
        }
        return color;
    }

    applyColorOverlay(baseColor, overlayColor, intensity = 0.5) {
        baseColor = this.resolveCssColor(baseColor);
        overlayColor = this.resolveCssColor(overlayColor);

        // Convert hex colors to RGB
        const hexToRgb = (hex) => {
            const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
            return result ? {
                r: parseInt(result[1], 16),
                g: parseInt(result[2], 16),
                b: parseInt(result[3], 16)
            } : null;
        };

        const rgbToHex = (r, g, b) => {
            return "#" + ((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1);
        };

        const baseRgb = hexToRgb(baseColor);
        const overlayRgb = hexToRgb(overlayColor);
        
        if (!baseRgb || !overlayRgb) return baseColor;

        // Apply color overlay
        const blendedR = Math.floor(baseRgb.r + (overlayRgb.r - baseRgb.r) * intensity);
        const blendedG = Math.floor(baseRgb.g + (overlayRgb.g - baseRgb.g) * intensity);
        const blendedB = Math.floor(baseRgb.b + (overlayRgb.b - baseRgb.b) * intensity);

        return rgbToHex(blendedR, blendedG, blendedB);
    }

    applyLighting(baseColor, intensity, lightColor) {
        baseColor = this.resolveCssColor(baseColor);
        lightColor = this.resolveCssColor(lightColor);

        // Convert hex colors to RGB
        const hexToRgb = (hex) => {
            const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
            return result ? {
                r: parseInt(result[1], 16),
                g: parseInt(result[2], 16),
                b: parseInt(result[3], 16)
            } : null;
        };

        const rgbToHex = (r, g, b) => {
            return "#" + ((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1);
        };

        const baseRgb = hexToRgb(baseColor);
        const lightRgb = hexToRgb(lightColor);
        
        if (!baseRgb || !lightRgb) return baseColor;

        // Enhanced lighting with additive blending for brighter effect
        const blendedR = Math.min(255, Math.floor(baseRgb.r + lightRgb.r * intensity * 0.8));
        const blendedG = Math.min(255, Math.floor(baseRgb.g + lightRgb.g * intensity * 0.8));
        const blendedB = Math.min(255, Math.floor(baseRgb.b + lightRgb.b * intensity * 0.8));

        return rgbToHex(blendedR, blendedG, blendedB);
    }

    getPalette() {
        return this.palette;
    }
}



/* --- js/graphics/lighting-system.js?v=pull-1 --- */
"use strict";

/**
 * Lighting system for dynamic visual effects
 */
class LightingSystem {
    constructor() {
        // Empty constructor
    }

    // Lighting system for bullets
    renderLighting(ctx, bullets, obstacles, player, enemy) {
        // Create lighting effects for each bullet
        bullets.forEach(bullet => {
            if (bullet.lightRadius && bullet.lightIntensity) {
                this.renderBulletLight(ctx, bullet, obstacles, player, enemy);
            }
        });
    }

    renderBulletLight(ctx, bullet, obstacles, player, enemy) {
        const bulletCenterX = bullet.x + bullet.width / 2;
        const bulletCenterY = bullet.y + bullet.height / 2;
        
        // Soft point light — keep radius small so shots don't look like slabs
        const radius = Math.min(24, bullet.lightRadius || 14);
        const gradient = ctx.createRadialGradient(
            bulletCenterX, bulletCenterY, 0,
            bulletCenterX, bulletCenterY, radius
        );
        
        // Light falloff
        const inten = Math.min(0.55, bullet.lightIntensity || 0.4);
        gradient.addColorStop(0, `rgba(255, 255, 255, ${inten})`);
        gradient.addColorStop(0.35, `rgba(255, 255, 255, ${inten * 0.35})`);
        gradient.addColorStop(1, 'rgba(255, 255, 255, 0)');
        
        // Apply lighting to nearby objects
        ctx.save();
        ctx.globalCompositeOperation = 'screen';
        ctx.fillStyle = gradient;
        ctx.fillRect(
            bulletCenterX - radius,
            bulletCenterY - radius,
            radius * 2,
            radius * 2
        );
        ctx.restore();
        
        // Illuminate nearby obstacles
        obstacles.forEach(obstacle => {
            const distance = this.getDistance(bulletCenterX, bulletCenterY, 
                obstacle.x + obstacle.width / 2, obstacle.y + obstacle.height / 2);
            
            if (distance < radius) {
                this.illuminateObject(ctx, obstacle, bullet, distance, radius);
            }
        });
        
        // Illuminate player if nearby
        if (player) {
            const distance = this.getDistance(bulletCenterX, bulletCenterY,
                player.x + player.width / 2, player.y + player.height / 2);
            
            if (distance < radius) {
                this.illuminateObject(ctx, player, bullet, distance, radius);
            }
        }
        
        // Illuminate enemy if nearby
        if (enemy) {
            const distance = this.getDistance(bulletCenterX, bulletCenterY,
                enemy.x + enemy.width / 2, enemy.y + enemy.height / 2);
            
            if (distance < radius) {
                this.illuminateObject(ctx, enemy, bullet, distance, radius);
            }
        }
    }

    illuminateObject(ctx, object, bullet, distance, radius) {
        const r = radius || Math.min(24, bullet.lightRadius || 14);
        const intensity = Math.max(0, 1 - (distance / r));
        const illumination = intensity * Math.min(0.55, bullet.lightIntensity || 0.4) * 0.2;
        
        if (illumination > 0.08) {
            ctx.save();
            ctx.globalCompositeOperation = 'screen';
            ctx.fillStyle = `rgba(255, 255, 255, ${illumination})`;
            ctx.fillRect(object.x, object.y, object.width, object.height);
            ctx.restore();
        }
    }

    getDistance(x1, y1, x2, y2) {
        return Math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2);
    }
}



