            background: 0.04,
            backgroundLight: 0.06,
            surface: 0.05,
            shadow: 0.03,
            disabled: 0.12,
            obstacle: 0.35,
            text: 0.04,
            textSecondary: 0.06,
            textMuted: 0.08,
            textDisabled: 0.06,
            highlight: 0.12,
