/* --- js/ui/ability-editor.js --- */
"use strict";

/**
 * Ability Editor — edit shared ability metadata (icon, cluster, type, …).
 * Open: Abilities viewer → EDIT / NEW
 */
class AbilityEditorUI {
    constructor() {
        this.visible = false;
        this.returnTo = null;
        this.selectedId = 'player_control';
        this.draft = null;
    }

    init() {
        this.ensureOverlay();
    }

    ensureOverlay() {
        if (document.getElementById('abilityEditorOverlay')) return;

        const overlay = document.createElement('div');
        overlay.id = 'abilityEditorOverlay';
        overlay.className = 'planet-editor-overlay ability-editor-overlay hidden';
        overlay.innerHTML = `
            <div class="planet-editor-panel">
                <div class="planet-editor-header">
                    <h2>ABILITY EDITOR</h2>
                    <div class="planet-editor-planet-select" id="aeTypeSelect"></div>
                </div>
                <div class="planet-editor-body ae-body-single">
                    <div class="planet-editor-controls" id="aeControls"></div>
                </div>
                <div class="planet-editor-footer">
                    <button type="button" class="pe-btn" id="aeNew">NEW</button>
                    <button type="button" class="pe-btn" id="aeReset">RESET</button>
                    <button type="button" class="pe-btn pe-primary" id="aeSave">SAVE</button>
                    <button type="button" class="pe-btn" id="aeClose">CLOSE</button>
                </div>
            </div>
        `;
        document.body.appendChild(overlay);

        overlay.querySelector('#aeSave').addEventListener('click', () => this.save());
        overlay.querySelector('#aeReset').addEventListener('click', () => this.reset());
        overlay.querySelector('#aeNew').addEventListener('click', () => this.createNew());
        overlay.querySelector('#aeClose').addEventListener('click', () => this.hide());

        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape' && this.visible) {
                e.preventDefault();
                this.hide();
            }
        });
    }

    persistMenuState() {
        if (typeof menuStateManager !== 'undefined' && this.visible) {
            menuStateManager.setScreen('ability-editor', {
                abilityId: this.selectedId,
                returnTo: this.returnTo
            });
        }
    }

    show(abilityId, fromRestore, options) {
        this.ensureOverlay();
        if (abilityId) this.selectedId = String(abilityId);
        if (options && options.returnTo) this.returnTo = options.returnTo;
        else if (!fromRestore) this.returnTo = null;
        this.loadDraft();
        this.visible = true;
        document.getElementById('abilityEditorOverlay').classList.remove('hidden');
        this.renderTypeSelect();
        this.renderControls();
        if (!fromRestore && typeof menuStateManager !== 'undefined') {
            menuStateManager.setScreen('ability-editor', {
                abilityId: this.selectedId,
                returnTo: this.returnTo
            });
        }
    }

    hide() {
        this.visible = false;
        const el = document.getElementById('abilityEditorOverlay');
        if (el) el.classList.add('hidden');
        const backTo = this.returnTo;
        this.returnTo = null;
        if (backTo === 'ability-viewer' && typeof abilityViewerUI !== 'undefined') {
            abilityViewerUI.show({ abilityId: this.selectedId });
            return;
        }
        if (backTo === 'defense-viewer' && typeof defenseViewerUI !== 'undefined') {
            defenseViewerUI.show({ defenseId: this.selectedId });
            return;
        }
        if (typeof menuStateManager !== 'undefined') {
            const container = document.querySelector('.game-container');
            const inGame = container && container.style.display !== 'none';
            menuStateManager.setScreen(inGame ? 'ingame' : 'start');
        }
    }

    loadDraft() {
        if (typeof abilityConfigManager === 'undefined') {
            this.draft = {
                id: this.selectedId,
                name: this.selectedId,
                description: '',
                icon: '◆',
                cluster: 'other',
                type: 'passive',
                tier: 1,
                uiDescription: '',
                custom: false
            };
            return;
        }
        this.draft = JSON.parse(JSON.stringify(abilityConfigManager.getAbility(this.selectedId)));
    }

    createNew() {
        if (typeof abilityConfigManager === 'undefined') return;
        const ability = abilityConfigManager.createAbility({ name: 'New Ability' });
        this.selectedId = ability.id;
        this.loadDraft();
        this.renderTypeSelect();
        this.renderControls();
        this.persistMenuState();
    }

    renderTypeSelect() {
        const root = document.getElementById('aeTypeSelect');
        if (!root) return;
        root.innerHTML = '';
        const ids = typeof abilityConfigManager !== 'undefined'
            ? abilityConfigManager.getIds()
            : [this.selectedId];
        ids.forEach((id) => {
            const btn = document.createElement('button');
            btn.type = 'button';
            btn.className = 'pe-planet-btn' + (id === this.selectedId ? ' active' : '');
            const meta = typeof abilityConfigManager !== 'undefined'
                ? abilityConfigManager.getAbility(id)
                : { icon: '◆', name: id };
            const iconHtml = typeof abilityConfigManager !== 'undefined'
                ? abilityConfigManager.resolveIconHtml(meta.icon, 14, 'cv-ability-icon-img')
                : meta.icon;
            btn.innerHTML = `${iconHtml} <span>${meta.name}</span>`;
            btn.addEventListener('click', () => {
                this.selectedId = id;
                this.loadDraft();
                this.renderTypeSelect();
                this.renderControls();
                this.persistMenuState();
            });
            root.appendChild(btn);
        });
    }

    renderControls() {
        const root = document.getElementById('aeControls');
        if (!root || !this.draft) return;
        root.innerHTML = '';

        const preview = document.createElement('div');
        preview.className = 'ae-preview';
        preview.innerHTML = `<span class="ae-preview-icon">${typeof abilityConfigManager !== 'undefined' ? abilityConfigManager.resolveIconHtml(this.draft.icon || '◆', 32, 'cv-ability-icon-img') : (this.draft.icon || '◆')}</span>` +
            `<span class="ae-preview-name">${this.draft.name || this.draft.id}</span>`;
        root.appendChild(preview);

        root.appendChild(this.makeTextInput('Name', this.draft.name || '', (v) => {
            this.draft.name = v;
            this.updatePreview();
        }));
        root.appendChild(this.makeTextInput('Icon key', this.draft.icon || '', (v) => {
            this.draft.icon = v || '◆';
            this.updatePreview();
        }));
        root.appendChild(this.makeTextInput('Description', this.draft.description || '', (v) => {
            this.draft.description = v;
        }));
        root.appendChild(this.makeTextInput('UI summary', this.draft.uiDescription || '', (v) => {
            this.draft.uiDescription = v;
        }));

        const clusters = (typeof abilityConfigManager !== 'undefined'
            ? abilityConfigManager.clusterOrder.map((c) => c.id)
            : ['core', 'mobility', 'offense', 'defense', 'combat', 'other']);
        root.appendChild(this.makeSelect('Cluster', this.draft.cluster || 'other', clusters, (v) => {
            this.draft.cluster = v;
        }));
        root.appendChild(this.makeSelect('Type', this.draft.type || 'passive', ['passive', 'active'], (v) => {
            this.draft.type = v;
        }));
        root.appendChild(this.makeSlider('Tier', this.draft.tier || 1, 1, 5, 1, (v) => {
            this.draft.tier = Math.round(v);
        }));
    }

    updatePreview() {
        const icon = document.querySelector('#aeControls .ae-preview-icon');
        const name = document.querySelector('#aeControls .ae-preview-name');
        if (icon) {
            icon.innerHTML = typeof abilityConfigManager !== 'undefined'
                ? abilityConfigManager.resolveIconHtml(this.draft.icon || '◆', 32, 'cv-ability-icon-img')
                : (this.draft.icon || '◆');
        }
        if (name) name.textContent = this.draft.name || this.draft.id;
    }

    makeSlider(labelText, value, min, max, step, onChange) {
        const row = document.createElement('div');
        row.className = 'pe-row';
        const label = document.createElement('label');
        label.textContent = labelText;
        const val = document.createElement('span');
        val.className = 'pe-val';
        const format = (v) => (step < 1 ? Number(v).toFixed(2) : String(Math.round(v)));
        val.textContent = format(value);
        const input = document.createElement('input');
        input.type = 'range';
        input.min = String(min);
        input.max = String(max);
        input.step = String(step);
        input.value = String(value);
        input.addEventListener('input', () => {
            const v = Number(input.value);
            val.textContent = format(v);
            onChange(v);
        });
        row.appendChild(label);
        row.appendChild(val);
        row.appendChild(input);
        return row;
    }

    makeSelect(labelText, value, options, onChange) {
        const row = document.createElement('div');
        row.className = 'pe-row';
        const label = document.createElement('label');
        label.textContent = labelText;
        const select = document.createElement('select');
        options.forEach((opt) => {
            const o = document.createElement('option');
            o.value = opt;
            o.textContent = opt;
            if (opt === value) o.selected = true;
            select.appendChild(o);
        });
        select.addEventListener('change', () => onChange(select.value));
        row.appendChild(label);
        row.appendChild(select);
        return row;
    }

    makeTextInput(labelText, value, onChange) {
        const row = document.createElement('div');
        row.className = 'pe-row';
        const label = document.createElement('label');
        label.textContent = labelText;
        const input = document.createElement('input');
        input.type = 'text';
        input.value = value;
        input.className = 'pe-text-input';
        input.addEventListener('input', () => onChange(input.value));
        row.appendChild(label);
        row.appendChild(input);
        return row;
    }

    save() {
        if (typeof abilityConfigManager === 'undefined' || !this.draft) return;
        abilityConfigManager.setAbility(this.selectedId, this.draft);
        this.loadDraft();
        this.renderTypeSelect();
        this.renderControls();
        const header = document.querySelector('#abilityEditorOverlay .planet-editor-header h2');
        if (header) {
            const prev = header.textContent;
            header.textContent = 'SAVED';
            setTimeout(() => { header.textContent = prev || 'ABILITY EDITOR'; }, 700);
        }
    }

    reset() {
        if (typeof abilityConfigManager === 'undefined') return;
        abilityConfigManager.resetAbility(this.selectedId);
        this.loadDraft();
        this.renderControls();
    }
}

const abilityEditorUI = new AbilityEditorUI();
abilityEditorUI.init();


/* --- js/ui/level-info-manager/core.js?v=field-1 --- */
"use strict";

const STAT_HIGHLIGHT_MS = 4000; // how long an improved stat stays lit
const STAT_ICON_KEYS = {
    hp: 'statHealth', shield: 'statShield', energy: 'statEnergy',
    speed: 'statSpeed', armor: 'statArmor', dmg: 'statDamage'
};

/**
 * Level Info Panel Manager
 * Displays real-time information about the current level
 */
// How long the MISSION block stays in the HUD after a run starts.
const MISSION_HUD_SHOW_MS = 8000;

class LevelInfoManager {
    constructor() {
        this.panel = null;
        this.body = null;
        this.levelData = null;
        this.updateInterval = null;
        this.stats = {
            score: 0,
            enemiesKilled: 0,
            startTime: null,
            levelTime: 0
        };
        this._timeString = '00:00';
        this.init();
    }
    init() {
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', () => this.initializePanel());
        } else {
            this.initializePanel();
        }
    }
    initializePanel() {
        this.panel = document.getElementById('gameInfoPanel');
        if (!this.panel) {
            console.error('Level info panel not found');
            return;
        }
        this.body = document.getElementById('giBody') || this.panel;
        this.under = document.getElementById('giUnderStage');
        this.loadoutSide = document.getElementById('giLoadoutSide');
        this.missionSide = document.getElementById('giMissionSide');
        this.panel.style.display = 'flex';
        this.startUpdateLoop();
        this.updateLevelData(this.collectLevelData());
    }
    showPanel() {
        if (this.panel) {
            this.panel.style.display = 'flex';
        }
        if (this.under) {
            this.under.hidden = false;
        }
        if (this.loadoutSide) {
            this.loadoutSide.hidden = false;
        }
        if (this.missionSide) {
            this.missionSide.hidden = false;
        }
    }
    hidePanel() {
        if (this.panel) {
            this.panel.style.display = 'none';
            this.stopUpdateLoop();
        }
        if (this.under) {
            this.under.hidden = true;
        }
        if (this.loadoutSide) {
            this.loadoutSide.hidden = true;
        }
        if (this.missionSide) {
            this.missionSide.hidden = true;
        }
    }
    /** Show HUD + refresh content without starting the combat clock. */
    prepareForCombat() {
        // New run: the loadout is the baseline, not an upgrade.
        this._statPrev = {};
        this._statFx = {};
        this.showPanel();
        this.startUpdateLoop();
        this.updateDisplay();
    }
    updateLevelData(levelData) {
        this.levelData = levelData;
        this.updateDisplay();
    }
    /** Loot tile: same metric cell as SHIP stats (icon left, count right). */
    lootChipHtml(r) {
        const key = (typeof economyConfig !== 'undefined' && economyConfig.getResourceIconKey)
            ? economyConfig.getResourceIconKey(r.id)
            : 'hsCargo';
        const tip = `${String(r.name || r.id).toUpperCase()} ×${r.amount}`.replace(/"/g, '&quot;');
        const tint = (typeof economyConfig !== 'undefined' && economyConfig.getResourceColor)
            ? economyConfig.getResourceColor(r.id) : undefined;
        const icon = (typeof iconRenderer !== 'undefined' && iconRenderer && iconRenderer.imgHtml)
            ? iconRenderer.imgHtml(key || 'hsCargo', 32, 'gi-icon', tint, tip) : '';
        const empty = !(Number(r.amount) > 0) ? ' gi-loot-empty' : '';
        return `<div class="gi-metric gi-loot${empty}" title="${tip}" style="--loot-color:${tint || 'currentColor'}">` +
            `<span class="gi-metric-label gi-stat-icon">${icon}</span>` +
            `<span class="gi-metric-value gi-loot-count">${r.amount}</span>` +
            `</div>`;
    }
    iconHtml(key, size, tipLabel) {
        if (typeof iconRenderer !== 'undefined' && iconRenderer && iconRenderer.imgHtml) {
            return iconRenderer.imgHtml(key, size || 32, 'gi-icon', undefined, tipLabel);
        }
        return '';
    }
    weaponIconKey(name) {
        if (typeof iconRenderer !== 'undefined' && iconRenderer.weaponIconInfo) {
            return iconRenderer.weaponIconInfo(name).key;
        }
        const w = String(name || '').toLowerCase().replace(/[\s_-]+/g, '');
        const map = {
            laser: 'shotLaser',
            normal: 'shotLaser',
            spread: 'shotSpread',
            spreadshot: 'shotSpread',
            rapid: 'shotRapid',
            rapidfire: 'shotRapid',
            plasma: 'shotPlasma',
            missile: 'shotMissile',
            ion: 'shotIon',
            wave: 'shotWave',
            burst: 'shotBurst',
            pierce: 'shotPierce',
            nova: 'shotNova'
        };
        return map[w] || 'statWeapon';
    }
    /** Loadout weapon glyph: correct shot sprite + per-weapon tint (not faction theme). */
    weaponIconHtml(weaponId, size, tipLabel) {
        if (typeof iconRenderer !== 'undefined' && iconRenderer.weaponImgHtml) {
            return iconRenderer.weaponImgHtml(weaponId, size || 24, 'gi-icon', tipLabel);
        }
        return this.iconHtml(this.weaponIconKey(weaponId), size, tipLabel);
    }
    rowHtml(iconKey, label, valueHtml, valueId) {
        const idAttr = valueId ? ` id="${valueId}"` : '';
        const tip = String(valueHtml || '').replace(/"/g, '&quot;');
        return `<div class="gi-row">` +
            `<span class="gi-row-icon">${this.iconHtml(iconKey, 24, label)}</span>` +
            `<span class="gi-row-text">` +
            `<span class="gi-row-label">${label}</span>` +
            `<span class="gi-row-value" title="${tip}"${idAttr}>${valueHtml}</span>` +
            `</span></div>`;
    }
    /** Like rowHtml, but the icon is a tinted weapon shot sprite. */
    weaponRowHtml(weaponId, label, valueHtml, valueId) {
        const idAttr = valueId ? ` id="${valueId}"` : '';
        const tip = String(valueHtml || '').replace(/"/g, '&quot;');
        return `<div class="gi-row">` +
            `<span class="gi-row-icon">${this.weaponIconHtml(weaponId, 24, label)}</span>` +
            `<span class="gi-row-text">` +
            `<span class="gi-row-label">${label}</span>` +
            `<span class="gi-row-value" title="${tip}"${idAttr}>${valueHtml}</span>` +
            `</span></div>`;
    }
    /** Current player ship stats (label, key, numeric value, display text). */
    playerStatList() {
        const pm = typeof playerManager !== 'undefined' ? playerManager : null;
        const num = (v) => (Number.isFinite(Number(v)) ? Number(v) : 0);
        const ps = typeof pickupManager !== 'undefined' && pickupManager.getPowerShot ? pickupManager.getPowerShot() : null;
        const dmg = ps ? ps.damage : 1;
        const list = [
            { key: 'hp', label: 'HULL', value: num(pm && pm.maxHealth) },
            { key: 'shield', label: 'SHIELD', value: num(pm && pm.shieldMax) },
            { key: 'energy', label: 'ENERGY', value: num(pm && pm.maxEnergy) },
            { key: 'speed', label: 'SPEED', value: num(pm && pm.player && pm.player.speed), digits: 1 },
            { key: 'armor', label: 'ARMOR', value: num(pm && pm.armor) },
            { key: 'dmg', label: 'DMG', value: dmg, text: '×' + dmg.toFixed(1) }
        ];
        list.forEach((st) => {
            if (!st.text) st.text = st.digits ? st.value.toFixed(st.digits) : String(Math.round(st.value));
        });
        return list;
    }
    /**
     * Compare with the last snapshot: a stat that went up (upgrade, power-up)
     * gets a highlight with its delta for a few seconds; down = warning tint.
     */
    trackPlayerStats() {
        const now = Date.now();
        const list = this.playerStatList();
        this._statPrev = this._statPrev || {};
        this._statFx = this._statFx || {};
        list.forEach((st) => {
            const prev = this._statPrev[st.key];
            if (prev != null && Math.abs(st.value - prev) > 1e-6) {
                const delta = st.value - prev;
                this._statFx[st.key] = { dir: delta > 0 ? 'up' : 'down', delta, until: now + STAT_HIGHLIGHT_MS };
            }
            this._statPrev[st.key] = st.value;
            const fx = this._statFx[st.key];
            st.fx = fx && fx.until > now ? fx : null;
        });
        // The weapon box shares the damage highlight (power shot etc.).
        const wi = document.getElementById('weaponInfo');
        const box = wi && (wi.closest('.weapon-selection') || wi.parentElement);
        if (box) {
            const dmgFx = list.find((st) => st.key === 'dmg');
            box.classList.toggle('gi-weapon-boosted', dmgFx.value > 1);
            box.classList.toggle('gi-weapon-flash', !!(dmgFx.fx && dmgFx.fx.dir === 'up'));
        }
        return list;
    }
    statMetricHtml(st) {
        const fx = st.fx;
        const cls = fx ? ' gi-stat-' + fx.dir : '';
        const d = fx ? Math.abs(fx.delta) : 0;
        const dTxt = fx ? `<span class="gi-stat-delta">${fx.dir === 'up' ? '▲' : '▼'}${st.key === 'dmg' ? d.toFixed(1) : (st.digits ? d.toFixed(st.digits) : Math.round(d))}</span>` : '';
        return `<div class="gi-metric gi-stat${cls}" data-stat="${st.key}">` +
            `<span class="gi-metric-label gi-stat-icon">${this.iconHtml(STAT_ICON_KEYS[st.key], 32, st.label) || st.label}</span>` +
            `<span class="gi-metric-value">${st.text}${dTxt}</span>` +
            `</div>`;
    }
    metricHtml(label, valueHtml, valueId, iconKey) {
        const idAttr = valueId ? ` id="${valueId}"` : '';
        const tip = String(label || '').toUpperCase();
        const labelHtml = iconKey
            ? `<span class="gi-metric-label gi-stat-icon">${this.iconHtml(iconKey, 24, tip) || tip}</span>`
            : `<span class="gi-metric-label">${tip}</span>`;
        return `<div class="gi-metric">` +
            labelHtml +
            `<span class="gi-metric-value"${idAttr}>${valueHtml}</span>` +
            `</div>`;
    }
    chipHtml(iconKey, title) {
        const full = String(title || '').toUpperCase();
        const short = full
            .replace(/\bSHOT\b/g, '')
            .replace(/\bFIRE\b/g, '')
            .replace(/\s+/g, ' ')
            .trim() || full;
        const tip = full.replace(/"/g, '&quot;');
        return `<span class="gi-chip" title="${tip}">` +
            `${this.iconHtml(iconKey, 24, full)}` +
            `<span class="gi-chip-label">${short}</span>` +
            `</span>`;
    }
    /**
     * Extra weapon chips only when more than one gun is slotted (avoids
     * duplicating the WEAPON row for a single loadout).
     */
    weaponChipsHtml() {
        const weapons = this.collectEquippedWeapons ? this.collectEquippedWeapons() : [];
        if (weapons.length <= 1) return '';
        const boosted = typeof pickupManager !== 'undefined' && pickupManager.getPowerShot
            && !!pickupManager.getPowerShot();
        // The body re-renders every second: offset by wall-clock so the breath keeps its phase.
        const phase = boosted ? ` style="--gi-breath-delay:-${Date.now() % 1600}ms"` : '';
        const chips = weapons.map((w) => {
            const name = String(w.name || w.id).toUpperCase();
            const tip = (name + (w.count > 1 ? ` ×${w.count}` : '')).replace(/"/g, '&quot;');
            return `<span class="gi-chip gi-chip-weapon${boosted ? ' gi-chip-boosted' : ''}" title="${tip}"${phase}>` +
                this.weaponIconHtml(w.id, 24, name) +
                `<span class="gi-chip-label">${w.count > 1 ? '×' + w.count : name}</span>` +
                `</span>`;
        }).join('');
        return `<div class="gi-weapon-chips">${chips}</div>`;
    }
    /** Cluster header: icon when known, otherwise the text label. */
    clusterTitleHtml(title) {
        const tip = String(title || '').toUpperCase();
        // SESSION: no header icon/label — metrics speak for themselves.
        if (tip === 'SESSION') return '';
        const key = ({
            SHIP: 'hsShip',
            FIELD: 'hsCargo'
        })[tip];
        if (key) {
            return `<h4 class="gi-cluster-title gi-cluster-title-icon" title="${tip}">` +
                `${this.iconHtml(key, 32, tip)}</h4>`;
        }
        return `<h4 class="gi-cluster-title">${tip}</h4>`;
    }
    clusterHtml(title, rowsHtml, extraClass) {
        const tip = String(title || '').toUpperCase();
        const hasIcon = !!({
            SHIP: 1, FIELD: 1
        })[tip];
        const cls = ['gi-cluster', extraClass, hasIcon ? 'gi-cluster-iconed' : '']
            .filter(Boolean).join(' ');
        return `<section class="${cls}">` +
            this.clusterTitleHtml(title) +
            `<div class="gi-cluster-body">${rowsHtml}</div>` +
            `</section>`;
    }
    /** Clear mission card: target icon + action/target lines + status. */
    missionCardHtml(iconHtml, label, status, statusId) {
        const raw = String(label || 'OBJECTIVE').replace(/:$/, '').trim();
        const parts = raw.split(/\s+/);
        const action = parts.length > 1 ? parts[0] : 'OBJECTIVE';
        const target = parts.length > 1 ? parts.slice(1).join(' ') : raw;
        const tip = String(status || '').replace(/"/g, '&quot;');
        const idAttr = statusId ? ` id="${statusId}"` : '';
        return `<div class="gi-mission-card" title="${raw.replace(/"/g, '&quot;')}">` +
            `<span class="gi-mission-card-icon">${iconHtml}</span>` +
            `<div class="gi-mission-card-copy">` +
            `<span class="gi-mission-card-action">${action}</span>` +
            `<span class="gi-mission-card-target">${target}</span>` +
            `<span class="gi-mission-card-status" title="${tip}"${idAttr}>${status}</span>` +
            `</div></div>`;
    }
    /** Planet title + stage line (avoid cramming "NAME — STAGE" into one wrapping h3). */
    splitLevelTitle(d) {
        const data = d || {};
        let planet = String(data.planetName || '').trim();
        let stage = String(data.stageLabel || '').trim();
        const full = String(data.name || '').trim();
        if ((!planet || !stage) && full) {
            const parts = full.split(/\s*[—–-]\s*/);
            if (parts.length >= 2) {
                if (!planet) planet = parts[0].trim();
                if (!stage) stage = parts.slice(1).join(' — ').trim();
            } else if (!planet) {
                planet = full;
            }
        }
        return {
            planet: (planet || 'UNKNOWN').toUpperCase(),
            stage: stage ? stage.toUpperCase() : ''
        };
    }
    updateDisplay() {
        if (!this.levelData || !this.panel) return;

        const title = this.splitLevelTitle(this.levelData);
        this.updateElement('levelName', title.planet);
        const stageEl = document.getElementById('levelStage');
        if (stageEl) {
            stageEl.textContent = title.stage;
            stageEl.hidden = !title.stage;
        }
        this.updateElement('levelDifficulty', this.levelData.difficulty || 'NORMAL');
        this.updatePlanetIcon();
        this.renderBody();
    }
    resolvePlanetId() {
        const raw = (this.levelData && (this.levelData.planetId || this.levelData.background || this.levelData.name)) || 'mars';
        const sid = String(raw).toLowerCase().split(/[\s—–-]/)[0];
        return sid || 'mars';
    }
    updatePlanetIcon() {
        try {
            const host = document.getElementById('levelPlanet');
            if (!host) return;
            const sid = this.resolvePlanetId();
            if (host.dataset.planetId === sid && host.innerHTML) return;

            let svg = '';
            if (typeof planetSVGManager !== 'undefined') {
                if (!planetSVGManager.planets || !Object.keys(planetSVGManager.planets).length) {
                    planetSVGManager.init();
                }
                svg = planetSVGManager.getPlanetSVG(sid) || '';
            }

            if (svg) {
                host.innerHTML = svg;
            } else {
                host.innerHTML = `<span class="game-info-planet-fallback" data-planet="${sid}"></span>`;
            }
            host.dataset.planetId = sid;
        } catch (e) {
            // Never let HUD planet updates crash the game loop
        }
    }
    /**
     * Small pixel icon of an enemy ship type (cached data URL). The model
     * loads async: until it is ready the generic enemy icon stands in.
     */
    enemyIconHtml(type, label) {
        const t = String(type || '');
        this._enemyIcons = this._enemyIcons || {};
        const url = t && this._enemyIcons[t];
        if (url) return `<img src="${url}" alt="" class="gi-icon gi-enemy-icon" title="${label || t}">`;
        if (t && url === undefined && typeof enemyManager !== 'undefined' && enemyManager.getEnemyShipModel
            && typeof shipRenderer !== 'undefined' && shipRenderer.renderShipPreview) {
            this._enemyIcons[t] = null; // pending
            enemyManager.getEnemyShipModel(t).then((model) => {
                if (!model) return;
                const c = document.createElement('canvas');
                c.width = 11;
                c.height = 15;
                shipRenderer.renderShipPreview(c, model, 1);
                this._enemyIcons[t] = c.toDataURL();
            }).catch(() => {});
        }
        return this.iconHtml('menuEnemies', 24, label || t);
    }
    /** Count goal row: only the target's icon and the count (no text label). */
    countRowHtml(iconHtml, label, value, valueId) {
        const idAttr = valueId ? ` id="${valueId}"` : '';
        return `<div class="gi-row gi-row-count" title="${String(label).replace(/"/g, '&quot;')}">` +
            `<span class="gi-row-icon">${iconHtml}</span>` +
            `<span class="gi-row-text"><span class="gi-row-value"${idAttr}>${value}</span></span></div>`;
    }
    getObjectiveBits() {
        let label = 'OBJECTIVE';
        let progress = '—';
        if (typeof objectiveManager !== 'undefined') {
            label = objectiveManager.label || label;
            progress = objectiveManager.getProgressText
                ? (objectiveManager.getProgressText() || '—')
                : '—';
        }
        return { label, progress };
    }
    getDailyBits() {
        let active = false;
        let progress = '—';
        let enemyType = '';
        if (typeof dailyTracker === 'undefined') return { active, progress, enemyType };

        const pid = (this.levelData && (this.levelData.planetId || this.levelData.background)) || 'mars';
        const status = dailyTracker.getStatus(pid);
        if (status && status.active) {
            active = true;
            enemyType = status.enemyType || '';
            progress = `${status.todayKills}/${status.killCountPerDay}` +
                ` · ${status.completedDays}/${status.requiredDays}d`;
        }
        return { active, progress, enemyType };
    }
}


/* --- js/ui/level-info-manager/core-part2.js?v=field-1 --- */
"use strict";

// LevelInfoManager members, continued from core.js (kept under ~500 lines per file).
extendClass(LevelInfoManager, {
    renderBody() {
        if (!this.body) return;
        const d = this.levelData;
        const obj = this.getObjectiveBits();
        const daily = this.getDailyBits();
        const weaponId = (typeof bulletManager !== 'undefined' && bulletManager.currentWeapon)
            ? bulletManager.currentWeapon
            : (d.currentWeapon || 'laser');
        const weaponName = (typeof iconRenderer !== 'undefined' && iconRenderer.weaponIconInfo)
            ? iconRenderer.weaponIconInfo(weaponId).name
            : String(weaponId).toUpperCase();

        const session = this.clusterHtml('SESSION',
            `<div class="gi-metrics gi-metrics-session">` +
            this.metricHtml('SCORE', String(this.stats.score), 'currentScore', 'navTrophy') +
            this.metricHtml('TIME', this._timeString, 'levelTime', 'navClock') +
            this.metricHtml('KILLS', String(this.stats.enemiesKilled), 'enemiesKilled', 'navSkull') +
            `</div>`,
            'gi-cluster-session'
        );

        // Loadout lives in the right rail (top).
        const loadout = this.clusterHtml('LOADOUT',
            this.rowHtml('menuEnemies', 'ENEMY', String(d.enemyType || '—').toUpperCase(), 'enemyType') +
            this.rowHtml('hsShip', 'SHIP', String(d.playerShipType || '—'), 'playerShipType') +
            this.weaponRowHtml(weaponId, 'WEAPON', weaponName, 'giCurrentWeapon'),
            'gi-cluster-loadout'
        );

        // Mission: text title + one clear card (target icon, goal, status).
        const o = typeof objectiveManager !== 'undefined' ? objectiveManager.getObjective() : null;
        const missionLabel = obj.label.replace(/:$/, '');
        const missionProgress = String(obj.progress).toUpperCase();
        const huntTarget = o && o.type === 'hunt' && o.targetEnemyId && objectiveManager.enemies
            ? objectiveManager.enemies.find((e) => e && e.id === o.targetEnemyId)
            : null;
        const missionIcon = (o && o.type === 'killCount' && o.enemyType)
            ? this.enemyIconHtml(o.enemyType, missionLabel)
            : (huntTarget
                ? this.enemyIconHtml(huntTarget.type, missionLabel)
                : this.iconHtml('menuEnemies', 28, missionLabel));
        const objCard = this.missionCardHtml(missionIcon, missionLabel, missionProgress, 'objectiveHudValue');
        const dailyRow = daily.active
            ? this.countRowHtml(this.enemyIconHtml(daily.enemyType, 'DAILY ' + daily.enemyType), 'DAILY', daily.progress, 'dailyHudValue')
            : '';
        const mission = this.clusterHtml('MISSION', objCard + dailyRow, 'gi-cluster-mission');

        // Player ship stats; anything an upgrade improves lights up.
        const stats = this.trackPlayerStats();
        const combat = this.clusterHtml('SHIP',
            `<div class="gi-metrics gi-metrics-2x2">` +
            stats.map((st) => this.statMetricHtml(st)).join('') +
            `</div>`,
            'gi-cluster-combat'
        );

        // Field loot: same 1-row metric tiles as SHIP.
        const resources = d.resources || [];
        const field = this.clusterHtml('FIELD',
            `<div class="gi-metrics gi-metrics-2x2 gi-metrics-loot">` +
            resources.map((r) => this.lootChipHtml(r)).join('') +
            `</div>`,
            'gi-cluster-field'
        );

        this.body.innerHTML = session;
        if (this.loadoutSide) {
            this.loadoutSide.innerHTML = loadout;
            this.loadoutSide.hidden = false;
        }
        if (this.under) {
            this.under.innerHTML = combat + field;
            this.under.hidden = false;
        }
        if (this.missionSide) {
            this.missionSide.innerHTML = mission;
            this.missionSide.hidden = false;
        }
    },
});


/* --- js/ui/level-info-manager/update-element.js?v=field-2 --- */
"use strict";

// LevelInfoManager methods, split from level-info-manager.js.
extendClass(LevelInfoManager, {
    updateElement(id, value) {
        const element = document.getElementById(id);
        if (element) {
            element.textContent = value;
        }
    },

    updateStats(stats) {
        this.stats = { ...this.stats, ...stats };
        this.updateElement('currentScore', this.stats.score);
        this.updateElement('enemiesKilled', this.stats.enemiesKilled);
    },

    startLevel() {
        this.stats.startTime = Date.now();
        this.stats.levelTime = 0;
        this._timeString = '00:00';
        this.prepareForCombat();
        this.updateElement('levelTime', this._timeString);
    },

    endLevel() {
        this.stopUpdateLoop();
        // Keep the panel mounted during game-over / transition so the next
        // mission start does not flash an empty vitals-only HUD.
    },

    startUpdateLoop() {
        this.stopUpdateLoop();
        this.updateInterval = setInterval(() => {
            if (typeof game !== 'undefined' && typeof game.score === 'number') {
                this.stats.score = game.score;
                this.updateElement('currentScore', this.stats.score);
            }
            if (this.stats.startTime) {
                this.stats.levelTime = Math.floor((Date.now() - this.stats.startTime) / 1000);
                const minutes = Math.floor(this.stats.levelTime / 60);
                const seconds = this.stats.levelTime % 60;
                this._timeString = `${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
                this.updateElement('levelTime', this._timeString);
            }
            if (typeof objectiveManager !== 'undefined' || typeof dailyTracker !== 'undefined') {
                const objVal = document.getElementById('objectiveHudValue');
                const dailyVal = document.getElementById('dailyHudValue');
                if (objVal) {
                    const obj = this.getObjectiveBits();
                    objVal.textContent = String(obj.progress).toUpperCase();
                }
                if (dailyVal) {
                    const daily = this.getDailyBits();
                    dailyVal.textContent = daily.active ? daily.progress : '—';
                }
                if (this.levelData) {
                    this.levelData.resources = this.collectRunResources();
                    this.updateDisplay();
                }
            }
        }, 1000);
    },

    stopUpdateLoop() {
        if (this.updateInterval) {
            clearInterval(this.updateInterval);
            this.updateInterval = null;
        }
    },

    collectPlanetObstacles(planetId) {
        if (typeof planetConfigManager === 'undefined' || !planetId) return [];
        const cfg = planetConfigManager.getConfig(planetId);
        if (!cfg) return [];
        const types = (Array.isArray(cfg.obstacles) && cfg.obstacles.length)
            ? cfg.obstacles.map((o) => (o && (o.type || o.id)) || o)
            : (cfg.obstacleTypes || []);
        // One chip per obstacle kind (small/medium asteroid -> ASTEROID);
        // the sizes go into the chip tooltip.
        const kinds = {};
        const order = [];
        types.forEach((t) => {
            if (!t) return;
            const parts = String(t).toLowerCase().split('_');
            const kind = parts[parts.length - 1];
            const size = parts.slice(0, -1).join(' ');
            if (!kinds[kind]) { kinds[kind] = []; order.push(kind); }
            if (size && kinds[kind].indexOf(size) === -1) kinds[kind].push(size);
        });
        return order.map((kind) => ({
            name: kind.charAt(0).toUpperCase() + kind.slice(1),
            sizes: kinds[kind]
        }));
    },

    collectEquippedWeapons() {
        if (typeof shipLoadoutManager === 'undefined' || typeof profileManager === 'undefined'
            || !profileManager.getActiveShipId) return [];
        const ids = (shipLoadoutManager.getLoadout(profileManager.getActiveShipId()).weapons || []);
        const seen = {};
        return ids.filter((id) => id && !seen[id] && (seen[id] = true)).map((id) => {
            const w = typeof weaponConfigManager !== 'undefined' ? weaponConfigManager.getWeapon(id) : null;
            return { name: (w && w.name) || id, id: id, count: ids.filter((x) => x === id).length };
        });
    },

    collectRunResources() {
        const bag = (typeof pickupManager !== 'undefined' && pickupManager.collectedThisRun)
            ? pickupManager.collectedThisRun
            : {};
        const ids = (typeof economyConfig !== 'undefined' && economyConfig.resourceIds)
            ? economyConfig.resourceIds
            : Object.keys(bag);
        return ids.map((id) => ({
            id: id,
            name: (typeof economyConfig !== 'undefined' && economyConfig.getResourceLabel)
                ? economyConfig.getResourceLabel(id)
                : String(id).toUpperCase(),
            amount: Number(bag[id]) || 0
        }));
    },

    collectLevelData() {
        const levelData = {
            name: 'MARS — STAGE 1/3',
            difficulty: 'EASY',
            enemyType: 'enemyBasic',
            enemySpeed: '0.8',
            enemyHealth: '100',
            enemyCount: '5',
            obstacles: [],
            obstacleSpawnRate: 1000,
            playerShipType: 'Starfighter',
            playerSpeed: '1.0',
            playerMaxHealth: '100',
            currentWeapon: 'Laser',
            weapons: [],
            resources: []
        };

        const coreLM = (typeof game !== 'undefined' && (game.coreLevelManager || game.levelManager))
            || (typeof gameCore !== 'undefined' && (gameCore.coreLevelManager || gameCore.levelManager))
            || null;
        const current = coreLM && coreLM.getCurrentLevel ? coreLM.getCurrentLevel() : null;
        if (current) {
            levelData.name = current.name || levelData.name;
            levelData.difficulty = current.difficulty || levelData.difficulty;
            levelData.enemyType = current.enemyType || levelData.enemyType;
            levelData.enemySpeed = current.enemySpeed != null ? String(current.enemySpeed) : levelData.enemySpeed;
            levelData.enemyHealth = current.enemyHealth != null ? String(current.enemyHealth) : levelData.enemyHealth;
            levelData.enemyCount = current.enemyCount != null ? String(current.enemyCount) : levelData.enemyCount;
            levelData.obstacles = current.obstacles || levelData.obstacles;
            levelData.obstacleSpawnRate = current.obstacleSpawnRate || levelData.obstacleSpawnRate;
            levelData.stageLabel = current.stageLabel || '';
            levelData.planetName = current.planetName || levelData.planetName || '';
            levelData.isBoss = !!current.isBoss;
            levelData.planetId = current.planetId || levelData.planetId;
            levelData.objective = current.objective || null;
            if (current.weapons) levelData.weapons = current.weapons;
        }
        // FIELD shows only what this run really has: the planet's obstacle
        // types and the weapons equipped on the flying ship.
        levelData.obstacles = this.collectPlanetObstacles(levelData.planetId);
        levelData.weapons = this.collectEquippedWeapons();
        levelData.resources = this.collectRunResources();

        if (typeof enemyManager !== 'undefined' && enemyManager.getEnemy()) {
            const enemy = enemyManager.getEnemy();
            levelData.enemySpeed = enemy.speed?.toFixed(1) || levelData.enemySpeed;
            levelData.enemyHealth = enemyManager.maxHealth || levelData.enemyHealth;
        }

        if (typeof playerManager !== 'undefined') {
            levelData.playerSpeed = playerManager.player?.speed?.toFixed(1) || '1.0';
            levelData.playerMaxHealth = playerManager.maxHealth || '100';
        }

        if (typeof obstacleManager !== 'undefined') {
            levelData.obstacleSpawnRate = obstacleManager.spawnInterval || levelData.obstacleSpawnRate;
        }

        if (typeof game !== 'undefined' && game.gameState) {
            levelData.obstacleSpawnRate = game.gameState.obstacleSpawnInterval || levelData.obstacleSpawnRate;
        }

        if (typeof graphicsManager !== 'undefined' && graphicsManager.currentPlayerModel) {
            levelData.playerShipType = graphicsManager.currentPlayerModel.name || 'Starfighter';
        }

        if (typeof game !== 'undefined' && game.currentWeaponName) {
            levelData.currentWeapon = game.currentWeaponName;
        } else {
            const weaponLabel = document.querySelector('.weapon-display #currentWeapon');
            if (weaponLabel && weaponLabel.textContent) {
                levelData.currentWeapon = weaponLabel.textContent.trim();
            }
        }

        return levelData;
    },

    showLootNotice(text) {
        const msg = String(text || '').trim();
        if (!msg) return;
        let el = document.getElementById('vfLootNotice');
        if (!el) {
            el = document.createElement('div');
            el.id = 'vfLootNotice';
            el.style.cssText = [
                'position:fixed',
                'top:12%',
                'left:50%',
                'transform:translateX(-50%)',
                'z-index:9999',
                'padding:8px 14px',
                'background:rgba(0,0,0,0.75)',
                'color:#b8f0c0',
                'font-family:monospace',
                'font-size:var(--font-text)',
                'letter-spacing:0.04em',
                'pointer-events:none',
                'border:var(--ui-border-width) solid rgba(184,240,192,0.4)'
            ].join(';');
            document.body.appendChild(el);
        }
        el.textContent = msg;
        el.style.opacity = '1';
        clearTimeout(this._lootNoticeTimer);
        this._lootNoticeTimer = setTimeout(() => {
            if (el) el.style.opacity = '0';
        }, 2800);
    },

    showEventAnnounce(text, options) {
        const msg = String(text || '').trim();
        if (!msg) return;
        const opts = options || {};
        const accent = opts.accent || '#e8c060';
        const holdMs = Math.max(800, Math.round(Number(opts.holdMs != null ? opts.holdMs : 2200)));
        let el = document.getElementById('vfEventAnnounce');
        if (!el) {
            el = document.createElement('div');
            el.id = 'vfEventAnnounce';
            el.className = 'vf-event-announce';
            document.body.appendChild(el);
        }
        el.textContent = msg;
        el.style.borderColor = accent;
        el.style.color = accent;
        el.style.opacity = '1';
        el.classList.add('vf-event-announce-pulse');
        clearTimeout(this._eventAnnounceTimer);
        this._eventAnnounceTimer = setTimeout(() => {
            if (el) {
                el.style.opacity = '0';
                el.classList.remove('vf-event-announce-pulse');
            }
        }, holdMs);
    },
});


/* --- js/ui/level-info-manager.js --- */
"use strict";

// LevelInfoManager is defined in level-info-manager/core.js and extended by the other files in level-info-manager/,
// which index.html loads before this file.
// Global instance
let levelInfoManager = new LevelInfoManager();


/* --- js/ui/mission-start/core.js --- */
"use strict";

/**
 * Mission start sequence: FIRE TO START → countdown → ships fly in → combat.
 */
class MissionStartManager {
    constructor() {
        this.active = false;
        this.phase = null;
        this.countdownValue = 3;
        this.countdownTimer = 0;
        this.goTimer = 0;
        this.flyInElapsed = 0;
        this.flyInDuration = 1400;
        this.overlay = null;
        this.textEl = null;
        this.playerFrom = null;
        this.playerTo = null;
        this.enemyFrom = null;
        this.enemyTo = null;
        this.sideFrom = [];
        this.sideTo = [];
        this._armed = false;
    }

    isActive() {
        return !!this.active;
    }

    isAwaitingFire() {
        return this.active && this.phase === 'awaitFire';
    }

    isPlaying() {
        return !this.active;
    }

    arm() {
        this._armed = true;
        this.active = true;
        this.phase = 'awaitFire';
        this.countdownValue = 3;
        this.countdownTimer = 0;
        this.goTimer = 0;
        this.flyInElapsed = 0;
        this.playerFrom = null;
        this.playerTo = null;
        this.enemyFrom = null;
        this.enemyTo = null;
        this.sideFrom = [];
        this.sideTo = [];
        if (typeof enemyManager !== 'undefined') {
            enemyManager.spawnFrozen = true;
            enemyManager.enemy = null;
            enemyManager.sideEnemies = [];
            enemyManager.scheduleElapsedMs = 0;
            if (Array.isArray(enemyManager.schedule)) {
                enemyManager.schedule.forEach((e) => { e.spawned = false; });
            }
        }
        if (typeof obstacleManager !== 'undefined' && obstacleManager.reset) {
            obstacleManager.reset();
        }
        if (typeof bulletManager !== 'undefined' && bulletManager.reset) {
            bulletManager.reset();
        }
    }

    begin() {
        if (!this._armed) this.arm();
        this.active = true;
        this.phase = 'awaitFire';

        if (typeof playerManager !== 'undefined') {
            if (playerManager.reset) playerManager.reset();
            const p = playerManager.player;
            const h = this.canvasHeight();
            p.y = h + (p.height || 24) + 40;
        }
        if (typeof enemyManager !== 'undefined') {
            enemyManager.spawnFrozen = true;
            enemyManager.enemy = null;
            enemyManager.sideEnemies = [];
            enemyManager.scheduleElapsedMs = 0;
            if (Array.isArray(enemyManager.schedule)) {
                enemyManager.schedule.forEach((e) => { e.spawned = false; });
            }
        }

        this.ensureOverlay();
        this.setText('FIRE TO START', true);
        this.showOverlay();

        if (typeof levelInfoManager !== 'undefined') {
            if (typeof levelInfoManager.prepareForCombat === 'function') {
                levelInfoManager.prepareForCombat();
            } else if (levelInfoManager.showPanel) {
                levelInfoManager.showPanel();
            }
        }
    }

    canvasWidth() {
        if (typeof game !== 'undefined') {
            return game.internalWidth || game.baseWidth || game.width || 240;
        }
        return 240;
    }

    canvasHeight() {
        if (typeof game !== 'undefined') {
            return game.internalHeight || game.baseHeight || game.height || 300;
        }
        return 300;
    }

    ensureOverlay() {
        if (this.overlay && this.overlay.isConnected) return;
        let el = document.getElementById('missionStartOverlay');
        if (!el) {
            el = document.createElement('div');
            el.id = 'missionStartOverlay';
            el.className = 'mission-start-overlay hidden';
            el.innerHTML = '<div class="mission-start-text" id="missionStartText">FIRE TO START</div>';
            const stage = document.querySelector('.game-stage') || document.querySelector('.game-canvas-container') || document.body;
            stage.appendChild(el);
        }
        this.overlay = el;
        this.textEl = el.querySelector('#missionStartText') || el.querySelector('.mission-start-text');
    }

    showOverlay() {
        this.ensureOverlay();
        if (this.overlay) this.overlay.classList.remove('hidden');
    }

    hideOverlay() {
        if (this.overlay) this.overlay.classList.add('hidden');
    }

    setText(msg, pulse) {
        this.ensureOverlay();
        if (this.textEl) {
            this.textEl.classList.toggle('mission-start-pulse', !!pulse);
            this.textEl.classList.toggle('mission-start-count', !pulse && /^\d+$/.test(String(msg)));
            this.textEl.classList.toggle('mission-start-go', String(msg) === 'GO!');
            if (!pulse && /^\d+$/.test(String(msg))) {
                if (!this.pixelCanvas) {
                    this.pixelCanvas = document.createElement('canvas');
                    this.pixelCanvas.className = 'mission-start-pixel-canvas';
                    this.textEl.textContent = '';
                    this.textEl.appendChild(this.pixelCanvas);
                }
                this.drawPixelText(String(msg));
            } else {
                this.pixelCanvas = null;
                this.textEl.textContent = msg;
            }
        }
    }

    /** Crisp 5×7 bitmap digits scaled with nearest-neighbour — no blurry font. */
    drawPixelText(msg) {
        if (!this.pixelCanvas) return;
        const GLYPHS = {
            '0': ['01110', '10001', '10011', '10101', '11001', '10001', '01110'],
            '1': ['00100', '01100', '00100', '00100', '00100', '00100', '01110'],
            '2': ['01110', '10001', '00001', '00110', '01000', '10000', '11111'],
            '3': ['11110', '00001', '00001', '01110', '00001', '00001', '11110'],
            '4': ['00010', '00110', '01010', '10010', '11111', '00010', '00010'],
            '5': ['11111', '10000', '11110', '00001', '00001', '10001', '01110'],
            '6': ['00110', '01000', '10000', '11110', '10001', '10001', '01110'],
            '7': ['11111', '00001', '00010', '00100', '01000', '01000', '01000'],
            '8': ['01110', '10001', '10001', '01110', '10001', '10001', '01110'],
            '9': ['01110', '10001', '10001', '01111', '00001', '00010', '01100']
        };
        const canvas = this.pixelCanvas;
        const chars = String(msg).split('').filter((c) => GLYPHS[c]);
        // 1px margin + 1px drop shadow; 1px gap between digits.
        canvas.width = chars.length * 6 + 2;
        canvas.height = 10;
        const ctx = canvas.getContext('2d');
        ctx.imageSmoothingEnabled = false;
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        const color = getComputedStyle(this.textEl).color;
        const paint = (ox, oy, fill, alpha) => {
            ctx.globalAlpha = alpha;
            ctx.fillStyle = fill;
            chars.forEach((c, i) => {
                GLYPHS[c].forEach((row, y) => {
                    for (let x = 0; x < 5; x++) {
                        if (row[x] === '1') ctx.fillRect(1 + i * 6 + x + ox, 1 + y + oy, 1, 1);
                    }
                });
            });
        };
        paint(1, 1, '#000', 0.55);
        paint(0, 0, color, 1);
        ctx.globalAlpha = 1;
        // Restart the per-second progress bar and pop-in animation.
        const el = this.textEl;
        el.classList.remove('mission-start-tick');
        void el.offsetWidth;
        el.classList.add('mission-start-tick');
    }

    onFire() {
        if (!this.active || this.phase !== 'awaitFire') return false;
        this.phase = 'countdown';
        this._lastTick = 0;
        this.countdownValue = 3;
        this.countdownTimer = 0;
        this.setText('3', false);
        if (typeof soundManager !== 'undefined' && soundManager.playShoot) {
            try { soundManager.playShoot(); } catch (e) { /* ignore */ }
        }
        return true;
    }

    update(deltaTime) {
        if (!this.active) return;

        // Countdown / GO run on wall-clock time: the loop caps deltaTime per frame, so a slow frame rate would stretch them.
        const now = performance.now();
        const real = this._lastTick ? Math.min(1000, now - this._lastTick) : deltaTime;
        this._lastTick = now;

        if (this.phase === 'countdown') {
            this.countdownTimer += Math.max(deltaTime, real);
            if (this.countdownTimer >= 900) {
                this.countdownTimer = 0;
                this.countdownValue -= 1;
                if (this.countdownValue > 0) {
                    this.setText(String(this.countdownValue), false);
                    if (typeof soundManager !== 'undefined' && soundManager.playShoot) {
                        try { soundManager.playShoot(); } catch (e) { /* ignore */ }
                    }
                } else {
                    this.phase = 'go';
                    this.goTimer = 0;
                    this.setText('GO!', false);
                    if (typeof soundManager !== 'undefined' && soundManager.playExplosion) {
                        try { soundManager.playExplosion(); } catch (e) { /* ignore */ }
                    }
                }
            }
            return;
        }

        if (this.phase === 'go') {
            this.goTimer += Math.max(deltaTime, real);
            if (this.goTimer >= 450) {
                this.startFlyIn();
            }
            return;
        }

        if (this.phase === 'preparingFlyIn') {
            return;
        }

        if (this.phase === 'flyIn') {
            this.flyInElapsed += deltaTime;
            const t = Math.min(1, this.flyInElapsed / this.flyInDuration);
            const ease = 1 - Math.pow(1 - t, 3);
            this.applyFlyIn(ease);
            if (t >= 1) {
                this.complete();
            }
        }
    }

    startFlyIn() {
        this.phase = 'preparingFlyIn';
        this.hideOverlay();
        this.prepareFlyIn().catch((err) => {
            console.error('Mission fly-in failed:', err);
            this.complete();
        });
    }
}


/* --- js/ui/mission-start/prepare-fly-in.js --- */
"use strict";

// MissionStartManager methods, split from mission-start.js.
extendClass(MissionStartManager, {
    async prepareFlyIn() {
        const w = this.canvasWidth();
        const h = this.canvasHeight();

        if (typeof playerManager !== 'undefined') {
            if (playerManager.reset) playerManager.reset();
            const p = playerManager.player;
            this.playerTo = { x: p.x, y: p.y };
            this.playerFrom = { x: p.x, y: h + p.height + 36 };
            p.x = this.playerFrom.x;
            p.y = this.playerFrom.y;
        }

        if (typeof enemyManager !== 'undefined') {
            enemyManager.spawnFrozen = false;
            enemyManager.scheduleElapsedMs = 0;
            if (!Array.isArray(enemyManager.schedule) || !enemyManager.schedule.length) {
                const type = enemyManager.currentShipType || 'enemyBasic';
                enemyManager.setEnemySchedule([{
                    id: 'main',
                    type: type,
                    champion: true,
                    level: 2,
                    spawnAt: 0
                }], {
                    planetId: (typeof game !== 'undefined' && game.coreLevelManager &&
                        game.coreLevelManager.getCurrentLevel &&
                        game.coreLevelManager.getCurrentLevel() &&
                        game.coreLevelManager.getCurrentLevel().planetId) || 'mars'
                });
            }
            if (Array.isArray(enemyManager.schedule)) {
                enemyManager.schedule.forEach((e) => { e.spawned = false; });
            }
            enemyManager.enemy = null;
            enemyManager.sideEnemies = [];
            const state = { width: w, height: h };

            // Spawn due-at-0 entries (respect cluster wave times); await champion model
            const clusterWaveAt = {};
            (enemyManager.schedule || []).forEach((e) => {
                const c = e.cluster || 'alpha';
                const at = Number(e.spawnAt != null ? e.spawnAt : 0);
                if (clusterWaveAt[c] == null || at < clusterWaveAt[c]) {
                    clusterWaveAt[c] = at;
                }
            });
            let due = (enemyManager.schedule || []).filter((entry) => {
                if (entry.spawned) return false;
                const at = Number(entry.spawnAt != null ? entry.spawnAt : 0);
                const waveAt = clusterWaveAt[entry.cluster || 'alpha'];
                const dueAt = Math.min(at, waveAt != null ? waveAt : at);
                return dueAt <= 0;
            });
            // Always bring at least the champion in during fly-in
            if (!due.length && enemyManager.schedule.length) {
                const champ = enemyManager.schedule.find((e) => e.champion) || enemyManager.schedule[0];
                if (champ) due = [champ];
            }
            for (const entry of due) {
                entry.spawned = true;
                if (entry.champion) {
                    await enemyManager.spawnChampionFromEntry(entry);
                } else {
                    enemyManager.spawnScheduledNormal(entry, state);
                }
            }

            if (enemyManager.enemy) {
                const e = enemyManager.enemy;
                this.enemyTo = { x: e.x, y: e.y };
                this.enemyFrom = { x: e.x, y: -e.height - 24 };
                e.x = this.enemyFrom.x;
                e.y = this.enemyFrom.y;
            } else {
                this.enemyFrom = null;
                this.enemyTo = null;
            }

            this.sideFrom = [];
            this.sideTo = [];
            (enemyManager.sideEnemies || []).forEach((s, i) => {
                const to = { x: s.x, y: s.y };
                let from;
                if (s.isEscort) {
                    from = { x: to.x, y: -s.height - 20 - i * 12 };
                } else if (s.speed < 0) {
                    from = { x: w + s.width + 30 + i * 10, y: to.y };
                } else {
                    from = { x: -s.width - 30 - i * 10, y: to.y };
                }
                this.sideFrom.push(from);
                this.sideTo.push(to);
                s.x = from.x;
                s.y = from.y;
            });
        }

        if (!this.active) return;
        this.phase = 'flyIn';
        this.flyInElapsed = 0;
    },

    applyFlyIn(ease) {
        if (this.playerFrom && this.playerTo && typeof playerManager !== 'undefined') {
            const p = playerManager.player;
            p.x = this.playerFrom.x + (this.playerTo.x - this.playerFrom.x) * ease;
            p.y = this.playerFrom.y + (this.playerTo.y - this.playerFrom.y) * ease;
        }
        if (this.enemyFrom && this.enemyTo && typeof enemyManager !== 'undefined' && enemyManager.enemy) {
            const e = enemyManager.enemy;
            e.x = this.enemyFrom.x + (this.enemyTo.x - this.enemyFrom.x) * ease;
            e.y = this.enemyFrom.y + (this.enemyTo.y - this.enemyFrom.y) * ease;
        }
        if (typeof enemyManager !== 'undefined' && enemyManager.sideEnemies) {
            enemyManager.sideEnemies.forEach((s, i) => {
                const from = this.sideFrom[i];
                const to = this.sideTo[i];
                if (!from || !to) return;
                s.x = from.x + (to.x - from.x) * ease;
                s.y = from.y + (to.y - from.y) * ease;
            });
        }
    },

    complete() {
        this.applyFlyIn(1);
        this.active = false;
        this.phase = null;
        this._armed = false;
        this.hideOverlay();

        if (typeof enemyManager !== 'undefined') {
            enemyManager.spawnFrozen = false;
        }

        if (typeof levelInfoManager !== 'undefined' && levelInfoManager.startLevel) {
            levelInfoManager.startLevel();
        }
        if (typeof game !== 'undefined' && game.gameState && game.gameState.stats) {
            game.gameState.stats.levelStartTime = Date.now();
        }
    },

    cancel() {
        this.active = false;
        this.phase = null;
        this._armed = false;
        this.hideOverlay();
        if (typeof enemyManager !== 'undefined') {
            enemyManager.spawnFrozen = false;
        }
    },
});


/* --- js/ui/mission-start.js --- */
"use strict";

// MissionStartManager is defined in mission-start/core.js and extended by the other files in mission-start/,
// which index.html loads before this file.
const missionStartManager = new MissionStartManager();


/* --- js/levels/mars.js --- */
"use strict";

// Mars Level - Easy Desert Environment
class MarsLevel {
    constructor() {
        this.id = "mars";
        this.name = "MARS";
        this.difficulty = "EASY";
        this.environment = "DESERT";
        this.color = "#808080";
        this.description = "Red planet with basic obstacles";
        this.background = "mars";
        this.enemyType = "enemyBasic";
        
        // Mars-specific obstacle patterns
        this.obstaclePatterns = [
            {
                type: "rock",
                spawnRate: 0.3,
                speed: 2,
                size: { width: 18, height: 18 }, // Reduced to moderate size
                color: "#606060"
            },
            {
                type: "dust_cloud",
                spawnRate: 0.2,
                speed: 1.5,
                size: { width: 25, height: 25 }, // Reduced to moderate size
                color: "#a0a0a0"
            }
        ];
        
        // Mars-specific settings
        this.obstacleSpawnInterval = 3000; // 3 seconds
        this.enemySpeed = 1.5;
        this.enemyHealth = 80;
        this.playerSpeed = 8;
    }
    
    getObstaclePattern() {
        // Return a random obstacle pattern based on spawn rates
        const totalRate = this.obstaclePatterns.reduce((sum, pattern) => sum + pattern.spawnRate, 0);
        let random = Math.random() * totalRate;
        
        for (const pattern of this.obstaclePatterns) {
            random -= pattern.spawnRate;
            if (random <= 0) {
                return pattern;
            }
        }
        
        // Fallback to first pattern
        return this.obstaclePatterns[0];
    }
    
    getEnvironmentColor() {
        return this.color;
    }
    
    getBackgroundElements() {
        return [
            { type: "dust_storm", intensity: 0.3 },
            { type: "red_sand", particles: 5 }
        ];
    }
}


