            disc('d', 0, 1, 2, 3);
            for (let i = 0; i < 3 + (big ? 1 : 0); i++) {
                const dir = i % 2 ? 1 : -1;
                const len = 6 + rnd(4);
                stroke('h', dir * 4, -2 + i * 2, dir * (4 + len), -7 + i * 5 - rnd(3), 3, 1);
            }
            stroke('h', 0, -5, 0, -12, 3, 1);
            stroke('h', -2, -5, -5, -11, 2, 1);
            stroke('h', 2, -5, 5, -11, 2, 1);
            stroke('d', -1, 6, -3, 11, 2, 1);
            stroke('d', 1, 6, 3, 11, 2, 1);
