        const enemies = {};
        (cfg.enemies || []).forEach((e) => {
            const t = String(e.type || '?') + (/_boss$/.test(String(e.id || '')) || e.boss ? ' ★' : '');
            enemies[t] = (enemies[t] || 0) + 1;
        });
