                const a = -(h.drag.rotation || 0);
                const ldx = dx * Math.cos(a) - dy * Math.sin(a);
                const ldy = dx * Math.sin(a) + dy * Math.cos(a);
                const outward = h.drag.side === 'left' ? -ldx : ldx;
