"use strict";

// HomeStationUI members, continued from bind-controls-toggle.js (kept under ~500 lines per file).
extendClass(HomeStationUI, {
    bindKeyNav() {
        this._keyHandler = (e) => {
            if (!this.isVisible) return;
            // Embedded WIKI viewer owns the keyboard (its own ↑↓ / ESC).
            if (this._embeddedViewer) return;
            if (typeof hangarTestArena !== 'undefined' && hangarTestArena.isVisible) return;
            // Profile overlay on top of the station owns the keyboard.
            if (typeof profileSelectionManager !== 'undefined' && profileSelectionManager.isVisible) return;
            if (this.overlay) {
                const root = this.overlay.querySelector('.home-station-content');
                if (root) root.classList.remove('hs-pointer-mode');
            }
            // Main menu (embedded tab or legacy overlay) owns keyboard while open.
            // Embedded menu only owns the keys after ENTER/SPACE entered it;
            // until then its tabs sit in the station tab row like any other tab.
            if (typeof startScreenManager !== 'undefined' &&
                (startScreenManager.isOverlayOpen() ||
                    (startScreenManager.isEmbeddedOpen() && this._menuArmed))) {
                return;
            }
            const playMapMounted = this.tab === 'play' &&
                typeof galaxyMapManager !== 'undefined' &&
                galaxyMapManager.isVisible &&
                galaxyMapManager._mountEl;
            const playMapActive = playMapMounted && this.isPlayMapActive();
            // SPACE with the map on screen jumps straight into it, skipping
            // the nav rows (ENTER still steps through them one level at a time).
            if (playMapMounted && !playMapActive && e.key === ' ' && !this._resBuyModal) {
                e.preventDefault();
                e.stopPropagation();
                this.enterPlayMap();
                return;
            }
            // ENTER / SPACE in a nav row goes exactly one level deeper
            // (area row → its sub-nav → content / map / menu section).
            if ((e.key === 'Enter' || e.key === ' ') && !playMapActive && !this._resBuyModal
                && this.enterOneNavLevel()) {
                e.preventDefault();
                e.stopPropagation();
                return;
            }
            if (playMapMounted && (e.key === 'Enter' || e.key === ' ')) {
                e.preventDefault();
                e.stopPropagation();
                if (!playMapActive) {
                    this.enterPlayMap();
                    return;
                }
                // First press focuses the start button, the next one starts.
                galaxyMapManager.confirmKey();
                return;
            }
            if (playMapActive) {
                if (e.key === 'Escape' || e.key === 'Backspace') {
                    e.preventDefault();
                    e.stopPropagation();
                    if (galaxyMapManager.hasActionFocus()) {
                        galaxyMapManager.clearActionFocus();
                        return;
                    }
                    this.exitPlayMap();
                    return;
                }
                // Arrows move the map cursor; D docks at a trading post —
                // both handled by the galaxy map's own key handler.
                if (e.key === 'ArrowLeft' || e.key === 'ArrowRight' ||
                    e.key === 'ArrowUp' || e.key === 'ArrowDown' ||
                    e.key === 'd' || e.key === 'D') {
                    return;
                }
            }
            const tag = e.target && e.target.tagName;
            if (typeof menuNavHelper !== 'undefined' && menuNavHelper.isTextEntry) {
                if (menuNavHelper.isTextEntry(e.target)) return;
                // Sliders keep ←/→ for their value; ↑/↓ still move focus.
                if (tag === 'INPUT' && e.target.type === 'range' &&
                    !e.shiftKey && (e.key === 'ArrowLeft' || e.key === 'ArrowRight')) return;
            } else if (tag === 'INPUT' || tag === 'TEXTAREA') {
                return;
            }

            if (e.shiftKey && (e.key === 'c' || e.key === 'C')) {
                e.preventDefault();
                if (typeof startScreenManager !== 'undefined') {
                    startScreenManager.toggleDevMode();
                    this.statusMsg = startScreenManager.devMode
                        ? 'DEV MODE ON — COMPONENTS + LAYOUT UNLOCKED' : 'DEV MODE OFF';
                    // Leaving dev mode keeps an open dev tab open; it vanishes
                    // from the rows once you navigate away.
                    this.createUI();
                }
                return;
            }
            if (e.shiftKey && (e.key === 'h' || e.key === 'H')) {
                e.preventDefault();
                if (typeof uiAppearanceManager !== 'undefined') {
                    uiAppearanceManager.toggleControlsHints();
                }
                return;
            }
            if (e.key === 'Escape' || e.key === 'Backspace') {
                if (this._resBuyModal) {
                    e.preventDefault();
                    e.stopPropagation();
                    this.closeResourceBuyModal();
                    return;
                }
                // Component editor ship preview fullscreen — close preview only
                if (typeof componentEditorUI !== 'undefined' && componentEditorUI._previewFs) {
                    e.preventDefault();
                    e.stopPropagation();
                    componentEditorUI.leavePreviewFullscreen();
                    return;
                }
                // Esc climbs exactly one level, decided by what is focused (the
                // stored nav level can be stale after mouse use).
                if (this.escapeOneNavLevel()) {
                    e.preventDefault();
                    e.stopPropagation();
                    return;
                }
                // Esc only climbs nav levels: content → section → sub-nav → area row.
                if (this.isContentNavActive()) {
                    e.preventDefault();
                    e.stopPropagation();
                    this.exitTabContent();
                    return;
                }
                // In the area sub-nav row: ESC climbs to the area row first.
                if (this.getFocusedNavRow() === 'subnav') {
                    e.preventDefault();
                    e.stopPropagation();
                    this.focusNavRow('area');
                    return;
                }
                // On tab bar: ESC swaps the left (game) tab row for the right
                // (menu) tab row and back — nothing else.
                e.preventDefault();
                if (this.isMenuRowTab()) {
                    const back = this._lastGameTab || 'station';
                    if (this.tab === 'menu') this.unmountMenuTab();
                    else this.unmountComponentsTab();
                    this._menuOpts = null;
                    this._prevTab = null;
                    this._menuArmed = false;
                    this.statusMsg = '';
                    this.focusIndex = 0;
                    this.tab = back;
                    this.persistTab();
                    this.createUI();
                } else {
                    // Top of the hierarchy: ESC in the area row opens the menu
                    // (its tabs appear as the sub-nav row below the areas).
                    if (this.getFocusedNavRow() !== 'area') {
                        this._navLevel = 'tabs';
                        if (!this.focusNavRow || !this.focusNavRow('area')) this.focusActiveTab();
                        return;
                    }
                    this._lastGameTab = this.tab;
                    this.openMainMenuOverlay({ force: true });
                    return;
                }
                this._navLevel = 'tabs';
                this.focusActiveTab();
                return;
            }
            // Shift+Enter skips the section level and jumps straight into content.
            if (e.shiftKey && (e.key === 'Enter' || e.key === ' ') &&
                !this._resBuyModal && this.tab !== 'play' && this.tab !== 'menu' &&
                this.getNavLevel() !== 'content') {
                e.preventDefault();
                this._navLevel = 'sub';
                this.enterTabContent();
                return;
            }
            // Shift+←/→ always cycle main tabs (except resource-buy modal).
            if (e.shiftKey && (e.key === 'ArrowLeft' || e.key === 'ArrowRight')) {
                if (this._resBuyModal) {
                    e.preventDefault();
                    return;
                }
                e.preventDefault();
                this._navLevel = 'tabs';
                this.switchTab(e.key === 'ArrowLeft' ? -1 : 1);
                return;
            }
            if (e.key === 'ArrowLeft' || e.key === 'ArrowRight' ||
                e.key === 'ArrowUp' || e.key === 'ArrowDown') {
                e.preventDefault();
                const level = this.getNavLevel();
                // Area row ↔ sub-nav row ↔ content (see handleNavRowArrow).
                if (!this._resBuyModal && level === 'tabs' && this.handleNavRowArrow(e.key)) return;
                // Main tabs: ←/→ switch sections
                if (!this._resBuyModal && level === 'tabs' &&
                    (e.key === 'ArrowLeft' || e.key === 'ArrowRight')) {
                    this.switchTab(e.key === 'ArrowLeft' ? -1 : 1);
                    return;
                }
                // Sub-tabs: ←/→ switch shop/upgrade categories
                if (!this._resBuyModal && level === 'sub' &&
                    (e.key === 'ArrowLeft' || e.key === 'ArrowRight')) {
                    this.switchSubTab(e.key === 'ArrowLeft' ? -1 : 1);
                    return;
                }
                // Section tabs (e.g. RESOURCES / PARTS / PORTALS): ↓ into the
                // content, ↑ back up to the tab rows.
                if (!this._resBuyModal && level === 'sub' && e.key === 'ArrowDown') {
                    if (this.tab !== 'play') this.enterTabContent();
                    return;
                }
                if (!this._resBuyModal && level === 'sub' && e.key === 'ArrowUp') {
                    this.exitTabContent();
                    return;
                }
                const dir = e.key === 'ArrowLeft' ? 'left'
                    : e.key === 'ArrowRight' ? 'right'
                        : e.key === 'ArrowUp' ? 'up' : 'down';
                this.moveStationFocus(dir);
                return;
            }
            if (e.key === 'Enter' || e.key === ' ') {
                const level = this.getNavLevel();
                // Tab bar / section tabs: Enter goes one level deeper
                if (!this._resBuyModal && (level === 'tabs' || level === 'sub')) {
                    e.preventDefault();
                    const list = this.getFocusables();
                    const focused = list[this.focusIndex];
                    const menuTabId = focused && focused.getAttribute && focused.getAttribute('data-menu-tab');
                    const shownMenuTab = (this.tab === 'menu' && typeof startScreenManager !== 'undefined')
                        ? startScreenManager.embeddedMenuTab : null;
                    // Menu tab row: ENTER goes into the shown section (unless a
                    // different, not-yet-shown menu tab is focused).
                    if (level === 'tabs' && focused && focused.hasAttribute && focused.hasAttribute('data-open-menu')) {
                        this.openMainMenuOverlay(this.menuButtonOpts(focused));
                        return;
                    }
                    if (focused && focused.hasAttribute && focused.hasAttribute('data-play-launch')) {
                        this.launchPlay();
                        return;
                    }
                    if (level === 'tabs' && focused && focused.id === 'hsLogout') {
                        this.logout();
                        return;
                    }
                    if (level === 'tabs' && menuTabId && menuTabId === this.tab) {
                        this.enterTabContent();
                        return;
                    }
                    if (level === 'tabs' && this.tab === 'menu' && (!menuTabId || menuTabId === shownMenuTab)) {
                        this.enterMenuContent();
                        return;
                    }
                    if (level === 'tabs' && menuTabId) {
                        this.openMainMenuOverlay({ tab: menuTabId });
                        this.focusActiveTab();
                        return;
                    }
                    if (level === 'tabs' && this.isMenuChrome(focused)) {
                        this.openMainMenuOverlay();
                        return;
                    }
                    if (level === 'sub') {
                        if (focused && this.isSubTabEl(focused) &&
                            !focused.classList.contains('active')) {
                            this.activateFocused();
                            return;
                        }
                    }
                    this.enterTabContent();
                    return;
                }
                if (this.tab === 'play' && !playMapActive) {
                    e.preventDefault();
                    this.enterPlayMap();
                    return;
                }
                e.preventDefault();
                this.activateFocused();
            }
        };
        document.addEventListener('keydown', this._keyHandler);
    },
    bindEvents() {
        this.bindNavigationEvents();
        this.bindShopEvents();
        this.bindStationEvents();
        this.bindHangarTabEvents();
        this.bindKeyNav();
    },
});


/* --- js/ui/home-station/bind-navigation-events.js?v=crest-3 --- */
"use strict";

// HomeStationUI methods, split from home-station.js.
extendClass(HomeStationUI, {
    /** Menu, logout, tabs and explore buttons. */
    bindNavigationEvents() {
        const menu = this.overlay.querySelector('#hsMenu');
        if (menu) menu.addEventListener('click', () => this.openMainMenuOverlay());
        this.overlay.querySelectorAll('[data-menu-tab]').forEach((btn) => {
            btn.addEventListener('click', () => {
                this.openMainMenuOverlay({ tab: btn.getAttribute('data-menu-tab') });
            });
        });
        const logout = this.overlay.querySelector('#hsLogout');
        if (logout) logout.addEventListener('click', () => this.logout());
        const root = this.overlay.querySelector('.home-station-content');
        if (root) {
            const activatePointerMode = () => {
                root.classList.add('hs-pointer-mode');
            };
            root.addEventListener('pointermove', activatePointerMode);
            root.addEventListener('pointerenter', activatePointerMode);
            root.addEventListener('mousemove', activatePointerMode);
        }

        this.bindResourceBuyModalEvents();
        this.bindTabOrderEditing();
        this.alignCreditsBarToTabs();

        this.overlay.querySelectorAll('[data-tab]').forEach((btn) => {
            btn.addEventListener('click', () => {
                const next = btn.getAttribute('data-tab') || 'station';
                if (this.tab === 'menu' && next !== 'menu') {
                    this.unmountMenuTab();
                    this._menuOpts = null;
                    this._prevTab = null;
                }
                this.tab = next;
                this._resBuyModal = null;
                this.statusMsg = '';
                this.focusIndex = 0;
                this._navLevel = 'tabs';
                this.persistTab();
                this.createUI();
            });
        });

        this.overlay.querySelectorAll('[data-explore]').forEach((btn) => {
            btn.addEventListener('click', () => {
                this.openExploration(btn.getAttribute('data-explore'));
            });
        });
    },

    /** Shop filters, frame/module upgrades, galaxy travel and the resource market. */
    bindShopEvents() {
        this.bindTradingPostEvents();
        this.bindShopSellEvents();
        this.bindShopStyleEvents();
        this.overlay.querySelectorAll('[data-shop-cat]').forEach((btn) => {
            btn.addEventListener('click', () => {
                const prev = this.shopCategory;
                this.shopCategory = btn.getAttribute('data-shop-cat') || 'ships';
                this.resetShopControlsIfNeeded(prev);
                this.statusMsg = '';
                this.focusIndex = 0;
                this._navLevel = 'sub';
                this.persistTab();
                this.createUI();
            });
        });

        this.overlay.querySelectorAll('[data-upgrade-sub]').forEach((btn) => {
            btn.addEventListener('click', () => {
                this.upgradeSubTab = btn.getAttribute('data-upgrade-sub') || 'station';
                this.persistTab();
                this._resBuyModal = null;
                this.statusMsg = '';
                this.focusIndex = 0;
                this._navLevel = 'sub';
                this.createUI();
            });
        });

        this.bindAreaUpgradeButtons();
        this.overlay.querySelectorAll('[data-frame-up]').forEach((btn) => {
            btn.addEventListener('click', () => {
                const id = btn.getAttribute('data-frame-up');
                const res = profileManager.purchaseShipFrameUpgrade(id);
                if (res.ok) {
                    this.playButtonResult(btn, true, 'FRAME UPGRADED: ' + this.shipName(id) + ' L' + res.level);
                } else if (res.reason === 'RESOURCES') {
                    this.openResourceBuyModal({
                        title: this.shipName(id) + ' · FRAME L' + (res.nextLevel || ''),
                        cost: res.cost,
                        action: { type: 'frame-upgrade', id: id }
                    });
                } else {
                    this.playButtonResult(btn, false, res.reason || 'FAILED');
                }
            });
        });

        this.overlay.querySelectorAll('[data-mod-up]').forEach((btn) => {
            btn.addEventListener('click', () => {
                const raw = btn.getAttribute('data-mod-up') || '';
                const sep = raw.indexOf(':');
                const cat = sep === -1 ? '' : raw.slice(0, sep);
                const track = sep === -1 ? raw : raw.slice(sep + 1);
                const res = profileManager.purchaseModuleUpgrade(cat, track);
                if (res.ok) {
                    this.playButtonResult(btn, true, 'MODULE UPGRADE: ' + cat.toUpperCase() + '/' + track.toUpperCase() + ' L' + res.level);
                } else if (res.reason === 'RESOURCES') {
                    const meta = (typeof economyConfig !== 'undefined' &&
                        economyConfig.moduleUpgradeDefs &&
                        economyConfig.moduleUpgradeDefs[cat] &&
                        economyConfig.moduleUpgradeDefs[cat][track])
                        ? economyConfig.moduleUpgradeDefs[cat][track]
                        : null;
                    this.openResourceBuyModal({
                        title: ((meta && meta.label) || (cat + '/' + track)).toUpperCase() +
                            (res.nextLevel ? (' · L' + res.nextLevel) : ''),
                        cost: res.cost,
                        action: { type: 'module-upgrade', cat: cat, track: track }
                    });
                } else {
                    this.playButtonResult(btn, false, res.reason || 'FAILED');
                }
            });
        });

        this.overlay.querySelectorAll('[data-travel]').forEach((btn) => {
            btn.addEventListener('click', () => {
                const gid = btn.getAttribute('data-travel');
                const res = profileManager.travelToGalaxy(gid);
                if (res.ok) {
                    const name = String(gid).replace(/_/g, ' ').toUpperCase();
                    const factionTag = res.faction ? (' · ' + String(res.faction).toUpperCase()) : '';
                    const seeded = res.seeded
                        ? (' · ' + ((res.planetIds && res.planetIds.length) || 0) + ' PLANETS CHARTED')
                        : '';
                    this.playButtonResult(btn, true, 'TRAVELLED TO ' + name + factionTag + seeded);
                } else if (res.reason === 'DRIVE') {
                    this.playButtonResult(btn, false, 'NEED WARP L' + (res.requireWarp || 1) + ' OR BUY PORTAL');
                } else {
                    this.playButtonResult(btn, false, res.reason || 'FAILED');
                }
            });
        });

        this.overlay.querySelectorAll('[data-shop-filter]').forEach((btn) => {
            btn.addEventListener('click', () => {
                this.shopFilter = btn.getAttribute('data-shop-filter') || 'all';
                this.captureShopPrefs();
                this.persistTab();
                this.statusMsg = '';
                if (this._navLevel !== 'tabs') this._navLevel = 'content';
                this.createUI();
            });
        });

        this.overlay.querySelectorAll('[data-shop-sort]').forEach((btn) => {
            btn.addEventListener('click', () => {
                this.shopSort = btn.getAttribute('data-shop-sort') || 'name';
                this.captureShopPrefs();
                this.persistTab();
                this.statusMsg = '';
                if (this._navLevel !== 'tabs') this._navLevel = 'content';
                this.createUI();
            });
        });

        this.overlay.querySelectorAll('[data-shop-qty]').forEach((btn) => {
            btn.addEventListener('click', () => {
                const raw = btn.getAttribute('data-shop-qty') || '1';
                const q = raw === 'all' ? 'all' : Math.round(Number(raw) || 1);
                this.shopResourceQty = this._resourceQtyOptions.indexOf(q) !== -1 ? q : 1;
                this.captureShopPrefs();
                this.persistTab();
                this.statusMsg = '';
                if (this._navLevel !== 'tabs') this._navLevel = 'content';
                this.createUI();
            });
        });

        this.overlay.querySelectorAll('[data-buy-res]').forEach((btn) => {
            btn.addEventListener('click', () => {
                const id = btn.getAttribute('data-buy-res');
                const bag = this.shopFilter === 'cargo' ? 'cargo' : 'station';
                const profile = this.getProfile();
                const qty = this.resolveResourceTradeQty(profile, id, bag, 'buy');
                if (qty < 1) {
                    this.playButtonResult(btn, false, 'NO ROOM OR CREDITS');
                    return;
                }
                const res = profileManager.buyShopResource(id, qty, bag);
                if (res.ok) {
                    const label = (typeof economyConfig !== 'undefined')
                        ? economyConfig.getResourceLabel(id)
                        : String(id).toUpperCase();
                    this.playButtonResult(btn, true, 'BOUGHT ' + res.amount + ' ' + label + ' → ' + bag.toUpperCase());
                } else {
                    this.playButtonResult(btn, false, res.reason || 'FAILED');
                }
            });
        });

        this.overlay.querySelectorAll('[data-sell-res]').forEach((btn) => {
            btn.addEventListener('click', () => {
                const id = btn.getAttribute('data-sell-res');
                const bag = this.shopFilter === 'cargo' ? 'cargo' : 'station';
                const profile = this.getProfile();
                const qty = this.resolveResourceTradeQty(profile, id, bag, 'sell');
                if (qty < 1) {
                    this.playButtonResult(btn, false, 'EMPTY');
                    return;
                }
                const res = profileManager.sellShopResource(id, qty, bag);
                if (res.ok) {
                    const label = (typeof economyConfig !== 'undefined')
                        ? economyConfig.getResourceLabel(id)
                        : String(id).toUpperCase();
                    const cred = (res.payout && res.payout.credits) || 0;
                    this.playButtonResult(btn, true, 'SOLD ' + res.amount + ' ' + label + ' · +' + cred + ' CREDITS');
                } else {
                    this.playButtonResult(btn, false, res.reason || 'FAILED');
                }
            });
        });
    },

    /** Start the resource row under the first tab so the crest can hang beside it. */
    alignCreditsBarToTabs() {
        const header = this.overlay && this.overlay.querySelector('.hs-header');
        const tabs = header && header.querySelector('.hs-tabs');
        // Set on the whole station box: tabs without a resource row (PLAY)
        // indent their first content row by the same amount.
        const root = header && header.closest('.home-station-content');
        if (!tabs || !root) return;
        const measure = () => {
            // Shift the whole tab row (PLAY button included) so its left edge
            // lines up with the first container below it.
            const body = header.nextElementSibling;
            const first = body && body.firstElementChild;
            const play = header.querySelector('[data-play-launch]') || tabs;
            if (first) {
                const zoom = window.vfEffectiveZoom ? window.vfEffectiveZoom(header) : 1;
                const cur = parseFloat(header.dataset.alignPad) || 0;
                const base = play.getBoundingClientRect().left - cur * zoom;
                const pad = Math.round((first.getBoundingClientRect().left - base) / zoom);
                // Hysteresis: ignore sub-2px differences so the row never jitters.
                if (Math.abs(pad) <= 30 && Math.abs(pad - cur) >= 2) {
                    header.dataset.alignPad = String(pad);
                    header.style.paddingLeft = pad + 'px';
                }
            }
            // Exclude the alignment padding itself, else offset and padding feed
            // each other and the row swings left/right while loading.
            const zoom2 = window.vfEffectiveZoom ? window.vfEffectiveZoom(header) : 1;
            const offset = (tabs.getBoundingClientRect().left - header.getBoundingClientRect().left) / zoom2 - (parseFloat(header.dataset.alignPad) || 0);
            root.style.setProperty('--hs-tabs-offset', Math.max(0, Math.round(offset)) + 'px');
        };
        measure();
        requestAnimationFrame(measure);
        // The content below builds up and the window / zoom can change after
        // this point: measure again so the row stays flush with it.
        // Re-measure only on a real window resize (debounced), never in a loop.
        if (!this._tabsAlignResizeBound) {
            this._tabsAlignResizeBound = true;
            let t = 0;
            window.addEventListener('resize', () => {
                clearTimeout(t);
                t = setTimeout(() => { const h = this.overlay && this.overlay.querySelector('.hs-header'); if (h) this.alignCreditsBarToTabs(); }, 200);
            });
        }
    },

    /**
     * Dev mode (Shift+C): drag tabs and '|' dividers within their row to
     * reorder them. Main row only: drag the "+ |" handle in to add a divider,
     * drag a divider out of the row to remove it.
     */
    bindTabOrderEditing() {
        if (typeof MENU_ORDER === 'undefined' || typeof startScreenManager === 'undefined' ||
            !startScreenManager.devMode) return;
        const row = this.overlay.querySelector('.hs-tabs');
        if (!row) return;
        // Top bar of areas: items carry data-area-order-index into getAreaOrder().
        const areaMode = !!row.querySelector('[data-area-order-index]');
        const isEsc = !areaMode && this.isMenuRowTab();
        const list = areaMode ? getAreaOrder() : (isEsc ? MENU_ORDER.esc : MENU_ORDER.main);
        const NEW_DIVIDER = -2;
        // Main row items carry their MENU_ORDER.main index; ESC row items are found by id.
        const indexOf = (el) => areaMode
            ? parseInt(el.getAttribute('data-area-order-index'), 10)
            : (isEsc
                ? list.indexOf(el.getAttribute('data-menu-tab'))
                : parseInt(el.getAttribute('data-order-index'), 10));
        const items = Array.from(row.querySelectorAll(areaMode ? '[data-area-order-index]' : (isEsc ? '[data-menu-tab]' : '[data-order-index]')))
            .filter((el) => indexOf(el) >= 0);
        const commit = () => {
            if (areaMode) {
                saveAreaOrder(list);
            } else {
                saveMenuOrder();
                this.applyMenuOrder();
            }
            this.createUI();
        };

        row.classList.add('hs-tabs-editing');
        // One bar shows where the dragged item will land (tabs are clip-pathed,
        // so it cannot be drawn on the tabs themselves).
        const marker = document.createElement('span');
        marker.className = 'hs-drop-marker';
        marker.setAttribute('aria-hidden', 'true');
        row.appendChild(marker);

        let dragFrom = -1;
        let dropAt = -1; // insertion index into list (before removal)
        const hideMarker = () => {
            marker.classList.remove('visible');
            dropAt = -1;
        };
        const showMarker = (el, after) => {
            const gap = 1;
            marker.style.left = (el.offsetLeft + (after ? el.offsetWidth + gap : -gap - 2)) + 'px';
            marker.style.top = el.offsetTop + 'px';
            marker.style.height = el.offsetHeight + 'px';
            marker.classList.add('visible');
        };
        const isNoop = (to) => dragFrom >= 0 && (to === dragFrom || to === dragFrom + 1);

        const startDrag = (el, from, e) => {
            dragFrom = from;
            e.dataTransfer.effectAllowed = 'move';
            try { e.dataTransfer.setData('text/plain', 'hs-tab'); } catch (err) { /* ignore */ }
            el.classList.add('hs-tab-dragging');
            row.classList.add('hs-tabs-dragging');
        };
        const endDrag = (el) => {
            dragFrom = -1;
            hideMarker();
            el.classList.remove('hs-tab-dragging');
            row.classList.remove('hs-tabs-dragging');
        };

        items.forEach((el) => {
            el.draggable = true;
            el.addEventListener('dragstart', (e) => startDrag(el, indexOf(el), e));
            el.addEventListener('dragend', (e) => {
                const from = dragFrom;
                endDrag(el);
                // A divider dropped outside the row is removed.
                if (!isEsc && from >= 0 && list[from] === '|' && e.dataTransfer.dropEffect === 'none') {
                    list.splice(from, 1);
                    commit();
                }
            });
        });

        // The whole row is the drop zone (gaps and row ends included): the
        // insertion point is the item edge closest to the pointer.
        const findDrop = (clientX) => {
            for (let k = 0; k < items.length; k++) {
                const rect = items[k].getBoundingClientRect();
                if (clientX < rect.left + rect.width / 2) return { el: items[k], after: false, to: indexOf(items[k]) };
            }
            const last = items[items.length - 1];
            return last ? { el: last, after: true, to: indexOf(last) + 1 } : null;
        };
        row.addEventListener('dragover', (e) => {
            if (dragFrom === -1) return;
            const hit = findDrop(e.clientX);
            if (!hit || isNoop(hit.to)) {
                hideMarker();
                return;
            }
            e.preventDefault();
            e.dataTransfer.dropEffect = dragFrom === NEW_DIVIDER ? 'copy' : 'move';
            dropAt = hit.to;
            showMarker(hit.el, hit.after);
        });
        row.addEventListener('drop', (e) => {
            e.preventDefault();
            const to = dropAt;
            const from = dragFrom;
            if (to < 0 || from === -1) return;
            if (from === NEW_DIVIDER) {
                list.splice(to, 0, '|');
            } else {
                const moved = list.splice(from, 1)[0];
                list.splice(from < to ? to - 1 : to, 0, moved);
            }
            commit();
        });
        row.addEventListener('dragleave', (e) => {
            if (!row.contains(e.relatedTarget)) hideMarker();
        });

        // Top bar: a "+ |" handle adds a divider (drag it between buttons); a
        // divider dragged out of the bar is removed.
        if (areaMode) {
            const handle = document.createElement('span');
            handle.className = 'hs-tab-divider-handle';
            handle.textContent = '+ |';
            handle.draggable = true;
            handle.title = 'Drag between buttons to add a divider';
            handle.addEventListener('dragstart', (e) => startDrag(handle, NEW_DIVIDER, e));
            handle.addEventListener('dragend', () => endDrag(handle));
            row.appendChild(handle);
        }
    },
});


/* --- js/ui/home-station/station-col-resize.js?v=1 --- */
"use strict";

// HomeStationUI: draggable column borders in the station storage grid
// (owned ships | blueprints | parts). Widths are kept as fr weights.
const STATION_COLS_KEY = 'vf_station_cols_v1';
const STATION_COLS_MIN = 0.25;

extendClass(HomeStationUI, {
    getStationCols() {
        try {
            const v = JSON.parse(localStorage.getItem(STATION_COLS_KEY) || 'null');
            if (Array.isArray(v) && v.length === 3 && v.every((n) => n >= STATION_COLS_MIN)) return v;
        } catch (e) { /* ignore */ }
        return [1, 1, 1];
    },

    bindStationColumnResize() {
        const grid = this.overlay && this.overlay.querySelector('.hs-station-grid');
        if (!grid) return;
        const cols = this.getStationCols();
        const apply = () => { grid.style.gridTemplateColumns = cols.map((c) => `minmax(0, ${c}fr)`).join(' '); };
        apply();
        const panels = ['.hs-panel-ships', '.hs-panel-bp', '.hs-panel-parts']
            .map((s) => grid.querySelector(s));
        if (panels.some((p) => !p)) return;
        grid.style.position = 'relative';
        const handles = [0, 1].map((i) => {
            const h = document.createElement('div');
            h.className = 'hs-col-resize';
            h.title = 'Drag to resize (double-click to reset)';
            grid.appendChild(h);
            return h;
        });
        const place = () => {
            handles.forEach((h, i) => {
                const a = panels[i];
                const b = panels[i + 1];
                const gap = b.offsetLeft - (a.offsetLeft + a.offsetWidth);
                h.style.left = (a.offsetLeft + a.offsetWidth + gap / 2 - 6) + 'px';
                h.style.top = a.offsetTop + 'px';
                h.style.height = a.offsetHeight + 'px';
            });
        };
        place();
        handles.forEach((h, i) => {
            h.addEventListener('dblclick', () => {
                cols[0] = cols[1] = cols[2] = 1;
                apply(); place();
                try { localStorage.removeItem(STATION_COLS_KEY); } catch (e) { /* ignore */ }
            });
            h.addEventListener('pointerdown', (e) => {
                e.preventDefault();
                e.stopPropagation();
                h.setPointerCapture(e.pointerId);
                const total = cols.reduce((s, c) => s + c, 0);
                const px = panels.reduce((s, p) => s + p.offsetWidth, 0) || 1;
                const startX = e.clientX;
                const pair = cols[i] + cols[i + 1];
                const startA = cols[i];
                h.classList.add('is-dragging');
                const move = (ev) => {
                    const d = (ev.clientX - startX) / px * total;
                    cols[i] = Math.max(STATION_COLS_MIN, Math.min(pair - STATION_COLS_MIN, startA + d));
                    cols[i + 1] = pair - cols[i];
                    apply(); place();
                };
                const up = () => {
                    h.classList.remove('is-dragging');
                    h.removeEventListener('pointermove', move);
                    h.removeEventListener('pointerup', up);
                    h.removeEventListener('pointercancel', up);
                    try { localStorage.setItem(STATION_COLS_KEY, JSON.stringify(cols)); } catch (err) { /* ignore */ }
                };
                h.addEventListener('pointermove', move);
                h.addEventListener('pointerup', up);
                h.addEventListener('pointercancel', up);
            });
        });
        if (window.ResizeObserver) new ResizeObserver(place).observe(grid);
    },

    /** Hangar: RESET ANATOMY / SET AS DEFAULT sit on the right of the ship's title row, so the stats row keeps its room. */
    moveHangarBayTools() {
        const tools = this.overlay && this.overlay.querySelector('.hs-hangar-bay-tools');
        const title = this.overlay && this.overlay.querySelector('.hs-hangar-head-title');
        if (!tools || !title) return;
        tools.classList.add('is-topbar');
        title.appendChild(tools);
    }
});


/* --- js/ui/home-station/bind-station-events.js?v=pull-1 --- */
"use strict";

// HomeStationUI methods, split from home-station.js.
extendClass(HomeStationUI, {
    /** Cargo teleport, station upgrade tree, unlocks, purchases and crafting. */
    bindStationEvents() {
        const teleport = this.overlay.querySelector('#hsTeleport');
        if (teleport) {
            teleport.addEventListener('click', () => {
                if (typeof profileManager === 'undefined') return;
                if (!profileManager.hasCargo()) {
                    this.playButtonResult(teleport, false, 'CARGO EMPTY');
                    return;
                }
                const moved = profileManager.teleportCargoToStation();
                if (!moved) {
                    this.playButtonResult(teleport, false, 'STATION FULL — UPGRADE STORAGE');
                    return;
                }
                if (profileManager.hasCargo()) {
                    this.playButtonResult(teleport, true, 'PARTIAL TELEPORT — STORAGE FULL');
                } else {
                    this.playButtonResult(teleport, true, 'CARGO TELEPORTED TO STATION');
                }
            });
        }

        this.overlay.querySelectorAll('[data-upgrade-node]').forEach((btn) => {
            btn.addEventListener('click', (ev) => {
                const id = btn.getAttribute('data-upgrade-node');
                this.selectedUpgradeNode = id;
                if (btn.hasAttribute('data-upgrade')) {
                    return;
                }
                ev.preventDefault();
                const node = (typeof economyConfig !== 'undefined')
                    ? economyConfig.getStationUpgradeNode(id)
                    : null;
                if (!node) return;
                const profile = this.getProfile();
                const level = profileManager.getStationUpgradeLevel(id, profile);
                if (level >= node.maxLevel) {
                    this.playButtonResult(btn, true, node.label + ' · MAX');
                    return;
                }
                const check = profileManager.canUnlockStationUpgrade(id, profile);
                if (check.reason === 'LOCKED') {
                    const req = economyConfig.getStationUpgradeNode(node.requires);
                    const reqName = req ? req.label : String(node.requires || '').toUpperCase();
                    this.playButtonResult(btn, false, 'REQ ' + reqName + ' L' + (node.requireLevel || 1));
                } else if (check.reason === 'RESOURCES') {
                    const cost = check.cost || economyConfig.getStationUpgradeCost(id, level + 1);
                    this.openResourceBuyModal({
                        title: node.label + ' · L' + (level + 1),
                        cost: cost,
                        action: { type: 'station-upgrade', id: id }
                    });
                } else {
                    this.playButtonResult(btn, false, check.reason || node.label);
                }
            });
        });
        this.bindUpgradeTipEvents();

        this.overlay.querySelectorAll('[data-upgrade]').forEach((btn) => {
            btn.addEventListener('click', () => {
                const id = btn.getAttribute('data-upgrade');
                this.selectedUpgradeNode = id;
                const res = profileManager.buyStationUpgrade(id);
                if (res.ok) {
                    const node = (typeof economyConfig !== 'undefined')
                        ? economyConfig.getStationUpgradeNode(id)
                        : null;
                    const label = node ? node.label : String(id || '').toUpperCase();
                    this.playButtonResult(btn, true, 'UPGRADED: ' + label + ' L' + res.level);
                } else if (res.reason === 'RESOURCES') {
                    const profile = this.getProfile();
                    const node = (typeof economyConfig !== 'undefined')
                        ? economyConfig.getStationUpgradeNode(id)
                        : null;
                    const level = profileManager.getStationUpgradeLevel(id, profile);
                    const cost = (typeof economyConfig !== 'undefined')
                        ? economyConfig.getStationUpgradeCost(id, level + 1)
                        : null;
                    this.openResourceBuyModal({
                        title: (node ? node.label : String(id || '').toUpperCase()) + ' · L' + (level + 1),
                        cost: cost,
                        action: { type: 'station-upgrade', id: id }
                    });
                } else {
                    this.playButtonResult(btn, false, res.reason || 'FAILED');
                }
            });
        });

        this.overlay.querySelectorAll('[data-unlock]').forEach((btn) => {
            btn.addEventListener('click', () => {
                const id = btn.getAttribute('data-unlock');
                const res = profileManager.unlockShopItem(id);
                this.playButtonResult(btn, !!res.ok, res.ok ? ('UNLOCKED: ' + this.shipName(id)) : (res.reason || 'FAILED'));
            });
        });

        this.overlay.querySelectorAll('[data-buy]').forEach((btn) => {
            btn.addEventListener('click', () => {
                const id = btn.getAttribute('data-buy');
                const res = profileManager.buyShip(id);
                this.playButtonResult(btn, !!res.ok, res.ok ? ('PURCHASED: ' + this.shipName(id)) : (res.reason || 'FAILED'));
            });
        });

        this.overlay.querySelectorAll('[data-buy-bp]').forEach((btn) => {
            btn.addEventListener('click', () => {
                const id = btn.getAttribute('data-buy-bp');
                const res = profileManager.buyBlueprint(id);
                this.playButtonResult(btn, !!res.ok, res.ok ? ('BLUEPRINT: ' + this.shipName(id)) : (res.reason || 'FAILED'));
            });
        });

        this.overlay.querySelectorAll('[data-buy-part]').forEach((btn) => {
            btn.addEventListener('click', () => {
                const raw = btn.getAttribute('data-buy-part') || '';
                const sep = raw.indexOf(':');
                const kind = sep === -1 ? '' : raw.slice(0, sep);
                const id = sep === -1 ? raw : raw.slice(sep + 1);
                const res = profileManager.buyPart(kind, id, this.visitPostId || null);
                this.playButtonResult(btn, !!res.ok, res.ok ? ('PART: ' + id.toUpperCase()) : (res.reason || 'FAILED'));
            });
        });

        this.overlay.querySelectorAll('[data-buy-portal]').forEach((btn) => {
            btn.addEventListener('click', () => {
                const gid = btn.getAttribute('data-buy-portal');
                const res = profileManager.buyPortal(gid);
                if (res.ok) {
                    const name = String(gid).replace(/_/g, ' ').toUpperCase();
                    this.playButtonResult(btn, true, 'PORTAL UNLOCKED: ' + name);
                } else if (res.reason === 'UNKNOWN FACTION') {
                    this.playButtonResult(btn, false, 'MEET THIS FACTION IN COMBAT FIRST');
                } else {
                    this.playButtonResult(btn, false, res.reason || 'FAILED');
                }
            });
        });

        this.overlay.querySelectorAll('[data-craft]').forEach((btn) => {
            btn.addEventListener('click', () => {
                const id = btn.getAttribute('data-craft');
                const res = profileManager.craftShip(id);
                this.playButtonResult(btn, !!res.ok, res.ok ? ('CRAFTED: ' + this.shipName(id)) : (res.reason || 'FAILED'));
            });
        });
    },

    /** Hangar ship list, anatomy reset, module toggles, fire modes and test area. */
    bindHangarTabEvents() {
        this.overlay.querySelectorAll('[data-hangar-ship]').forEach((btn) => {
            btn.addEventListener('click', () => {
                const selectedShipId = btn.getAttribute('data-hangar-ship');
                if (selectedShipId === this.hangarShipId) return;
                this.hangarShipId = selectedShipId;
                this.statusMsg = '';
                this.createUI();
            });
        });

        this.overlay.querySelectorAll('[data-hangar-sidebar]').forEach((btn) => {
            btn.addEventListener('click', () => {
                this.toggleHangarSidebar(btn.getAttribute('data-hangar-sidebar'));
            });
        });
        // A collapsed live-preview strip opens from a click anywhere on it.
        const collapsedPreview = this.overlay.querySelector('.hs-hangar-split.hs-hangar-right-collapsed > .hs-hangar-preview');
        if (collapsedPreview) {
            collapsedPreview.style.cursor = 'pointer';
            collapsedPreview.addEventListener('click', (e) => {
                if (e.target.closest('[data-hangar-sidebar]')) return; // the button handles itself
                this.toggleHangarSidebar('right');
            });
        }
        const resetAnatomy = this.overlay.querySelector('#hsResetAnatomy');
        if (resetAnatomy) resetAnatomy.addEventListener('click', () => this.resetHangarAnatomy());
        const saveAnatomy = this.overlay.querySelector('#hsSaveAnatomyDefault');
        if (saveAnatomy) saveAnatomy.addEventListener('click', () => this.saveHangarAnatomyDefault());
        this.overlay.querySelectorAll('[data-activate-ship]').forEach((btn) => {
            btn.addEventListener('click', () => {
                const id = btn.getAttribute('data-activate-ship');
                if (typeof profileManager !== 'undefined' && profileManager.setActiveShip) {
                    profileManager.setActiveShip(id);
                } else if (typeof profileManager !== 'undefined') {
                    const p = profileManager.getActiveProfile();
                    if (p) {
                        p.activeShipId = id;
                        profileManager.save();
                    }
                }
                if (typeof shipConfigManager !== 'undefined') {
                    shipConfigManager.applyToRuntime(id);
                }
                this.playButtonResult(btn, true, 'ACTIVE: ' + this.shipName(id));
            });
        });

        this.overlay.querySelectorAll('[data-toggle-mod]').forEach((btn) => {
            btn.addEventListener('click', (e) => {
                const kind = btn.getAttribute('data-toggle-mod');
                const modId = btn.getAttribute('data-mod-id');
                if (e.altKey || e.shiftKey) {
                    e.preventDefault();
                    this.openComponentEditorForModule(kind, modId);
                    return;
                }
                if (typeof shipLoadoutManager === 'undefined') return;
                const check = shipLoadoutManager.canInstallModule(this.hangarShipId, kind, modId);
                if (!check.ok && !check.removing) {
                    let msg = 'SLOT FULL — UPGRADE FRAME';
                    if (check.reason === 'NEED_CHARGE_SHOT') msg = 'NEED CHARGE SHOT FIRST';
                    if (check.reason === 'NEED_CHARGE_DRIVE') msg = 'NEED CHARGE DRIVE FIRST';
                    this.playButtonResult(btn, false, msg);
                    return;
                }
                shipLoadoutManager.toggleModule(this.hangarShipId, kind, modId);
                if (typeof shipConfigManager !== 'undefined') {
                    const active = (typeof profileManager !== 'undefined' && profileManager.getActiveProfile())
                        ? profileManager.getActiveProfile().activeShipId
                        : this.hangarShipId;
                    if (active === this.hangarShipId) {
                        shipConfigManager.applyToRuntime(this.hangarShipId);
                    }
                }
                const L = shipLoadoutManager.getLoadout(this.hangarShipId);
                const n = shipLoadoutManager.moduleCount(L);
                this.playButtonResult(btn, true, 'LOADOUT UPDATED · ' + n + ' MODULES');
            });
            btn.addEventListener('contextmenu', (e) => {
                e.preventDefault();
                const kind = btn.getAttribute('data-toggle-mod');
                const modId = btn.getAttribute('data-mod-id');
                this.openComponentEditorForModule(kind, modId);
            });
        });

        // Main voxel size slider in the hangar header: live redraw, and keep
        // the other voxel sliders (area panels) in step.
        this.overlay.querySelectorAll('[data-hangar-voxel]').forEach((input) => {
            input.addEventListener('input', () => {
                if (typeof shipLoadoutManager === 'undefined' || !shipLoadoutManager.setVoxelScale) return;
                const value = Number(input.value);
                shipLoadoutManager.setVoxelScale(this.hangarShipId, value);
                const out = this.overlay.querySelector('[data-hangar-voxel-out]');
                if (out) out.textContent = value.toFixed(2) + '×';
                this.overlay.querySelectorAll('[data-voxel-scale]').forEach((other) => {
                    if (other !== input) other.value = String(value);
                });
                this.drawHangarBay();
            });
        });

        // Zoom buttons in the bay (the mouse wheel zooms too).
        const zoomSlider = this.overlay.querySelector('#hsBayZoomSlider');
        if (zoomSlider) {
            zoomSlider.addEventListener('input', () => this.hangarBayZoomStep('set', zoomSlider.value));
            this.syncHangarZoomSlider();
        }
        this.overlay.querySelectorAll('[data-bay-zoom]').forEach((btn) => {
            btn.addEventListener('click', () => this.hangarBayZoomStep(btn.getAttribute('data-bay-zoom')));
        });

        const openTest = this.overlay.querySelector('#hsOpenTestArea');
        if (openTest) {
            openTest.addEventListener('click', () => this.openHangarTestArea());
        }
    },

    /**
     * Ship fire mode (AUTO / CHARGE), set from the weapon details panel.
     * Returns true when the mode was applied.
     */
    setHangarFireMode(mode, btn) {
        if (typeof shipLoadoutManager === 'undefined') return false;
        if (mode === 'charge' && !shipLoadoutManager.ownsChargePart('ability', 'charge_shot')) {
            this.playButtonResult(btn, false, 'BUY CHARGE SHOT IN PARTS SHOP');
            return false;
        }
        const before = shipLoadoutManager.getLoadout(this.hangarShipId);
        shipLoadoutManager.setFireMode(this.hangarShipId, mode);
        const after = shipLoadoutManager.getLoadout(this.hangarShipId);
        if (mode === 'charge' && (after.abilities || []).indexOf('charge_shot') === -1) {
            this.playButtonResult(btn, false, 'NO ABILITY SLOT — UPGRADE FRAME');
            return false;
        }
        if (typeof shipConfigManager !== 'undefined') {
            const active = (typeof profileManager !== 'undefined' && profileManager.getActiveProfile())
                ? profileManager.getActiveProfile().activeShipId
                : this.hangarShipId;
            if (active === this.hangarShipId) {
                shipConfigManager.applyToRuntime(this.hangarShipId);
            }
        }
        if (typeof bulletManager !== 'undefined' && bulletManager.setFireMode) {
            bulletManager.setFireMode(after.fireMode || 'auto');
        }
        if (typeof chargeSystem !== 'undefined' && typeof shipConfigManager !== 'undefined') {
            const model = shipConfigManager.getMergedModel(this.hangarShipId);
            if (model) chargeSystem.syncFromShipModel(model);
        }
        void before;
        this.playButtonResult(btn, true, 'FIRE MODE: ' + String(after.fireMode || 'auto').toUpperCase());
        return true;
    },
});


