"use strict";

// HomeStationUI methods, split from home-station.js.
extendClass(HomeStationUI, {
    renderComponentTree(shipId, treeContainer) {
        if (!this.overlay) return;
        shipId = shipId || this.hangarShipId || 'player_scrap';
        treeContainer = treeContainer || this.overlay.querySelector(`[data-ship-id="${shipId}"]`);
        if (!treeContainer) return;
        if (typeof window.componentTree !== 'undefined') {
            window.componentTree.setShip(shipId);
            treeContainer.querySelectorAll('.hs-tree-branch, .hs-tree-item').forEach((node) => {
                window.componentTree.setNodeExpanded(node.id, node.open);
                // Accordion: opening a section closes its open siblings.
                if (!this._areaPager && node.open && node.classList.contains('hs-tree-branch') && node.parentElement) {
                    Array.from(node.parentElement.children).forEach((sib) => {
                        if (sib !== node && sib.classList.contains('hs-tree-branch') && sib.open) sib.open = false;
                    });
                }
            });
        }

        const modelClass = this.shipModelClass(
            shipId,
            typeof shipConfigManager !== 'undefined' ? shipConfigManager.getConfig(shipId) : null
        ) || 'starfighter';
        const merged = (typeof shipConfigManager !== 'undefined' && shipConfigManager.getMergedModel)
            ? shipConfigManager.getMergedModel(shipId)
            : null;
        const loadout = (typeof shipLoadoutManager !== 'undefined')
            ? shipLoadoutManager.getLoadout(shipId)
            : { weapons: [], defenses: [], abilities: [], energy: [] };
        const inventory = (typeof shipLoadoutManager !== 'undefined')
            ? shipLoadoutManager.getInventory(shipId)
            : loadout;
        const hangarSlots = (typeof shipLoadoutManager !== 'undefined' && shipLoadoutManager.buildHangarSlots)
            ? shipLoadoutManager.buildHangarSlots(shipId, modelClass, merged)
            : { slots: [] };

        if (typeof window.componentTree !== 'undefined') {
            const layoutModules = (hangarSlots.layout && hangarSlots.layout.modules) || [];
            const usedModules = new Set();
            const slotsWithAreas = (hangarSlots.slots || []).map((slot) => {
                const moduleIndex = slot.id
                    ? layoutModules.findIndex((candidate, index) =>
                        !usedModules.has(index)
                        && candidate.kind === slot.kind
                        && candidate.id === slot.id
                        && (!slot.face || candidate.face === slot.face)
                    )
                    : -1;
                const module = moduleIndex === -1 ? null : layoutModules[moduleIndex];
                if (moduleIndex !== -1) usedModules.add(moduleIndex);
                const mountSegment = module && module.mountSegment;
                const emptySlotArea = slot.kind === 'weapon'
                    ? (slot.index % 2 === 0 ? 'wingLeft' : 'wingRight')
                    : (slot.kind === 'ability' ? 'back' : 'center');
                const area = mountSegment === 'wing'
                    ? (module.face === 'right' ? 'wingRight' : 'wingLeft')
                    : (mountSegment || emptySlotArea);
                return { ...slot, area };
            });
            // Keep every style strip where the user left it across the
            // rebuild; only strips that never scrolled get centred.
            const trackScroll = {};
            treeContainer.querySelectorAll('.hs-style-carousel-track').forEach((track) => {
                const key = track.closest('.hs-tree-branch, .hs-tree-item');
                if (key && key.id) trackScroll[key.id] = track.scrollLeft;
            });
            this._styleTrackScroll = trackScroll;
            // Weapons are set only in the centre bay (slot bar / ship markers),
            // not in the area tree.
            treeContainer.innerHTML = window.componentTree.render(
                { ...hangarSlots, slots: slotsWithAreas.filter((s) => s.kind !== 'weapon') },
                loadout,
                inventory,
                (kind, slot, moduleId) => {
                    const skins = shipLoadoutManager.getAvailableSkins(kind);
                    const activeSkin = shipLoadoutManager.getModuleSkin(
                        shipId,
                        kind,
                        moduleId,
                        slot.face
                    );
                    return skins.map((skin) => ({
                        ...skin,
                        active: skin.id === activeSkin,
                        // The worn skin stays usable even if not bought.
                        locked: skin.id !== activeSkin && !this.isStyleOwned('skin:' + kind, skin.id)
                    }));
                },
                (area) => {
                    if (typeof profileManager === 'undefined'
                        || typeof graphicsManager === 'undefined'
                        || !graphicsManager.shipAssetLoader) {
                        return [];
                    }
                    const isWing = area === 'wingLeft' || area === 'wingRight';
                    const symmetric = !isWing || profileManager.getWingStyleSymmetry(shipId);
                    const segmentId = isWing && symmetric ? 'wing' : area;
                    const loader = graphicsManager.shipAssetLoader;
                    const count = segmentId === 'wing'
                        ? loader.wingShapeVariants.length
                        : loader.bodyShapeVariantCount(segmentId);
                    const savedStyle = profileManager.getSegmentShapeVariant(shipId, segmentId);
                    const styleLabels = segmentId === 'wing'
                        ? loader.wingShapeVariants.map((v) => v.label)
                        : loader.bodyShapeVariantLabels(segmentId);
                    const defaultSegmentId = segmentId === 'wing'
                        ? 'wingLeft'
                        : segmentId;
                    const activeStyle = savedStyle == null
                        ? loader.hullShapeVariantIndex(
                            loader.resolveHullShapeSeed({ id: shipId }),
                            defaultSegmentId,
                            count
                        )
                        : savedStyle;
                    return {
                        isWing,
                        symmetric,
                        styles: Array.from({ length: count }, (_, index) => ({
                            segmentId,
                            index,
                            label: styleLabels[index] || `STYLE ${index + 1}`,
                            active: index === activeStyle,
                            locked: index !== activeStyle
                                && !this.isStyleOwned(profileManager.hullStyleGroup(segmentId), index)
                        }))
                    };
                }
            );
            this.appendConnectionBranches(treeContainer, shipId);
            if (this.appendAreaToggles) this.appendAreaToggles(treeContainer, shipId);
            this.renderStyleThumbs(treeContainer);
        }
    },
    /**
     * WING, NOSE and AFT CONNECTION as their own expandable tree
     * sections, carrying the same settings as the floating joint panels.
     */
    appendConnectionBranches(treeContainer, shipId) {
        const root = treeContainer.querySelector('.hs-tree-root');
        if (!root || typeof shipLoadoutManager === 'undefined' || !window.componentTree) return;
        const tree = window.componentTree;
        const lo = shipLoadoutManager.getLoadout(shipId);
        const styles = ['strut', 'plate', 'double', 'hinge'];
        const styleCarousel = (joint, active) => tree.renderStyleCarousel(styles.map((style) => ({
            active: style === active,
            locked: style !== active && !this.isStyleOwned('joint', style),
            label: style.toUpperCase(),
            attrs: `data-tree-joint-style="${joint}" data-style-id="${style}"`,
            thumb: `data-thumb="joint" data-thumb-style="${style}"`
        })));
        const toggle = (joint, key, label) =>
            `<label class="hs-connection-link-ends"><input type="checkbox" data-tree-joint-show="${joint}"${lo[key] ? '' : ' checked'}> <span>${label}</span></label>`;
        const branch = (id, icon, label, body) => {
            const nodeId = `hs-tree-conn-${id}`;
            return `<details class="hs-tree-branch hs-tree-connection" id="${nodeId}"${tree.expandedNodes.has(nodeId) ? ' open' : ''}>
                <summary class="hs-tree-branch-label">
                    <span class="hs-tree-toggle">▶</span>
                    <span class="hs-tree-icon">${icon}</span>
                    <span class="hs-tree-text">${label}</span>
                </summary>
                <div class="hs-tree-items hs-tree-connection-body" data-joint-panel="${id}">${body}</div>
            </details>`;
        };
        const wingStart = Number(lo.wingConnectionWidth) || 0.1;
        // Nose↔core and core↔aft joints each get their own section.
        const spineBranch = (joint, id, icon, label, showLabel) => {
            const j = resolveSpineJoint(lo, joint);
            return branch(id, icon, label, `
                <div data-spine-joint="${joint}">
                <span class="hs-tree-skin-label">STYLE</span>
                ${styleCarousel(joint, j.style)}
                ${toggle(joint, joint === 'spineFront' ? 'hideSpineFront' : 'hideSpineBack', showLabel)}
                ${this.connectionStrengthRow('START', 'data-spine-width', 0.05, 0.6, j.width)}
                ${this.connectionStrengthRow('END', 'data-spine-width-end', 0.05, 0.6, j.widthEnd || j.width)}
                <label class="hs-connection-link-ends"><input type="checkbox" data-link-ends${j.widthEnd ? '' : ' checked'}> <span>SAME BOTH ENDS</span></label>
                <label class="hs-tree-joint-range"><span>OFFSET</span><input type="range" data-tree-joint-offset="${joint}" min="-1" max="1" step="0.01" value="${j.x}"></label>
                </div>`);
        };
        const html =
            branch('wing', '╪', 'WING CONNECTION', `
                <span class="hs-tree-skin-label">STYLE</span>
                ${styleCarousel('wing', lo.wingConnectionStyle || 'strut')}
                ${toggle('wing', 'hideWingConnection', 'SHOW')}
                ${this.connectionStrengthRow('HULL', 'data-wing-connection-width', 0.02, 0.5, wingStart)}
                ${this.connectionStrengthRow('WING', 'data-wing-connection-width-end', 0.02, 0.5, Number(lo.wingConnectionWidthEnd) || wingStart)}
                <label class="hs-connection-link-ends"><input type="checkbox" data-link-ends${Number(lo.wingConnectionWidthEnd) ? '' : ' checked'}> <span>SAME BOTH ENDS</span></label>
                <label class="hs-tree-joint-range"><span>OFFSET</span><input type="range" data-tree-joint-offset="wing" min="-1" max="1" step="0.01" value="${Number(lo.wingConnectionY) || 0}"></label>`) +
            spineBranch('spineFront', 'spine-front', '╫', 'NOSE CONNECTION', 'SHOW NOSE ↔ CORE') +
            spineBranch('spineBack', 'spine-back', '╫', 'AFT CONNECTION', 'SHOW CORE ↔ AFT');
        // Each connection lives inside the part it joins: the wing bridge
        // under WINGS (left wing when asymmetric), nose↔core under NOSE and
        // core↔aft under AFT.
        const wingHost = root.querySelector('#hs-tree-area-wings > .hs-tree-items, #hs-tree-area-wingLeft > .hs-tree-items');
        const noseHost = root.querySelector('#hs-tree-area-front > .hs-tree-items');
        const aftHost = root.querySelector('#hs-tree-area-back > .hs-tree-items');
        const tmp = document.createElement('div');
        tmp.innerHTML = html;
        const wingConn = tmp.querySelector('#hs-tree-conn-wing');
        (wingHost || root).appendChild(wingConn);
        (noseHost || root).appendChild(tmp.querySelector('#hs-tree-conn-spine-front'));
        (aftHost || root).appendChild(tmp.querySelector('#hs-tree-conn-spine-back'));

        const refresh = () => {
            this.renderAllComponentTrees();
            this.bindComponentTreeEvents();
            this.drawHangarBay();
        };
        root.querySelectorAll('[data-tree-joint-style]').forEach((button) => {
            button.addEventListener('click', () => {
                const style = button.getAttribute('data-style-id');
                const joint = button.getAttribute('data-tree-joint-style');
                if (joint === 'wing') {
                    shipLoadoutManager.setWingConnectionStyle(shipId, style);
                } else {
                    shipLoadoutManager.setSpineConnectionStyle(shipId, style, joint);
                }
                refresh();
            });
        });
        root.querySelectorAll('[data-tree-joint-show]').forEach((input) => {
            input.addEventListener('change', () => {
                shipLoadoutManager.setConnectionHidden(shipId, input.getAttribute('data-tree-joint-show'), !input.checked);
                this.drawHangarBay();
            });
        });
        root.querySelectorAll('[data-tree-joint-offset]').forEach((input) => {
            input.addEventListener('input', () => {
                const joint = input.getAttribute('data-tree-joint-offset');
                if (joint === 'wing') {
                    shipLoadoutManager.setWingConnection(shipId, Number(input.value));
                } else {
                    shipLoadoutManager.setSpineConnectionX(shipId, Number(input.value), joint);
                }
                this.drawHangarBay();
            });
        });
        const wingPanel = root.querySelector('[data-joint-panel="wing"]');
        if (wingPanel) {
            this.bindConnectionStrength(wingPanel, {
                start: '[data-wing-connection-width]',
                end: '[data-wing-connection-width-end]',
                setStart: (v) => shipLoadoutManager.setWingConnectionWidth(shipId, v),
                setEnd: (v) => shipLoadoutManager.setWingConnectionWidthEnd(shipId, v)
            });
        }
        root.querySelectorAll('[data-spine-joint]').forEach((panel) => {
            const joint = panel.getAttribute('data-spine-joint');
            this.bindConnectionStrength(panel, {
                start: '[data-spine-width]',
                end: '[data-spine-width-end]',
                setStart: (v) => shipLoadoutManager.setSpineConnectionWidth(shipId, v, joint),
                setEnd: (v) => shipLoadoutManager.setSpineConnectionWidthEnd(shipId, v, joint)
            });
        });
    },
    /**
     * Paint every style thumbnail canvas under root: hull areas via the
     * procedural part renderers, module skins via the module renderer — the
     * same art the ship shows, in the ship's faction colours. The active
     * thumbnail is scrolled into view so the strip opens on the choice.
     */
    /** Style unlock check that stays permissive if the unlock system is missing. */
    isStyleOwned(groupId, styleId) {
        if (typeof profileManager === 'undefined' || !profileManager.isStyleUnlocked) return true;
        return profileManager.isStyleUnlocked(groupId, styleId);
    },
    renderStyleThumbs(root) {
        const loader = typeof graphicsManager !== 'undefined' && graphicsManager.shipAssetLoader;
        if (!root || !loader) return;
        root.querySelectorAll('canvas[data-thumb]').forEach((canvas) => {
            const ctx = canvas.getContext('2d');
            if (!ctx) return;
            const shipTree = canvas.closest('[data-ship-tree]');
            const shipId = (shipTree && shipTree.getAttribute('data-ship-tree')) || this.hangarShipId || 'player_scrap';
            const model = typeof shipConfigManager !== 'undefined' && shipConfigManager.getMergedModel
                ? shipConfigManager.getMergedModel(shipId)
                : null;
            const w = canvas.width;
            const h = canvas.height;
            ctx.clearRect(0, 0, w, h);
            ctx.fillStyle = '#09090d';
            ctx.fillRect(0, 0, w, h);
            ctx.imageSmoothingEnabled = false;
            // Thumbnails use their own coarse voxel so shapes stay readable.
            const prevCell = loader._shipVoxelCell;
            const prevAnchor = loader._shipVoxelAnchor;
            loader._shipVoxelCell = 3;
            loader._shipVoxelAnchor = null;
            try {
                if (canvas.getAttribute('data-thumb') === 'joint') {
                    // Two stub plates with the joint style between them.
                    const faction = loader.resolvePlayerFactionStyle(model);
                    const layout = {
                        loadout: {
                            spineConnectionStyle: canvas.getAttribute('data-thumb-style'),
                            spineConnectionWidth: 0.22
                        },
                        segments: [
                            { id: 'front', x: 2, y: 0, width: 12, height: 2 },
                            { id: 'center', x: 2, y: 10, width: 12, height: 2 }
                        ]
                    };
                    loader.renderSpineJoints(ctx, layout, layout.segments, 0, 0, 3, null, 0, faction);
                    // Plates on top, like the real parts covering the seats.
                    const palette = loader.buildHullPartPalette(null, 0, faction);
                    ctx.fillStyle = palette[1];
                    ctx.fillRect(6, 0, 36, 6);
                    ctx.fillRect(6, 30, 36, 6);
                } else if (canvas.getAttribute('data-thumb') === 'area') {
                    const area = canvas.getAttribute('data-thumb-area');
                    const index = Number(canvas.getAttribute('data-thumb-index'));
                    const faction = loader.resolvePlayerFactionStyle(model);
                    const seed = loader.resolveHullShapeSeed({ id: shipId });
                    // Draw the part at the ship's own proportions and voxel
                    // count: a fixed 48×36 box with 3 px voxels stretched
                    // every shape and resampled it to a different grid, so
                    // the thumbnail did not match the part on the ship.
                    const geo = this.styleThumbGeometry(shipId, area, loader);
                    const aspect = geo ? geo.aspect : (area.indexOf('wing') === 0 ? 1.4 : 1.1);
                    const boxW = w - 6;
                    const boxH = h - 6;
                    const fw = Math.min(boxW, boxH * aspect);
                    const fh = Math.min(boxH, boxW / aspect);
                    loader._shipVoxelCell = geo ? Math.max(1, Math.min(fw / geo.cols, fh / geo.rows)) : 3;
                    const fx = 3 + (boxW - fw) / 2;
                    const fy = 3 + (boxH - fh) / 2;
                    if (area === 'wingLeft' || area === 'wingRight') {
                        loader.renderProceduralWing(ctx, { id: area }, fx, fy, fw, fh,
                            null, 0, faction, seed, index, null, 0, 1, 1);
                    } else {
                        loader.renderProceduralBodyBand(ctx, { id: area }, fx, fy, fw, fh,
                            null, 0, faction, seed, index, 1, 1);
                    }
                } else {
                    const kind = canvas.getAttribute('data-thumb-kind');
                    const id = canvas.getAttribute('data-thumb-module');
                    const size = Math.min(w, h) - 6;
                    loader.renderShipModule(ctx, {
                        id,
                        kind,
                        role: typeof shipLoadoutManager !== 'undefined' && shipLoadoutManager.getModuleVisualRole
                            ? shipLoadoutManager.getModuleVisualRole(kind, id)
                            : kind,
                        face: 'up',
                        skin: canvas.getAttribute('data-thumb-skin')
                    }, (w - size) / 2, (h - size) / 2, size, size, null, 0, null,
                    loader.resolveModuleFactionStyle ? loader.resolveModuleFactionStyle(model) : null);
                }
            } catch (e) {
                /* a thumbnail failing must not break the tree */
            } finally {
                loader._shipVoxelCell = prevCell;
                loader._shipVoxelAnchor = prevAnchor;
            }
        });
        const saved = this._styleTrackScroll || {};
        this._styleTrackScroll = null;
        root.querySelectorAll('.hs-style-carousel-track').forEach((track) => {
            // Instant, not smooth: a rebuild must not visibly scroll other
            // strips (picking an AFT style used to slide the WINGS strip).
            track.style.scrollBehavior = 'auto';
            const owner = track.closest('.hs-tree-branch, .hs-tree-item');
            const active = track.querySelector('.hs-style-thumb.is-active');
            if (owner && owner.id && saved[owner.id] != null) {
                track.scrollLeft = saved[owner.id];
                // Still bring the active thumb into view if it is off-strip.
                if (active && (active.offsetLeft < track.scrollLeft
                    || active.offsetLeft + active.offsetWidth > track.scrollLeft + track.clientWidth)) {
                    track.scrollLeft = active.offsetLeft - (track.clientWidth - active.offsetWidth) / 2;
                }
            } else if (active) {
                track.scrollLeft = active.offsetLeft - (track.clientWidth - active.offsetWidth) / 2;
            }
            track.style.scrollBehavior = '';
            // The strip hides its scrollbar, so map the mouse wheel to
            // horizontal scrolling and keep the page from scrolling instead.
            if (!track._wheelBound) {
                track._wheelBound = true;
                track.addEventListener('wheel', (e) => {
                    if (track.scrollWidth <= track.clientWidth) return;
                    const delta = Math.abs(e.deltaX) > Math.abs(e.deltaY) ? e.deltaX : e.deltaY;
                    if (!delta) return;
                    e.preventDefault();
                    track.scrollLeft += delta;
                }, { passive: false });
            }
        });
    },
    /**
     * A ship part's frame aspect and voxel grid size as the bay draws it,
     * so style thumbnails reproduce the same shape at a smaller size.
     */
    styleThumbGeometry(shipId, area, loader) {
        const model = this._hangarLastModel;
        if (!model || !model.layout || (this.hangarShipId || 'player_scrap') !== shipId) return null;
        const seg = (model.layout.segments || []).find((item) => item.id === area);
        if (!seg || !seg.width || !seg.height) return null;
        const scale = this._hangarLastScale || 1;
        const cell = loader.shipVoxelCell(model, scale);
        const res = loader.hullPartResolution(seg.width * scale, seg.height * scale,
            Number(model.layout.loadout && model.layout.loadout.voxelScale) || 0.5, scale);
        return {
            aspect: seg.width / seg.height,
            cols: Math.max(1, Math.round(seg.width * scale / cell)) || res.resW,
            rows: Math.max(1, Math.round(seg.height * scale / cell)) || res.resH
        };
    },
    renderAllComponentTrees() {
        if (!this.overlay) return;
        this.overlay.querySelectorAll('.hs-component-tree[data-ship-id]').forEach((tree) => {
            this.renderComponentTree(tree.getAttribute('data-ship-id'), tree);
        });
    },
});


/* --- js/ui/home-station/render-component-tree-part2.js?v=sdrop-2 --- */
"use strict";

// HomeStationUI members, continued from render-component-tree.js (kept under ~500 lines per file).
extendClass(HomeStationUI, {
    bindComponentTreeEvents() {
        if (!this.overlay) return;
        this.overlay.querySelectorAll('.hs-tree-branch, .hs-tree-item').forEach((node) => {
            node.addEventListener('toggle', () => {
                if (typeof window.componentTree === 'undefined' || !node.id) return;
                const shipTree = node.closest('[data-ship-tree]');
                if (shipTree) {
                    window.componentTree.setShip(shipTree.getAttribute('data-ship-tree'));
                }
                window.componentTree.setNodeExpanded(node.id, node.open);
                // Accordion: opening a section closes its open siblings.
                if (!this._areaPager && node.open && node.classList.contains('hs-tree-branch') && node.parentElement) {
                    Array.from(node.parentElement.children).forEach((sib) => {
                        if (sib !== node && sib.classList.contains('hs-tree-branch') && sib.open) sib.open = false;
                    });
                }
            });
        });

        this.overlay.querySelectorAll('.hs-tree-slot-select').forEach((select) => {
            select.addEventListener('change', (event) => {
                const kind = select.getAttribute('data-slot-kind');
                const slotIndex = Number(select.getAttribute('data-slot-index'));
                const selectedId = event.target.value;
                const shipTree = select.closest('[data-ship-tree]');
                const shipId = shipTree ? shipTree.getAttribute('data-ship-tree') : this.hangarShipId;
                const loadoutKeys = {
                    weapon: 'weapons',
                    defense: 'defenses',
                    ability: 'abilities',
                    energy: 'energy'
                };
                const loadoutKey = loadoutKeys[kind];

                if (!loadoutKey || typeof shipLoadoutManager === 'undefined') return;
                const loadout = shipLoadoutManager.getLoadout(shipId);
                const modules = loadout[loadoutKey];
                const currentId = modules[slotIndex];

                if (!selectedId) {
                    if (kind === 'weapon' && modules.length <= 1) {
                        this.setStatus('AT LEAST ONE WEAPON IS REQUIRED');
                        this.renderAllComponentTrees();
                        return;
                    }
                    modules.splice(slotIndex, 1);
                } else {
                    const selectedIndex = modules.indexOf(selectedId);
                    if (selectedIndex !== -1 && selectedIndex !== slotIndex) {
                        modules[selectedIndex] = currentId;
                    }
                    modules[slotIndex] = selectedId;
                }
                shipLoadoutManager.setLoadout(shipId, loadout);
                this.renderAllComponentTrees();
                this.drawHangarBay();
            });
        });

        this.overlay.querySelectorAll('[data-tree-skin-set]').forEach((button) => {
            button.addEventListener('click', () => {
                if (typeof shipLoadoutManager === 'undefined') return;
                const kind = button.getAttribute('data-tree-skin-set');
                const slotIndex = Number(button.getAttribute('data-slot-index'));
                const face = button.getAttribute('data-mod-face') || '';
                const skinId = button.getAttribute('data-skin-id') || 'default';
                const shipTree = button.closest('[data-ship-tree]');
                const shipId = shipTree ? shipTree.getAttribute('data-ship-tree') : this.hangarShipId;
                const loadoutKey = shipLoadoutManager.kindToLoadoutKey(kind);
                // The tree renders the equipped id on the option; the slot
                // index can drift from the loadout list (toggle-only parts
                // like abilities), which made the pick a silent no-op.
                const list = loadoutKey ? (shipLoadoutManager.getLoadout(shipId)[loadoutKey] || []) : [];
                const moduleId = button.getAttribute('data-mod-id') || list[slotIndex] || null;
                if (!moduleId) return;

                shipLoadoutManager.setModuleSkin(
                    shipId,
                    kind,
                    moduleId,
                    face,
                    skinId
                );
                this.renderAllComponentTrees();
                this.bindComponentTreeEvents();
                this.drawHangarBay();
            });
        });

        this.overlay.querySelectorAll('[data-tree-area-style]').forEach((button) => {
            button.addEventListener('click', () => {
                if (typeof profileManager === 'undefined') return;
                const segmentId = button.getAttribute('data-segment-id');
                const styleIndex = Number(button.getAttribute('data-style-index'));
                const shipTree = button.closest('[data-ship-tree]');
                const shipId = shipTree ? shipTree.getAttribute('data-ship-tree') : this.hangarShipId;
                if (!segmentId || !Number.isInteger(styleIndex)) return;

                profileManager.setSegmentShapeVariant(shipId, segmentId, styleIndex);
                this.renderAllComponentTrees();
                this.bindComponentTreeEvents();
                this.drawHangarBay();
            });
        });

        this.overlay.querySelectorAll('[data-tree-wing-symmetry]').forEach((button) => {
            button.addEventListener('click', () => {
                if (typeof profileManager === 'undefined') return;
                const enableSymmetry = button.getAttribute('data-tree-wing-symmetry') !== 'on';
                const shipTree = button.closest('[data-ship-tree]');
                const shipId = shipTree ? shipTree.getAttribute('data-ship-tree') : this.hangarShipId;
                profileManager.setWingStyleSymmetry(shipId, enableSymmetry);
                this.renderAllComponentTrees();
                this.bindComponentTreeEvents();
                this.drawHangarBay();
            });
        });
    },
});


/* --- js/ui/home-station/area-pager.js --- */
"use strict";

// Hangar sidebar: show one ship area at a time (always open) with
// previous / next buttons above it, instead of an accordion of closed sections.
(function () {
    HomeStationUI.prototype._areaPager = true; // replaces the accordion behaviour
    const original = HomeStationUI.prototype.renderComponentTree;

    function branches(container) {
        return Array.from(container.querySelectorAll(':scope .hs-tree-root > .hs-tree-branch'));
    }

    function labelOf(branch) {
        const s = branch.querySelector(':scope > summary');
        return s ? s.textContent.replace(/\s+/g, ' ').trim().toUpperCase() : 'AREA';
    }

    function apply(ui, container) {
        const list = branches(container);
        if (!list.length) return;
        const idx = Math.max(0, Math.min(list.length - 1, ui._areaIdx || 0));
        ui._areaIdx = idx;
        list.forEach((b, i) => {
            b.classList.toggle('is-paged-out', i !== idx);
            b.classList.toggle('is-paged-in', i === idx);
            if (i === idx && !b.open) b.open = true;
        });
        // Everything stays expanded: no collapsing of areas or their sub-sections.
        container.querySelectorAll('.hs-tree-branch.is-paged-in, .hs-tree-branch.is-paged-in details').forEach((d) => {
            if (!d.open) d.open = true;
            if (!d._noCollapse) {
                d._noCollapse = true;
                const sum = d.querySelector(':scope > summary');
                if (sum) sum.addEventListener('click', (e) => { if (!e.target.closest('input, label, button, select')) e.preventDefault(); });
            }
        });
        const tc = container.closest('.hs-component-tree-container');
        const aside = container.closest('.hs-hangar-list');
        const shipsBox = aside && aside.querySelector('#hsHangarShipsContainer');
        const isCurrent = container.getAttribute('data-ship-id') === ui.hangarShipId;
        // The area bar is pinned above the scrolling ship list, so the
        // scrollbar starts below it and the bar never scrolls away.
        let head = tc ? tc.querySelector('.hs-component-tree-header') : null;
        const pinned = aside ? aside.querySelector(':scope > .hs-component-tree-header.is-pinned') : null;
        if (isCurrent && shipsBox) {
            if (!head) head = pinned;
            if (head && head !== pinned) {
                if (pinned) pinned.remove();
                head.classList.add('is-pinned');
                aside.insertBefore(head, shipsBox);
            }
        } else if (!head) {
            return;
        }
        if (!head) return;
        // Icon buttons: ‹ [nose] [core] [wings] [aft] ›  (selected area lit)
        const kindOf = (b) => {
            const t = labelOf(b);
            return /NOSE|FRONT/.test(t) ? 'front' : /CORE|CENTER/.test(t) ? 'center' : /WING/.test(t) ? 'wing' : /AFT|BACK|REAR/.test(t) ? 'back' : 'center';
        };
        // Zoomed, bright close-ups of each area (16x16 grid): hull in light, details in accent.
        const H = 'class="ai-hull"', A = 'class="ai-acc"';
        const art = {
            front: '<path ' + H + ' d="M7 1h2v2h1v2h1v2h1v3H4V7h1V5h1V3h1z"/><path ' + A + ' d="M7 4h2v3H7z"/><path ' + H + ' d="M3 12h10v2H3z"/>',
            center: '<path ' + H + ' d="M3 2h10v12H3z"/><path d="M5 4h6v8H5z" fill="#05060a"/><path ' + A + ' d="M6 6h4v4H6z"/><path ' + H + ' d="M7 7h2v2H7z"/>',
            wing: '<path ' + H + ' d="M1 4h4v2h2v2h2v2h2v2h4v2H1z"/><path ' + A + ' d="M2 12h4v1H2zM4 8h2v1H4z"/><path ' + H + ' d="M14 4h1v6h-1z"/>',
            back: '<path ' + H + ' d="M3 2h10v6H3z"/><path d="M4 3h8v4H4z" fill="#05060a"/><path ' + H + ' d="M3 9h4v3H3zM9 9h4v3H9z"/><path ' + A + ' d="M4 13h2v2H4zM10 13h2v2h-2z"/>'
        };
        const icon = (kind) => '<svg viewBox="0 0 16 16" shape-rendering="crispEdges" aria-hidden="true">' + (art[kind] || art.center) + '</svg>';
        head.innerHTML = '<button type="button" class="hs-area-nav is-step" data-nav-item data-area-step="-1" title="Previous area" aria-label="Previous area">‹</button>' +
            '<span class="hs-area-icons">' + list.map((b, i) =>
                '<button type="button" class="hs-area-nav is-icon' + (i === idx ? ' is-current' : '') + '" data-nav-item data-area-go="' + i + '" title="' +
                labelOf(b).replace(/[0-9]+$/, '').trim() + '" aria-label="' + labelOf(b) + '">' + icon(kindOf(b)) + '</button>').join('') + '</span>' +
            '<button type="button" class="hs-area-nav is-step" data-nav-item data-area-step="1" title="Next area" aria-label="Next area">›</button>';
        const go = (n) => { ui._areaIdx = n; apply(ui, container); };
        head.querySelectorAll('[data-area-step]').forEach((btn) => {
            btn.addEventListener('click', (e) => {
                e.preventDefault(); e.stopPropagation();
                go((idx + Number(btn.getAttribute('data-area-step')) + list.length) % list.length);
            });
        });
        head.querySelectorAll('[data-area-go]').forEach((btn) => {
            btn.addEventListener('click', (e) => {
                e.preventDefault(); e.stopPropagation();
                go(Number(btn.getAttribute('data-area-go')));
            });
        });
    }

    HomeStationUI.prototype.renderComponentTree = function (shipId, treeContainer) {
        const r = original.apply(this, arguments);
        const c = treeContainer || (this.overlay && this.overlay.querySelector('.hs-component-tree[data-ship-id]'));
        if (c) apply(this, c);
        return r;
    };
})();


/* --- js/ui/home-station/area-upgrades.js?v=nocenter-1 --- */
"use strict";

// HomeStationUI: hull area upgrades (slot size S → M → L), shown in the
// hangar head bar and in the upgrade tab's SHIPS list.
extendClass(HomeStationUI, {
    /** One row per area: level, slots it holds, next size, cost, button. */
    renderAreaUpgradeRows(shipId, profile, compact) {
        if (typeof shipLoadoutManager === 'undefined' || !shipLoadoutManager.getShipAreas
            || typeof profileManager === 'undefined' || !profileManager.getShipAreaLevels) return '';
        const slm = shipLoadoutManager;
        const wallet = profile.resources || {};
        const levels = profileManager.getShipAreaLevels(shipId, profile);
        const max = profileManager.maxShipAreaLevel();
        const kindsIn = { front: 'NOSE WEAPON', center: 'DEFENSE · ENERGY', back: 'ABILITY', wing: 'WING WEAPONS (PAIRS)' };
        return slm.getShipAreas().map((area) => {
            const lv = levels[area.id] || 0;
            const size = 'LV' + lv;
            const maxed = lv >= max;
            const check = profileManager.canPurchaseShipAreaUpgrade(shipId, area.id, profile);
            const cost = check.cost || (!maxed ? economyConfig.getShipAreaUpgradeCost(area.id, lv + 1) : null);
            const bonus = !maxed ? slm.getAreaSlotBonusAt(area.id, lv + 1) : [];
            const bonusText = bonus.length ? ' +' + bonus.length + ' ' + this.slotKindName(bonus[0]) + (bonus.length > 1 ? ' SLOTS' : ' SLOT') : '';
            // Missing resources stays clickable: the click opens the buy modal.
            const lockAttr = check.ok ? '' : (check.reason === 'RESOURCES' ? 'data-short="1"' : 'disabled');
            const action = maxed
                ? '<span class="hs-muted hs-line-action">MAX</span>'
                : `<button type="button" class="action-button hs-line-action" data-area-up="${shipId}|${area.id}" ${lockAttr}` +
                    ` title="${area.label}: ${size} → ${('LV' + (lv + 1))}${bonusText}">` +
                    `${size} → ${('LV' + (lv + 1))}</button>`;
            return `<div class="hs-area-row${compact ? ' is-compact' : ''}" data-area="${area.id}">` +
                (compact ? '' : `<canvas class="hs-area-thumb" width="72" height="48" data-area-thumb="${shipId}|${area.id}"` +
                    ` aria-label="${area.label} on ${this.shipName(shipId)}"></canvas>`) +
                `<span class="hs-area-name"><span class="hs-slot-size is-${size}">${size}</span>` +
                `<strong>${area.label}</strong>` +
                (compact ? '' : `<small>${kindsIn[area.id]}${bonusText ? ' · NEXT' + bonusText : ''}</small>`) +
                `</span>` +
                (cost && !maxed ? this.renderCostGrid(cost, wallet) : '<span></span>') +
                action +
                `</div>`;
        }).join('');
    },

    /** Only the resources the cost actually needs, icon + amount, short ones marked. */
    renderCompactCost(cost, wallet) {
        const ids = (typeof economyConfig !== 'undefined') ? economyConfig.resourceIds : ['scrap', 'ore', 'crystal', 'voltex'];
        return ids.filter((id) => (cost[id] || 0) > 0).map((id) => {
            const short = ((wallet && wallet[id]) || 0) < cost[id];
            return `<span class="hs-area-cost${short ? ' is-short' : ''}" title="${id.toUpperCase()}">` +
                `${this.iconHtml(this.resourceIconKey(id), 16, 'hs-pixel hs-pixel-16')}${cost[id]}</span>`;
        }).join('');
    },

    /** Hangar: four compact area tiles — icon + ON/OFF switch. */
    renderHangarAreaUpgrades(shipId, profile) {
        if (typeof shipLoadoutManager === 'undefined' || !shipLoadoutManager.getShipAreas
            || typeof profileManager === 'undefined' || !profileManager.getShipAreaLevels) return '';
        const slm = shipLoadoutManager;
        const toggleable = slm.getToggleableAreas ? slm.getToggleableAreas() : [];
        // ON/OFF switch for every area except the core.
        const switchHtml = (areaId, on) => toggleable.indexOf(areaId) === -1 ? '' :
            `<label class="hs-area-switch" title="${on ? 'Switch off' : 'Switch on'}">` +
            `<input type="checkbox" data-area-toggle="${shipId}|${areaId}"${on ? ' checked' : ''} aria-label="${this.areaLabel(areaId)} on/off">` +
            `<span class="hs-area-switch-track"><span class="hs-area-switch-label">${on ? 'ON' : 'OFF'}</span></span></label>`;
        // The core has no ON/OFF switch, so it gets no tile.
        const tiles = slm.getShipAreas().map((area) => {
            // Icon (ship with this area lit) instead of the text label; label in the tooltip.
            const name = `<strong class="hs-area-icon" data-ui-tip="${area.label}">${this.hangarAreaIconSvg(area.id)}</strong>`;
            if (toggleable.indexOf(area.id) === -1) return ''; // the core cannot be switched, so no tile
            if (slm.isAreaEnabled && !slm.isAreaEnabled(shipId, area.id)) {
                return `<div class="hs-area-tile is-off" data-area="${area.id}">` +
                    `<span class="hs-area-name">${name}${switchHtml(area.id, false)}</span>` +
                    `</div>`;
            }
            return `<div class="hs-area-tile" data-area="${area.id}">` +
                `<span class="hs-area-name">${name}${switchHtml(area.id, true)}</span>` +
                `</div>`;
        }).join('');
        return `<div class="hs-hangar-areas" aria-label="Hull areas">${tiles}</div>`;
    },

    /** Area pictogram (same art as the sidebar's area bar); hull in light, details in the accent. */
    hangarAreaIconSvg(areaId) {
        const H = 'class="ai-hull"';
        const A = 'class="ai-acc"';
        const art = {
            front: '<path ' + H + ' d="M7 1h2v2h1v2h1v2h1v3H4V7h1V5h1V3h1z"/><path ' + A + ' d="M7 4h2v3H7z"/><path ' + H + ' d="M3 12h10v2H3z"/>',
            center: '<path ' + H + ' d="M3 2h10v12H3z"/><path d="M5 4h6v8H5z" fill="#05060a"/><path ' + A + ' d="M6 6h4v4H6z"/><path ' + H + ' d="M7 7h2v2H7z"/>',
            wing: '<path ' + H + ' d="M1 4h4v2h2v2h2v2h2v2h4v2H1z"/><path ' + A + ' d="M2 12h4v1H2zM4 8h2v1H4z"/><path ' + H + ' d="M14 4h1v6h-1z"/>',
            back: '<path ' + H + ' d="M3 2h10v6H3z"/><path d="M4 3h8v4H4z" fill="#05060a"/><path ' + H + ' d="M3 9h4v3H3zM9 9h4v3H9z"/><path ' + A + ' d="M4 13h2v2H4zM10 13h2v2h-2z"/>'
        };
        return '<svg viewBox="0 0 16 16" width="44" height="44" shape-rendering="crispEdges" aria-hidden="true">' + (art[areaId] || art.center) + '</svg>';
    },

    /** Upgrade tab → SHIPS: per ship, its four hull areas. */
    renderShipFrameUpgrades(profile) {
        const owned = profile.ownedShipIds || [];
        if (!owned.length) {
            return this.emptyHtml('hsShip', 'NO SHIPS OWNED');
        }
        const max = (typeof economyConfig !== 'undefined') ? (economyConfig.maxShipFrameLevel || 8) : 8;
        return owned.map((id) => {
            const level = profileManager.getShipFrameLevel(id, profile);
            const caps = (typeof shipLoadoutManager !== 'undefined')
                ? shipLoadoutManager.getSlotCaps(id, this.shipModelClass(id, typeof shipConfigManager !== 'undefined' ? shipConfigManager.getConfig(id) : null) || 'starfighter')
                : { weapons: 1, defenses: 1, abilities: 1, energy: 1 };
            return `<div class="hs-area-ship">` +
                `<div class="hs-line hs-shop-line">` +
                `<span class="hs-line-name">` +
                `<canvas class="hs-area-thumb is-ship" width="72" height="48" data-area-thumb="${id}|"></canvas>` +
                `<span class="hs-line-text">` +
                `<strong>${this.shipName(id)}</strong>` +
                `<span class="hs-line-meta">AREAS ${level}/${max} · SLOTS W${caps.weapons}/D${caps.defenses}/A${caps.abilities}/E${caps.energy || 1}</span>` +
                this.renderShipClassAffinity(id) +
                `</span></span></div>` +
                this.renderAreaUpgradeRows(id, profile, false) +
                `</div>`;
        }).join('');
    },

    /** "+20% LASER · BURST" — the weapon families this hull type favours. */
    renderShipClassAffinity(shipId) {
        if (typeof weaponConfigManager === 'undefined' || !weaponConfigManager.getShipClassWeaponAffinity) return '';
        const cls = this.shipModelClass(shipId, typeof shipConfigManager !== 'undefined' ? shipConfigManager.getConfig(shipId) : null);
        const ids = weaponConfigManager.getShipClassWeaponAffinity(cls);
        if (!ids.length) return '';
        const names = ids.map((w) => (weaponConfigManager.getWeapon(w).name || w).toUpperCase());
        return `<span class="hs-line-meta hs-class-affinity">${this.shipClassLabel(cls)} · +20% DMG: ${names.join(' · ')}</span>`;
    },

    /**
     * Small ship render per area row with that area outlined, so the row
     * shows where on the hull the upgrade lands. Empty area = whole ship.
     */
    drawAreaThumbs() {
        if (!this.overlay || typeof shipLoadoutManager === 'undefined') return;
        const loader = (typeof graphicsManager !== 'undefined') ? graphicsManager.shipAssetLoader : null;
        // Until ship assets are loaded the renderers only produce a stand-in shape;
        // keep the placeholder icon instead (scheduleShipThumbs retries).
        if (!loader || !loader.loaded) return;
        const accent = this.getHangarPreviewAccent ? this.getHangarPreviewAccent() : '#ffffff';
        const models = {};
        this.overlay.querySelectorAll('canvas[data-area-thumb]').forEach((c) => {
            const [shipId, areaId] = (c.getAttribute('data-area-thumb') || '').split('|');
            let model = models[shipId];
            if (!model) {
                model = Object.assign({}, this.getHangarShipModel(shipId));
                if (shipLoadoutManager.applyLayoutToModel) shipLoadoutManager.applyLayoutToModel(model, shipId);
                models[shipId] = model;
            }
            const ctx = c.getContext('2d');
            ctx.clearRect(0, 0, c.width, c.height);
            ctx.imageSmoothingEnabled = false;
            const mw = Math.max(8, model.width || 20);
            const mh = Math.max(8, model.height || 16);
            const scale = Math.max(1, Math.floor(Math.min((c.width - 4) / mw, (c.height - 4) / mh)));
            const ox = Math.round((c.width - mw * scale) / 2);
            const oy = Math.round((c.height - mh * scale) / 2);
            try {
                loader.renderShip(ctx, model, ox, oy, scale, null, 0, { allowColorMountSprites: true });
            } catch (e) { return; }
            // Hide the placeholder icon once the canvas actually has ship pixels.
            if (c.parentNode && c.parentNode.classList) {
                let drawn = false;
                try {
                    const px = ctx.getImageData(0, 0, c.width, c.height).data;
                    for (let i = 3; i < px.length; i += 4) { if (px[i]) { drawn = true; break; } }
                } catch (e) { drawn = true; }
                c.parentNode.classList.toggle('is-drawn', drawn);
            }
            if (!areaId || !model.layout) return;
            const ids = areaId === 'wing' ? ['wingLeft', 'wingRight'] : [areaId];
            ctx.strokeStyle = accent;
            ctx.lineWidth = 1;
            (model.layout.segments || []).filter((seg) => ids.indexOf(seg.id) !== -1).forEach((seg) => {
                ctx.strokeRect(Math.round(ox + seg.x * scale) + 0.5, Math.round(oy + seg.y * scale) + 0.5,
                    Math.max(1, Math.round(seg.width * scale) - 1), Math.max(1, Math.round(seg.height * scale) - 1));
            });
        });
    },

    bindAreaUpgradeButtons() {
        if (!this.overlay) return;
        this.drawAreaThumbs();
        this.overlay.querySelectorAll('[data-area-toggle]').forEach((input) => {
            input.addEventListener('change', () => {
                const [id, area] = (input.getAttribute('data-area-toggle') || '').split('|');
                const res = shipLoadoutManager.setAreaEnabled(id, area, input.checked);
                if (!res.ok) return;
                this.statusMsg = this.areaLabel(area) + (input.checked ? ' ON' : ' OFF');
                this._hangarRecenter = true;
                this.createUI();
            });
        });
        this.overlay.querySelectorAll('[data-area-up]').forEach((btn) => {
            btn.addEventListener('click', () => {
                const [id, area] = (btn.getAttribute('data-area-up') || '').split('|');
                this.openAreaUpgradeModal(id, area);
            });
        });
    },

    /** Buy an area level (after the confirm modal). */
    confirmAreaUpgrade(id, area) {
        const label = this.shipName(id) + ' · ' + this.areaLabel(area);
        const btn = this.overlay && this.overlay.querySelector(`[data-area-up="${id}|${area}"]`);
        const res = profileManager.purchaseShipAreaUpgrade(id, area);
        if (res.ok) {
            const msg = label + ' → ' + ('LV' + res.level);
            if (btn) this.playButtonResult(btn, true, msg);
            else this.setStatus(msg);
        } else if (res.reason === 'RESOURCES') {
            this.openResourceBuyModal({
                title: label + ' → ' + ('LV' + (res.nextLevel || 1)),
                cost: res.cost,
                action: { type: 'area-upgrade', id: id, area: area }
            });
        } else if (btn) {
            this.playButtonResult(btn, false, res.reason || 'FAILED');
        }
    },

    /**
     * Confirm dialog for an area upgrade: what changes (slot size, new
     * slots, hull bonus), the cost against the wallet, CONFIRM / CANCEL.
     */
    openAreaUpgradeModal(shipId, areaId) {
        const root = this.overlay && this.overlay.querySelector('.home-station-content');
        if (!root || typeof shipLoadoutManager === 'undefined') return;
        this.closeAreaUpgradeModal();
        const slm = shipLoadoutManager;
        const profile = this.getProfile();
        const lv = profileManager.getShipAreaLevels(shipId, profile)[areaId] || 0;
        const check = profileManager.canPurchaseShipAreaUpgrade(shipId, areaId, profile);
        const cost = check.cost || economyConfig.getShipAreaUpgradeCost(areaId, lv + 1);
        const from = 'LV' + lv;
        const to = ('LV' + (lv + 1));
        const bonus = slm.getAreaSlotBonusAt(areaId, lv + 1);
        // Every area level is one frame level: +8 HP, +1 armor (getFrameHullBonus).
        const hull = { hp: 8, armor: 1 };
        const holds = { front: 'the nose weapon', center: 'defense and energy parts', back: 'ability parts', wing: 'the wing weapons' }[areaId] || '';
        const lines = [
            `<li>${this.areaLabel(areaId)} (${holds}): <strong>${from} → ${to}</strong> — slot sizes are upgraded per slot in the hangar</li>`,
            bonus.length ? `<li>New: <strong>+${bonus.length} ${this.slotKindName(bonus[0])} slot${bonus.length > 1 ? 's' : ''}</strong></li>` : '',
            hull ? `<li>Hull: <strong>+${hull.hp} HP, +${hull.armor} armor</strong></li>` : ''
        ].join('');
        const short = check.reason === 'RESOURCES';
        const modal = document.createElement('div');
        modal.className = 'hs-res-buy-modal hs-area-modal';
        modal.setAttribute('role', 'dialog');
        modal.setAttribute('aria-modal', 'true');
        modal.setAttribute('aria-label', 'Area upgrade');
        modal.innerHTML = `<div class="hs-res-buy-dialog">` +
            `<div class="hs-res-buy-head"><h3>UPGRADE ${this.areaLabel(areaId)}</h3>` +
            `<p class="hs-res-buy-sub">${this.shipName(shipId)} · ${from} → ${to}</p></div>` +
            `<ul class="hs-area-modal-list">${lines}</ul>` +
            `<div class="hs-res-buy-cost">${cost ? this.renderCostGrid(cost, profile.resources || {}, profile) : ''}</div>` +
            (short ? `<p class="hs-area-modal-short">NOT ENOUGH RESOURCES — CONFIRM OPENS THE RESOURCE SHOP</p>` : '') +
            `<div class="hs-res-buy-actions">` +
            `<button type="button" class="action-button hs-res-buy-close" data-area-modal-cancel>CANCEL</button>` +
            `<button type="button" class="action-button" data-area-modal-confirm ${check.ok || short ? '' : 'disabled'}>` +
            `${short ? 'GET RESOURCES' : 'CONFIRM'}</button>` +
            `</div></div>`;
        root.appendChild(modal);
        const confirmBtn = modal.querySelector('[data-area-modal-confirm]');
        const close = () => this.closeAreaUpgradeModal();
        modal.querySelector('[data-area-modal-cancel]').addEventListener('click', close);
        // Click on the dark backdrop cancels too.
        modal.addEventListener('click', (e) => { if (e.target === modal) close(); });
        confirmBtn.addEventListener('click', () => {
            close();
            this.confirmAreaUpgrade(shipId, areaId);
        });
        // ESC cancels, ENTER confirms; the station's own keys stay out of it.
        this._areaModalKeys = (e) => {
            if (e.key === 'Escape' || e.key === 'Backspace') close();
            else if (e.key === 'Enter' && !confirmBtn.disabled) confirmBtn.click();
            else return;
            e.preventDefault();
            e.stopImmediatePropagation();
        };
        document.addEventListener('keydown', this._areaModalKeys, true);
        (confirmBtn.disabled ? modal.querySelector('[data-area-modal-cancel]') : confirmBtn).focus();
    },

    closeAreaUpgradeModal() {
        if (this._areaModalKeys) {
            document.removeEventListener('keydown', this._areaModalKeys, true);
            this._areaModalKeys = null;
        }
        const m = this.overlay && this.overlay.querySelector('.hs-area-modal');
        if (m) m.remove();
    },

    /** Singular slot name for a loadout key (weapons → WEAPON). */
    slotKindName(key) {
        return { weapons: 'WEAPON', defenses: 'DEFENSE', abilities: 'ABILITY', energy: 'ENERGY' }[key]
            || String(key || '').toUpperCase();
    },

    /**
     * ON/OFF switch in the NOSE and AFT branch headers of the component
     * tree. A switched-off area is dimmed and its contents collapsed.
     */
    appendAreaToggles(treeContainer, shipId) {
        if (typeof shipLoadoutManager === 'undefined' || !shipLoadoutManager.getToggleableAreas) return;
        shipLoadoutManager.getToggleableAreas().forEach((area) => {
            // Wings are one branch, or left/right branches when asymmetric.
            const branch = area === 'wing'
                ? treeContainer.querySelector('#hs-tree-area-wings, #hs-tree-area-wingLeft')
                : treeContainer.querySelector(`#hs-tree-area-${area}`);
            const summary = branch && branch.querySelector(':scope > summary');
            if (!summary || summary.querySelector('.hs-area-switch')) return;
            const on = shipLoadoutManager.isAreaEnabled(shipId, area);
            const branches = area === 'wing'
                ? Array.from(treeContainer.querySelectorAll('#hs-tree-area-wings, #hs-tree-area-wingLeft, #hs-tree-area-wingRight'))
                : [branch];
            branches.forEach((b) => {
                b.classList.toggle('is-area-off', !on);
                if (!on) b.removeAttribute('open');
            });
            const sw = document.createElement('label');
            sw.className = 'hs-area-switch';
            sw.title = (on ? 'Switch off ' : 'Switch on ') + this.areaLabel(area);
            sw.innerHTML = `<input type="checkbox"${on ? ' checked' : ''} aria-label="${this.areaLabel(area)} on/off">` +
                `<span class="hs-area-switch-track"><span class="hs-area-switch-label">${on ? 'ON' : 'OFF'}</span></span>`;
            // Clicks on the switch must not open/close the branch.
            sw.addEventListener('click', (e) => e.stopPropagation());
            sw.querySelector('input').addEventListener('change', (e) => {
                const res = shipLoadoutManager.setAreaEnabled(shipId, area, e.target.checked);
                if (!res.ok) return;
                this.statusMsg = this.areaLabel(area) + (e.target.checked ? ' ON' : ' OFF');
                this._hangarRecenter = true;
                this.createUI();
            });
            summary.appendChild(sw);
        });
    },

    areaLabel(areaId) {
        const a = (typeof shipLoadoutManager !== 'undefined' && shipLoadoutManager.getShipAreas)
            ? shipLoadoutManager.getShipAreas().find((x) => x.id === areaId) : null;
        return a ? a.label : String(areaId || '').toUpperCase();
    },
});


/* --- js/ui/home-station/slot-upgrades.js?v=stats-1 --- */
"use strict";

// HomeStationUI: per-slot size upgrades (S → M → L) in the hangar slot menu.
// Logic in js/core/ship-loadout/slot-sizes.js.
extendClass(HomeStationUI, {
    /** "SLOT S → M · cost · UPGRADE" row at the top of a slot's menu. */
    renderSlotUpgradeRow(kind, index) {
        if (typeof shipLoadoutManager === 'undefined' || !shipLoadoutManager.getSlotSizeLevel
            || typeof profileManager === 'undefined' || !profileManager.canPurchaseSlotUpgrade) return '';
        const shipId = this.hangarShipId;
        const slm = shipLoadoutManager;
        const size = slm.getSlotSizeLevel(shipId, kind, index);
        const split = slm.isSplitSlot(shipId, kind, index);
        const label = slm.slotSizeLabel(size);
        const kindTag = split ? 'SPLIT PAIR' : 'CENTRED';
        if (size >= slm.getMaxSlotSizeLevel()) {
            return `<div class="hs-slot-upgrade is-max"><span class="hs-slot-upgrade-label">SLOT <span class="hs-slot-size">${label}</span> · ${kindTag}</span><span class="hs-muted">MAX</span></div>`;
        }
        const check = profileManager.canPurchaseSlotUpgrade(shipId, kind, index);
        const cost = check.cost || profileManager.getSlotUpgradeCost(size + 1, split);
        const profile = this.getProfile ? this.getProfile() : profileManager.getActiveProfile();
        const costHtml = this.renderCompactCost ? this.renderCompactCost(cost, profile && profile.resources) : '';
        return `<div class="hs-slot-upgrade">` +
            `<span class="hs-slot-upgrade-label">SLOT <span class="hs-slot-size">${label}</span> → <span class="hs-slot-size">${slm.slotSizeLabel(size + 1)}</span> · ${kindTag}</span>` +
            `<span class="hs-slot-upgrade-cost">${costHtml}</span>` +
            `<button type="button" class="action-button hs-slot-upgrade-btn" data-slot-up="${kind}|${index}"${check.ok ? '' : (check.reason === 'RESOURCES' ? ' data-short="1"' : ' disabled')}>UPGRADE</button>` +
            `</div>`;
    },

    /**
     * Smoothly pan the hangar bay so the clicked slot marker sits in the
     * centre. `target` is the marker that was clicked (either half of a
     * split pair); without it the slot's main marker is used.
     */
    panHangarToSlot(kind, index, target) {
        const canvas = this.overlay && this.overlay.querySelector('#hsHangarBayCanvas');
        const marker = (target && target.classList && target.classList.contains('hs-hangar-slot-pin'))
            ? target
            : this.overlay && this.overlay.querySelector(
                `.hs-hangar-slot[data-slot-kind="${kind}"][data-slot-index="${index}"] .hs-hangar-slot-pin:not(.is-mirror)`);
        if (!canvas || !marker) return;
        const cr = canvas.getBoundingClientRect();
        const pr = marker.getBoundingClientRect();
        if (!pr.width && !pr.height) return;
        const px = pr.left + pr.width / 2;
        const py = pr.top + pr.height / 2;
        // Screen → canvas pixels (the pan offset is in canvas pixels).
        const sx = canvas.width / Math.max(1, cr.width);
        const sy = canvas.height / Math.max(1, cr.height);
        const dx = (cr.left + cr.width / 2 - px) * sx;
        const dy = (cr.top + cr.height / 2 - py) * sy;
        if (Math.abs(dx) < 2 && Math.abs(dy) < 2) return;
        const fromX = this._hangarBayPanX || 0;
        const fromY = this._hangarBayPanY || 0;
        const start = performance.now();
        const dur = 260;
        if (this._hangarPanRaf) cancelAnimationFrame(this._hangarPanRaf);
        const step = (now) => {
            const t = Math.min(1, (now - start) / dur);
            const e = 1 - Math.pow(1 - t, 3);
            this._hangarBayPanX = Math.round(fromX + dx * e);
            this._hangarBayPanY = Math.round(fromY + dy * e);
            if (this.isVisible && this.tab === 'hangar') this.drawHangarBay();
            this._hangarPanRaf = t < 1 ? requestAnimationFrame(step) : 0;
        };
        this._hangarPanRaf = requestAnimationFrame(step);
    },

    bindSlotUpgradeEvents() {
        if (!this.overlay) return;
        this.overlay.querySelectorAll('[data-slot-up]').forEach((btn) => {
            if (btn.dataset.bound === '1') return;
            btn.dataset.bound = '1';
            btn.addEventListener('click', (e) => {
                e.preventDefault();
                e.stopPropagation();
                const [kind, idx] = (btn.getAttribute('data-slot-up') || '').split('|');
                const index = Number(idx) || 0;
                const res = profileManager.purchaseSlotUpgrade(this.hangarShipId, kind, index);
                if (res.ok) {
                    this.statusMsg = 'SLOT UPGRADED → ' + shipLoadoutManager.slotSizeLabel(res.size);
                    // Keep the slot's menu open after the rebuild.
                    this._hangarOpenSlot = { kind: kind, index: index };
                    this.createUI();
                } else if (res.reason === 'RESOURCES' && this.openResourceBuyModal) {
                    this.playButtonResult(btn, false, 'NOT ENOUGH RESOURCES');
                } else {
                    this.playButtonResult(btn, false, res.reason || 'NOT AVAILABLE');
                }
            });
        });
    }
});

// Hangar header stat tile: icon · label / big value · detail line.
extendClass(HomeStationUI, {
    hangarStatTile(icon, label, valueHtml, title, detailHtml, extraClass, tint) {
        // Icons sit bare in the title bar: tint them (accent by default) so they don't fall back to white.
        let color = tint || null;
        if (!color) {
            try {
                const v = getComputedStyle(this.overlay || document.documentElement).getPropertyValue('--color-primary').trim();
                if (v && v.charAt(0) === '#') color = v;
            } catch (e) { /* ignore */ }
        }
        return `<div class="hs-hangar-stat${extraClass || ''}" title="${String(title || '').replace(/"/g, '&quot;')}">` +
            `<span class="hs-stat-icon">${this.iconHtml(icon, 32, 'hs-pixel', label, color)}</span>` +
            `<span class="hs-stat-body">` +
                `<em>${label}</em>` +
                `<strong class="hs-stat-value">${valueHtml}</strong>` +
                (detailHtml ? `<span class="hs-stat-detail">${detailHtml}</span>` : '') +
            `</span>` +
            `</div>`;
    }
});


