/* --- js/ui/start-screen/build-font-menu-items.js?v=1791486957 --- */
"use strict";

// StartScreenManager methods, split from start-screen.js.
extendClass(StartScreenManager, {
    buildFontMenuItems() {
        const ua = (typeof uiAppearanceManager !== 'undefined') ? uiAppearanceManager : null;
        return [
            {
                name: 'Family',
                value: ua ? ua.font : 'COURIER',
                options: ua ? ua.getFontOptions() : ['COURIER', 'MONO', 'SYSTEM', 'SERIF'],
                type: 'font'
            },
            {
                name: 'LG · Titles Size',
                value: ua ? ua.fontSizes.h1 : '20',
                options: ua ? ua.getFontSizeOptions('h1') : ['20', '24', '28', '32', '36', '40', '48'],
                type: 'fontSize',
                sizeKey: 'h1'
            },
            {
                name: 'LG · Titles Font',
                value: ua ? ua.fontFamilies.h1 : 'GLOBAL',
                options: ua ? ua.getFontFamilyOptions() : ['GLOBAL', 'COURIER', 'MONO', 'SYSTEM', 'SERIF'],
                type: 'fontFamilyType',
                sizeKey: 'h1'
            },
            {
                name: 'MD · Values Size',
                value: ua ? ua.fontSizes.h2 : '14',
                options: ua ? ua.getFontSizeOptions('h2') : ['10', '11', '12', '14', '16', '18', '20', '24'],
                type: 'fontSize',
                sizeKey: 'h2'
            },
            {
                name: 'MD · Values Font',
                value: ua ? ua.fontFamilies.h2 : 'GLOBAL',
                options: ua ? ua.getFontFamilyOptions() : ['GLOBAL', 'COURIER', 'MONO', 'SYSTEM', 'SERIF'],
                type: 'fontFamilyType',
                sizeKey: 'h2'
            },
            {
                name: 'SM · Labels Size',
                value: ua ? ua.fontSizes.small : '11',
                options: ua ? ua.getFontSizeOptions('small') : ['7', '8', '9', '10', '11', '12'],
                type: 'fontSize',
                sizeKey: 'small'
            },
            {
                name: 'SM · Labels Font',
                value: ua ? ua.fontFamilies.small : 'GLOBAL',
                options: ua ? ua.getFontFamilyOptions() : ['GLOBAL', 'COURIER', 'MONO', 'SYSTEM', 'SERIF'],
                type: 'fontFamilyType',
                sizeKey: 'small'
            },
            {
                name: 'In-Game HUD %',
                value: ua ? ua.fontSizes.game : '100',
                options: ua ? ua.getFontSizeOptions('game') : ['70', '85', '100', '115', '130', '150'],
                type: 'fontSize',
                sizeKey: 'game'
            }
        ];
    },

    getGlobalLookValue(key, fallback) {
        if (typeof colorPaletteSystem === 'undefined' || !colorPaletteSystem.getGlobalLook) {
            return String(fallback);
        }
        const look = colorPaletteSystem.getGlobalLook();
        return String(look[key] == null ? fallback : Math.round(look[key]));
    },

    syncFontMenuItems() {
        this.fontMenuItems = this.buildFontMenuItems();
    },

    loadDevMode() {
        try {
            return localStorage.getItem(this.devModeStorageKey) === 'true';
        } catch (e) {
            return false;
        }
    },

    saveDevMode() {
        try {
            localStorage.setItem(this.devModeStorageKey, this.devMode ? 'true' : 'false');
        } catch (e) { /* ignore */ }
    },

    toggleDevMode() {
        this.devMode = !this.devMode;
        this.saveDevMode();
        this.rebuildVisibleMenu();
        if (this.selectedIndex >= this.menuItems.length) {
            this.selectedIndex = Math.max(0, this.menuItems.length - 1);
        }
        this.createStartScreenUI();
        // Dev-only tabs (COMPONENTS, LAYOUT) appear / vanish in the station rows.
        if (typeof homeStationUI !== 'undefined' && homeStationUI.isVisible && homeStationUI.createUI) {
            homeStationUI.createUI();
        }
    },

    isMenuItemVisible(itemId) {
        // Already inside the station modal — STATION entry is redundant.
        if (itemId === 'STATION') {
            return !(this.embeddedMode || this.overlayMode);
        }
        // PROFILES too: it is how a first pilot gets created or picked.
        if (itemId === 'PROFILES' || itemId === 'SETTINGS' || itemId === 'ASSETS' || itemId === 'CREDITS' || itemId === 'GALAXIES') {
            return true;
        }
        if (this.devMode) return true;
        return false;
    },

    isExploreItemVisible(itemId) {
        if (this.devMode) return true;
        if (typeof profileManager === 'undefined' || !profileManager.hasActiveProfile()) return false;
        if (itemId === 'SHIPS') return profileManager.hasDiscovered('ships');
        if (itemId === 'PLANETS') return profileManager.hasDiscovered('planets');
        if (itemId === 'ENEMIES') return profileManager.hasDiscovered('enemies');
        if (itemId === 'FACTIONS') return profileManager.hasDiscovered('factions');
        if (itemId === 'EVENTS') return profileManager.hasDiscovered('events');
        if (itemId === 'WEAPONS') return profileManager.hasDiscovered('weapons');
        if (itemId === 'ABILITIES') return profileManager.hasDiscovered('abilities');
        if (itemId === 'DEFENSE SYSTEMS') return profileManager.hasDiscovered('defenses');
        if (itemId === 'COMPONENTS') {
            return profileManager.hasDiscovered('weapons')
                || profileManager.hasDiscovered('abilities')
                || profileManager.hasDiscovered('defenses');
        }
        return false;
    },

    rebuildVisibleMenu() {
        this.visibleMenuClusters = this.menuClusters.map((cluster) => {
            const items = cluster.items.filter((entry) => this.isMenuItemVisible(entry.id));
            return { id: cluster.id, label: cluster.label, items: items };
        }).filter((cluster) => cluster.items.length > 0);

        this.menuItems = this.visibleMenuClusters.reduce((acc, cluster) => {
            return acc.concat(cluster.items.map((item) => item.id));
        }, []);
    },

    get planets() {
        if (typeof planetSelectionManager !== 'undefined') {
            return planetSelectionManager.planets;
        }
        return [];
    },

    hasActiveProfile() {
        return typeof profileManager !== 'undefined' && profileManager.hasActiveProfile();
    },

    hasAnyProfiles() {
        return typeof profileManager !== 'undefined'
            && typeof profileManager.getProfiles === 'function'
            && profileManager.getProfiles().length > 0;
    },

    isMenuItemLocked(itemId) {
        if (itemId === 'PROFILES') return !this.hasAnyProfiles();
        return false;
    },

    /** Hub after leave/quit: Station when profile loaded, else start menu. */
    returnToHub(options) {
        const opts = options || {};
        if (this.hasActiveProfile() && typeof homeStationUI !== 'undefined') {
            this.hide();
            homeStationUI.show(opts);
            return;
        }
        this.show(Object.assign({}, opts, { forceMenu: true }));
    },

    isOverlayOpen() {
        return !!(this.overlayMode && this.visible && this.overlayEl);
    },

    isEmbeddedOpen() {
        return !!(this.embeddedMode && this.visible && this.embeddedHost);
    },

    isStationMenuContext() {
        return this.isOverlayOpen() || this.isEmbeddedOpen();
    },

    getUIHost() {
        if (this.embeddedMode && this.embeddedHost) {
            return this.embeddedHost;
        }
        if (this.overlayMode && this.overlayEl) {
            return this.overlayEl.querySelector('.hs-main-menu-host') || this.overlayEl;
        }
        return document.getElementById('startScreen');
    },

    show(options) {
        const opts = options || {};

        if (opts.asOverlay) {
            // With profile: embed menu as station tab (no separate overlay BG).
            if (!this.hasActiveProfile()) {
                this.show(Object.assign({}, opts, { asOverlay: false, forceMenu: true }));
                return;
            }
            if (typeof homeStationUI !== 'undefined') {
                if (!homeStationUI.isVisible) {
                    homeStationUI.show({
                        skipPersist: opts.skipPersist,
                        tab: opts.tab,
                        shopCategory: opts.shopCategory
                    });
                }
                homeStationUI.openMainMenuOverlay({
                    force: true,
                    showSettings: !!opts.showSettings,
                    showCredits: !!opts.showCredits,
                    skipPersist: !!opts.skipPersist
                });
                return;
            }
            this.showOverlay(opts);
            return;
        }

        // Profile loaded → Station is the hub; fullscreen start menu only without profile.
        if (!opts.forceMenu && this.hasActiveProfile() && typeof homeStationUI !== 'undefined') {
            this.hide();
            const startScreen = document.getElementById('startScreen');
            if (startScreen) startScreen.classList.add('hidden');
            homeStationUI.show({
                skipPersist: opts.skipPersist,
                tab: opts.tab,
                shopCategory: opts.shopCategory,
                onClose: opts.onClose
            });
            return;
        }

        this.hideEmbedded();
        this.teardownOverlay();
        this.overlayMode = false;
        this.visible = true;
        this.rebuildVisibleMenu();
        // Restore menu theme before baking icon data-URLs (context theme may still be active after gameplay)
        if (typeof themeContextManager !== 'undefined') {
            themeContextManager.restoreAppTheme();
            if (this.settingsItems && this.settingsItems[0] && this.settingsItems[0].type === 'palette') {
                this.settingsItems[0].value = themeContextManager.getAppTheme();
            }
            this.syncSecondBaseSettingValue();
        }
        const startScreen = document.getElementById('startScreen');
        if (startScreen) startScreen.classList.remove('hidden');
        this.createStartScreenUI();
        if (typeof soundManager !== 'undefined' && soundManager.startMenuMusic) {
            soundManager.startMenuMusic();
        }
        const skipPersist = opts.skipPersist;
        if (!skipPersist && typeof menuStateManager !== 'undefined') {
            if (this.showSettings) menuStateManager.setScreen('settings');
            else if (this.showCredits) menuStateManager.setScreen('credits');
            else menuStateManager.setScreen('start');
        }
    },
});


/* --- js/ui/start-screen/show-overlay.js?v=galaxies-2 --- */
"use strict";

// StartScreenManager methods, split from start-screen.js.
extendClass(StartScreenManager, {
    showOverlay(options) {
        const opts = options || {};
        this.hideEmbedded();
        this.overlayMode = true;
        this.visible = true;
        this.onOverlayClose = typeof opts.onOverlayClose === 'function' ? opts.onOverlayClose : null;
        if (opts.showSettings) this.showSettings = true;
        if (opts.showCredits) this.showCredits = true;
        if (opts.resetPanels) {
            this.showSettings = false;
            this.showCredits = false;
            this.showProfiles = false;
            this.showFontMenu = false;
            this.showLevels = false;
        }

        this.rebuildVisibleMenu();
        if (typeof themeContextManager !== 'undefined') {
            themeContextManager.restoreAppTheme();
            if (this.settingsItems && this.settingsItems[0] && this.settingsItems[0].type === 'palette') {
                this.settingsItems[0].value = themeContextManager.getAppTheme();
            }
        }

        const startScreen = document.getElementById('startScreen');
        if (startScreen) startScreen.classList.add('hidden');

        if (!this.overlayEl || !this.overlayEl.isConnected) {
            this.overlayEl = document.createElement('div');
            this.overlayEl.className = 'hs-main-menu-overlay';
            this.overlayEl.innerHTML = '<div class="hs-main-menu-host"></div>';
            this.overlayEl.addEventListener('click', (e) => {
                if (e.target === this.overlayEl) this.hideOverlay();
            });
            const mount = document.body;
            mount.appendChild(this.overlayEl);
        }

        this.createStartScreenUI();
        const skipPersist = opts.skipPersist;
        if (!skipPersist && typeof menuStateManager !== 'undefined') {
            if (typeof homeStationUI !== 'undefined' && homeStationUI.isVisible) homeStationUI.persistTab();
            else if (this.showSettings) menuStateManager.setScreen('settings');
            else if (this.showCredits) menuStateManager.setScreen('credits');
            else if (typeof homeStationUI !== 'undefined' && homeStationUI.isVisible) {
                homeStationUI.persistTab();
            }
        }
    },

    showEmbedded(options) {
        const opts = options || {};
        this.teardownOverlay();
        this.overlayMode = false;
        this.embeddedMode = true;
        this.visible = true;
        this.embeddedHost = opts.host || null;
        if (!this.embeddedHost) return;

        if (opts.tab && this.embeddedMenuTabs.some((t) => t.id === opts.tab)) this.embeddedMenuTab = opts.tab;
        else if (opts.showSettings) this.embeddedMenuTab = 'settings';
        else if (opts.showCredits) this.embeddedMenuTab = 'credits';
        else if (opts.resetPanels || !this.embeddedMenuTab) this.embeddedMenuTab = 'settings';
        this.syncEmbeddedFlags();

        if (opts.resetPanels && !opts.showSettings && !opts.showCredits) {
            this.showFontMenu = false;
            this.showLevels = false;
        }

        this.rebuildVisibleMenu();
        if (typeof themeContextManager !== 'undefined') {
            themeContextManager.restoreAppTheme();
            if (this.settingsItems && this.settingsItems[0] && this.settingsItems[0].type === 'palette') {
                this.settingsItems[0].value = themeContextManager.getAppTheme();
            }
        }

        const startScreen = document.getElementById('startScreen');
        if (startScreen) startScreen.classList.add('hidden');

        this.createStartScreenUI();
        const skipPersist = opts.skipPersist;
        if (!skipPersist && typeof menuStateManager !== 'undefined') {
            // Inside the station the open menu tab is station state.
            if (typeof homeStationUI !== 'undefined' && homeStationUI.isVisible) homeStationUI.persistTab();
            else if (this.showSettings) menuStateManager.setScreen('settings');
            else if (this.showCredits) menuStateManager.setScreen('credits');
        }
    },

    syncEmbeddedFlags() {
        this.showSettings = this.embeddedMode && this.embeddedMenuTab === 'settings';
        this.showCredits = this.embeddedMode && this.embeddedMenuTab === 'credits';
    },

    setEmbeddedMenuTab(tabId) {
        const ok = this.embeddedMenuTabs.some((t) => t.id === tabId);
        if (!ok) return;
        this.embeddedMenuTab = tabId;
        this.showFontMenu = false;
        this.syncEmbeddedFlags();
        this.createStartScreenUI();
        if (typeof menuStateManager !== 'undefined') {
            if (typeof homeStationUI !== 'undefined' && homeStationUI.isVisible) homeStationUI.persistTab();
            else if (tabId === 'settings') menuStateManager.setScreen('settings');
            else if (tabId === 'credits') menuStateManager.setScreen('credits');
            else if (typeof homeStationUI !== 'undefined' && homeStationUI.isVisible) {
                homeStationUI.persistTab();
            }
        }
    },

    cycleEmbeddedMenuTab(dir) {
        const ids = this.embeddedMenuTabs.map((t) => t.id);
        const idx = ids.indexOf(this.embeddedMenuTab);
        const next = (idx + dir + ids.length) % ids.length;
        this.setEmbeddedMenuTab(ids[next]);
    },

    hideEmbedded() {
        if (!this.embeddedMode && !this.embeddedHost) {
            return;
        }
        this.embeddedMode = false;
        if (this.embeddedHost) {
            this.embeddedHost.innerHTML = '';
        }
        this.embeddedHost = null;
        if (!this.overlayMode) {
            this.visible = false;
            this.showSettings = false;
            this.showCredits = false;
            this.showFontMenu = false;
            this.showLevels = false;
        }
    },

    hideOverlay() {
        const cb = this.onOverlayClose;
        this.teardownOverlay();
        this.overlayMode = false;
        this.visible = false;
        this.showSettings = false;
        this.showCredits = false;
        this.showFontMenu = false;
        this.showLevels = false;
        this.onOverlayClose = null;
        if (typeof cb === 'function') cb();
        if (typeof homeStationUI !== 'undefined' && homeStationUI.isVisible) {
            homeStationUI.persistTab();
        }
    },

    teardownOverlay() {
        if (this.overlayEl) {
            this.overlayEl.remove();
            this.overlayEl = null;
        }
    },

    hide() {
        this.visible = false;
        this.hideEmbedded();
        this.teardownOverlay();
        this.overlayMode = false;
        this.onOverlayClose = null;
        this.removeStartScreenUI();
        const startScreen = document.getElementById('startScreen');
        if (startScreen) startScreen.classList.add('hidden');
    },

    /** Remembers the open start-screen page + selected item (restored on load). */
    saveMenuState() {
        const page = this.showGalaxies ? 'galaxies' : this.showSettings ? 'settings' : this.showCredits ? 'credits' : 'menu';
        try {
            localStorage.setItem('vf_start_menu_state_v1', JSON.stringify({
                page, selected: this.menuItems[this.selectedIndex] || null
            }));
        } catch (e) { /* storage unavailable */ }
    },

    restoreMenuState() {
        let st = null;
        try { st = JSON.parse(localStorage.getItem('vf_start_menu_state_v1') || 'null'); } catch (e) { st = null; }
        if (!st) return;
        const i = st.selected ? this.menuItems.indexOf(st.selected) : -1;
        if (i >= 0) this.selectedIndex = i;
        this.showGalaxies = st.page === 'galaxies';
        this.showSettings = st.page === 'settings';
        this.showCredits = st.page === 'credits';
    },

    createStartScreenUI() {
        const host = this.getUIHost();
        if (!host) {
            console.error('Start screen host not found');
            return;
        }
        // First main-menu render: reopen the page the player was on.
        if (!this._menuStateRestored && !this.overlayMode && !this.embeddedMode) {
            this._menuStateRestored = true;
            if (!this.showProfiles && !this.showLevels && !this.showFontMenu &&
                !this.showSettings && !this.showCredits && !this.showGalaxies) {
                this.restoreMenuState();
            }
        }

        if (!this._settingsOutsideClickBound) {
            this._settingsOutsideClickBound = true;
            const startScreen = document.getElementById('startScreen');
            if (startScreen) {
                startScreen.addEventListener('click', (e) => {
                    if (e.target === startScreen && this.showSettings && !this.overlayMode && !this.embeddedMode) {
                        this.handleEscape();
                    }
                });
            }
        }

        if (this.overlayMode || this.embeddedMode) {
            host.innerHTML = '';
        } else {
            // Keep parallax BG layers across rebuilds (enables crossfade, avoids black flash)
            const keep = Array.from(host.querySelectorAll(
                ':scope > .vf-bg-parallax-base, :scope > .vf-bg-parallax-glow'
            ));
            host.innerHTML = '';
            for (let i = keep.length - 1; i >= 0; i--) {
                host.insertBefore(keep[i], host.firstChild);
            }
        }

        // Create content container
        const content = document.createElement('div');
        if (this.embeddedMode) {
            content.className = 'start-screen-content start-screen-content-overlay start-screen-content-embedded';
        } else {
            content.className = 'start-screen-content' +
                (this.overlayMode ? ' start-screen-content-overlay' : '');
        }

        if (this.embeddedMode) {
            if (this.showFontMenu) {
                this.createFontMenuUI(content);
            } else {
                this.createEmbeddedMenuUI(content);
            }
        } else if (this.showProfiles) {
            this.createProfilesScreenUI(content);
        } else if (this.showGalaxies && typeof galaxyViewer !== 'undefined') {
            content.classList.add('start-screen-galaxies');
            galaxyViewer.mount(content, {
                onClose: () => {
                    this.showGalaxies = false;
                    this.createStartScreenUI();
                }
            });
        } else if (this.showCredits) {
            this.createCreditsUI(content);
        } else if (this.showFontMenu) {
            this.createFontMenuUI(content);
        } else if (this.showSettings) {
            this.createSettingsUI(content);
        } else if (this.showLevels) {
            this.createLevelsUI(content);
        } else {
            this.createMainMenuUI(content);
        }

        // Every start-screen page (menu, settings, credits, profiles) lives
        // inside the same terminal screen.
        if (!this.overlayMode && !this.embeddedMode) content.classList.add('start-screen-retro');
        host.appendChild(content);
        if (!this.overlayMode && !this.embeddedMode) this.saveMenuState();

        // Update menu selection
        this.updateMenuSelection();

        if (typeof VFBgMouseParallax !== 'undefined' && VFBgMouseParallax.refresh) {
            VFBgMouseParallax.refresh();
        }
    },
});


/* --- js/ui/start-screen/create-main-menu-ui.js?v=inline-3 --- */
"use strict";

// StartScreenManager methods, split from start-screen.js.
extendClass(StartScreenManager, {
    createMainMenuUI(content) {
        content.classList.add('start-screen-retro');
        this.rebuildVisibleMenu();
        if (this.selectedIndex >= this.menuItems.length) {
            this.selectedIndex = Math.max(0, this.menuItems.length - 1);
        }
        // Don't land on a greyed-out entry (e.g. LOAD with no pilots).
        if (this.isMenuItemLocked(this.menuItems[this.selectedIndex])) {
            const first = this.menuItems.findIndex((id) => !this.isMenuItemLocked(id));
            if (first >= 0) this.selectedIndex = first;
        }

        const title = document.createElement('h1');
        title.textContent = 'GLXEE';
        title.className = 'start-screen-title';

        const subtitle = document.createElement('p');
        subtitle.textContent = '...a MRDSN Production';
        subtitle.className = 'start-screen-subtitle';

        const menu = document.createElement('div');
        menu.className = 'start-screen-menu start-screen-menu-clustered';

        let flatIndex = 0;
        this.visibleMenuClusters.forEach((cluster) => {
            const group = document.createElement('div');
            group.className = 'menu-cluster';
            group.dataset.cluster = cluster.id;

            if (cluster.label) {
                const header = document.createElement('div');
                header.className = 'menu-cluster-title';
                header.textContent = cluster.label;
                group.appendChild(header);
            }

            cluster.items.forEach((entry) => {
                const index = flatIndex;
                flatIndex += 1;
                const itemId = entry.id;
                const locked = this.isMenuItemLocked(itemId);
                const menuItem = document.createElement('div');
                const primaryClass = entry.primary ? ' menu-item-primary' : '';
                const lockedClass = locked ? ' locked' : '';
                menuItem.className = `menu-item${primaryClass}${lockedClass}${index === this.selectedIndex ? ' selected' : ''}`;
                menuItem.dataset.menuIndex = String(index);
                menuItem.dataset.cluster = cluster.id;
                if (locked) menuItem.setAttribute('aria-disabled', 'true');

                const iconWrap = document.createElement('span');
                iconWrap.className = 'menu-item-icon';
                const iconKey = entry.icon || this.menuIconById[itemId];
                if (typeof iconRenderer !== 'undefined' && iconKey) {
                    // Big chunky variant where one exists, shown at 64 px.
                    const hdKey = { hsStation: 'menuStationHd', menuProfiles: 'menuProfilesHd', menuLoad: 'menuLoadHd', menuNewPilot: 'menuNewPilotHd', menuSettings: 'menuSettingsHd', menuCredits: 'menuCreditsHd' }[iconKey];
                    const hd = hdKey && typeof IconSprites !== 'undefined' && IconSprites[hdKey];
                    iconWrap.innerHTML = iconRenderer.imgHtml(hd ? hdKey : iconKey, hd ? 64 : 48, 'menu-pixel-icon');
                }

                const text = document.createElement('span');
                text.className = 'menu-item-text';
                const label = document.createElement('span');
                label.className = 'menu-item-label';
                label.textContent = entry.label || itemId;
                text.appendChild(label);
                // Description lives in the tooltip, not as a subline
                if (locked && itemId === 'PROFILES') {
                    menuItem.dataset.uiTip = 'No pilots to load — create a new pilot first';
                } else if (entry.desc) {
                    menuItem.dataset.uiTip = entry.desc;
                }

                menuItem.appendChild(iconWrap);
                menuItem.appendChild(text);
                menuItem.addEventListener('mouseenter', () => {
                    this.selectedIndex = index;
                    this.updateMenuSelection();
                });
                menuItem.addEventListener('click', () => {
                    if (locked) return;
                    this.selectedIndex = index;
                    this.updateMenuSelection();
                    this.selectMenuItem();
                });
                group.appendChild(menuItem);
            });

            menu.appendChild(group);
        });

        const instructions = this.buildControlsHint([
            'ARROW KEYS / MOUSE: Navigate',
            'SPACEBAR / CLICK: Select'
        ]);

        const footer = document.createElement('div');
        footer.className = 'start-screen-footer';
        if (this.devMode) {
            footer.innerHTML =
                '<span class="dev-mode-badge">DEV MODE ON</span>' +
                '<span class="dev-mode-hint">SHIFT+C TOGGLE</span>' +
                '<span class="dev-mode-hint-block">' +
                'ARCHIVE: K Know/Forget • B Build/Unbuild • V Visit/Unvisit • C Clear/Unclear' +
                '</span>';
        } else {
            footer.innerHTML = '<span class="dev-mode-hint">SHIFT+C DEV MODE</span>';
        }

        content.appendChild(title);
        content.appendChild(subtitle);
        // Menu on the left, recent-pilots scoreboard on the right.
        const menuRow = document.createElement('div');
        menuRow.className = 'start-menu-row';
        menuRow.appendChild(menu);
        const board = this.buildRecentPilotsBoard();
        if (board) menuRow.appendChild(board);
        content.appendChild(menuRow);
        content.appendChild(instructions);
        const utilRow = document.createElement('div');
        utilRow.className = 'ui-menu-util-row';
        utilRow.appendChild(this.buildControlsShowBtn());
        utilRow.appendChild(this.buildIntroBtn());
        content.appendChild(utilRow);
        // Dev hint lives in the hover row; the DEV MODE ON badge stays visible
        if (this.devMode) content.appendChild(footer);
        else utilRow.appendChild(footer);
    },
    /** Top-5 style scoreboard of the last five played profiles. */
    buildRecentPilotsBoard() {
        const pm = typeof profileManager !== 'undefined' ? profileManager : null;
        if (!pm || !pm.getRecentProfiles) return null;
        // Last five played, ranked by score like an arcade top 5.
        const recent = pm.getRecentProfiles(5)
            .map((p) => ({ p, score: pm.getProfileScore(p) }))
            .sort((a, b) => b.score - a.score);
        const esc = (v) => String(v == null ? '' : v).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
        const activeId = pm.hasActiveProfile() ? pm.getActiveProfile().id : null;
        const board = document.createElement('div');
        board.className = 'start-scoreboard';
        const rows = recent.map(({ p, score: raw }, i) => {
            const faction = String(p.faction || 'pirate');
            const emblem = typeof profileSelectionManager !== 'undefined' && profileSelectionManager.getFactionEmblemHtml
                ? profileSelectionManager.getFactionEmblemHtml(faction, 24) : '';
            const score = raw.toLocaleString('en-US');
            return `<li class="start-scoreboard-row is-pickable${p.id === activeId ? ' is-active' : ''}" data-profile-id="${esc(p.id)}" tabindex="0" role="button" data-ui-tip="${p.id === activeId ? 'Active pilot' : 'Select pilot'}">` +
                `<span class="start-scoreboard-rank">${i + 1}</span>` +
                `<span class="start-scoreboard-emblem">${emblem}</span>` +
                `<span class="start-scoreboard-name">${esc(p.name)}</span>` +
                `<span class="start-scoreboard-score">${score}</span>` +
                '</li>';
        }).join('') + Array.from({ length: Math.max(0, 5 - recent.length) }, (_, k) =>
            '<li class="start-scoreboard-row is-empty">' +
            `<span class="start-scoreboard-rank">${recent.length + k + 1}</span>` +
            '<span class="start-scoreboard-emblem"></span>' +
            '<span class="start-scoreboard-name">---</span>' +
            '<span class="start-scoreboard-score">0</span>' +
            '</li>').join('');
        board.innerHTML =
            '<div class="start-scoreboard-title">RECENT PILOTS</div>' +
            '<div class="start-scoreboard-head"><span>#</span><span></span><span>NAME</span><span>SCORE</span></div>' +
            `<ol class="start-scoreboard-list">${rows}</ol>`;
        // Picking a row loads that pilot and launches straight into the game
        // (START is always a new game).
        board.querySelectorAll('.start-scoreboard-row.is-pickable').forEach((row) => {
            const pick = () => {
                const id = row.getAttribute('data-profile-id');
                if (id !== activeId) pm.setActive(id);
                // Always land in the home station (not the last saved tab /
                // menu) — same order as the START path: station first, then
                // hide the start screen. If the switch fails in place
                // (state of the previous pilot), a reload loads the new one.
                try {
                    if (typeof homeStationUI === 'undefined') throw new Error('no station');
                    homeStationUI.show({ tab: 'station', menuTab: null, onClose: () => this.returnToHub() });
                    this.hide();
                    if (!homeStationUI.isVisible) throw new Error('station not shown');
                } catch (err) {
                    console.warn('[start] pilot switch fell back to reload:', err);
                    location.reload();
                }
            };
            row.addEventListener('click', pick);
            row.addEventListener('keydown', (e) => {
                if (e.key !== 'Enter' && e.key !== ' ') return;
                e.preventDefault();
                e.stopPropagation();
                pick();
            });
        });
        return board;
    },
    createEmbeddedMenuUI(content) {
        this.syncEmbeddedFlags();

        const header = document.createElement('div');
        header.className = 'hs-menu-panel-header';

        // The MENU panel no longer lists the game title / profile line (the pilot card shows it).
        const brand = document.createElement('div');
        brand.className = 'hs-menu-panel-brand';
        header.appendChild(brand);

        const tabs = document.createElement('div');
        tabs.className = 'hs-menu-panel-tabs';
        this.embeddedMenuTabs.forEach((tab) => {
            const btn = document.createElement('button');
            btn.type = 'button';
            btn.className = 'hs-menu-panel-tab' + (tab.id === this.embeddedMenuTab ? ' active' : '');
            btn.dataset.menuTab = tab.id;
            const iconWrap = document.createElement('span');
            iconWrap.className = 'hs-menu-panel-tab-icon';
            if (typeof iconRenderer !== 'undefined' && tab.icon) {
                iconWrap.innerHTML = iconRenderer.imgHtml(tab.icon, 28, 'menu-pixel-icon');
            }
            const label = document.createElement('span');
            label.className = 'hs-menu-panel-tab-label';
            label.textContent = tab.label;
            btn.appendChild(iconWrap);
            btn.appendChild(label);
            btn.addEventListener('click', () => this.setEmbeddedMenuTab(tab.id));
            tabs.appendChild(btn);
        });
        // The station top bar already shows these tabs (renderMenuTabs);
        // only build the in-panel copy when no station bar hosts the menu.
        const stationHostsTabs = typeof homeStationUI !== 'undefined' && homeStationUI.isVisible;
        if (!stationHostsTabs) header.appendChild(tabs);

        const body = document.createElement('div');
        body.className = 'hs-menu-panel-body';
        if (this.embeddedMenuTab === 'profiles') {
            this.fillEmbeddedProfiles(body);
        } else if (this.embeddedMenuTab === 'settings' || this.embeddedMenuTab === 'assets') {
            this.createSettingsUI(body, { bare: true });
        } else if (this.embeddedMenuTab === 'assets') {
            this.fillEmbeddedAssets(body);
        } else if (this.embeddedMenuTab === 'layout' && this.fillEmbeddedLayout) {
            this.fillEmbeddedLayout(body);
        } else {
            body.classList.add('hs-menu-panel-body-credits');
            this.fillEmbeddedCredits(body);
        }

        const footer = document.createElement('div');
        footer.className = 'start-screen-footer hs-menu-panel-footer';
        footer.innerHTML = this.devMode
            ? '<span class="dev-mode-badge">DEV MODE ON</span><span class="dev-mode-hint">SHIFT+C TOGGLE</span>'
            : '<span class="dev-mode-hint">SHIFT+C DEV MODE</span>';

        content.appendChild(header);
        content.appendChild(body);
        const utilRow = document.createElement('div');
        utilRow.className = 'ui-menu-util-row';
        utilRow.appendChild(this.buildControlsShowBtn());
        utilRow.appendChild(this.buildIntroBtn());
        content.appendChild(utilRow);
        // Dev hint lives in the hover row; the DEV MODE ON badge stays visible
        if (this.devMode) content.appendChild(footer);
        else utilRow.appendChild(footer);
    },
    fillEmbeddedProfiles(body) {
        const panel = document.createElement('div');
        panel.className = 'hs-menu-panel-section';

        const heading = document.createElement('h2');
        heading.className = 'hs-menu-panel-section-title';
        heading.textContent = 'PROFILES';
        panel.appendChild(heading);

        const active = document.createElement('p');
        active.className = 'hs-menu-panel-copy';
        if (typeof profileManager !== 'undefined' && profileManager.hasActiveProfile()) {
            const p = profileManager.getActiveProfile();
            active.textContent = `Active pilot: ${p.name}`;
        } else {
            active.textContent = 'No profile loaded.';
        }
        panel.appendChild(active);

        // Profiles listed right here — pick one to switch pilots.
        if (typeof profileManager !== 'undefined' && profileManager.getProfiles) {
            const activeId = profileManager.hasActiveProfile() ? profileManager.getActiveProfile().id : null;
            const profiles = profileManager.getProfiles();
            const factions = (typeof factionManager !== 'undefined' && factionManager.getFactionIds)
                ? factionManager.getFactionIds().slice() : [];
            profiles.forEach((p) => {
                const f = p.faction || 'pirate';
                if (factions.indexOf(f) === -1) factions.push(f);
            });
            if (this._profileFactionFilter && factions.indexOf(this._profileFactionFilter) === -1) {
                this._profileFactionFilter = null;
            }
            const list = document.createElement('div');
            list.className = 'hs-menu-profile-list';
            let applyFilter = () => {
                const f = this._profileFactionFilter;
                list.querySelectorAll('.hs-menu-profile-row').forEach((row) => {
                    row.hidden = !!f && row.getAttribute('data-faction') !== f;
                });
                filterBar.querySelectorAll('[data-profile-filter]').forEach((b) => {
                    const on = !!f && b.getAttribute('data-profile-filter') === f;
                    b.classList.toggle('is-active', on);
                    b.setAttribute('aria-pressed', on ? 'true' : 'false');
                });
            };
            const filterBar = document.createElement('div');
            filterBar.className = 'hs-menu-profile-filters';
            filterBar.setAttribute('role', 'group');
            filterBar.setAttribute('aria-label', 'Filter by faction');
            // The five faction buttons are the only filter: one at a time, none = show all.
            factions.forEach((f) => {
                const b = document.createElement('button');
                b.type = 'button';
                b.className = 'hs-menu-profile-filter';
                b.setAttribute('data-profile-filter', f);
                const count = profiles.filter((p) => (p.faction || 'pirate') === f).length;
                const emblem = f && typeof profileSelectionManager !== 'undefined' && profileSelectionManager.getFactionEmblemHtml
                    ? profileSelectionManager.getFactionEmblemHtml(f, 24)
                    : '';
                b.innerHTML = emblem ? `<span class="hs-menu-profile-filter-ico">${emblem}</span>` : '';
                b.appendChild(document.createTextNode(f.toUpperCase()));
                if (!count) b.classList.add('is-empty');
                if (f && typeof factionShipStyles !== 'undefined' && factionShipStyles.getFactionStyle) {
                    const st = factionShipStyles.getFactionStyle(f);
                    if (st && st.accent) b.style.setProperty('--row-accent', st.accent);
                }
                b.addEventListener('click', () => {
                    // Clicking the active faction again clears the filter.
                    this._profileFactionFilter = this._profileFactionFilter === f ? null : f;
                    applyFilter();
                });
                filterBar.appendChild(b);
            });
            const createBtn = document.createElement('button');
            createBtn.type = 'button';
            createBtn.className = 'hs-menu-profile-filter hs-menu-profile-create';
            createBtn.innerHTML = '<svg class="hs-menu-profile-act-ico" viewBox="0 0 16 16" aria-hidden="true"><path d="M8 2v12M2 8h12"/></svg>CREATE PROFILE';
            createBtn.addEventListener('click', () => this.openProfileCreate(this._profileFactionFilter));
            filterBar.appendChild(createBtn);
            panel.appendChild(filterBar);
            let pinned = null;
            // Redraw after switch / delete; with no pilot left, back to the start menu.
            const rerender = () => {
                if (!profileManager.hasActiveProfile()) {
                    if (typeof homeStationUI !== 'undefined' && homeStationUI.isVisible) homeStationUI.hide();
                    if (this.hideEmbedded) this.hideEmbedded();
                    this.show({ forceMenu: true });
                    return;
                }
                if (typeof homeStationUI !== 'undefined' && homeStationUI.isVisible) {
                    homeStationUI.createUI();
                    if (homeStationUI._menuArmed && this.focusEmbeddedButtons) this.focusEmbeddedButtons();
                } else {
                    this.createStartScreenUI();
                }
            };
            profiles.forEach((p) => {
                const faction = p.faction || 'pirate';
                // Row = div (it holds its own SWITCH / DELETE buttons).
                const row = document.createElement('div');
                row.tabIndex = 0;
                row.setAttribute('role', 'button');
                row.className = 'hs-menu-profile-row' + (p.id === activeId ? ' is-active' : '');
                row.setAttribute('data-faction', faction);
                if (typeof factionShipStyles !== 'undefined' && factionShipStyles.getFactionStyle) {
                    const st = factionShipStyles.getFactionStyle(faction);
                    if (st && st.accent) row.style.setProperty('--row-accent', st.accent);
                }
                const emblem = (typeof profileSelectionManager !== 'undefined' && profileSelectionManager.getFactionEmblemHtml)
                    ? profileSelectionManager.getFactionEmblemHtml(faction, 32, 4) : '';
                const icoSwitch = '<svg class="hs-menu-profile-act-ico" viewBox="0 0 16 16" aria-hidden="true"><path d="M2 5h10M9 2l3 3-3 3M14 11H4M7 8l-3 3 3 3"/></svg>';
                const icoDelete = '<svg class="hs-menu-profile-act-ico" viewBox="0 0 16 16" aria-hidden="true"><path d="M2 4h12M6 4V2h4v2M4 4l1 10h6l1-10M7 7v4M9 7v4"/></svg>';
                const esc = (t) => String(t == null ? '' : t).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
                row.innerHTML =
                    `<span class="hs-menu-profile-emblem">${emblem}</span>` +
                    `<span class="hs-menu-profile-name">${esc(p.name)}</span>` +
                    `<span class="hs-menu-profile-faction">${esc(faction.toUpperCase())}</span>` +
                    // Badge cell always present (empty when inactive) so the actions keep their column.
                    (p.id === activeId ? '<span class="hs-menu-profile-badge">ACTIVE</span>' : '<span class="hs-menu-profile-badge-slot"></span>') +
                    `<span class="hs-menu-profile-actions">` +
                    (p.id === activeId ? '' : `<button type="button" class="hs-menu-profile-act" data-profile-switch="${esc(p.id)}">${icoSwitch}<span class="hs-menu-profile-act-label">SWITCH</span></button>`) +
                    `<button type="button" class="hs-menu-profile-act is-danger" data-profile-delete="${esc(p.id)}">${icoDelete}<span class="hs-menu-profile-act-label">DELETE</span></button>` +
                    `</span>`;
                row.addEventListener('keydown', (e) => {
                    if (e.key === 'Enter' && e.target === row) row.click();
                });
                // Row click only shows this pilot's details; switching is explicit.
                row.addEventListener('click', (e) => {
                    if (e.target.closest('.hs-menu-profile-act')) return;
                    pinned = p;
                    renderStats(p);
                });
                const switchBtn = row.querySelector('[data-profile-switch]');
                if (switchBtn) {
                    switchBtn.addEventListener('click', (e) => {
                        e.stopPropagation();
                        profileManager.setActive(p.id);
                        rerender();
                    });
                }
                const delBtn = row.querySelector('[data-profile-delete]');
                delBtn.addEventListener('click', (e) => {
                    e.stopPropagation();
                    // Two-step: first click arms, second (within 3 s) deletes.
                    if (!delBtn.classList.contains('is-armed')) {
                        delBtn.classList.add('is-armed');
                        delBtn.querySelector('.hs-menu-profile-act-label').textContent = 'CONFIRM?';
                        clearTimeout(delBtn._disarm);
                        delBtn._disarm = setTimeout(() => {
                            delBtn.classList.remove('is-armed');
                            delBtn.querySelector('.hs-menu-profile-act-label').textContent = 'DELETE';
                        }, 3000);
                        return;
                    }
                    clearTimeout(delBtn._disarm);
                    profileManager.delete(p.id);
                    rerender();
                });
                list.appendChild(row);
            });
            const renderStats = (profile) => {
                if (typeof profileSelectionManager === 'undefined' || !profileSelectionManager.renderProfileDetails) return;
                stats.innerHTML = profileSelectionManager.renderProfileDetails(profile || null);
                if (profile && typeof factionShipStyles !== 'undefined' && factionShipStyles.getFactionStyle) {
                    const st = factionShipStyles.getFactionStyle(profile.faction || 'pirate');
                    if (st && st.accent) stats.style.setProperty('--row-accent', st.accent);
                }
            };
            // No pilot active yet: preview the first one instead of an empty panel.
            const activeProfile = profiles.find((p) => p.id === activeId) || profiles[0] || null;
            list.querySelectorAll('.hs-menu-profile-row').forEach((row, i) => {
                const show = () => renderStats(profiles[i]);
                row.addEventListener('mouseenter', show);
                row.addEventListener('focus', show);
            });
            list.addEventListener('mouseleave', () => renderStats(pinned || activeProfile));
            const split = document.createElement('div');
            split.className = 'hs-menu-profile-split';
            const left = document.createElement('div');
            left.className = 'hs-menu-profile-col';
            const stats = document.createElement('aside');
            stats.className = 'profile-details hs-menu-profile-stats';
            const empty = document.createElement('p');
            empty.className = 'hs-menu-panel-copy hs-menu-profile-empty';
            empty.textContent = 'No pilots in this faction.';
            left.appendChild(list);
            left.appendChild(empty);
            split.appendChild(left);
            split.appendChild(stats);
            panel.appendChild(split);
            renderStats(activeProfile);
            const baseApply = applyFilter;
            applyFilter = () => {
                baseApply();
                empty.hidden = !!list.querySelector('.hs-menu-profile-row:not([hidden])');
            };
            applyFilter();
        }

        body.appendChild(panel);
    },
});


/* --- js/ui/start-screen/create-main-menu-ui-part2.js?v=inline-3 --- */
"use strict";

// StartScreenManager members, continued from create-main-menu-ui.js (kept under ~500 lines per file).
extendClass(StartScreenManager, {
    /** Start menu PROFILES page, shown inside the terminal screen. */
    createProfilesScreenUI(content) {
        const host = document.createElement('div');
        host.className = 'start-screen-profiles-host';
        content.appendChild(host);
        if (typeof profileSelectionManager === 'undefined') return;
        // The profile dialog itself, rendered inside the terminal screen.
        const createNew = !!this._profilesCreate;
        this._profilesCreate = false;
        profileSelectionManager.show({
            host,
            create: createNew,
            onClose: () => {
                this.showProfiles = false;
                const thenStart = this._profilesThenStart;
                this._profilesThenStart = false;
                if (thenStart && this.hasActiveProfile()) {
                    this.returnToHub();
                    return;
                }
                this.createStartScreenUI();
                if (typeof menuStateManager !== 'undefined') menuStateManager.setScreen('start');
            }
        });
    },
    openProfileCreate(factionId) {
        this.showProfiles = false;
        if (typeof profileSelectionManager === 'undefined') return;
        this.hideEmbedded();
        profileSelectionManager.show({
            onClose: () => {
                if (this.hasActiveProfile()) {
                    this.returnToHub();
                } else {
                    this.show({ forceMenu: true });
                }
            }
        });
        const ids = profileSelectionManager.getFactionIds ? profileSelectionManager.getFactionIds() : [];
        profileSelectionManager.mode = 'create';
        profileSelectionManager.createStep = 'faction';
        profileSelectionManager._heroDefaultName = '';
        profileSelectionManager.pendingFaction = (factionId && ids.indexOf(factionId) !== -1) ? factionId : ids[0];
        profileSelectionManager.createUI();
    },
    fillEmbeddedAssets(body) {
        const panel = document.createElement('div');
        panel.className = 'hs-menu-panel-section';

        const heading = document.createElement('h2');
        heading.className = 'hs-menu-panel-section-title';
        heading.textContent = 'ASSETS';
        panel.appendChild(heading);

        const status = document.createElement('p');
        status.className = 'hs-menu-panel-copy';
        status.dataset.assetStatus = '1';
        status.textContent = 'Bridge: …';
        panel.appendChild(status);

        const actions = document.createElement('div');
        actions.className = 'hs-menu-panel-actions';

        const mk = (label, opts) => {
            const b = document.createElement('button');
            b.type = 'button';
            b.className = 'action-button hs-menu-panel-action';
            b.textContent = label;
            b.addEventListener('click', () => this.openAssetGenerator(opts));
            return b;
        };
        actions.appendChild(mk('OPEN GENERATOR', { returnToSettings: true }));
        actions.appendChild(mk('FACTIONS', { typeId: 'faction', returnToSettings: true }));
        actions.appendChild(mk('FACTION SHIPS', { typeId: 'faction', returnToSettings: true }));
        panel.appendChild(actions);
        body.appendChild(panel);

        this.refreshAssetBridgeStatus().then(() => {
            const item = this.settingsItems.find((s) => s.type === 'assetStatus');
            if (item && status.isConnected) {
                status.textContent = `Bridge: ${item.value}`;
                status.classList.toggle('settings-asset-ready', item.value === 'READY');
                status.classList.toggle('settings-asset-warn', /BRIDGE/.test(item.value));
                status.classList.toggle('settings-asset-off', item.value === 'OFFLINE');
            }
        });
    },
});


