"use strict";

// StartScreenManager methods, split from start-screen.js.
// Line icons (16×16 path data) shown before each settings section title.
const SETTINGS_SECTION_ICONS = {
    theme: 'M8 2a6 6 0 1 0 0 12c1 0 1-1 .5-2s0-2 1.5-2h2a2 2 0 0 0 2-2c0-3.3-2.7-6-6-6zM5 7h1M7 4.5h1M10 5h1',
    look: 'M1.5 8S4 3.5 8 3.5 14.5 8 14.5 8 12 12.5 8 12.5 1.5 8 1.5 8zM8 6a2 2 0 1 0 0 4 2 2 0 1 0 0-4',
    style: 'M2 14l3-1 8-8-2-2-8 8-1 3zM10 4l2 2',
    fx: 'M1.5 3h13v9h-13zM1.5 5.5h13M1.5 8h13M1.5 10.5h13M6 14h4',
    sound: 'M2 6h3l4-3v10l-4-3H2zM11 5.5a3.5 3.5 0 0 1 0 5M12.5 3.5a6 6 0 0 1 0 9',
    game: 'M3 5h10a2 2 0 0 1 2 2v3a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V7a2 2 0 0 1 2-2zM4 7.5v2M3 8.5h2M11 8h.5M12.5 9.5h.5',
    enemies: 'M8 2l2 3h3l-2.5 2 1 3L8 8.5 4.5 10l1-3L3 5h3zM3 12h10v2H3z',
    shots: 'M7 2h2v8H7zM6 10h4v1H6zM7.5 12h1v2h-1zM3 4h2v5H3zM11 5h2v4h-2z',
    assets: 'M2 5l6-3 6 3v6l-6 3-6-3zM2 5l6 3 6-3M8 8v6'
};

extendClass(StartScreenManager, {
    fillEmbeddedCredits(body) {
        const panel = document.createElement('div');
        panel.className = 'hs-menu-panel-section hs-menu-panel-credits';
        panel.innerHTML =
            '<h2 class="hs-menu-panel-section-title">CREDITS</h2>' +
            '<div class="hs-credits-crawl-stage" aria-hidden="false">' +
            '<div class="hs-credits-crawl">' +
            '<div class="hs-credits-crawl-text">' +
            '<div class="hs-credits-crawl-line hs-credits-crawl-role">CREATOR</div>' +
            '<div class="hs-credits-crawl-line">LANCE MEIER / MEIERDESIGNS</div>' +
            '<div class="hs-credits-crawl-line hs-credits-crawl-title">GLXEE</div>' +
            '<div class="hs-credits-crawl-line">A RETRO SPACE SHOOTER</div>' +
            '<div class="hs-credits-crawl-line hs-credits-crawl-role">PILOT PORTRAITS</div>' +
            '<div class="hs-credits-crawl-line">3D HEAD SCAN BY LEE PERRY-SMITH</div>' +
            '<div class="hs-credits-crawl-line">INFINITE REALITIES / TRIPLEGANGERS - CC BY 3.0</div>' +
            '</div>' +
            '</div>' +
            '</div>';
        body.appendChild(panel);
    },

    getClusterNavMap() {
        return {
            main: { up: null, down: null, left: null, right: null }
        };
    },

    getClusterIndexRanges() {
        const ranges = {};
        let start = 0;
        this.visibleMenuClusters.forEach((cluster) => {
            const end = start + cluster.items.length - 1;
            ranges[cluster.id] = { start: start, end: end };
            start = end + 1;
        });
        return ranges;
    },

    jumpToCluster(targetClusterId, preferOffset) {
        const ranges = this.getClusterIndexRanges();
        const range = ranges[targetClusterId];
        if (!range) return false;
        const offset = preferOffset != null ? preferOffset : 0;
        this.selectedIndex = Math.min(range.end, range.start + Math.max(0, offset));
        this.updateMenuSelection();
        return true;
    },

    getSelectedClusterOffset() {
        const ranges = this.getClusterIndexRanges();
        const id = this.menuItems[this.selectedIndex];
        let clusterId = null;
        this.visibleMenuClusters.forEach((c) => {
            if (c.items.some((item) => item.id === id)) clusterId = c.id;
        });
        if (!clusterId || !ranges[clusterId]) return { clusterId: null, offset: 0 };
        return {
            clusterId: clusterId,
            offset: this.selectedIndex - ranges[clusterId].start
        };
    },

    getMainMenuItemElements() {
        const host = this.getUIHost();
        if (!host) return [];
        return Array.from(host.querySelectorAll('.start-screen-menu-clustered .menu-item'));
    },

    /**
     * Spatial arrow nav: pick nearest item in direction, prefer same row/column.
     */
    navigateMainMenuSpatially(direction) {
        const items = this.getMainMenuItemElements();
        if (!items.length) return false;
        const current = items.find((el) => Number(el.dataset.menuIndex) === this.selectedIndex)
            || items[this.selectedIndex];
        if (!current) return false;
        const curRect = current.getBoundingClientRect();
        const cx = curRect.left + curRect.width / 2;
        const cy = curRect.top + curRect.height / 2;

        let best = null;
        let bestScore = Infinity;
        items.forEach((el) => {
            const idx = Number(el.dataset.menuIndex);
            if (idx === this.selectedIndex || Number.isNaN(idx)) return;
            const r = el.getBoundingClientRect();
            const x = r.left + r.width / 2;
            const y = r.top + r.height / 2;
            const dx = x - cx;
            const dy = y - cy;
            const absDx = Math.abs(dx);
            const absDy = Math.abs(dy);
            const rowSlop = Math.max(18, curRect.height * 0.75);
            const colSlop = Math.max(24, curRect.width * 0.6);

            let ok = false;
            let primary = 0;
            let secondary = 0;
            if (direction === 'up') {
                ok = dy < -4;
                primary = -dy;
                secondary = absDx;
                if (absDx <= colSlop) secondary *= 0.15;
            } else if (direction === 'down') {
                ok = dy > 4;
                primary = dy;
                secondary = absDx;
                if (absDx <= colSlop) secondary *= 0.15;
            } else if (direction === 'left') {
                ok = dx < -4;
                primary = -dx;
                secondary = absDy;
                if (absDy <= rowSlop) secondary *= 0.1;
            } else if (direction === 'right') {
                ok = dx > 4;
                primary = dx;
                secondary = absDy;
                if (absDy <= rowSlop) secondary *= 0.1;
            }
            if (!ok) return;
            const score = primary + secondary * 2.5;
            if (score < bestScore) {
                bestScore = score;
                best = idx;
            }
        });

        if (best == null) return false;
        this.selectedIndex = best;
        this.updateMenuSelection();
        return true;
    },

    /** Guarantee the five enemy-class size rows exist (survives stale caches). */
    sizePxDefaults(kind, id) {
        if (kind === 'player') return { min: 6, max: 60, fallback: 18 };
        if (kind === 'shot') return { min: 1, max: 40, fallback: 4 };
        return { min: 12, max: 200, fallback: ({ scout: 36, assault: 48, heavy: 58, elite: 70, capital: 84 })[id] || 48 };
    },

    readSizePxSetting(kind, id) {
        const def = this.sizePxDefaults(kind, id);
        if (typeof uiAppearanceManager !== 'undefined' && uiAppearanceManager.getSizePx) {
            return String(Math.round(uiAppearanceManager.getSizePx(kind, id)));
        }
        return String(def.fallback);
    },

    ensureEnemyClassSizeSettings() {
        if (!Array.isArray(this.settingsItems)) this.settingsItems = [];
        const classes = [
            { id: 'scout', name: 'Scout Size' },
            { id: 'assault', name: 'Assault Size' },
            { id: 'heavy', name: 'Heavy Size' },
            { id: 'elite', name: 'Elite Size' },
            { id: 'capital', name: 'Capital Size' }
        ];
        // Drop legacy single "Enemy Size" row if present.
        this.settingsItems = this.settingsItems.filter((item) => item && item.type !== 'enemySize');
        let insertAt = this.settingsItems.findIndex((item) => item && item.type === 'shipRenderStyle');
        insertAt = insertAt >= 0 ? insertAt + 1 : this.settingsItems.length;

        let playerItem = this.settingsItems.find((s) => s && s.type === 'playerSize');
        const playerDef = this.sizePxDefaults('player');
        if (!playerItem) {
            playerItem = {
                name: 'Player Size',
                value: this.readSizePxSetting('player'),
                min: playerDef.min, max: playerDef.max, step: 1, suffix: 'px',
                type: 'playerSize'
            };
            this.settingsItems.splice(insertAt, 0, playerItem);
            insertAt += 1;
        } else {
            playerItem.name = 'Player Size';
            playerItem.min = playerDef.min;
            playerItem.max = playerDef.max;
            playerItem.step = 1;
            playerItem.suffix = 'px';
            delete playerItem.options;
            playerItem.value = this.readSizePxSetting('player');
        }

        classes.forEach((cls, i) => {
            const def = this.sizePxDefaults('enemy', cls.id);
            let item = this.settingsItems.find((s) => s && s.type === 'enemyClassSize' && s.enemyClass === cls.id);
            if (!item) {
                item = {
                    name: cls.name,
                    value: this.readSizePxSetting('enemy', cls.id),
                    min: def.min, max: def.max, step: 1, suffix: 'px',
                    type: 'enemyClassSize',
                    enemyClass: cls.id
                };
                this.settingsItems.splice(insertAt + i, 0, item);
            } else {
                item.name = cls.name;
                item.min = def.min;
                item.max = def.max;
                item.step = 1;
                item.suffix = 'px';
                delete item.options;
                item.value = this.readSizePxSetting('enemy', cls.id);
            }
        });
    },

    /** Guarantee player / enemy / boss shot-size rows exist. */
    ensureShotSizeSettings() {
        if (!Array.isArray(this.settingsItems)) this.settingsItems = [];
        const kinds = [
            { id: 'player', name: 'Player Shots' },
            { id: 'enemy', name: 'Enemy Shots' },
            { id: 'boss', name: 'Boss Shots' }
        ];
        let insertAt = this.settingsItems.findIndex((item) => item && item.type === 'enemyClassSize'
            && item.enemyClass === 'capital');
        insertAt = insertAt >= 0 ? insertAt + 1 : this.settingsItems.length;
        kinds.forEach((kind, i) => {
            const def = this.sizePxDefaults('shot', kind.id);
            let item = this.settingsItems.find((s) => s && s.type === 'shotSize' && s.shotKind === kind.id);
            if (!item) {
                item = {
                    name: kind.name,
                    value: this.readSizePxSetting('shot', kind.id),
                    min: def.min, max: def.max, step: 1, suffix: 'px',
                    type: 'shotSize',
                    shotKind: kind.id
                };
                this.settingsItems.splice(insertAt + i, 0, item);
            } else {
                item.name = kind.name;
                item.min = def.min;
                item.max = def.max;
                item.step = 1;
                item.suffix = 'px';
                delete item.options;
                item.value = this.readSizePxSetting('shot', kind.id);
            }
        });
    },

    createSettingsUI(content, opts) {
        const bare = !!(opts && opts.bare);
        this.ensureEnemyClassSizeSettings();
        this.ensureShotSizeSettings();
        if (typeof VFBgMouseParallax !== 'undefined') {
            const parallaxItem = this.settingsItems.find(item => item.type === 'bgParallax');
            if (parallaxItem) parallaxItem.value = VFBgMouseParallax.getIntensity();
        }
        if (typeof uiAppearanceManager !== 'undefined') {
            this.settingsItems.forEach((item) => {
                if (item.type === 'uiFx' && item.fxKey) {
                    item.value = uiAppearanceManager.isEnumFx(item.fxKey) ? uiAppearanceManager.getFxValue(item.fxKey) : String(uiAppearanceManager.getFxPercent(item.fxKey));
                }
                if (item.type === 'shipRenderStyle') {
                    item.value = uiAppearanceManager.shipRenderStyle;
                }
                if (item.type === 'voxelSize') {
                    item.value = String(uiAppearanceManager.voxelSize || '1');
                    item.options = uiAppearanceManager.getVoxelSizeOptions
                        ? uiAppearanceManager.getVoxelSizeOptions()
                        : ['1', '2', '3', '4'];
                }
                if (item.type === 'enemyClassSize' && item.enemyClass) {
                    item.value = this.readSizePxSetting('enemy', item.enemyClass);
                }
                if (item.type === 'playerSize') {
                    item.value = this.readSizePxSetting('player');
                }
                if (item.type === 'shotSize' && item.shotKind) {
                    item.value = this.readSizePxSetting('shot', item.shotKind);
                }
            });
        }
        this.syncControlsSettingFromAppearance();
        const ytItem = this.settingsItems.find((item) => item.type === 'youtubeUrl');
        if (ytItem && typeof youtubeSoundtrackManager !== 'undefined') {
            ytItem.value = youtubeSoundtrackManager.getMenuUrl() || '';
        }
        const soundCodeItem = this.settingsItems.find((item) => item.type === 'soundCode');
        if (soundCodeItem && typeof startupSound !== 'undefined' && startupSound.toCode) {
            soundCodeItem.value = startupSound.toCode();
        }
        const difficultyItem = this.settingsItems.find((item) => item.name === 'Difficulty');
        if (difficultyItem && typeof difficultyConfigManager !== 'undefined') {
            difficultyItem.value = String(difficultyConfigManager.current || 'normal').toUpperCase();
        }
        const look = (typeof colorPaletteSystem !== 'undefined' && colorPaletteSystem.getGlobalLook)
            ? colorPaletteSystem.getGlobalLook() : null;
        const brightness = this.settingsItems.find((item) => item.lookKey === 'brightness');
        const contrast = this.settingsItems.find((item) => item.lookKey === 'contrast');
        const saturation = this.settingsItems.find((item) => item.lookKey === 'saturation');
        const grayscale = this.settingsItems.find((item) => item.type === 'grayscale');
        if (look) {
            if (brightness) brightness.value = String(Math.round(look.brightness));
            if (contrast) contrast.value = String(Math.round(look.contrast));
            if (saturation) saturation.value = String(Math.round(look.saturation));
            if (grayscale) grayscale.value = look.saturation === 0 ? 'ON' : 'OFF';
        }

        if (!bare) {
            const header = document.createElement('div');
            header.className = 'settings-modal-header';

            const title = document.createElement('h2');
            title.textContent = 'SETTINGS';
            title.className = 'start-screen-title settings-modal-title';
            header.appendChild(title);

            const closeBtn = document.createElement('button');
            closeBtn.type = 'button';
            closeBtn.className = 'settings-modal-close';
            closeBtn.setAttribute('aria-label', 'Close');
            closeBtn.title = 'Close';
            closeBtn.textContent = '✕';
            closeBtn.addEventListener('click', () => this.handleEscape());
            header.appendChild(closeBtn);

            content.appendChild(header);
        }

        const panel = document.createElement('div');
        panel.className = 'settings-panel settings-panel-clustered';

        const left = document.createElement('div');
        left.className = 'settings-cluster';
        left.dataset.cluster = 'appearance';

        const middle = document.createElement('div');
        middle.className = 'settings-cluster';
        middle.dataset.cluster = 'style-fx';

        const right = document.createElement('div');
        right.className = 'settings-cluster';
        right.dataset.cluster = 'audio-game';

        // Prefer SHOTS once on first land so the new rows are visible;
        // otherwise keep the last-opened section.
        let openSection = 'shots';
        try {
            const seen = localStorage.getItem('vf_settings_shots_seen_v1');
            if (seen) {
                openSection = localStorage.getItem('vf_settings_open_section') || 'enemies';
            } else {
                localStorage.setItem('vf_settings_shots_seen_v1', '1');
                localStorage.setItem('vf_settings_open_section', 'shots');
                openSection = 'shots';
            }
        } catch (e) { /* optional */ }

        const addSection = (parent, sectionId, sectionTitle, predicate) => {
            const items = this.settingsItems
                .map((item, index) => ({ item, index }))
                .filter(({ item }) => predicate(item));
            if (!items.length) return;

            const sectionEl = document.createElement('details');
            sectionEl.className = 'settings-section';
            sectionEl.dataset.section = sectionId;
            sectionEl.open = sectionId === openSection;
            sectionEl.addEventListener('toggle', () => {
                if (!sectionEl.open) return;
                panel.querySelectorAll('details.settings-section[open]').forEach((d) => {
                    if (d !== sectionEl) d.open = false;
                });
                try { localStorage.setItem('vf_settings_open_section', sectionId); } catch (e) { /* optional */ }
            });

            const heading = document.createElement('summary');
            heading.className = 'settings-section-title';
            const icon = SETTINGS_SECTION_ICONS[sectionId];
            heading.innerHTML = (icon ? `<svg class="settings-section-icon" viewBox="0 0 16 16" aria-hidden="true"><path d="${icon}"/></svg>` : '') +
                `<span class="settings-section-name"></span>`;
            heading.querySelector('.settings-section-name').textContent = sectionTitle;
            sectionEl.appendChild(heading);

            const list = document.createElement('div');
            list.className = 'settings-section-list';
            items.forEach(({ item, index }) => {
                const row = this.buildSettingsRow(item, index);
                row.dataset.settingsKey = this.settingsItemKey(item);
                list.appendChild(row);
            });

            sectionEl.appendChild(list);
            parent.appendChild(sectionEl);
        };

        addSection(left, 'theme', 'THEME', (item) =>
            item.type === 'palette' || item.type === 'secondBase'
        );
        addSection(left, 'look', 'LOOK', (item) =>
            item.type === 'globalLook' || item.type === 'grayscale'
        );
        addSection(bare ? left : middle, 'style', 'STYLE', (item) =>
            item.type === 'borderWeight' ||
            item.type === 'indicatorWeight' ||
            item.type === 'fontMenu' ||
            item.type === 'bgParallax' ||
            item.type === 'controlsHints'
        );
        const isVoxelItem = (item) => item.type === 'shipRenderStyle' || item.type === 'voxelSize'
            || (item.type === 'uiFx' && typeof uiAppearanceManager !== 'undefined'
                && (item.fxKey === 'guiVoxel' || item.fxKey === 'gvCell' || item.fxKey === 'framePx' || item.fxKey === 'frameRound' || !!uiAppearanceManager.gvPartKey(item.fxKey)));
        addSection(bare ? left : middle, 'voxel', 'VOXEL', isVoxelItem);
        addSection(bare ? left : middle, 'fx', 'RETRO FX', (item) => item.type === 'uiFx' && !isVoxelItem(item));
        addSection(right, 'sound', 'SOUND', (item) =>
            item.type === 'volume' ||
            item.name === 'Sound' ||
            item.name === 'Music' ||
            item.type === 'youtubeUrl' ||
            item.type === 'soundCode' ||
            item.action === 'startupSound'
        );
        addSection(right, 'game', 'GAME', (item) =>
            item.name === 'Difficulty' || item.action === 'difficultyEditor'
                || item.action === 'factionCommand'
        );
        addSection(right, 'enemies', 'ENEMIES', (item) =>
            item.type === 'enemyClassSize' || item.type === 'playerSize');
        addSection(right, 'shots', 'SHOTS', (item) => item.type === 'shotSize');
        // Asset editor lives here only (no main-menu entry).
        addSection(right, 'assets', 'ASSETS', (item) =>
            (item.type === 'action' && item.action !== 'difficultyEditor'
                && item.action !== 'factionCommand'
                && item.action !== 'startupSound') || item.type === 'assetStatus'
        );

        this.attachShipRenderPreview(bare ? left : middle);

        panel.appendChild(left);
        if (!bare) {
            panel.classList.add('settings-panel-3col');
            panel.appendChild(middle);
        }
        panel.appendChild(right);
        this.buildSettingsMaster(panel);
        content.appendChild(panel);

        if (!bare) {
            const instructions = this.buildControlsHint([
                'ARROW KEYS / MOUSE: Navigate',
                'LEFT/RIGHT / CLICK: Change Value',
                'ASSETS: Open Generator (Comfy + Bridge)',
                'ESC: Back'
            ]);
            content.appendChild(instructions);
            content.appendChild(this.buildControlsShowBtn());
        }

        this.refreshAssetBridgeStatus();
    },
});


/* --- js/ui/start-screen/settings-reorder.js?v=reorder-11 --- */
"use strict";

// StartScreenManager methods: drag & drop order of the rows inside each settings section.
// The order is saved per row key in localStorage and applied to settingsItems before the
// panel is built, so keyboard navigation follows the visible order.
const SETTINGS_GROUPS_KEY = 'vf_settings_groups_v1';
const SETTINGS_DEFAULT_GROUPS = {
    fx: [
        { id: 'light', title: 'LIGHT', rows: ['uiFx:glow', 'uiFx:hdr', 'uiFx:vignette'] },
        { id: 'scan', title: 'SCANLINES', rows: ['uiFx:scanlines', 'uiFx:scanSize', 'uiFx:scanSpeed', 'uiFx:scanWarp'] },
        { id: 'tube', title: 'TUBE', rows: ['uiFx:crt', 'uiFx:chroma', 'uiFx:noise', 'uiFx:flicker'] },
        { id: 'bloom', title: 'BLOOM', rows: ['uiFx:bloom', 'uiFx:bloomSpread', 'uiFx:bloomThreshold'] },
        { id: 'misc', title: 'GENERAL', rows: ['uiFx:fxScale', 'uiFx:arcade', 'uiFx:fxArea'] },
    ],
};
const SETTINGS_NAV_KEY = 'vf_settings_nav_v2';
const SETTINGS_DEFAULT_CLUSTERS = [
    { id: 'appearance', title: 'APPEARANCE', sections: ['theme', 'look', 'style', 'voxel', 'fx'] },
    { id: 'game', title: 'GAME', sections: ['game', 'enemies', 'shots'] },
    { id: 'audio', title: 'AUDIO', sections: ['sound'] },
    { id: 'tools', title: 'TOOLS', sections: ['assets'] },
];

extendClass(StartScreenManager, {
    /** Compact solid drag preview (the browser's own ghost of a glowing row looks washed out). */
    setSettingsDragImage(e, source, text) {
        const ghost = document.createElement('div');
        ghost.className = 'settings-drag-ghost';
        const icon = source.querySelector('.settings-section-icon');
        if (icon) ghost.appendChild(icon.cloneNode(true));
        const t = document.createElement('span');
        t.textContent = text;
        ghost.appendChild(t);
        document.body.appendChild(ghost);
        try { e.dataTransfer.setDragImage(ghost, 14, ghost.offsetHeight / 2); } catch (err) { /* optional */ }
        setTimeout(() => ghost.remove(), 0);
    },

    /** Moves the absolutely positioned drop bar to the gap before `ref` (or after the last child) without touching the layout. */
    positionDropLine(line, container, parent, ref) {
        if (line.parentNode !== container) container.appendChild(line);
        const c = container.getBoundingClientRect();
        let y;
        if (ref) y = ref.getBoundingClientRect().top - 4;
        else {
            const last = Array.from(parent.children).filter((n) => n !== line).pop();
            y = last ? last.getBoundingClientRect().bottom + 2 : parent.getBoundingClientRect().top;
        }
        line.style.top = Math.round(y - c.top + container.scrollTop) + 'px';
    },

    settingsItemKey(item) {
        return `${item.type || ''}:${item.fxKey || item.lookKey || item.enemyClass || item.shotKind || item.action || item.name || ''}`;
    },

    /** Next/previous settings row in the order shown on screen (rows can be regrouped by the user). */
    stepSettingsIndex(dir) {
        const host = this.getUIHost && this.getUIHost();
        const rows = host ? Array.from(host.querySelectorAll('.settings-row[data-settings-index]')) : [];
        const at = rows.findIndex((r) => Number(r.dataset.settingsIndex) === this.settingsIndex);
        if (at < 0) return Math.max(0, Math.min(this.settingsItems.length - 1, this.settingsIndex + dir));
        const next = rows[Math.max(0, Math.min(rows.length - 1, at + dir))];
        return Number(next.dataset.settingsIndex);
    },

    /** Splits one section's rows into movable sub-clusters (saved per section). */
    buildSectionGroups(det) {
        const list = det.querySelector('.settings-section-list');
        if (!list) return;
        const sid = det.dataset.section;
        const rows = Array.from(list.children).filter((r) => r.dataset.settingsKey);
        if (!rows.length) return;
        const byKey = new Map(rows.map((r) => [r.dataset.settingsKey, r]));
        let all = {};
        try { all = JSON.parse(localStorage.getItem(SETTINGS_GROUPS_KEY) || '{}') || {}; } catch (e) { all = {}; }
        const base = all[sid] || SETTINGS_DEFAULT_GROUPS[sid] || [{ id: 'main', title: '', rows: rows.map((r) => r.dataset.settingsKey) }];
        const layout = base.map((g) => ({ id: String(g.id), title: String(g.title || ''), rows: (g.rows || []).filter((k) => byKey.has(k)) }));
        const placed = new Set(layout.flatMap((g) => g.rows));
        rows.forEach((r) => {
            if (placed.has(r.dataset.settingsKey)) return;
            const last = layout[layout.length - 1] || (layout[0] = { id: 'main', title: '', rows: [] });
            last.rows.push(r.dataset.settingsKey);
        });

        list.style.position = 'relative';
        list.classList.add('settings-grouped');
        list.replaceChildren();
        const line = document.createElement('div');
        line.className = 'settings-drop-line is-abs';
        let drag = null;
        let target = null;
        let lastKey = '';
        const root = document.documentElement;
        const endDrag = () => {
            if (drag) drag.el.classList.remove('is-dragging');
            drag = null; target = null; lastKey = '';
            line.remove();
            root.removeAttribute('data-vf-dragging');
        };
        const save = () => {
            const out = Array.from(list.querySelectorAll(':scope > .settings-group')).map((g) => ({
                id: g.dataset.group,
                title: g.querySelector('.settings-group-title').textContent,
                rows: Array.from(g.querySelectorAll('.settings-row')).map((r) => r.dataset.settingsKey),
            }));
            all[sid] = out;
            try { localStorage.setItem(SETTINGS_GROUPS_KEY, JSON.stringify(all)); } catch (e) { /* optional */ }
        };
        const place = (parent, ref, key) => {
            if (key === lastKey) return;
            lastKey = key;
            target = { parent, ref };
            this.positionDropLine(line, list, parent, ref);
        };
        const before = (e, el) => { const r = el.getBoundingClientRect(); return e.clientY < r.top + r.height / 2; };
        const startDrag = (e, el, type, text) => {
            drag = { el, type };
            el.classList.add('is-dragging');
            root.setAttribute('data-vf-dragging', 'on');
            e.dataTransfer.effectAllowed = 'move';
            try { e.dataTransfer.setData('text/plain', text); } catch (err) { /* optional */ }
            this.setSettingsDragImage(e, el, text);
        };
        const dropHere = (e) => {
            if (!drag || !target) return;
            e.preventDefault();
            target.parent.insertBefore(drag.el, target.ref);
            endDrag();
            save();
        };
        const wireRow = (row) => {
            const label = row.querySelector('.settings-row-label');
            if (!label) return;
            label.draggable = true;
            label.title = 'Drag to reorder or move to another cluster';
            label.addEventListener('dragstart', (e) => { e.stopPropagation(); startDrag(e, row, 'row', label.textContent.trim()); });
            label.addEventListener('dragend', endDrag);
            row.addEventListener('dragover', (e) => {
                if (!drag || drag.type !== 'row' || drag.el === row) return;
                e.preventDefault();
                const b = before(e, row);
                place(row.parentNode, b ? row : row.nextElementSibling, row.dataset.settingsKey + (b ? '<' : '>'));
            });
            row.addEventListener('drop', dropHere);
        };
        const makeGroup = (g) => {
            const blk = document.createElement('div');
            blk.className = 'settings-group';
            blk.dataset.group = g.id;
            const head = document.createElement('div');
            head.className = 'settings-group-head';
            head.draggable = true;
            head.title = 'Drag to move the cluster, double-click to rename';
            const title = document.createElement('span');
            title.className = 'settings-group-title';
            title.textContent = g.title;
            head.appendChild(title);
            const del = document.createElement('button');
            del.type = 'button';
            del.className = 'settings-cluster-del';
            del.textContent = '✕';
            del.title = 'Remove empty cluster';
            del.addEventListener('click', () => { blk.remove(); save(); });
            head.appendChild(del);
            head.addEventListener('dblclick', () => {
                const next = window.prompt('Cluster name', title.textContent);
                if (next != null) { title.textContent = next.trim().toUpperCase().slice(0, 24); head.classList.toggle('is-untitled', !title.textContent); save(); }
            });
            head.classList.toggle('is-untitled', !g.title);
            const body = document.createElement('div');
            body.className = 'settings-group-body';
            g.rows.forEach((k) => { const r = byKey.get(k); wireRow(r); body.appendChild(r); });
            head.addEventListener('dragstart', (e) => startDrag(e, blk, 'group', title.textContent || 'Cluster'));
            head.addEventListener('dragend', endDrag);
            blk.addEventListener('dragover', (e) => {
                if (!drag || drag.el === blk) return;
                if (drag.type === 'group') {
                    e.preventDefault();
                    const b = before(e, blk);
                    const nx = blk.nextElementSibling;
                    place(list, b ? blk : (nx && nx.classList.contains('settings-group') ? nx : addBtn), g.id + (b ? '<' : '>'));
                } else if (head.contains(e.target) || e.target === body || !body.children.length) {
                    e.preventDefault();
                    place(body, body.firstElementChild, g.id + ':top');
                }
            });
            blk.addEventListener('drop', dropHere);
            blk.appendChild(head);
            blk.appendChild(body);
            return blk;
        };
        const addBtn = document.createElement('button');
        addBtn.type = 'button';
        addBtn.className = 'settings-nav-add';
        addBtn.textContent = '+ CLUSTER';
        addBtn.addEventListener('click', () => {
            const blk = makeGroup({ id: 'g' + Date.now(), title: 'NEW', rows: [] });
            list.insertBefore(blk, addBtn);
            save();
        });
        layout.forEach((g) => list.appendChild(makeGroup(g)));
        list.appendChild(addBtn);
    },

    /** Master/detail layout: clustered section list on the left, the open section on the right. */
    buildSettingsMaster(panel) {
        if (!panel.querySelector('details.settings-section[data-section="debug"]')) {
            const debug = document.createElement('details');
            debug.className = 'settings-section';
            debug.dataset.section = 'debug';
            debug.open = false;
            debug.innerHTML = `
                <summary class="settings-section-title">
                    <span class="settings-section-name">DEBUG</span>
                </summary>
                <div class="settings-section-list">
                    <div class="settings-grouped">
                        <div class="settings-group">
                            <div class="settings-group-head"><span>DIAGNOSTICS</span></div>
                            <div class="settings-group-body">
                                <div class="settings-row">
                                    <span class="settings-row-label">FPS COUNTER</span>
                                    <button type="button" class="settings-cycle-btn" data-debug-action="fps">OFF</button>
                                </div>
                                <div class="settings-row">
                                    <span class="settings-row-label">PERFORMANCE MODE</span>
                                    <button type="button" class="settings-cycle-btn" data-debug-action="perf">OFF</button>
                                </div>
                            </div>
                        </div>
                        <div class="settings-group">
                            <div class="settings-group-head"><span>ACTIONS</span></div>
                            <div class="settings-group-body">
                                <div class="settings-row">
                                    <span class="settings-row-label">RELOAD GAME</span>
                                    <button type="button" class="settings-cycle-btn" data-debug-action="reload">RUN</button>
                                </div>
                                <div class="settings-row">
                                    <span class="settings-row-label">CLEAR LOCAL SETTINGS</span>
                                    <button type="button" class="settings-cycle-btn" data-debug-action="clear">CLEAR</button>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>`;
            panel.appendChild(debug);
            debug.querySelectorAll('[data-debug-action]').forEach((button) => {
                button.addEventListener('click', () => {
                    const action = button.dataset.debugAction;
                    if (action === 'reload') window.location.reload();
                    if (action === 'clear') {
                        try { localStorage.clear(); sessionStorage.clear(); } catch (e) { /* optional */ }
                        window.location.reload();
                    }
                    if (action === 'fps') {
                        const on = document.documentElement.toggleAttribute('data-vf-debug-fps');
                        button.textContent = on ? 'ON' : 'OFF';
                    }
                    if (action === 'perf') {
                        const on = document.documentElement.toggleAttribute('data-vf-performance');
                        button.textContent = on ? 'ON' : 'OFF';
                    }
                });
            });
        }
        const dets = Array.from(panel.querySelectorAll('details.settings-section'));
        if (!dets.length) return;
        const byId = new Map(dets.map((d) => [d.dataset.section, d]));
        let saved = null;
        try { saved = JSON.parse(localStorage.getItem(SETTINGS_NAV_KEY) || 'null'); } catch (e) { saved = null; }
        const layout = (Array.isArray(saved) && saved.length ? saved : SETTINGS_DEFAULT_CLUSTERS)
            .map((c) => ({ id: String(c.id), title: String(c.title || 'CLUSTER'), sections: (c.sections || []).filter((id) => byId.has(id)) }));
        const placed = new Set(layout.flatMap((c) => c.sections));
        dets.forEach((d) => {
            if (placed.has(d.dataset.section)) return;
            const home = SETTINGS_DEFAULT_CLUSTERS.find((c) => c.sections.includes(d.dataset.section));
            const target = (home && layout.find((c) => c.id === home.id)) || layout[layout.length - 1] || (layout[0] = { id: 'main', title: 'SETTINGS', sections: [] });
            target.sections.push(d.dataset.section);
        });

        dets.forEach((d) => this.buildSectionGroups(d));
        const nav = document.createElement('div');
        nav.className = 'settings-nav';
        const detail = document.createElement('div');
        detail.className = 'settings-detail';
        const items = new Map();
        const line = document.createElement('div');
        line.className = 'settings-drop-line is-abs';
        let target = null;
        let drag = null;
        let lastKey = '';
        const root = document.documentElement;
        const endDrag = () => {
            if (drag) drag.el.classList.remove('is-dragging');
            drag = null; lastKey = ''; target = null;
            line.remove();
            root.removeAttribute('data-vf-dragging');
        };
        const save = () => {
            const out = Array.from(nav.querySelectorAll(':scope > .settings-cluster-block')).map((blk) => ({
                id: blk.dataset.cluster,
                title: blk.querySelector('.settings-cluster-title').textContent,
                sections: Array.from(blk.querySelectorAll('.settings-nav-item')).map((b) => b.dataset.section),
            }));
            try { localStorage.setItem(SETTINGS_NAV_KEY, JSON.stringify(out)); } catch (e) { /* optional */ }
        };
        const show = (id) => {
            dets.forEach((d) => {
                const on = d.dataset.section === id;
                if (d.open !== on) d.open = on;
                items.get(d.dataset.section).classList.toggle('active', on);
            });
        };
        // Where the dragged thing would land: [parent, referenceNode], or null.
        const place = (parent, ref, key) => {
            if (key === lastKey) return;
            lastKey = key;
            target = { parent, ref };
            this.positionDropLine(line, nav, parent, ref);
        };
        const before = (e, el) => { const r = el.getBoundingClientRect(); return e.clientY < r.top + r.height / 2; };
        const startDrag = (e, el, type, text, iconSrc) => {
            drag = { el, type };
            el.classList.add('is-dragging');
            root.setAttribute('data-vf-dragging', 'on');
            e.dataTransfer.effectAllowed = 'move';
            try { e.dataTransfer.setData('text/plain', text); } catch (err) { /* optional */ }
            this.setSettingsDragImage(e, iconSrc || el, text);
        };
        const dropHere = (e) => {
            if (!drag || !target) return;
            e.preventDefault();
            target.parent.insertBefore(drag.el, target.ref);
            endDrag();
            save();
        };

        const makeItem = (d) => {
            const id = d.dataset.section;
            const head = d.querySelector(':scope > summary.settings-section-title');
            const btn = document.createElement('button');
            btn.type = 'button';
            btn.className = 'settings-nav-item';
            btn.dataset.section = id;
            btn.draggable = true;
            btn.title = 'Click to open, drag to reorder or move to another cluster';
            const icon = head && head.querySelector('.settings-section-icon');
            if (icon) btn.appendChild(icon.cloneNode(true));
            const name = document.createElement('span');
            name.textContent = head ? head.textContent.trim() : id;
            btn.appendChild(name);
            btn.addEventListener('click', () => show(id));
            btn.addEventListener('dragstart', (e) => startDrag(e, btn, 'section', name.textContent));
            btn.addEventListener('dragend', endDrag);
            btn.addEventListener('dragover', (e) => {
                if (!drag || drag.type !== 'section' || drag.el === btn) return;
                e.preventDefault();
                const b = before(e, btn);
                place(btn.parentNode, b ? btn : btn.nextElementSibling, id + (b ? '<' : '>'));
            });
            btn.addEventListener('drop', dropHere);
            items.set(id, btn);
            detail.appendChild(d);
            d.addEventListener('toggle', () => { if (d.open) show(id); });
            return btn;
        };

        const makeCluster = (c) => {
            const blk = document.createElement('div');
            blk.className = 'settings-cluster-block';
            blk.dataset.cluster = c.id;
            const head = document.createElement('div');
            head.className = 'settings-cluster-head';
            head.draggable = true;
            head.title = 'Drag to move the cluster, double-click to rename';
            const title = document.createElement('span');
            title.className = 'settings-cluster-title';
            title.textContent = c.title;
            head.appendChild(title);
            const del = document.createElement('button');
            del.type = 'button';
            del.className = 'settings-cluster-del';
            del.textContent = '✕';
            del.title = 'Remove empty cluster';
            del.addEventListener('click', () => { blk.remove(); save(); });
            head.appendChild(del);
            head.addEventListener('dblclick', () => {
                const next = window.prompt('Cluster name', title.textContent);
                if (next && next.trim()) { title.textContent = next.trim().toUpperCase().slice(0, 24); save(); }
            });
            const body = document.createElement('div');
            body.className = 'settings-cluster-body';
            c.sections.forEach((id) => body.appendChild(makeItem(byId.get(id))));
            head.addEventListener('dragstart', (e) => startDrag(e, blk, 'cluster', title.textContent));
            head.addEventListener('dragend', endDrag);
            blk.addEventListener('dragover', (e) => {
                if (!drag || drag.el === blk) return;
                if (drag.type === 'cluster') {
                    e.preventDefault();
                    const b = before(e, blk);
                    place(nav, b ? blk : (blk.nextElementSibling && blk.nextElementSibling.classList.contains('settings-cluster-block') ? blk.nextElementSibling : add), c.id + (b ? '<' : '>'));
                } else if (e.target === head || head.contains(e.target) || !body.children.length || e.target === body) {
                    // Over the header (or an empty cluster): the item goes to the top of this cluster.
                    e.preventDefault();
                    place(body, body.firstElementChild, c.id + ':top');
                }
            });
            blk.addEventListener('drop', dropHere);
            blk.appendChild(head);
            blk.appendChild(body);
            return blk;
        };
        layout.forEach((c) => nav.appendChild(makeCluster(c)));

        const add = document.createElement('button');
        add.type = 'button';
        add.className = 'settings-nav-add';
        add.textContent = '+ CLUSTER';
        add.addEventListener('click', () => {
            nav.insertBefore(makeCluster({ id: 'c' + Date.now(), title: 'NEW', sections: [] }), add);
            save();
        });
        nav.appendChild(add);

        panel.querySelectorAll('.settings-cluster').forEach((c) => c.remove());
        panel.classList.add('settings-panel-master');
        panel.appendChild(nav);
        panel.appendChild(detail);
        const open = dets.find((d) => d.open) || dets[0];
        show(open.dataset.section);
    },
});


/* --- js/ui/start-screen/fill-embedded-layout.js?v=btn-4 --- */
"use strict";

// Menu → LAYOUT: sort and regroup the station navigation (MENU_AREAS).
// Areas can be reordered; each tab can be moved up / down inside its area,
// moved to another area, or made the area's default (★ = where a click on
// the area lands). Changes save at once (saveMenuAreas) and rebuild the
// station's tab rows. RESET restores the built-in layout.
extendClass(StartScreenManager, {
    fillEmbeddedLayout(body) {
        const panel = document.createElement('div');
        panel.className = 'hs-menu-panel-section hs-layout-editor';
        body.appendChild(panel);
        if (typeof MENU_AREAS === 'undefined') {
            panel.innerHTML = '<p class="hs-menu-panel-copy">No menu layout available.</p>';
            return;
        }
        const hs = typeof homeStationUI !== 'undefined' ? homeStationUI : null;
        const tabLabel = (id) => {
            if (id === 'station') return 'STORAGE';
            if (id === 'hangar') return 'SHIPYARD';
            const meta = hs && hs._tabMeta && hs._tabMeta[id];
            return (meta && meta.label) || String(id).toUpperCase();
        };
        const esc = (t) => String(t == null ? '' : t).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

        // MENU row: its tabs in their current order. Station pages (e.g.
        // COMPONENTS) may move between the menu and the areas; the pure menu
        // pages (profiles / settings / layout / credits) stay in the menu.
        const MENU = '__menu';
        // (STORAGE stays in an area: the menu row can't host it.)
        const STATION_TABS = ['play', 'hangar', 'travel', 'explorations', 'factions', 'ffleet', 'ftrade',
            'fcontracts', 'upgrade', 'components', 'missions', 'craft', 'shop'];
        const embedded = (this.embeddedMenuTabs || []);
        const menuIds = () => (hs && hs.getMenuRowTabs ? hs.getMenuRowTabs().map((t) => t.id)
            : (typeof MENU_ORDER !== 'undefined' ? MENU_ORDER.esc.slice() : []));
        const menuLabel = (id) => {
            const e = embedded.find((t) => t.id === id);
            return e ? e.label : tabLabel(id);
        };
        // Icons: current (player choice or default) per tab / 'area:<id>'.
        const defaultIcon = (key) => {
            if (key.indexOf('area:') === 0) {
                const base = (typeof MENU_AREAS_DEFAULTS !== 'undefined' ? MENU_AREAS_DEFAULTS : MENU_AREAS)
                    .find((a) => 'area:' + a.id === key);
                return base ? base.icon : '';
            }
            if (key === 'station') return 'hsStores';
            const e = embedded.find((t) => t.id === key);
            if (e) return e.icon;
            const meta = hs && hs._tabMeta && hs._tabMeta[key];
            return (meta && meta.icon) || '';
        };
        const iconOf = (key) => (typeof getMenuIcon === 'function' ? getMenuIcon(key, defaultIcon(key)) : defaultIcon(key));
        // Cleaned variant (no grey fringe, centred) — same as the station tabs.
        const iconImg = (k, size) => {
            if (!hs || !hs.iconHtml || !k) return '';
            const key = hs.tabIconKey ? hs.tabIconKey(k) : k;
            return hs.iconHtml(key, size || 32, 'hs-pixel', false);
        };
        const iconBtn = (key) => `<button type="button" class="hs-layout-btn hs-layout-icon" data-act="icon" data-icon-key="${esc(key)}" title="Change icon" data-nav-item>${iconImg(iconOf(key))}</button>`;
        // Names: default per key, and the shown one (player rename or default).
        const defaultLabel = (key) => {
            if (key.indexOf('area:') === 0) {
                const a = MENU_AREAS.find((x) => 'area:' + x.id === key);
                return a ? a.label : key;
            }
            return menuLabel(key);
        };
        const labelOf = (key) => (typeof getMenuLabel === 'function' ? getMenuLabel(key, defaultLabel(key)) : defaultLabel(key));
        const renameBtn = (key) => `<button type="button" class="hs-layout-rename" data-act="rename" data-label-key="${esc(key)}" title="Rename" tabindex="-1">✎</button>`;
        const setMenu = (ids) => { if (typeof MENU_ORDER !== 'undefined') MENU_ORDER.esc = ids; };

        const apply = () => {
            if (typeof saveMenuAreas === 'function') saveMenuAreas();
            if (typeof saveMenuOrder === 'function') saveMenuOrder();
            if (hs && hs.applyMenuOrder) hs.applyMenuOrder();
            // Rebuild the station (its tab rows) and this panel.
            if (hs && hs.isVisible && hs.createUI) hs.createUI();
            else { body.innerHTML = ''; this.fillEmbeddedLayout(body); }
        };
        const move = (arr, i, d) => {
            const j = i + d;
            if (j < 0 || j >= arr.length) return false;
            const t = arr[i]; arr[i] = arr[j]; arr[j] = t;
            return true;
        };

        const areasHtml = MENU_AREAS.map((area, ai) => {
            const rows = area.tabs.map((tab, ti) => {
                const others = MENU_AREAS.filter((a) => a !== area)
                    .map((a) => `<option value="${esc(a.id)}">${esc(a.label)}</option>`).join('');
                const isDefault = (area.defaultTab || area.tabs[0]) === tab;
                return `<li class="hs-layout-tab" data-area="${esc(area.id)}" data-tab="${esc(tab)}">` +
                    iconBtn(tab) +
                    `<button type="button" class="hs-layout-btn hs-layout-star${isDefault ? ' is-on' : ''}" data-act="default" title="Default tab of this area" data-nav-item>★</button>` +
                    `<span class="hs-layout-name" draggable="true" title="Drag to move">${esc(labelOf(tab))}</span>` + renameBtn(tab) +
                    `</li>`;
            }).join('');
            return `<section class="hs-layout-area" data-area="${esc(area.id)}">` +
                `<header class="hs-layout-area-head">` + iconBtn('area:' + area.id) +
                `<span class="hs-layout-area-name" draggable="true" title="Drag to reorder areas">${esc(labelOf('area:' + area.id))}</span>` + renameBtn('area:' + area.id) +
                `</header><ul class="hs-layout-tabs">${rows}</ul></section>`;
        }).join('');

        const menuRows = menuIds().map((id) => {
            const fixed = STATION_TABS.indexOf(id) === -1;
            return `<li class="hs-layout-tab${fixed ? ' is-fixed' : ''}" data-area="${MENU}" data-tab="${esc(id)}">` +
                iconBtn(id) + `<span class="hs-layout-name" draggable="true" title="${fixed ? 'Drag to reorder (menu page, stays in the menu)' : 'Drag to move'}">${esc(labelOf(id))}</span>` + renameBtn(id) +
                `</li>`;
        }).join('');
        const menuHtml = `<section class="hs-layout-area hs-layout-area-menu" data-area="${MENU}">` +
            `<header class="hs-layout-area-head"><span class="hs-layout-area-name">MENU</span></header>` +
            `<ul class="hs-layout-tabs">${menuRows}</ul></section>`;

        panel.innerHTML =
            '<h2 class="hs-menu-panel-section-title">MENU LAYOUT</h2>' +
            '<p class="hs-menu-panel-copy">Drag the area names to reorder the top bar; drag a tab name to reorder it or move it into another area. Click an icon to change it; hover a name and click ✎ to rename it. ★ marks the tab an area opens on. Every area keeps at least one tab. The MENU card orders the menu row; station pages can move between the menu and the areas.</p>' +
            `<div class="hs-layout-areas">${areasHtml}${menuHtml}</div>` +
            '<div class="hs-menu-panel-actions"><button type="button" class="action-button hs-menu-panel-action" data-act="reset" data-nav-item>RESET LAYOUT</button></div>';

        // ---- Drag & drop: tabs between / inside areas, areas left-right.
        let drag = null; // { kind: 'tab'|'area', area, tab }
        const clearMarks = () => panel.querySelectorAll('.is-drop-before, .is-drop-after, .is-drop-into, .is-dragging')
            .forEach((el) => el.classList.remove('is-drop-before', 'is-drop-after', 'is-drop-into', 'is-dragging'));
        const dropSpot = (e) => {
            if (!drag) return null;
            if (drag.kind === 'tab') {
                const row = e.target.closest('.hs-layout-tab');
                if (row) {
                    const r = row.getBoundingClientRect();
                    return { row, area: row.getAttribute('data-area'), tab: row.getAttribute('data-tab'),
                        after: e.clientY > r.top + r.height / 2 };
                }
                const areaEl = e.target.closest('.hs-layout-area');
                return areaEl ? { areaEl, area: areaEl.getAttribute('data-area'), tab: null, after: true } : null;
            }
            const areaEl = e.target.closest('.hs-layout-area');
            if (!areaEl) return null;
            const r = areaEl.getBoundingClientRect();
            return { areaEl, area: areaEl.getAttribute('data-area'), after: e.clientX > r.left + r.width / 2 };
        };
        panel.addEventListener('dragstart', (e) => {
            // Only the labels are handles (tab name / area name).
            const row = e.target.closest('.hs-layout-name') && e.target.closest('.hs-layout-tab');
            const head = e.target.closest('.hs-layout-area-name') && e.target.closest('.hs-layout-area-head');
            if (row) drag = { kind: 'tab', area: row.getAttribute('data-area'), tab: row.getAttribute('data-tab'), el: row };
            else if (head) {
                const areaEl = head.closest('.hs-layout-area');
                drag = { kind: 'area', area: areaEl.getAttribute('data-area'), el: areaEl };
            } else return;
            e.dataTransfer.effectAllowed = 'move';
            try { e.dataTransfer.setData('text/plain', drag.tab || drag.area); } catch (err) { /* ignore */ }
            drag.el.classList.add('is-dragging');
        });
        panel.addEventListener('dragover', (e) => {
            const spot = dropSpot(e);
            if (!spot) return;
            e.preventDefault();
            e.dataTransfer.dropEffect = 'move';
            panel.querySelectorAll('.is-drop-before, .is-drop-after, .is-drop-into')
                .forEach((el) => el.classList.remove('is-drop-before', 'is-drop-after', 'is-drop-into'));
            if (spot.row) spot.row.classList.add(spot.after ? 'is-drop-after' : 'is-drop-before');
            else if (drag.kind === 'tab') spot.areaEl.classList.add('is-drop-into');
            else spot.areaEl.classList.add(spot.after ? 'is-drop-after' : 'is-drop-before');
        });
        panel.addEventListener('dragend', () => { drag = null; clearMarks(); });
        panel.addEventListener('drop', (e) => {
            const spot = dropSpot(e);
            const d = drag;
            drag = null;
            clearMarks();
            if (!spot || !d) return;
            e.preventDefault();
            if (d.kind === 'area') {
                if (spot.area === MENU) return;
                const from = MENU_AREAS.findIndex((a) => a.id === d.area);
                const item = MENU_AREAS[from];
                if (!item || spot.area === d.area) return;
                MENU_AREAS.splice(from, 1);
                let to = MENU_AREAS.findIndex((a) => a.id === spot.area);
                if (spot.after) to += 1;
                MENU_AREAS.splice(to, 0, item);
                apply();
                return;
            }
            if (d.area === MENU || spot.area === MENU) {
                if (spot.tab === d.tab) return;
                const ids = menuIds();
                const insertAt = (list) => {
                    let i = spot.tab ? list.indexOf(spot.tab) : list.length;
                    if (spot.tab && spot.after) i += 1;
                    return Math.max(0, i < 0 ? list.length : i);
                };
                if (d.area === MENU && spot.area === MENU) {
                    const next = ids.filter((t) => t !== d.tab);
                    next.splice(insertAt(next), 0, d.tab);
                    setMenu(next);
                } else if (spot.area === MENU) {
                    // Area → menu (station pages only; the area keeps one tab).
                    const src = MENU_AREAS.find((a) => a.id === d.area);
                    if (!src || src.tabs.length < 2 || STATION_TABS.indexOf(d.tab) === -1) return;
                    src.tabs = src.tabs.filter((t) => t !== d.tab);
                    if (src.defaultTab === d.tab) src.defaultTab = src.tabs[0];
                    const next = ids.filter((t) => t !== d.tab);
                    next.splice(insertAt(next), 0, d.tab);
                    setMenu(next);
                } else {
                    // Menu → area (station pages only).
                    const dst = MENU_AREAS.find((a) => a.id === spot.area);
                    if (!dst || STATION_TABS.indexOf(d.tab) === -1) return;
                    setMenu(ids.filter((t) => t !== d.tab));
                    dst.tabs.splice(insertAt(dst.tabs), 0, d.tab);
                }
                apply();
                return;
            }
            const src = MENU_AREAS.find((a) => a.id === d.area);
            const dst = MENU_AREAS.find((a) => a.id === spot.area);
            if (!src || !dst || spot.tab === d.tab) return;
            // Every area keeps at least one tab.
            if (src !== dst && src.tabs.length < 2) return;
            src.tabs = src.tabs.filter((t) => t !== d.tab);
            if (src !== dst && src.defaultTab === d.tab) src.defaultTab = src.tabs[0];
            let idx = spot.tab ? dst.tabs.indexOf(spot.tab) : dst.tabs.length;
            if (spot.tab && spot.after) idx += 1;
            dst.tabs.splice(Math.max(0, idx), 0, d.tab);
            apply();
        });

        // ---- Icon picker modal.
        const openIconPicker = (key) => {
            const cur = iconOf(key);
            const def = defaultIcon(key);
            // Every sprite once (identical pixel art only the first time);
            // the clean nav icons first.
            const all = typeof IconSprites !== 'undefined' && IconSprites
                ? Object.keys(IconSprites).filter((k) => k.indexOf('__') === -1 && Array.isArray(IconSprites[k])) : [];
            all.sort((a, b) => ((b.indexOf('nav') === 0) - (a.indexOf('nav') === 0)));
            const seenArt = {};
            const keys = all.filter((k) => {
                const sig = JSON.stringify(IconSprites[k].map((row) => row.map((v) => (v >= 10 ? 1 : 0))));
                if (seenArt[sig]) return false;
                seenArt[sig] = true;
                return true;
            });
            if (cur && keys.indexOf(cur) === -1) keys.unshift(cur);
            const back = document.createElement('div');
            back.className = 'hs-layout-icon-modal-back';
            back.innerHTML = `<div class="hs-layout-icon-modal" role="dialog" aria-label="Choose icon">` +
                `<h3 class="hs-menu-panel-section-title">CHOOSE ICON</h3>` +
                `<div class="hs-layout-icon-grid">` + keys.map((k) =>
                    `<button type="button" class="hs-layout-icon-pick${k === cur ? ' is-on' : ''}${k === def ? ' is-default' : ''}" data-pick="${esc(k)}" title="${esc(k)}${k === def ? ' (default)' : ''}">${iconImg(k, 32)}</button>`).join('') +
                `</div><div class="hs-menu-panel-actions">` +
                `<button type="button" class="action-button hs-menu-panel-action hs-layout-modal-btn" data-pick="__close">CANCEL</button>` +
                `<button type="button" class="action-button hs-menu-panel-action hs-layout-modal-btn" data-pick="__default">DEFAULT</button>` +
                `</div></div>`;
            document.body.appendChild(back);
            const close = () => {
                document.removeEventListener('keydown', onKey, true);
                back.remove();
            };
            // ESC closes only the modal (capture: the station never sees it).
            const onKey = (e) => {
                if (e.key === 'Escape' || e.key === 'Backspace') {
                    e.preventDefault(); e.stopImmediatePropagation(); close();
                } else if (e.key !== 'Tab' && e.key !== 'Enter' && e.key !== ' ') {
                    e.stopImmediatePropagation();
                }
            };
            document.addEventListener('keydown', onKey, true);
            back.addEventListener('click', (e) => {
                if (e.target === back) { close(); return; }
                const b = e.target.closest('[data-pick]');
                if (!b) return;
                const v = b.getAttribute('data-pick');
                close();
                if (v === '__close') return;
                if (typeof setMenuIcon === 'function') setMenuIcon(key, v === '__default' || v === def ? null : v);
                apply();
            });
            const on = back.querySelector('.hs-layout-icon-pick.is-on') || back.querySelector('[data-pick]');
            if (on) on.focus();
        };

        // ---- Inline rename: the pencil swaps the name for a text field.
        // ENTER / blur saves, ESC cancels, an empty name restores the default.
        const startRename = (btn) => {
            const key = btn.getAttribute('data-label-key');
            const nameEl = btn.previousElementSibling;
            if (!nameEl || nameEl.tagName === 'INPUT') return;
            const input = document.createElement('input');
            input.type = 'text';
            input.className = 'hs-layout-rename-input';
            input.value = labelOf(key);
            input.maxLength = 24;
            nameEl.replaceWith(input);
            btn.hidden = true;
            input.focus();
            input.select();
            let done = false;
            const finish = (save) => {
                if (done) return;
                done = true;
                if (save) {
                    const v = input.value.trim().toUpperCase();
                    if (typeof setMenuLabel === 'function') {
                        setMenuLabel(key, !v || v === defaultLabel(key) ? null : v);
                    }
                    apply();
                } else {
                    input.replaceWith(nameEl);
                    btn.hidden = false;
                }
            };
            input.addEventListener('keydown', (e) => {
                e.stopPropagation();
                if (e.key === 'Enter') { e.preventDefault(); finish(true); }
                else if (e.key === 'Escape') { e.preventDefault(); finish(false); }
            });
            input.addEventListener('blur', () => finish(true));
            // Don't start a drag or a click on the row from inside the field.
            ['mousedown', 'click', 'dragstart'].forEach((t) => input.addEventListener(t, (e) => e.stopPropagation()));
        };

        panel.addEventListener('click', (e) => {
            const renameB = e.target.closest('button[data-act="rename"]');
            if (renameB) { startRename(renameB); return; }
            const iconB = e.target.closest('button[data-act="icon"]');
            if (iconB) { openIconPicker(iconB.getAttribute('data-icon-key')); return; }
            const btn = e.target.closest('button[data-act]');
            if (!btn || btn.disabled) return;
            const act = btn.getAttribute('data-act');
            if (act === 'reset') {
                if (typeof resetMenuAreas === 'function') resetMenuAreas();
                if (typeof resetMenuIcons === 'function') resetMenuIcons();
                if (typeof resetMenuLabels === 'function') resetMenuLabels();
                apply();
                return;
            }
            const areaEl = btn.closest('[data-area]');
            const ai = MENU_AREAS.findIndex((a) => a.id === (areaEl && areaEl.getAttribute('data-area')));
            if (ai < 0) return;
            const area = MENU_AREAS[ai];
            if (act === 'area-up' || act === 'area-down') {
                if (move(MENU_AREAS, ai, act === 'area-up' ? -1 : 1)) apply();
                return;
            }
            const tab = btn.closest('[data-tab]') && btn.closest('[data-tab]').getAttribute('data-tab');
            const ti = area.tabs.indexOf(tab);
            if (ti < 0) return;
            if (act === 'default') { area.defaultTab = tab; apply(); return; }
            if (act === 'tab-up' || act === 'tab-down') {
                if (move(area.tabs, ti, act === 'tab-up' ? -1 : 1)) apply();
            }
        });
        panel.addEventListener('change', (e) => {
            const sel = e.target.closest('select[data-act="tab-move"]');
            if (!sel || !sel.value) return;
            const row = sel.closest('[data-tab]');
            const from = MENU_AREAS.find((a) => a.id === row.getAttribute('data-area'));
            const to = MENU_AREAS.find((a) => a.id === sel.value);
            const tab = row.getAttribute('data-tab');
            if (!from || !to || from.tabs.length < 2) return;
            from.tabs = from.tabs.filter((t) => t !== tab);
            if (from.defaultTab === tab) from.defaultTab = from.tabs[0];
            to.tabs.push(tab);
            apply();
        });
    }
});


/* --- js/ui/start-screen/build-settings-row.js?v=1791486957 --- */
"use strict";

// StartScreenManager methods, split from start-screen.js.
extendClass(StartScreenManager, {
    buildSettingsRow(item, index) {
        const menuItem = document.createElement('div');
        menuItem.className = `menu-item settings-row ${index === this.settingsIndex ? 'selected' : ''}`;
        menuItem.dataset.settingsIndex = String(index);
        menuItem.style.textAlign = 'left';
        menuItem.addEventListener('mouseenter', () => {
            this.settingsIndex = index;
            this.updateMenuSelection();
        });

        if (item.type === 'palette') {
            menuItem.classList.add('settings-row-theme');
            this.buildThemeStrip(menuItem, item, index);
            return menuItem;
        }

        if (item.type === 'secondBase') {
            menuItem.classList.add('settings-row-second-base');
            this.buildSecondBaseRow(menuItem, item, index);
            return menuItem;
        }

        if (item.type === 'volume') {
            menuItem.classList.add('volume-settings-item', 'settings-row-volume');
            menuItem.appendChild(this.createVolumeControlsUI());
            return menuItem;
        }

        if (item.type === 'fontMenu') {
            const family = (typeof uiAppearanceManager !== 'undefined') ? uiAppearanceManager.font : 'COURIER';
            menuItem.innerHTML = '';
            const label = document.createElement('span');
            label.className = 'settings-row-label';
            label.textContent = item.name;
            const value = document.createElement('span');
            value.className = 'settings-row-value';
            value.dataset.settingsValue = String(index);
            value.textContent = `${family} ›`;
            menuItem.appendChild(label);
            menuItem.appendChild(value);
            menuItem.addEventListener('click', () => {
                this.settingsIndex = index;
                this.openFontMenu();
            });
            return menuItem;
        }

        if (item.type === 'action' || item.type === 'assetStatus') {
            menuItem.classList.add('settings-row-action');
            menuItem.innerHTML = '';
            const label = document.createElement('span');
            label.className = 'settings-row-label';
            label.textContent = item.name;
            const value = document.createElement('span');
            value.className = 'settings-row-value';
            value.dataset.settingsValue = String(index);
            value.textContent = item.value;
            if (item.type === 'assetStatus') {
                value.classList.add('settings-asset-status');
                value.dataset.assetStatus = '1';
            }
            menuItem.appendChild(label);
            menuItem.appendChild(value);
            menuItem.addEventListener('click', () => {
                this.settingsIndex = index;
                if (item.type === 'action') this.runSettingsAction(item);
                else this.refreshAssetBridgeStatus();
            });
            return menuItem;
        }

        if (item.type === 'youtubeUrl') {
            menuItem.classList.add('settings-row-youtube');
            menuItem.innerHTML = '';
            const label = document.createElement('span');
            label.className = 'settings-row-label';
            label.textContent = item.name;
            const input = document.createElement('input');
            input.type = 'url';
            input.className = 'settings-youtube-input';
            input.placeholder = 'YouTube URL / ID';
            input.spellcheck = false;
            input.autocomplete = 'off';
            input.value = item.value || '';
            input.dataset.settingsYoutube = String(index);
            const sync = () => {
                item.value = String(input.value || '').trim();
                if (typeof youtubeSoundtrackManager !== 'undefined') {
                    youtubeSoundtrackManager.setMenuUrl(item.value);
                }
                if (typeof soundManager !== 'undefined' && soundManager.startMenuMusic) {
                    soundManager.startMenuMusic();
                }
            };
            input.addEventListener('change', sync);
            input.addEventListener('keydown', (e) => {
                if (e.key === 'Enter') {
                    e.preventDefault();
                    sync();
                    input.blur();
                }
                e.stopPropagation();
            });
            input.addEventListener('click', (e) => e.stopPropagation());
            menuItem.appendChild(label);
            menuItem.appendChild(input);
            menuItem.addEventListener('click', () => {
                this.settingsIndex = index;
                input.focus();
            });
            return menuItem;
        }

        if (item.type === 'soundCode') {
            menuItem.classList.add('settings-row-sound-code');
            menuItem.innerHTML = '';
            const label = document.createElement('span');
            label.className = 'settings-row-label';
            label.textContent = item.name;
            const input = document.createElement('textarea');
            input.className = 'settings-sound-code-input';
            input.rows = 8;
            input.spellcheck = false;
            input.autocomplete = 'off';
            input.placeholder = '{ "wave": "square", "volume": 0.06, "notes": [...] }';
            input.value = item.value || (typeof startupSound !== 'undefined' && startupSound.toCode
                ? startupSound.toCode() : '');
            input.dataset.settingsSoundCode = String(index);
            const status = document.createElement('span');
            status.className = 'settings-sound-code-status';
            const sync = (play) => {
                if (typeof startupSound === 'undefined' || !startupSound.applyCode) return;
                try {
                    const p = startupSound.applyCode(input.value, !!play);
                    item.value = startupSound.toCode(p);
                    input.value = item.value;
                    input.classList.remove('is-invalid');
                    status.textContent = play ? 'PLAYED' : 'SAVED';
                } catch (err) {
                    input.classList.add('is-invalid');
                    status.textContent = 'INVALID CODE';
                }
            };
            input.addEventListener('change', () => sync(true));
            input.addEventListener('blur', () => {
                if (input.classList.contains('is-invalid')) return;
                sync(false);
            });
            input.addEventListener('keydown', (e) => {
                e.stopPropagation();
                if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') {
                    e.preventDefault();
                    sync(true);
                }
            });
            input.addEventListener('click', (e) => e.stopPropagation());
            const actions = document.createElement('div');
            actions.className = 'settings-sound-code-actions';
            const playBtn = document.createElement('button');
            playBtn.type = 'button';
            playBtn.className = 'settings-cycle-btn';
            playBtn.textContent = 'PLAY';
            playBtn.addEventListener('click', (e) => {
                e.stopPropagation();
                this.settingsIndex = index;
                sync(true);
            });
            actions.appendChild(playBtn);
            actions.appendChild(status);
            menuItem.appendChild(label);
            menuItem.appendChild(input);
            menuItem.appendChild(actions);
            menuItem.addEventListener('click', () => {
                this.settingsIndex = index;
                input.focus();
            });
            return menuItem;
        }

        if (item.type === 'globalLook' || (item.type === 'uiFx' && !(typeof uiAppearanceManager !== 'undefined' && uiAppearanceManager.isEnumFx(item.fxKey)))
            || item.type === 'playerSize' || item.type === 'enemyClassSize' || item.type === 'shotSize') {
            menuItem.classList.add('settings-row-look');
            this.buildLookSliderRow(menuItem, item, index);
            return menuItem;
        }

        const suffix = item.suffix || (item.type === 'indicatorWeight' ? 'px' : '');
        const label = document.createElement('span');
        label.className = 'settings-row-label';
        label.textContent = item.name;

        const controls = document.createElement('div');
        controls.className = 'settings-row-controls';

        const prevBtn = document.createElement('button');
        prevBtn.type = 'button';
        prevBtn.className = 'settings-cycle-btn';
        prevBtn.textContent = '‹';
        prevBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            this.settingsIndex = index;
            this.changeSettingValue(-1);
        });

        const value = document.createElement('span');
        value.className = 'settings-row-value';
        value.dataset.settingsValue = String(index);
        value.textContent = `${item.value}${suffix}`;

        const nextBtn = document.createElement('button');
        nextBtn.type = 'button';
        nextBtn.className = 'settings-cycle-btn';
        nextBtn.textContent = '›';
        nextBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            this.settingsIndex = index;
            this.changeSettingValue(1);
        });

        controls.appendChild(prevBtn);
        controls.appendChild(value);
        controls.appendChild(nextBtn);
        menuItem.appendChild(label);
        menuItem.appendChild(controls);
        if (item.tip) menuItem.setAttribute('data-ui-tip', item.tip);

        menuItem.addEventListener('click', (e) => {
            if (e.target.closest('.settings-cycle-btn')) return;
            this.settingsIndex = index;
            this.changeSettingValue(1);
        });

        return menuItem;
    },

    syncLookSliderFill(slider, value, min, max) {
        if (!slider) return;
        const lo = Number(min);
        const hi = Number(max);
        const v = Number(value);
        const span = Math.max(1, hi - lo);
        const pct = Math.max(0, Math.min(100, ((v - lo) / span) * 100));
        slider.style.setProperty('--look-fill', `${pct}%`);
        slider.value = String(v);
    },

    buildLookSliderRow(menuItem, item, index) {
        const isSizePx = item.type === 'playerSize' || item.type === 'enemyClassSize' || item.type === 'shotSize';
        const min = item.min != null ? item.min : 0;
        const max = item.max != null ? item.max : 200;
        const step = item.step != null ? item.step : (isSizePx ? 1 : 5);
        const suffix = item.suffix || (isSizePx ? 'px' : '%');
        const numeric = Math.max(min, Math.min(max, Number(item.value) || 0));
        item.value = String(Math.round(numeric));

        const label = document.createElement('span');
        label.className = 'settings-row-label';
        label.textContent = item.name;

        const controls = document.createElement('div');
        controls.className = 'settings-row-controls settings-look-controls';

        const slider = document.createElement('input');
        slider.type = 'range';
        slider.min = String(min);
        slider.max = String(max);
        slider.step = String(step);
        slider.className = 'settings-look-slider';
        slider.dataset.settingsLook = String(index);
        slider.setAttribute('aria-label', item.name);

        const value = document.createElement('span');
        value.className = 'settings-row-value';
        value.dataset.settingsValue = String(index);
        value.textContent = `${item.value}${suffix}`;

        this.syncLookSliderFill(slider, item.value, min, max);

        const applyLookValue = (raw) => {
            const next = Math.max(min, Math.min(max, Math.round(Number(raw))));
            item.value = String(next);
            value.textContent = `${item.value}${suffix}`;
            this.syncLookSliderFill(slider, next, min, max);
            if (item.lookKey === 'saturation') {
                const grayItem = this.settingsItems.find((i) => i.type === 'grayscale');
                if (grayItem) {
                    grayItem.value = item.value === '0' ? 'ON' : 'OFF';
                    this.refreshSettingsRow(this.settingsItems.indexOf(grayItem));
                }
            }
            if (item.type === 'uiFx' && typeof uiAppearanceManager !== 'undefined') {
                uiAppearanceManager.setFx(item.fxKey, item.value);
            }
            this.applySettings();
        };

        slider.addEventListener('input', (e) => {
            e.stopPropagation();
            this.settingsIndex = index;
            applyLookValue(e.target.value);
            this.updateMenuSelection();
        });
        slider.addEventListener('click', (e) => e.stopPropagation());
        slider.addEventListener('mousedown', (e) => e.stopPropagation());
        slider.addEventListener('pointerdown', (e) => e.stopPropagation());

        controls.appendChild(slider);
        controls.appendChild(value);
        menuItem.appendChild(label);
        menuItem.appendChild(controls);

        menuItem.addEventListener('click', (e) => {
            if (e.target.closest('.settings-look-slider')) return;
            this.settingsIndex = index;
            this.updateMenuSelection();
        });
    },

    buildThemeSwatchEl(palette) {
        const swatch = document.createElement('span');
        swatch.className = 'theme-list-swatch';
        const baseHex = (palette && (palette.baseColor || palette.primary)) || '#888888';
        const secondHex = (palette && palette.secondBaseColor)
            || (typeof colorPaletteSystem !== 'undefined' && colorPaletteSystem.defaultSecondBaseColor)
            || '#FFFFFF';
        swatch.style.background = `linear-gradient(135deg, ${baseHex} 50%, ${secondHex} 50%)`;
        swatch.title = `Base ${baseHex} · 2nd ${secondHex}`;
        return swatch;
    },

    bindThemeDropdownOutsideClick() {
        if (this._themeDropdownOutsideBound) return;
        this._themeDropdownOutsideBound = (e) => {
            if (!this.themeDropdownOpen) return;
            if (e.target && e.target.closest && e.target.closest('.settings-row-theme')) return;
            this.themeDropdownOpen = false;
            const host = this.getUIHost();
            const row = host && host.querySelector('.settings-row-theme');
            if (row) row.classList.remove('is-open');
        };
        document.addEventListener('click', this._themeDropdownOutsideBound);
    },
});


/* --- js/ui/start-screen/build-theme-strip.js?v=pull-1 --- */
"use strict";

// StartScreenManager methods, split from start-screen.js.
extendClass(StartScreenManager, {
    buildThemeStrip(menuItem, item, index) {
        const head = document.createElement('div');
        head.className = 'settings-theme-head';

        const paletteLabel = document.createElement('div');
        paletteLabel.className = 'settings-row-label';
        paletteLabel.textContent = item.name;
        head.appendChild(paletteLabel);

        const hint = document.createElement('div');
        hint.className = 'settings-hint type-text';
        hint.textContent = 'Set by your faction';
        head.appendChild(hint);
        menuItem.appendChild(head);

        // App theme follows the faction — show it, don't offer a picker.
        // The editor stays for planet / galaxy / stage themes.
        const colors = (typeof colorPaletteSystem !== 'undefined' && colorPaletteSystem.getCurrentColors)
            ? colorPaletteSystem.getCurrentColors() : null;
        const factionId = (typeof themeContextManager !== 'undefined' && themeContextManager.currentFactionId)
            ? themeContextManager.currentFactionId() : '';
        const current = {
            id: item.value,
            name: String(factionId || 'Faction').toUpperCase(),
            primary: colors && colors.primary,
            baseColor: colors && colors.baseColor,
            secondBaseColor: colors && colors.secondBaseColor
        };
        const badge = document.createElement('div');
        badge.className = 'theme-dropdown-toggle is-readonly';
        badge.appendChild(this.buildThemeSwatchEl(current));
        const badgeName = document.createElement('span');
        badgeName.className = 'theme-list-name';
        badgeName.textContent = current.name;
        badge.appendChild(badgeName);
        menuItem.appendChild(badge);

        const editBtn = document.createElement('button');
        editBtn.type = 'button';
        editBtn.className = 'theme-edit-btn';
        editBtn.textContent = 'PLANET THEMES';
        editBtn.title = 'Edit the environment themes used by planets';
        editBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            this.openThemeEditor(null);
        });
        menuItem.appendChild(editBtn);
    },

    syncSecondBaseSettingValue() {
        const item = this.settingsItems && this.settingsItems.find((s) => s.type === 'secondBase');
        if (!item) return;
        if (typeof colorPaletteSystem !== 'undefined' && colorPaletteSystem.getSecondBaseColor) {
            item.value = colorPaletteSystem.getSecondBaseColor();
        }
    },

    buildSecondBaseRow(menuItem, item, index) {
        this.syncSecondBaseSettingValue();

        const label = document.createElement('span');
        label.className = 'settings-row-label';
        label.textContent = item.name;

        const controls = document.createElement('div');
        controls.className = 'settings-row-controls settings-second-base-controls';

        const prevBtn = document.createElement('button');
        prevBtn.type = 'button';
        prevBtn.className = 'settings-cycle-btn';
        prevBtn.textContent = '‹';
        prevBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            this.settingsIndex = index;
            this.changeSettingValue(-1);
        });

        const swatch = document.createElement('button');
        swatch.type = 'button';
        swatch.className = 'settings-second-base-swatch';
        swatch.dataset.color = this.toSettingsHex(item.value);
        swatch.style.backgroundColor = swatch.dataset.color;
        swatch.title = '2nd basecolor (text / icons)';
        swatch.setAttribute('aria-label', 'Pick 2nd basecolor');
        swatch.addEventListener('click', (e) => {
            e.preventDefault();
            e.stopPropagation();
            this.settingsIndex = index;
            if (typeof colorPickerOverlay === 'undefined' || !colorPickerOverlay.open) return;
            colorPickerOverlay.open(swatch.dataset.color || item.value, {
                anchor: swatch,
                onChange: (hex) => {
                    const next = this.toSettingsHex(hex);
                    item.value = next;
                    swatch.dataset.color = next;
                    swatch.style.backgroundColor = next;
                    this.applySecondBaseChange(next);
                    this.refreshSettingsRow(index);
                }
            });
        });

        const value = document.createElement('span');
        value.className = 'settings-row-value';
        value.dataset.settingsValue = String(index);
        value.textContent = this.toSettingsHex(item.value).toUpperCase();

        const nextBtn = document.createElement('button');
        nextBtn.type = 'button';
        nextBtn.className = 'settings-cycle-btn';
        nextBtn.textContent = '›';
        nextBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            this.settingsIndex = index;
            this.changeSettingValue(1);
        });

        controls.appendChild(prevBtn);
        controls.appendChild(swatch);
        controls.appendChild(value);
        controls.appendChild(nextBtn);
        menuItem.appendChild(label);
        menuItem.appendChild(controls);

        menuItem.addEventListener('click', (e) => {
            if (e.target.closest('.settings-cycle-btn') || e.target.closest('.settings-second-base-swatch')) return;
            this.settingsIndex = index;
            this.changeSettingValue(1);
        });
    },

    toSettingsHex(color) {
        if (typeof colorPaletteSystem !== 'undefined' && colorPaletteSystem.normalizeHex) {
            return colorPaletteSystem.normalizeHex(color).toLowerCase();
        }
        if (!color || typeof color !== 'string') return '#ffffff';
        if (/^#[0-9a-fA-F]{6}$/.test(color)) return color.toLowerCase();
        return '#ffffff';
    },

    applySecondBaseChange(hex) {
        if (typeof colorPaletteSystem === 'undefined' || !colorPaletteSystem.setSecondBaseColor) return;
        colorPaletteSystem.setSecondBaseColor(hex, { persist: true, apply: true });
        if (typeof colorManager !== 'undefined') {
            colorManager.currentColors = colorPaletteSystem.getCurrentColors();
            if (colorManager._syncOverlay) colorManager._syncOverlay(colorPaletteSystem.currentPalette);
        }
        if (typeof iconRenderer !== 'undefined' && iconRenderer.clearCache) {
            iconRenderer.clearCache();
        }
        if (typeof homeStationUI !== 'undefined' && homeStationUI.isVisible && homeStationUI.createUI) {
            try { homeStationUI.createUI(); } catch (e) { /* ignore */ }
        }
    },

    syncThemeStripActive(list, paletteId, scrollIntoView) {
        if (!list) return;
        const scrollTop = list.scrollTop;
        let active = null;
        list.querySelectorAll('.theme-list-item, .theme-strip-item').forEach((btn) => {
            const isActive = btn.dataset.paletteId === paletteId;
            btn.classList.toggle('active', isActive);
            if (isActive) active = btn;
        });
        if (scrollIntoView && active) {
            const target = active.offsetTop - (list.clientHeight / 2) + (active.offsetHeight / 2);
            list.scrollTop = Math.max(0, target);
        } else {
            list.scrollTop = scrollTop;
        }
    },
});


